            <div>
              <h1 className="text-xl font-bold text-gray-900">{t('band.band-protocol.title')}</h1>
              <p className="text-xs text-gray-500">{t('band.bandProtocol.subtitle')}</p>
            </div>
          </div>

          {/* 右侧：操作按钮（桌面端显示在标题右侧） */}
          <div className="hidden lg:block">
            <ActionButtons
              onRefresh={onRefresh}
              onExport={onExport}
              isRefreshing={isRefreshing}
