// 右侧迷你价格图表组件
function MiniPriceChart({
  historicalData,
  currentPrice,
  themeColor,
  t,
}: {
  historicalData: PriceData[];
  currentPrice: PriceData | null;
  themeColor: string;
  t: (key: string) => string;
}) {
  const chartData = useMemo(() => {
    if (historicalData.length >= 20) {
      return historicalData.slice(-20).map((d) => d.price);
    }
    const basePrice = currentPrice?.price || 100;
    // Generate deterministic mock data based on index
    return Array.from({ length: 20 }, (_, i) => basePrice * (1 + (Math.sin(i * 0.5) * 0.05)));
  }, [historicalData, currentPrice]);

  const priceChange = useMemo(() => {
    if (chartData.length < 2) return 0;
    return ((chartData[chartData.length - 1] - chartData[0]) / chartData[0]) * 100;
  }, [chartData]);

  const isPositive = priceChange >= 0;

  if (!chartData.length) return null;

  return (
    <div className="h-full flex flex-col">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-1.5 text-xs text-gray-500">
          <TrendingUpIcon className="w-3.5 h-3.5" />
          <span>{t('chronicle.hero.trend24h')}</span>
        </div>
        <span className={`text-xs font-medium ${isPositive ? 'text-emerald-600' : 'text-red-600'}`}>
          {isPositive ? '+' : ''}
          {priceChange.toFixed(2)}%
        </span>
      </div>
      <div className="flex-1 min-h-[80px] flex items-end">
        <Sparkline data={chartData} positive={isPositive} width={180} height={70} t={t} />
      </div>
      <div className="flex justify-between mt-2 text-[10px] text-gray-400">
        <span>{t('chronicle.hero.24hAgo')}</span>
        <span>{t('chronicle.hero.now')}</span>
      </div>
    </div>
  );
}

