interface ReferenceLineConfig {
  id: string;
  y: number;
  label: string;
  color: string;
  strokeDasharray?: string;
}

interface InteractivePriceChartProps {
  chartData: ChartDataPoint[];
  chartDataWithMA: ChartDataPoint[];
  filteredChains: Blockchain[];
  hiddenLines: Set<string>;
  scatterData: Array<
    Partial<ChartDataPoint> & {
      outlierChain: Blockchain;
      outlierPrice: number;
      deviation: number;
      timestamp: number;
    }
  >;
  avgPrice: number;
  medianPrice: number;
  onLegendClick: (e: { dataKey: string; color: string; type: string; value: string }) => void;
  onLegendDoubleClick: (chain: Blockchain) => void;
}

interface ViewState {
  startIndex: number;
  endIndex: number;
}

// Custom tooltip component
interface CustomTooltipProps {
  active?: boolean;
  payload?: ReadonlyArray<{ dataKey?: string | number; value?: number; color?: string }>;
  label?: string;
  filteredChains: Blockchain[];
}

function CustomTooltip({ active, payload, label, filteredChains }: CustomTooltipProps) {
  if (!active || !payload || payload.length === 0) return null;

  const priceData = payload.filter(
    (p) =>
      p.dataKey &&
      !String(p.dataKey).includes('_MA') &&
      isBlockchain(p.dataKey) &&
      filteredChains.includes(p.dataKey)
  );

  return (
    <div className="bg-white border border-gray-200 p-3 rounded-lg shadow-lg min-w-[240px]">
      <p className="text-gray-600 text-xs mb-2 font-medium border-b border-gray-100 pb-2">
        {label}
      </p>
      {priceData.map((entry) => {
        const dataKey = entry.dataKey;
        const chainName = isBlockchain(dataKey) ? chainNames[dataKey] : String(dataKey);
        return (
          <div
            key={String(entry.dataKey)}
            className="mb-1.5 pb-1.5 border-b border-gray-100 last:border-0 last:mb-0 last:pb-0"
          >
            <div className="flex items-center gap-2 mb-0.5">
              <span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: entry.color }} />
              <span className="text-sm font-medium text-gray-900">{chainName}</span>
            </div>
            <div className="text-sm text-gray-700 pl-4.5 font-mono">
              ${Number(entry.value).toFixed(4)}
            </div>
          </div>
        );
      })}
    </div>
  );
}

export function InteractivePriceChart({
  chartData,
  chartDataWithMA,
  filteredChains,
  hiddenLines,
  scatterData,
  avgPrice,
  medianPrice,
  onLegendClick,
}: InteractivePriceChartProps) {
  const t = useTranslations();
  const containerRef = useRef<HTMLDivElement>(null);
  const [viewState, setViewState] = useState<ViewState>(() => ({
    startIndex: 0,
    endIndex: Math.max(0, chartData.length - 1),
  }));
  const [referenceLines, setReferenceLines] = useState<ReferenceLineConfig[]>([]);
  const [isSelecting, setIsSelecting] = useState(false);
  const [selectionStart, setSelectionStart] = useState<{ x: number; y: number } | null>(null);
  const [selectionEnd, setSelectionEnd] = useState<{ x: number; y: number } | null>(null);
  const [showSelectionBox, setShowSelectionBox] = useState(false);
  const [selectedTimeRange, setSelectedTimeRange] = useState<TimeRange>('24H');

  const handleTimeRangeChange = useCallback((range: string) => {
    setSelectedTimeRange(range as TimeRange);
  }, []);

  const getTimeRangeInMs = useCallback((range: TimeRange): number => {
    const now = Date.now();
    switch (range) {
      case '1H':
        return now - 60 * 60 * 1000;
      case '24H':
        return now - 24 * 60 * 60 * 1000;
      case '7D':
        return now - 7 * 24 * 60 * 60 * 1000;
      case '30D':
        return now - 30 * 24 * 60 * 60 * 1000;
      default:
        return now - 24 * 60 * 60 * 1000;
    }
  }, []);

  const timeFilteredData = useMemo(() => {
    if (chartDataWithMA.length === 0) return [];
    const cutoffTime = getTimeRangeInMs(selectedTimeRange);
    return chartDataWithMA.filter((point) => point.timestamp >= cutoffTime);
  }, [chartDataWithMA, selectedTimeRange, getTimeRangeInMs]);

  const prevDataLengthRef = useRef(chartData.length);
  useEffect(() => {
    if (chartData.length !== prevDataLengthRef.current) {
      prevDataLengthRef.current = chartData.length;
      if (chartData.length > 0) {
        queueMicrotask(() => {
          setViewState({
            startIndex: 0,
            endIndex: chartData.length - 1,
          });
        });
      }
    }
  }, [chartData.length]);

  useEffect(() => {
    if (timeFilteredData.length > 0) {
      queueMicrotask(() => {
        setViewState({
          startIndex: 0,
          endIndex: timeFilteredData.length - 1,
        });
      });
    }
  }, [selectedTimeRange, timeFilteredData.length]);

  const visibleData = useMemo(() => {
    if (timeFilteredData.length === 0) return [];
    return timeFilteredData.slice(viewState.startIndex, viewState.endIndex + 1);
  }, [timeFilteredData, viewState]);

  // Export price chart data to CSV
  const handleExport = useCallback(() => {
    if (visibleData.length === 0 || filteredChains.length === 0) {
      return;
    }

    try {
      const cutoffTime = getTimeRangeInMs(selectedTimeRange);
      const startTime = new Date(cutoffTime).toISOString();
      const endTime = new Date().toISOString();

      const csvLines: string[] = [];

      csvLines.push('=== Price Chart Data ===');
      csvLines.push(`Export Timestamp,${new Date().toISOString()}`);
      csvLines.push(`Time Range,${selectedTimeRange}`);
      csvLines.push(`Data Start Time,${startTime}`);
      csvLines.push(`Data End Time,${endTime}`);
      csvLines.push(`Visible Data Points,${visibleData.length}`);
      csvLines.push(
        `View Range,${viewState.startIndex + 1}-${viewState.endIndex + 1} of ${chartData.length}`
      );
      csvLines.push('');

      const headers = ['Timestamp', 'Time', ...filteredChains.map((chain) => chainNames[chain])];
      csvLines.push(headers.join(','));

      visibleData.forEach((point) => {
        const row: string[] = [String(point.timestamp || ''), String(point.time || '')];
        filteredChains.forEach((chain) => {
          const price = point[chain] as number | undefined;
          row.push(price !== undefined && !isNaN(price) ? price.toFixed(6) : '');
        });
        csvLines.push(row.join(','));
      });

      const csvContent = csvLines.join('\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.setAttribute('href', url);
      link.setAttribute(
        'download',
        `price-chart-${selectedTimeRange}-${new Date().toISOString().slice(0, 19).replace(/:/g, '-')}.csv`
      );
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Failed to export price chart data:', error);
    }
  }, [
    visibleData,
    filteredChains,
    selectedTimeRange,
    viewState,
    chartData.length,
    getTimeRangeInMs,
  ]);

  // Calculate price domain for Y axis
  const priceDomain = useMemo(() => {
    if (visibleData.length === 0) return ['auto', 'auto'] as [string, string];

    let minPrice = Infinity;
    let maxPrice = -Infinity;

    visibleData.forEach((point) => {
      filteredChains.forEach((chain) => {
        const price = point[chain] as number | undefined;
        if (price !== undefined && !isNaN(price)) {
          minPrice = Math.min(minPrice, price);
          maxPrice = Math.max(maxPrice, price);
        }
      });
    });

    const padding = (maxPrice - minPrice) * 0.1;
    return [minPrice - padding, maxPrice + padding] as [number, number];
  }, [visibleData, filteredChains]);

  // Zoom controls
  const handleZoomIn = useCallback(() => {
    setViewState((prev) => {
      const totalPoints = chartData.length;
      const currentRange = prev.endIndex - prev.startIndex;
      const newRange = Math.max(10, Math.floor(currentRange * 0.7));
      const center = Math.floor((prev.startIndex + prev.endIndex) / 2);
      const newStart = Math.max(0, center - Math.floor(newRange / 2));
      const newEnd = Math.min(totalPoints - 1, newStart + newRange);
      return { startIndex: newStart, endIndex: newEnd };
    });
  }, [chartData.length]);

  const handleZoomOut = useCallback(() => {
    setViewState((prev) => {
      const totalPoints = chartData.length;
      const currentRange = prev.endIndex - prev.startIndex;
      const newRange = Math.min(totalPoints - 1, Math.floor(currentRange * 1.4));
      const center = Math.floor((prev.startIndex + prev.endIndex) / 2);
      const newStart = Math.max(0, center - Math.floor(newRange / 2));
      const newEnd = Math.min(totalPoints - 1, newStart + newRange);
      return { startIndex: newStart, endIndex: newEnd };
    });
  }, [chartData.length]);

  const handleResetZoom = useCallback(() => {
    setViewState({
      startIndex: 0,
      endIndex: Math.max(0, chartData.length - 1),
    });
  }, [chartData.length]);

  // Pan controls
  const handlePanLeft = useCallback(() => {
    setViewState((prev) => {
      const currentRange = prev.endIndex - prev.startIndex;
      const shift = Math.max(1, Math.floor(currentRange * 0.2));
      const newStart = Math.max(0, prev.startIndex - shift);
      const newEnd = Math.min(chartData.length - 1, newStart + currentRange);
      return { startIndex: newStart, endIndex: newEnd };
    });
  }, [chartData.length]);

  const handlePanRight = useCallback(() => {
    setViewState((prev) => {
      const currentRange = prev.endIndex - prev.startIndex;
      const shift = Math.max(1, Math.floor(currentRange * 0.2));
      const newEnd = Math.min(chartData.length - 1, prev.endIndex + shift);
      const newStart = Math.max(0, newEnd - currentRange);
      return { startIndex: newStart, endIndex: newEnd };
    });
  }, [chartData.length]);

  // Box selection for zoom
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (e.button === 0) {
      const rect = containerRef.current?.getBoundingClientRect();
      if (rect) {
        setIsSelecting(true);
        setSelectionStart({ x: e.clientX - rect.left, y: e.clientY - rect.top });
        setSelectionEnd({ x: e.clientX - rect.left, y: e.clientY - rect.top });
        setShowSelectionBox(true);
      }
    }
  }, []);

  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      if (isSelecting && selectionStart) {
        const rect = containerRef.current?.getBoundingClientRect();
        if (rect) {
          setSelectionEnd({ x: e.clientX - rect.left, y: e.clientY - rect.top });
        }
      }
    },
    [isSelecting, selectionStart]
  );

  const handleMouseUp = useCallback(() => {
    if (isSelecting && selectionStart && selectionEnd) {
      const chartWidth = containerRef.current?.clientWidth || 1;
      const selectionWidth = Math.abs(selectionEnd.x - selectionStart.x);
      const selectionHeight = Math.abs(selectionEnd.y - selectionStart.y);

      if (selectionWidth > 30 && selectionHeight > 30) {
        const leftPercent = Math.min(selectionStart.x, selectionEnd.x) / chartWidth;
        const rightPercent = Math.max(selectionStart.x, selectionEnd.x) / chartWidth;
        const currentRange = viewState.endIndex - viewState.startIndex;
        const newStart = Math.floor(viewState.startIndex + leftPercent * currentRange);
        const newEnd = Math.ceil(viewState.startIndex + rightPercent * currentRange);

        if (newEnd > newStart + 5) {
          setViewState({
            startIndex: Math.max(0, newStart),
            endIndex: Math.min(chartData.length - 1, newEnd),
          });
        }
      }
    }

    setIsSelecting(false);
    setSelectionStart(null);
    setSelectionEnd(null);
    setShowSelectionBox(false);
  }, [isSelecting, selectionStart, selectionEnd, viewState, chartData.length]);

  // Reference line functions
  const addReferenceLine = useCallback(
    (type: 'current' | 'avg' | 'median' | 'custom') => {
      const id = `ref-${Date.now()}`;
      let y = 0;
      let label = '';
      let color = '';

      switch (type) {
        case 'current':
          if (visibleData.length > 0) {
            const lastPoint = visibleData[visibleData.length - 1];
            const prices = filteredChains
              .map((chain) => lastPoint[chain] as number | undefined)
              .filter((p): p is number => p !== undefined && !isNaN(p));
            y = prices.length > 0 ? prices.reduce((a, b) => a + b, 0) / prices.length : 0;
          }
          label = t('crossChain.currentPrice');
          color = chartColors.recharts.primary;
          break;
        case 'avg':
          y = avgPrice;
          label = t('crossChain.averagePrice');
          color = semanticColors.success.main;
          break;
        case 'median':
          y = medianPrice;
          label = t('crossChain.medianPrice');
          color = semanticColors.warning.main;
          break;
        case 'custom':
          y =
            priceDomain[0] === 'auto'
              ? 0
              : (priceDomain[0] as number) +
                ((priceDomain[1] as number) - (priceDomain[0] as number)) / 2;
          label = t('crossChain.customLine');
          color = semanticColors.info.main;
          break;
      }

      if (y > 0) {
        setReferenceLines((prev) => [...prev, { id, y, label, color, strokeDasharray: '5 5' }]);
      }
    },
    [visibleData, filteredChains, avgPrice, medianPrice, priceDomain, t]
  );

  const removeReferenceLine = useCallback((id: string) => {
    setReferenceLines((prev) => prev.filter((line) => line.id !== id));
  }, []);

  const clearAllReferenceLines = useCallback(() => {
    setReferenceLines([]);
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey) {
        switch (e.key) {
          case 'ArrowLeft':
            e.preventDefault();
            handlePanLeft();
            break;
          case 'ArrowRight':
            e.preventDefault();
            handlePanRight();
            break;
          case '0':
            e.preventDefault();
            handleResetZoom();
            break;
        }
      }

      if (!e.ctrlKey && !e.altKey && !e.metaKey) {
        switch (e.key) {
          case 'ArrowLeft':
            handlePanLeft();
            break;
          case 'ArrowRight':
            handlePanRight();
            break;
          case 'Home':
            handleResetZoom();
            break;
        }
      }
    };

    const handleWheel = (e: WheelEvent) => {
      if (e.ctrlKey) {
        e.preventDefault();
        if (e.deltaY < 0) {
          handleZoomIn();
        } else {
          handleZoomOut();
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    const container = containerRef.current;
    if (container) {
      container.addEventListener('wheel', handleWheel, { passive: false });
    }

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      if (container) {
        container.removeEventListener('wheel', handleWheel);
      }
    };
  }, [handleZoomIn, handleZoomOut, handlePanLeft, handlePanRight, handleResetZoom]);

  // Selection box style
  const selectionBoxStyle = useMemo(() => {
    if (!selectionStart || !selectionEnd || !showSelectionBox) return { display: 'none' };

    const left = Math.min(selectionStart.x, selectionEnd.x);
    const top = Math.min(selectionStart.y, selectionEnd.y);
    const width = Math.abs(selectionEnd.x - selectionStart.x);
    const height = Math.abs(selectionEnd.y - selectionStart.y);

    return {
      left,
      top,
      width,
      height,
      display: 'block',
    };
  }, [selectionStart, selectionEnd, showSelectionBox]);

  // Tooltip content renderer
  const renderTooltip = useCallback(
    (props: unknown) => {
      const tooltipProps = props as {
        active?: boolean;
        payload?: ReadonlyArray<{ dataKey?: string | number; value?: number; color?: string }>;
        label?: string;
      };
      return <CustomTooltip {...tooltipProps} filteredChains={filteredChains} />;
    },
    [filteredChains]
  );

  return (
    <div className="mb-6 pb-6 border-b border-gray-200">
      {/* Chart Toolbar */}
      <ChartToolbar
        timeRanges={['1H', '24H', '7D', '30D']}
        selectedRange={selectedTimeRange}
        onRangeChange={handleTimeRangeChange}
        onExport={handleExport}
        className="mb-3"
      />

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-3">
        <h3 className="text-sm font-semibold text-gray-900 uppercase tracking-wide">
          {t('crossChain.priceChart')}
        </h3>

        {/* Control Buttons */}
        <div className="flex items-center gap-2 flex-wrap">
          {/* Zoom Controls */}
          <div className="flex items-center gap-1 bg-gray-100 p-1 rounded-md">
            <button
              onClick={handleZoomIn}
              className="p-1.5 bg-white hover:bg-gray-50 border border-gray-300 rounded transition-all duration-200 hover:border-gray-400"
              title={t('crossChain.zoomIn')}
            >
              <svg
                className="w-4 h-4 text-gray-600"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM10 7v3m0 0v3m0-3h3m-3 0H7"
                />
              </svg>
            </button>
            <button
              onClick={handleZoomOut}
              className="p-1.5 bg-white hover:bg-gray-50 border border-gray-300 rounded transition-all duration-200 hover:border-gray-400"
              title={t('crossChain.zoomOut')}
            >
              <svg
                className="w-4 h-4 text-gray-600"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM13 10H7"
                />
              </svg>
            </button>
            <button
              onClick={handleResetZoom}
              className="p-1.5 bg-white hover:bg-gray-50 border border-gray-300 rounded transition-all duration-200 hover:border-gray-400"
              title={t('crossChain.resetZoom')}
            >
              <svg
                className="w-4 h-4 text-gray-600"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
                />
              </svg>
            </button>
          </div>

          {/* Pan Controls */}
          <div className="flex items-center gap-1 bg-gray-100 p-1 rounded-md">
            <button
              onClick={handlePanLeft}
              className="p-1.5 bg-white hover:bg-gray-50 border border-gray-300 rounded transition-all duration-200 hover:border-gray-400"
              title={t('crossChain.panLeft')}
            >
              <svg
                className="w-4 h-4 text-gray-600"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M15 19l-7-7 7-7"
                />
              </svg>
            </button>
            <button
              onClick={handlePanRight}
              className="p-1.5 bg-white hover:bg-gray-50 border border-gray-300 rounded transition-all duration-200 hover:border-gray-400"
              title={t('crossChain.panRight')}
            >
              <svg
                className="w-4 h-4 text-gray-600"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M9 5l7 7-7 7"
                />
              </svg>
            </button>
          </div>

          {/* Reference Line Controls */}
          <div className="flex items-center gap-1">
            <button
              onClick={() => addReferenceLine('current')}
              className="px-2 py-1.5 text-xs bg-blue-50 text-blue-700 hover:bg-blue-100 border border-blue-200 rounded transition-all duration-200"
            >
              {t('crossChain.currentPrice')}
            </button>
            <button
              onClick={() => addReferenceLine('avg')}
              className="px-2 py-1.5 text-xs bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 rounded transition-all duration-200"
            >
              {t('crossChain.averagePrice')}
            </button>
            <button
              onClick={() => addReferenceLine('median')}
              className="px-2 py-1.5 text-xs bg-amber-50 text-amber-700 hover:bg-amber-100 border border-amber-200 rounded transition-all duration-200"
            >
              {t('crossChain.medianPrice')}
            </button>
            {referenceLines.length > 0 && (
              <button
                onClick={clearAllReferenceLines}
                className="px-2 py-1.5 text-xs bg-red-50 text-red-700 hover:bg-red-100 border border-red-200 rounded transition-all duration-200"
              >
                {t('crossChain.clearAll')}
              </button>
            )}
          </div>

          {/* View Range Info */}
          <div className="text-xs text-gray-500 px-2">
            {viewState.startIndex + 1} - {viewState.endIndex + 1} / {chartData.length}
          </div>
        </div>
      </div>

      {/* Reference Lines List */}
      {referenceLines.length > 0 && (
        <div className="flex items-center gap-2 mb-2 flex-wrap">
          <span className="text-xs text-gray-500">{t('crossChain.referenceLines')}:</span>
          {referenceLines.map((line) => (
            <div
              key={line.id}
              className="flex items-center gap-1 px-2 py-1 bg-gray-50 border border-gray-200 rounded text-xs"
            >
              <span className="w-2 h-0.5 rounded-full" style={{ backgroundColor: line.color }} />
              <span className="text-gray-600">{line.label}:</span>
              <span className="font-mono text-gray-800">${line.y.toFixed(4)}</span>
              <button
                onClick={() => removeReferenceLine(line.id)}
                className="ml-1 text-gray-400 hover:text-red-500 transition-colors"
              >
                ×
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Chart Container */}
      <div
        ref={containerRef}
        className="h-80 relative select-none bg-white border border-gray-200 rounded-lg p-2"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        role="img"
        aria-label={t('crossChain.priceChart')}
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === 'ArrowLeft') {
            handlePanLeft();
          } else if (e.key === 'ArrowRight') {
            handlePanRight();
          } else if (e.key === '+' || e.key === '=') {
            handleZoomIn();
          } else if (e.key === '-') {
            handleZoomOut();
          } else if (e.key === 'Home') {
            handleResetZoom();
          }
        }}
      >
        <div className="sr-only">
          {t('crossChain.priceChart')} - {t('crossChain.shortcuts')}: Arrow keys to pan, +/- to
          zoom, Home to reset
        </div>
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart data={visibleData} margin={{ top: 10, right: 30, left: 10, bottom: 10 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
            <XAxis dataKey="time" stroke="#9ca3af" tick={{ fill: '#6b7280', fontSize: 11 }} />
            <YAxis
              domain={priceDomain}
              tickFormatter={(v) => `$${Number(v).toLocaleString()}`}
              width={70}
              stroke="#9ca3af"
              tick={{ fill: '#6b7280', fontSize: 11 }}
            />
            <RechartsTooltip content={renderTooltip} />
            <Legend
              onClick={(data: unknown) => {
                const legendData = data as {
                  dataKey: string;
                  color: string;
                  type: string;
                  value: string;
                };
                onLegendClick(legendData);
              }}
            />

            {filteredChains.map((chain) => (
              <Line
                key={chain}
                type="monotone"
                dataKey={chain}
                name={chainNames[chain]}
                stroke={chainColors[chain]}
                strokeWidth={2}
                dot={false}
                hide={hiddenLines.has(chain)}
              />
            ))}

            {scatterData.length > 0 && (
              <Scatter
                data={scatterData.filter((d) => {
                  const index = chartData.findIndex((cd) => cd.timestamp === d.timestamp);
                  return index >= viewState.startIndex && index <= viewState.endIndex;
                })}
                fill={semanticColors.warning.dark}
                name={t('crossChain.anomalyPoint')}
              />
            )}

            {/* Reference Lines */}
            {referenceLines.map((line) => (
              <ReferenceLine
                key={line.id}
                y={line.y}
                stroke={line.color}
                strokeDasharray={line.strokeDasharray}
                label={{
                  value: `${line.label}: $${line.y.toFixed(2)}`,
                  fill: line.color,
                  fontSize: 11,
                }}
              />
            ))}
          </ComposedChart>
        </ResponsiveContainer>

        {/* Selection Box Overlay */}
        {showSelectionBox && (
          <div
            className="absolute border-2 border-blue-500 bg-blue-500/10 pointer-events-none rounded"
            style={selectionBoxStyle}
          />
        )}
      </div>

      {/* Keyboard Shortcuts Hint */}
      <div className="mt-2 text-xs text-gray-400 flex items-center gap-4 flex-wrap">
        <span>{t('crossChain.shortcuts')}:</span>
        <span>
          Ctrl + {t('crossChain.scroll')}: {t('crossChain.zoom')}
        </span>
        <span>← →: {t('crossChain.pan')}</span>
        <span>Home: {t('crossChain.reset')}</span>
        <span>
          {t('crossChain.dragSelect')}: {t('crossChain.zoomToArea')}
        </span>
      </div>
    </div>
  );
}

export default InteractivePriceChart;

'use client';

import { DataTablePro, type ColumnDef, type ConditionalFormattingRule } from '@/components/ui';
import { useTranslations } from '@/i18n';
import { type Blockchain } from '@/lib/oracles';
import { isBlockchain } from '@/lib/utils/chainUtils';

import { type useCrossChainData } from '../useCrossChainData';
import { chainNames, chainColors, getDiffTextColor, calculateZScore, isOutlier } from '../utils';

interface PriceComparisonTableProps {
  data: ReturnType<typeof useCrossChainData>;
}

interface TableRow extends Record<string, unknown> {
  chain: Blockchain;
  price: number;
  diff: number;
  diffPercent: number;
  isOutlier: boolean;
  zScore: number | null;
  priceHistory: number[];
}

export function PriceComparisonTable({ data }: PriceComparisonTableProps) {
  const t = useTranslations();
  const {
    sortedPriceDifferences,
    selectedBaseChain,
    historicalPrices,
    avgPrice,
    standardDeviation,
    tableFilter,
    setTableFilter,
  } = data;

  // Transform data for DataTablePro
  const tableData: TableRow[] = sortedPriceDifferences.map((item) => {
    const zScore = calculateZScore(item.price, avgPrice, standardDeviation);
    const chainHistoricalPrices = isBlockchain(item.chain)
      ? historicalPrices[item.chain]
      : undefined;
    const priceHistory = chainHistoricalPrices?.map((p) => p.price) ?? [];

    return {
      chain: item.chain,
      price: item.price,
      diff: item.diff,
      diffPercent: item.diffPercent,
      isOutlier: isOutlier(zScore),
      zScore,
      priceHistory,
    };
  });

  // Conditional formatting rules for price differences
  const conditionalFormatting = [
    {
      field: 'diffPercent',
      rules: [
        {
          condition: 'gt' as const,
          value: 0.5,
          style: 'danger' as const,
        },
        {
          condition: 'lt' as const,
          value: -0.5,
          style: 'success' as const,
        },
      ] as ConditionalFormattingRule[],
    },
  ];

  // Define columns using ColumnDef interface
  const columns: ColumnDef<TableRow>[] = [
    {
      key: 'chain',
      header: t('crossChain.blockchain'),
      width: 160,
      minWidth: 140,
      fixed: 'left',
      sortable: true,
      formatter: (_value: unknown, row: TableRow) => {
        const chain = row.chain;
        const chainName = chainNames[chain];
        const color = chainColors[chain];

        return (
          <div className="flex items-center gap-2">
            <div
              className="w-2.5 h-2.5 rounded-sm flex-shrink-0"
              style={{ backgroundColor: color }}
            />
            <span className="text-sm font-medium text-gray-900 truncate">{chainName}</span>
            {row.isOutlier && (
              <span className="flex-shrink-0 text-amber-700 text-xs font-medium bg-amber-100 px-1.5 py-0.5 rounded">
                {t('crossChain.outlier')}
              </span>
            )}
          </div>
        );
      },
    },
    {
      key: 'price',
      header: t('crossChain.price'),
      width: 130,
      minWidth: 110,
      fixed: 'left',
      align: 'right',
      sortable: true,
      formatter: (value: unknown) => {
        const price = value as number;
        return (
          <span className="font-mono text-sm text-gray-900">
            $
            {price.toLocaleString(undefined, {
              minimumFractionDigits: 2,
              maximumFractionDigits: 4,
            })}
          </span>
        );
      },
    },
    {
      key: 'diff',
      header: t('crossChain.differenceVs', {
        chain: selectedBaseChain ? chainNames[selectedBaseChain] : '-',
      }),
      width: 130,
      minWidth: 110,
      align: 'right',
      sortable: true,
      formatter: (value: unknown, row: TableRow) => {
        const diff = value as number;
        const isPositive = diff >= 0;
        const isSignificant = Math.abs(row.diffPercent) > 0.5;

        return (
          <span
            className={`font-mono text-sm ${
              isSignificant
                ? isPositive
                  ? 'text-red-600 font-semibold'
                  : 'text-emerald-600 font-semibold'
                : isPositive
                  ? 'text-red-600'
                  : 'text-emerald-600'
            }`}
          >
            {isPositive ? '+' : ''}${diff.toFixed(4)}
          </span>
        );
      },
    },
    {
      key: 'diffPercent',
      header: t('crossChain.percentDifference'),
      width: 130,
      minWidth: 110,
      align: 'right',
      sortable: true,
      formatter: (value: unknown, row: TableRow) => {
        const diffPercent = value as number;
        const isSignificant = Math.abs(diffPercent) > 0.5;

        return (
          <span
            className={`font-mono text-sm ${
              isSignificant ? 'font-semibold' : ''
            } ${diffPercent > 0 ? 'text-red-600' : 'text-emerald-600'}`}
          >
            {diffPercent >= 0 ? '+' : ''}
            {diffPercent.toFixed(4)}%
          </span>
        );
      },
      conditionalFormat: {
        rules: [
          {
            condition: 'gt',
            value: 0.5,
            style: 'danger',
          },
          {
            condition: 'lt',
            value: -0.5,
            style: 'success',
          },
        ],
      },
    },
    {
      key: 'zScore',
      header: t('crossChain.zScore'),
      width: 100,
      minWidth: 80,
      align: 'right',
      sortable: true,
      formatter: (value: unknown, row: TableRow) => {
        const zScore = value as number | null;
        if (zScore === null) return <span className="text-gray-400">-</span>;

        const isSignificant = Math.abs(zScore) > 2;
        return (
          <span
            className={`font-mono text-sm ${
              isSignificant ? 'text-amber-600 font-semibold' : 'text-gray-600'
            }`}
          >
            {zScore.toFixed(2)}
          </span>
        );
      },
    },
    {
      key: 'trend',
      header: t('crossChain.trend'),
      width: 80,
      minWidth: 60,
      align: 'center',
      sortable: false,
      formatter: (_value: unknown, row: TableRow) => {
        const chain = row.chain;
        const color = chainColors[chain];
        const prices = row.priceHistory;

        if (!prices || prices.length < 2) {
          return <span className="text-gray-300">-</span>;
        }

        // 简单的趋势指示
        const firstPrice = prices[0];
        const lastPrice = prices[prices.length - 1];
        const trend = lastPrice > firstPrice ? 'up' : lastPrice < firstPrice ? 'down' : 'neutral';

        return (
          <div className="flex items-center justify-center">
            <span
              className={`text-lg ${
                trend === 'up'
                  ? 'text-emerald-500'
                  : trend === 'down'
                    ? 'text-red-500'
                    : 'text-gray-400'
              }`}
            >
              {trend === 'up' ? '↗' : trend === 'down' ? '↘' : '→'}
            </span>
          </div>
        );
      },
    },
  ];

  // Fixed columns configuration
  const fixedColumns = {
    left: ['chain', 'price'],
  };

  return (
    <div className="mb-6 pb-6 border-b border-gray-200">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-4">
        <h3 className="text-sm font-semibold text-gray-900 uppercase tracking-wide">
          {t('crossChain.priceComparisonTable')}
        </h3>
        <div className="flex items-center gap-2 flex-wrap">
          <span className="text-xs text-gray-500">{t('crossChain.filter')}:</span>
          {(['all', 'abnormal', 'normal'] as const).map((filter) => (
            <button
              key={filter}
              onClick={() => setTableFilter(filter)}
              className={`px-3 py-1 text-xs font-medium transition-all duration-200 rounded-md ${
                tableFilter === filter
                  ? filter === 'abnormal'
                    ? 'bg-red-100 text-red-700 border border-red-200'
                    : filter === 'normal'
                      ? 'bg-emerald-100 text-emerald-700 border border-emerald-200'
                      : 'bg-blue-100 text-blue-700 border border-blue-200'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200 border border-transparent'
              }`}
            >
              {t(`crossChain.filter${filter.charAt(0).toUpperCase() + filter.slice(1)}`)}
            </button>
          ))}
        </div>
      </div>

      <DataTablePro<TableRow>
        data={tableData}
        columns={columns}
        fixedColumns={fixedColumns}
        conditionalFormatting={conditionalFormatting}
        density="normal"
        maxHeight={400}
        emptyText={t('crossChain.noData')}
      />
    </div>
  );
}

export default PriceComparisonTable;

'use client';

import { useState, useMemo } from 'react';

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  ResponsiveContainer,
  Area,
  ComposedChart,
  Legend,
  ReferenceLine,
} from 'recharts';

import { DropdownSelect } from '@/components/ui';
import { useTranslations } from '@/i18n';
import { chartColors, semanticColors } from '@/lib/config/colors';
import { isBlockchain } from '@/lib/utils/chainUtils';
import { type Blockchain } from '@/types/oracle';

import { type useCrossChainData } from '../useCrossChainData';
import {
  chainNames,
  chainColors,
  calculateRollingVolatility,
  calculateVolatilityCone,
  calculatePearsonCorrelation,
  type RollingVolatilityPoint,
  type VolatilityConePoint,
} from '../utils';

interface VolatilitySurfaceProps {
  data: ReturnType<typeof useCrossChainData>;
}

const VOLATILITY_WINDOW_SIZES = [
  { value: 20, label: '20' },
  { value: 50, label: '50' },
  { value: 100, label: '100' },
];

interface VolatilityChartDataPoint {
  index: number;
  time: string;
  [key: string]: number | string;
}

interface VolatilityCorrelationData {
  chainX: Blockchain;
  chainY: Blockchain;
  correlation: number;
}

export function VolatilitySurface({ data }: VolatilitySurfaceProps) {
  const t = useTranslations();
  const { filteredChains, chartData, historicalPrices } = data;
  const [volatilityWindowSize, setVolatilityWindowSize] = useState(50);
  const [hiddenLines, setHiddenLines] = useState<Set<string>>(new Set());
  const [selectedConeChain, setSelectedConeChain] = useState<Blockchain | null>(null);

  // 计算各链的滚动波动率
  const rollingVolatilityData = useMemo(() => {
    if (chartData.length === 0) return [];

    const chainVolatilities: Partial<Record<Blockchain, RollingVolatilityPoint[]>> = {};

    filteredChains.forEach((chain) => {
      const prices = chartData
        .map((point) => point[chain] as number | undefined)
        .filter((p): p is number => p !== undefined && !isNaN(p) && p > 0);

      if (prices.length >= volatilityWindowSize) {
        chainVolatilities[chain] = calculateRollingVolatility(prices, volatilityWindowSize);
      }
    });

    // 找到最大长度
    const maxLength = Math.max(
      ...Object.values(chainVolatilities).map((arr) => arr?.length || 0),
      0
    );

    // 构建图表数据点
    const dataPoints: VolatilityChartDataPoint[] = [];
    for (let i = 0; i < maxLength; i++) {
      const chartPoint = chartData[i + volatilityWindowSize];
      const point: VolatilityChartDataPoint = {
        index: i,
        time: chartPoint?.time || `#${i}`,
      };

      filteredChains.forEach((chain) => {
        const volatilities = chainVolatilities[chain];
        if (volatilities && volatilities[i]) {
          point[chain] = volatilities[i].volatility;
        }
      });

      dataPoints.push(point);
    }

    return dataPoints;
  }, [chartData, filteredChains, volatilityWindowSize]);

  // 计算波动率相关性矩阵
  const volatilityCorrelationMatrix = useMemo(() => {
    const correlations: VolatilityCorrelationData[] = [];

    // 获取各链的波动率序列
    const chainVolatilitySeries: Partial<Record<Blockchain, number[]>> = {};
    filteredChains.forEach((chain) => {
      const prices = chartData
        .map((point) => point[chain] as number | undefined)
        .filter((p): p is number => p !== undefined && !isNaN(p) && p > 0);

      if (prices.length >= volatilityWindowSize) {
        const vols = calculateRollingVolatility(prices, volatilityWindowSize);
        chainVolatilitySeries[chain] = vols.map((v) => v.volatility);
      }
    });

    // 计算两两相关性
    for (let i = 0; i < filteredChains.length; i++) {
      for (let j = i + 1; j < filteredChains.length; j++) {
        const chainX = filteredChains[i];
        const chainY = filteredChains[j];
        const volsX = chainVolatilitySeries[chainX] || [];
        const volsY = chainVolatilitySeries[chainY] || [];

        if (volsX.length > 0 && volsY.length > 0) {
          const correlation = calculatePearsonCorrelation(volsX, volsY);
          correlations.push({
            chainX,
            chainY,
            correlation: isNaN(correlation) ? 0 : correlation,
          });
        }
      }
    }

    return correlations;
  }, [chartData, filteredChains, volatilityWindowSize]);

  // 计算波动率锥数据
  const volatilityConeData = useMemo(() => {
    const targetChain = selectedConeChain || filteredChains[0];
    if (!targetChain) return [];

    const prices = historicalPrices[targetChain]?.map((p) => p.price) || [];
    if (prices.length < 50) return [];

    return calculateVolatilityCone(prices, [10, 20, 30, 50, 100]);
  }, [historicalPrices, filteredChains, selectedConeChain]);

  // 获取波动率颜色
  const getVolatilityLevelColor = (volatility: number): string => {
    if (volatility < 30) return semanticColors.success.DEFAULT;
    if (volatility < 60) return semanticColors.warning.DEFAULT;
    return semanticColors.danger.DEFAULT;
  };

  const getCorrelationColor = (correlation: number): string => {
    const absCorr = Math.abs(correlation);
    if (absCorr >= 0.7) return chartColors.recharts.primary;
    if (absCorr >= 0.4) return chartColors.recharts.primaryLight;
    if (absCorr >= 0.2) return chartColors.semantic.neutral;
    return chartColors.recharts.grid;
  };

  const handleLegendClick = (e: unknown) => {
    const dataKey = (e as { dataKey?: string | number })?.dataKey;
    if (typeof dataKey === 'string') {
      const newSet = new Set(hiddenLines);
      if (newSet.has(dataKey)) newSet.delete(dataKey);
      else newSet.add(dataKey);
      setHiddenLines(newSet);
    }
  };

  const VolatilityTooltip = ({
    active,
    payload,
    label,
  }: {
    active?: boolean;
    payload?: Array<{ dataKey: string; value: number; color: string }>;
    label?: string | number;
  }) => {
    if (!active || !payload || payload.length === 0) return null;

    const validPayload = payload.filter(
      (p) =>
        p.value !== undefined &&
        !isNaN(p.value) &&
        isBlockchain(p.dataKey) &&
        filteredChains.includes(p.dataKey)
    );
    if (validPayload.length === 0) return null;

    // 按波动率排序
    const sortedPayload = [...validPayload].sort((a, b) => (b.value || 0) - (a.value || 0));

    return (
      <div className="bg-white border border-gray-200 p-3 min-w-[220px]">
        <p className="text-gray-600 text-xs mb-2 font-medium border-b border-gray-100 pb-1">
          {typeof label === 'string'
            ? label
            : t('crossChain.dataPointLabel', { index: label ?? 0 })}
        </p>
        {sortedPayload.map((entry, index: number) => {
          const chain = entry.dataKey;
          if (!isBlockchain(chain)) return null;
          const volatility = entry.value || 0;
          const level =
            volatility < 30
              ? t('crossChain.lowVolatility')
              : volatility < 60
                ? t('crossChain.mediumVolatility')
                : t('crossChain.highVolatility');
          return (
            <div key={index} className="mb-1.5 pb-1.5 border-b border-gray-100 last:border-0">
              <div className="flex items-center gap-2">
                <span className="w-3 h-3" style={{ backgroundColor: entry.color }} />
                <span className="text-xs text-gray-700">{chainNames[chain]}</span>
              </div>
              <div className="text-xs pl-5 font-mono flex items-center gap-2">
                <span
                  className="font-semibold"
                  style={{ color: getVolatilityLevelColor(volatility) }}
                >
                  {volatility.toFixed(2)}%
                </span>
                <span className="text-gray-400">({level})</span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const ConeTooltip = ({
    active,
    payload,
  }: {
    active?: boolean;
    payload?: ReadonlyArray<{
      dataKey: string;
      value: number;
      color?: string;
      payload?: VolatilityConePoint;
    }>;
  }) => {
    if (!active || !payload || payload.length === 0) return null;

    const data = payload[0]?.payload;
    if (!data) return null;

    return (
      <div className="bg-white border border-gray-200 p-3 min-w-[180px]">
        <p className="text-gray-600 text-xs mb-2 font-medium border-b border-gray-100 pb-1">
          {t('crossChain.windowSize')}: {data.windowSize}
        </p>
        <div className="space-y-1 text-xs">
          <div className="flex justify-between">
            <span className="text-gray-500">{t('crossChain.maxValue')}:</span>
            <span className="font-mono text-danger-600">{data.maxVolatility.toFixed(2)}%</span>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-500">{t('crossChain.p90')}:</span>
            <span className="font-mono">{data.p90.toFixed(2)}%</span>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-500">{t('crossChain.p75')}:</span>
            <span className="font-mono">{data.p75.toFixed(2)}%</span>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-500">{t('crossChain.median')}:</span>
            <span className="font-mono font-semibold">{data.medianVolatility.toFixed(2)}%</span>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-500">{t('crossChain.mean')}:</span>
            <span className="font-mono">{data.meanVolatility.toFixed(2)}%</span>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-500">{t('crossChain.p25')}:</span>
            <span className="font-mono">{data.p25.toFixed(2)}%</span>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-500">{t('crossChain.p10')}:</span>
            <span className="font-mono">{data.p10.toFixed(2)}%</span>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-500">{t('crossChain.minValue')}:</span>
            <span className="font-mono text-success-600">{data.minVolatility.toFixed(2)}%</span>
          </div>
        </div>
      </div>
    );
  };

  if (filteredChains.length === 0) {
    return null;
  }

  return (
    <div className="space-y-8">
      {/* 滚动波动率时序图 */}
      <div className="mb-8 pb-8 border-b border-gray-200">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h3 className="text-sm font-medium text-gray-900 uppercase tracking-wide">
              {t('crossChain.rollingVolatility')}
            </h3>
            <p className="text-xs text-gray-500 mt-1">
              {t('crossChain.windowSize')}: {volatilityWindowSize}
            </p>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-xs text-gray-500">{t('crossChain.windowSize')}:</span>
            <div className="flex items-center gap-1 border border-gray-200">
              {VOLATILITY_WINDOW_SIZES.map((option) => (
                <button
                  key={option.value}
                  onClick={() => setVolatilityWindowSize(option.value)}
                  className={`px-3 py-1 text-xs transition-colors ${
                    volatilityWindowSize === option.value
                      ? 'bg-gray-900 text-white'
                      : 'text-gray-600 hover:border-gray-300 border border-transparent'
                  }`}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="bg-gray-50 p-4 border border-gray-200">
          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart
                data={rollingVolatilityData}
                margin={{ top: 10, right: 30, left: 10, bottom: 10 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke={chartColors.recharts.grid} />
                <XAxis
                  dataKey="time"
                  tick={{ fontSize: 10 }}
                  angle={-45}
                  textAnchor="end"
                  height={60}
                />
                <YAxis
                  tick={{ fontSize: 11 }}
                  tickFormatter={(value) => `${value.toFixed(0)}%`}
                  width={50}
                  label={{
                    value: t('crossChain.annualizedVolatility'),
                    angle: -90,
                    position: 'insideLeft',
                    fontSize: 12,
                  }}
                />
                <RechartsTooltip content={<VolatilityTooltip />} />
                <Legend onClick={handleLegendClick} />

                <ReferenceLine
                  y={30}
                  stroke={semanticColors.success.DEFAULT}
                  strokeDasharray="5 5"
                  strokeOpacity={0.5}
                />
                <ReferenceLine
                  y={60}
                  stroke={semanticColors.warning.DEFAULT}
                  strokeDasharray="5 5"
                  strokeOpacity={0.5}
                />

                {filteredChains.map((chain) => (
                  <Line
                    key={chain}
                    type="monotone"
                    dataKey={chain}
                    name={chainNames[chain]}
                    stroke={chainColors[chain]}
                    strokeWidth={2}
                    dot={false}
                    hide={hiddenLines.has(chain)}
                    strokeOpacity={0.8}
                    activeDot={{ r: 4, strokeWidth: 0 }}
                  />
                ))}
              </LineChart>
            </ResponsiveContainer>
          </div>

          {/* 波动率水平说明 */}
          <div className="mt-4 flex items-center justify-center gap-6 text-xs">
            <div className="flex items-center gap-2">
              <div className="w-6 h-0.5 bg-success-500" />
              <span className="text-gray-600">&lt; 30% ({t('crossChain.lowVolatility')})</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-6 h-0.5 bg-warning-500" />
              <span className="text-gray-600">30% - 60% ({t('crossChain.mediumVolatility')})</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-6 h-0.5 bg-danger-500" />
              <span className="text-gray-600">&gt; 60% ({t('crossChain.highVolatility')})</span>
            </div>
          </div>
        </div>
      </div>

      {/* 波动率相关性矩阵 */}
      <div className="mb-8 pb-8 border-b border-gray-200">
        <h3 className="text-sm font-medium text-gray-900 uppercase tracking-wide mb-4">
          {t('crossChain.volatilityCorrelationMatrix')}
        </h3>
        <p className="text-xs text-gray-500 mb-4">{t('crossChain.volatilityCorrelationMatrix')}</p>

        <div className="overflow-x-auto">
          <div className="min-w-full">
            <div className="flex">
              <div className="w-24 shrink-0" />
              {filteredChains.map((chain) => (
                <div key={chain} className="flex-1 min-w-20 text-center px-1 py-2">
                  <span className="text-xs font-medium text-gray-600">{chainNames[chain]}</span>
                </div>
              ))}
            </div>
            {filteredChains.map((chainX) => (
              <div key={chainX} className="flex">
                <div className="w-24 shrink-0 flex items-center py-1">
                  <span className="text-xs font-medium text-gray-600">{chainNames[chainX]}</span>
                </div>
                {filteredChains.map((chainY) => {
                  if (chainX === chainY) {
                    return (
                      <div
                        key={`${chainX}-${chainY}`}
                        className="flex-1 min-w-20 h-12 flex items-center justify-center px-0.5 bg-gray-100"
                      >
                        <span className="text-xs font-medium text-gray-400">-</span>
                      </div>
                    );
                  }

                  const correlationData = volatilityCorrelationMatrix.find(
                    (c) =>
                      (c.chainX === chainX && c.chainY === chainY) ||
                      (c.chainX === chainY && c.chainY === chainX)
                  );
                  const correlation = correlationData?.correlation ?? 0;
                  const bgColor = getCorrelationColor(correlation);
                  const textColor = Math.abs(correlation) > 0.4 ? 'text-white' : 'text-gray-900';

                  return (
                    <div
                      key={`${chainX}-${chainY}`}
                      className="flex-1 min-w-20 h-12 flex items-center justify-center px-0.5 cursor-pointer transition-transform hover:scale-105"
                      style={{ backgroundColor: bgColor }}
                      title={`${chainNames[chainX]} vs ${chainNames[chainY]}: r = ${correlation.toFixed(4)}`}
                    >
                      <span className={`text-xs font-medium ${textColor}`}>
                        {correlation.toFixed(2)}
                      </span>
                    </div>
                  );
                })}
              </div>
            ))}
            <div className="mt-4 flex items-center justify-center gap-4">
              <div className="flex items-center gap-2">
                <span className="text-xs text-gray-500">
                  {t('crossChain.correlationStrength')}:
                </span>
                <div
                  className="w-32 h-3"
                  style={{
                    background: `linear-gradient(to right, ${chartColors.recharts.grid}, ${chartColors.semantic.neutral}, ${chartColors.recharts.primaryLight}, ${chartColors.recharts.primary})`,
                  }}
                />
                <span className="text-xs text-gray-500">{t('crossChain.weakToStrong')}</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 波动率锥分析 */}
      <div className="mb-8 pb-8 border-b border-gray-200">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h3 className="text-sm font-medium text-gray-900 uppercase tracking-wide">
              {t('crossChain.volatilityConeAnalysis')}
            </h3>
            <p className="text-xs text-gray-500 mt-1">{t('crossChain.volatilityConeDesc')}</p>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-gray-500">{t('crossChain.selectChain')}:</span>
            <DropdownSelect<Blockchain | ''>
              options={filteredChains.map((chain) => ({
                value: chain,
                label: chainNames[chain],
              }))}
