          historicalPrices[chainX]?.map((p) => ({ timestamp: p.timestamp, price: p.price })) || [];
        const dataY: TimestampedPrice[] =
          historicalPrices[chainY]?.map((p) => ({ timestamp: p.timestamp, price: p.price })) || [];

        if (chainX === chainY) {
          matrix[chainX]![chainY] = 1;
