export function ComparisonTabs(props: ComparisonTabsProps) {
  const {
    activeTab,
    onTabChange,
    // OverviewTab props
    selectedSymbol,
    selectedOracles,
    priceData,
    filteredPriceData,
    isLoading,
    timeRange,
    zoomLevel,
    hoveredOracle,
    setHoveredOracle,
    setOracleFilter,
    setIsChartFullscreen,
    chartContainerRef,
    sortColumn,
    sortDirection,
    expandedRow,
    setExpandedRow,
    selectedRowIndex,
    hoveredRowIndex,
