            setOracleFilter={setOracleFilter}
            setIsChartFullscreen={setIsChartFullscreen}
            chartContainerRef={chartContainerRef}
            sortColumn={sortColumn}
            sortDirection={sortDirection}
            expandedRow={expandedRow}
