            setSelectedRowIndex={setSelectedRowIndex}
            avgPrice={avgPrice}
            weightedAvgPrice={weightedAvgPrice}
            maxPrice={maxPrice}
            minPrice={minPrice}
            priceRange={priceRange}
            standardDeviation={standardDeviation}
            standardDeviationPercent={standardDeviationPercent}
            variance={variance}
