  timeRange,
  zoomLevel,
  hoveredOracle,
  setHoveredOracle,
  setOracleFilter,
  setIsChartFullscreen,
  chartContainerRef,
  sortColumn,
  sortDirection,
  expandedRow,
  setExpandedRow,
  selectedRowIndex,
  hoveredRowIndex,
  setHoveredRowIndex,
  setSelectedRowIndex,
  avgPrice,
  weightedAvgPrice,
  maxPrice,
  minPrice,
  priceRange,
  standardDeviation,
  standardDeviationPercent,
  variance,
  validPrices,
  lastStats,
  historyMinMax,
  oracleChartColors,
  getChartData,
  qualityScoreData,
  handleSort,
  handleZoomIn,
  handleZoomOut,
  handleResetZoom,
  setTimeRange,
