'use client';

import { useState, useCallback, useEffect, useMemo } from 'react';

import { useRefresh, useExport, useDIAAllData } from '@/hooks';
import { useTranslations } from '@/i18n';
import { getOracleConfig } from '@/lib/config/oracles';
import { OracleProvider } from '@/types/oracle';

import { type DIATabId } from '../types';

export function useDIAPage() {
  const t = useTranslations();
  const [activeTab, setActiveTab] = useState<DIATabId>('market');
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);

  const config = useMemo(() => getOracleConfig(OracleProvider.DIA), []);

  const { price, historicalData, networkStats, isLoading, isError, errors, refetchAll } =
    useDIAAllData({
      symbol: config.symbol,
      chain: config.defaultChain,
      enabled: true,
    });

  // Update lastUpdated when price changes
  useEffect(() => {
    if (price) {
      setLastUpdated(new Date());
    }
  }, [price]);

  const { exportData } = useExport({
    data: {
      timestamp: new Date().toISOString(),
      price,
      historical: historicalData,
      network: networkStats,
    },
    filename: 'dia-data',
  });

  const { isRefreshing, refresh } = useRefresh({
    onRefresh: async () => {
      await refetchAll();
    },
    minLoadingTime: 500,
  });

  const handleTabChange = useCallback((tab: DIATabId) => {
    setActiveTab(tab);
  }, []);

  return {
    activeTab,
    config,
    price,
    historicalData,
    networkStats,
    isLoading,
    isError,
    error: errors[0] || null,
    lastUpdated,
    isRefreshing,

    setActiveTab: handleTabChange,
    refresh,
    exportData,
    t,
  };
}

'use client';

import { useState } from 'react';

import {
  LoadingState,
  ErrorFallback,
  MobileMenuButton,
  OracleErrorBoundary,
} from '@/components/oracle';
import { MobileSidebar } from '@/components/ui/MobileSidebar';
import { useTranslations } from '@/i18n';

import {
  DIASidebar,
  DIAMarketView,
  DIANetworkView,
  DIADataFeedsView,
  DIANFTView,
  DIAStakingView,
  DIAEcosystemView,
  DIARiskView,
  DIAHero,
} from './components';
import { useDIAPage } from './hooks/useDIAPage';
import { type DIATabId } from './types';

export default function DIAPage() {
  const {
    activeTab,
    config,
    price,
    historicalData,
    networkStats,
    isLoading,
    isError,
    error,
    lastUpdated,
    isRefreshing,

    setActiveTab,
    refresh,
    exportData,
    t,
  } = useDIAPage();

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const isInitialLoading = isLoading && !price && !historicalData.length && !networkStats;
  const hasCriticalError = isError && !price && error;

  if (isInitialLoading) {
    return <LoadingState themeColor={config.themeColor} />;
  }

  if (hasCriticalError) {
    return <ErrorFallback error={error} onRetry={refresh} themeColor={config.themeColor} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'market':
        return (
          <DIAMarketView
            config={config}
            price={price}
            historicalData={historicalData}
            isLoading={isLoading}
          />
        );
      case 'network':
        return <DIANetworkView config={config} networkStats={networkStats} isLoading={isLoading} />;
      case 'data-feeds':
        return <DIADataFeedsView />;
      case 'nft-data':
        return <DIANFTView />;
      case 'staking':
        return <DIAStakingView />;
      case 'ecosystem':
        return <DIAEcosystemView />;
      case 'risk':
        return <DIARiskView />;
      default:
        return null;
    }
  };

  return (
    <OracleErrorBoundary themeColor={config.themeColor} onReset={refresh}>
      <div className="min-h-screen bg-insight">
        <DIAHero
          config={config}
          price={price ?? null}
          historicalData={historicalData}
          networkStats={networkStats}
          isLoading={isLoading}
          isError={isError}
          isRefreshing={isRefreshing}
          lastUpdated={lastUpdated}
          onRefresh={refresh}
          onExport={exportData}
        />

        <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex flex-col lg:flex-row gap-6">
            <div className="hidden lg:block w-64 flex-shrink-0">
              <div className="sticky top-6">
                <DIASidebar
                  activeTab={activeTab}
                  onTabChange={(tab) => setActiveTab(tab as DIATabId)}
                />
              </div>
            </div>

            <div className="lg:hidden">
              <MobileMenuButton
                isOpen={isMobileMenuOpen}
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                themeColor={config.themeColor}
                label={t('dia.menu.title')}
              />
            </div>

            <MobileSidebar
              isOpen={isMobileMenuOpen}
              onClose={() => setIsMobileMenuOpen(false)}
              title={t('dia.navigation.title')}
            >
              <DIASidebar
                activeTab={activeTab}
                onTabChange={(tab) => {
                  setActiveTab(tab as DIATabId);
                  setIsMobileMenuOpen(false);
                }}
              />
            </MobileSidebar>

            <div className="flex-1 min-w-0">{renderContent()}</div>
          </div>
        </div>
      </div>
    </OracleErrorBoundary>
  );
}

'use client';

import { useState, useEffect } from 'react';

import { Rocket, Layers, Code, Wrench, ChevronRight, Menu, X } from 'lucide-react';

import { useTranslations } from '@/i18n';

interface NavItem {
  id: string;
  label: string;
  icon: React.ReactNode;
}

export default function DocsNavigation() {
  const t = useTranslations();
  const [activeSection, setActiveSection] = useState('quickstart');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems: NavItem[] = [
    {
      id: 'quickstart',
      label: t('docs.nav.quickstart'),
      icon: <Rocket className="w-4 h-4" />,
    },
    {
      id: 'features',
      label: t('docs.nav.features'),
      icon: <Layers className="w-4 h-4" />,
    },
    {
      id: 'technical',
      label: t('docs.nav.technical'),
      icon: <Code className="w-4 h-4" />,
    },
    {
      id: 'developer',
      label: t('docs.nav.developer'),
      icon: <Wrench className="w-4 h-4" />,
    },
  ];

  useEffect(() => {
    const handleScroll = () => {
      const sections = navItems.map((item) => ({
        id: item.id,
        element: document.getElementById(item.id),
      }));

      const scrollPosition = window.scrollY + 200;

      for (let i = sections.length - 1; i >= 0; i--) {
        const section = sections[i];
        if (section.element) {
          const offsetTop = section.element.offsetTop;
          if (scrollPosition >= offsetTop) {
            setActiveSection(section.id);
            break;
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [navItems]);

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const offsetTop = element.offsetTop - 100;
      window.scrollTo({
        top: offsetTop,
        behavior: 'smooth',
      });
      setActiveSection(id);
      setIsMobileMenuOpen(false);
    }
  };

