'use client';

import { useEffect, useState } from 'react';

interface LineConfig {
  id: number;
  top: string;
  duration: number;
  delay: number;
  opacity: number;
  blur: number;
}

const linesConfig: LineConfig[] = [
  { id: 1, top: '10%', duration: 25, delay: 0, opacity: 0.2, blur: 2 },
  { id: 2, top: '20%', duration: 35, delay: 2, opacity: 0.15, blur: 3 },
  { id: 3, top: '30%', duration: 20, delay: 4, opacity: 0.25, blur: 1 },
  { id: 4, top: '40%', duration: 40, delay: 1, opacity: 0.1, blur: 4 },
  { id: 5, top: '50%', duration: 30, delay: 3, opacity: 0.2, blur: 2 },
  { id: 6, top: '60%', duration: 22, delay: 5, opacity: 0.15, blur: 3 },
  { id: 7, top: '70%', duration: 38, delay: 2.5, opacity: 0.25, blur: 1 },
  { id: 8, top: '80%', duration: 28, delay: 1.5, opacity: 0.1, blur: 4 },
  { id: 9, top: '90%', duration: 32, delay: 4.5, opacity: 0.2, blur: 2 },
];

export default function DataFlowLines() {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mediaQuery.matches);

    const handleChange = (event: MediaQueryListEvent) => {
      setPrefersReducedMotion(event.matches);
    };

    mediaQuery.addEventListener('change', handleChange);

    return () => {
      mediaQuery.removeEventListener('change', handleChange);
    };
  }, []);

  if (prefersReducedMotion) {
    return null;
  }

  return (
    <div className="pointer-events-none absolute inset-0 overflow-hidden">
      {linesConfig.map((line) => (
        <div
          key={line.id}
          className="absolute h-px w-full"
          style={{
            top: line.top,
            opacity: line.opacity,
            filter: `blur(${line.blur}px)`,
          }}
        >
          <div
            className="h-full w-1/3 animate-flow"
            style={{
              background:
                'linear-gradient(90deg, transparent 0%, #3b82f6 20%, #8b5cf6 80%, transparent 100%)',
              boxShadow: '0 0 10px rgba(59, 130, 246, 0.5), 0 0 20px rgba(139, 92, 246, 0.3)',
              animationDuration: `${line.duration}s`,
              animationDelay: `${line.delay}s`,
            }}
          />
        </div>
      ))}

      <style jsx>{`
        @keyframes flow {
          0% {
            transform: translateX(-100%);
          }
          100% {
            transform: translateX(400%);
          }
        }

        .animate-flow {
          animation: flow linear infinite;
        }
      `}</style>
    </div>
  );
}

'use client';

import { useState, useCallback } from 'react';

import Link from 'next/link';

import {
  Search,
  GitCompare,
  Globe,
  History,
  ArrowRight,
  TrendingUp,
  Activity,
  BarChart3,
  LineChart,
} from 'lucide-react';
import {
  AreaChart,
  Area,
  ResponsiveContainer,
  BarChart,
  Bar,
  LineChart as ReLineChart,
  Line,
} from 'recharts';

import { Icon } from '@/components/ui';
import { useRoutePrefetch } from '@/hooks';
import { useTranslations } from '@/i18n';
import { chartColors } from '@/lib/config/colors';

interface FeatureCard {
  id: string;
  titleKey: string;
  descriptionKey: string;
  icon: React.ElementType;
  href: string;
  statsValue: string;
  statsKey: string;
  chartType: 'area' | 'bar' | 'line';
  chartData: { value: number; label: string }[];
}

const generateChartData = (baseValue: number, variance: number, count: number = 7) => {
  return Array.from({ length: count }, (_, i) => ({
    value: baseValue + Math.random() * variance - variance / 2,
    label: `${i + 1}`,
  }));
};

const features: FeatureCard[] = [
  {
    id: 'price-query',
    titleKey: 'home.features.priceQuery.title',
    descriptionKey: 'home.features.priceQuery.description',
    icon: Search,
    href: '/price-query',
    statsValue: '1,000+',
    statsKey: 'home.features.priceQuery.stats',
    chartType: 'area',
    chartData: generateChartData(85, 15),
  },
  {
    id: 'cross-oracle',
    titleKey: 'home.features.crossOracle.title',
    descriptionKey: 'home.features.crossOracle.description',
    icon: GitCompare,
    href: '/cross-oracle',
    statsValue: '5+',
    statsKey: 'home.features.crossOracle.stats',
    chartType: 'bar',
    chartData: [
      { value: 92, label: 'CL' },
      { value: 88, label: 'PY' },
      { value: 85, label: 'API' },
      { value: 90, label: 'BD' },
      { value: 87, label: 'UM' },
