  {
    id: 'cross-chain',
    titleKey: 'home.features.crossChain.title',
    descriptionKey: 'home.features.crossChain.description',
    icon: Globe,
    href: '/cross-chain',
    statsValue: '10+',
    statsKey: 'home.features.crossChain.stats',
    chartType: 'line',
    chartData: generateChartData(75, 20),
  },
  {
    id: 'history',
    titleKey: 'home.features.history.title',
    descriptionKey: 'home.features.history.description',
    icon: History,
    href: '/history',
    statsValue: '30D',
    statsKey: 'home.features.history.stats',
    chartType: 'area',
    chartData: generateChartData(65, 25),
  },
];

function MiniChart({
  type,
  data,
  isHovered,
}: {
  type: 'area' | 'bar' | 'line';
  data: { value: number; label: string }[];
  isHovered: boolean;
}) {
  const chartColor = chartColors.chart.blue;
  const gradientId = 'featureChartGradient';

  const renderChart = () => {
    switch (type) {
      case 'area':
        return (
          <AreaChart data={data} margin={{ top: 5, right: 5, bottom: 5, left: 5 }}>
            <defs>
              <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={chartColor} stopOpacity={0.2} />
                <stop offset="95%" stopColor={chartColor} stopOpacity={0.02} />
              </linearGradient>
            </defs>
            <Area
              type="monotone"
              dataKey="value"
              stroke={chartColor}
              strokeWidth={isHovered ? 2 : 1.5}
              fill={`url(#${gradientId})`}
              animationDuration={1000}
            />
          </AreaChart>
        );
      case 'bar':
        return (
          <BarChart data={data} margin={{ top: 5, right: 5, bottom: 5, left: 5 }}>
            <Bar
              dataKey="value"
              fill={chartColor}
              animationDuration={1000}
              opacity={isHovered ? 1 : 0.8}
            />
          </BarChart>
        );
      case 'line':
        return (
          <ReLineChart data={data} margin={{ top: 5, right: 5, bottom: 5, left: 5 }}>
            <Line
              type="monotone"
              dataKey="value"
              stroke={chartColor}
              strokeWidth={isHovered ? 2 : 1.5}
              dot={false}
              animationDuration={1000}
            />
          </ReLineChart>
        );
      default:
        return null;
    }
  };

  return (
    <div className="h-14 w-full">
      <ResponsiveContainer width="100%" height="100%">
        {renderChart()}
      </ResponsiveContainer>
    </div>
  );
}

