          <p className="text-base sm:text-lg text-gray-600 max-w-2xl mx-auto px-4">
            {t('home.features.sectionDescription')}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {features.map((feature) => {
            const Icon = feature.icon;
