            return (
              <Link
                key={feature.id}
                href={feature.href}
                className={`
                  relative group bg-white border border-gray-200 p-5 sm:p-6
                  transition-colors duration-200
                  ${isHovered ? 'border-gray-400' : ''}
                `}
                onMouseEnter={() => handleMouseEnter(feature.id, feature.href)}
