'use client';

import { useState } from 'react';

import {
  AlertTriangle,
  Bell,
  X,
  TrendingUp,
  TrendingDown,
  Activity,
  Clock,
  ChevronDown,
  ChevronUp,
} from 'lucide-react';

import { useTranslations } from '@/i18n';

import { type AnomalyData } from '../types';

interface AnomalyAlertProps {
  data: AnomalyData[];
  loading?: boolean;
  onAcknowledge?: (id: string) => void;
}

export default function AnomalyAlert({ data, loading = false, onAcknowledge }: AnomalyAlertProps) {
  const t = useTranslations('marketOverview.anomaly');
  const [expandedItems, setExpandedItems] = useState<Set<string>>(new Set());
  const [dismissedItems, setDismissedItems] = useState<Set<string>>(new Set());

  // 过滤已关闭的警报
  const activeAlerts = data.filter((alert) => !dismissedItems.has(alert.id));

  // 按严重程度排序
  const sortedAlerts = [...activeAlerts].sort((a, b) => {
    const levelOrder: Record<string, number> = { critical: 0, high: 1, medium: 2, low: 3 };
    return levelOrder[a.level] - levelOrder[b.level];
  });

  // 切换展开状态
  const toggleExpand = (id: string) => {
    const newExpanded = new Set(expandedItems);
    if (newExpanded.has(id)) {
      newExpanded.delete(id);
    } else {
      newExpanded.add(id);
    }
    setExpandedItems(newExpanded);
  };

  // 关闭警报
  const dismissAlert = (id: string) => {
    setDismissedItems(new Set(dismissedItems).add(id));
    onAcknowledge?.(id);
  };

  // 获取严重程度样式
  const getLevelStyle = (level: AnomalyData['level']) => {
    switch (level) {
      case 'critical':
        return 'bg-danger-50 border-l-2 border-danger-500';
      case 'high':
        return 'bg-warning-50 border-l-2 border-orange-500';
      case 'medium':
        return 'bg-warning-50 border-l-2 border-warning-500';
      case 'low':
        return 'bg-primary-50 border-l-2 border-primary-500';
      default:
        return 'bg-gray-50 border-l-2 border-gray-500';
    }
  };

  // 获取严重程度图标
  const getLevelIcon = (level: AnomalyData['level']) => {
    switch (level) {
      case 'critical':
        return <AlertTriangle className="w-4 h-4 text-danger-500" />;
      case 'high':
        return <AlertTriangle className="w-4 h-4 text-warning-500" />;
      case 'medium':
        return <Bell className="w-4 h-4 text-warning-500" />;
      case 'low':
        return <Activity className="w-4 h-4 text-primary-500" />;
      default:
        return <Activity className="w-4 h-4 text-gray-500" />;
    }
  };

  // 获取严重程度标签
  const getLevelLabel = (level: AnomalyData['level']) => {
    const labels: Record<AnomalyData['level'], string> = {
      critical: t('critical'),
      high: t('high'),
      medium: t('medium'),
      low: t('low'),
    };
    return labels[level];
  };

  // 获取类型图标
  const getTypeIcon = (type: AnomalyData['type']) => {
    switch (type) {
      case 'price_spike':
        return <TrendingUp className="w-3.5 h-3.5" />;
      case 'price_drop':
        return <TrendingDown className="w-3.5 h-3.5" />;
      case 'volatility_spike':
        return <Activity className="w-3.5 h-3.5" />;
      case 'trend_break':
        return <TrendingDown className="w-3.5 h-3.5" />;
      case 'volume_anomaly':
        return <Activity className="w-3.5 h-3.5" />;
      case 'correlation_break':
        return <Activity className="w-3.5 h-3.5" />;
      default:
        return <Activity className="w-3.5 h-3.5" />;
    }
  };

  // 获取类型标签
  const getTypeLabel = (type: AnomalyData['type']) => {
    const labels: Record<AnomalyData['type'], string> = {
      price_spike: t('priceSpike'),
      price_drop: t('priceDrop'),
      volatility_spike: t('volatilitySpike'),
      trend_break: t('trendBreak'),
      volume_anomaly: t('volumeAnomaly'),
      correlation_break: t('correlationBreak'),
    };
    return labels[type];
  };

  // 格式化时间
  const formatTime = (timestamp: number) => {
    const date = new Date(timestamp);
    const now = Date.now();
    const diff = now - timestamp;

    // 小于1小时
    if (diff < 3600000) {
      const minutes = Math.floor(diff / 60000);
      return t('minutesAgo', { minutes });
    }
    // 小于24小时
    if (diff < 86400000) {
      const hours = Math.floor(diff / 3600000);
      return t('hoursAgo', { hours });
    }
    // 默认显示日期
    return date.toLocaleDateString(undefined, {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  if (loading) {
    return (
      <div className="py-12 flex items-center justify-center">
        <div className="flex flex-col items-center gap-2">
          <div className="w-6 h-6 border-2 border-gray-400 border-t-transparent animate-spin" />
          <span className="text-gray-500 text-sm">{t('loading')}</span>
        </div>
      </div>
    );
  }

  if (sortedAlerts.length === 0) {
    return (
      <div className="py-8 flex items-center justify-center">
        <div className="text-center">
          <div className="w-10 h-10 bg-success-100 border border-green-200 flex items-center justify-center mx-auto mb-2">
            <Activity className="w-5 h-5 text-success-600" />
          </div>
          <p className="text-gray-500 text-sm">{t('noAlerts')}</p>
          <p className="text-xs text-gray-400 mt-1">{t('allNormal')}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {/* 统计摘要 */}
      <div className="flex items-center gap-3 text-xs mb-3">
        <span className="text-gray-500">
          {t('active')}: {sortedAlerts.length}
        </span>
        {sortedAlerts.some((a) => a.level === 'critical') && (
          <span className="px-1.5 py-0.5 bg-danger-100 text-danger-700 font-medium">
            {sortedAlerts.filter((a) => a.level === 'critical').length} {t('critical')}
          </span>
        )}
        {sortedAlerts.some((a) => a.level === 'high') && (
          <span className="px-1.5 py-0.5 bg-warning-100 text-orange-700 font-medium">
            {sortedAlerts.filter((a) => a.level === 'high').length} {t('high')}
          </span>
        )}
      </div>

      {/* 警报列表 */}
      <div className="space-y-1.5 max-h-[360px] overflow-auto">
        {sortedAlerts.map((alert) => (
          <div key={alert.id} className={`py-2.5 px-3 border ${getLevelStyle(alert.level)}`}>
            <div className="flex items-start justify-between">
              <div className="flex items-start gap-2 flex-1 min-w-0">
                <div className="mt-0.5">{getLevelIcon(alert.level)}</div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="font-medium text-gray-900 text-sm">{alert.asset}</span>
                    <span className="px-1.5 py-0.5 bg-white/60 text-xs font-medium text-gray-600 flex items-center gap-1">
                      {getTypeIcon(alert.type)}
                      {getTypeLabel(alert.type)}
                    </span>
                    <span
                      className={`px-1.5 py-0.5 text-xs font-medium ${
                        alert.level === 'critical'
                          ? 'bg-danger-100 text-danger-700'
                          : alert.level === 'high'
                            ? 'bg-warning-100 text-orange-700'
                            : alert.level === 'medium'
                              ? 'bg-warning-100 text-warning-700'
                              : 'bg-primary-100 text-primary-700'
                      }`}
                    >
                      {getLevelLabel(alert.level)}
                    </span>
                  </div>
                  <p className="text-xs text-gray-600 mt-1">{alert.description}</p>
                  <div className="flex items-center gap-3 mt-1.5 text-xs text-gray-500">
                    <span className="flex items-center gap-1">
                      <Clock className="w-3 h-3" />
                      {formatTime(alert.timestamp)}
                    </span>
                    <span>
                      {t('currentValue')}:{' '}
                      <span className="font-medium text-gray-700">{alert.value}</span>
                    </span>
                    <span>
                      {t('expectedValue')}:{' '}
                      <span className="font-medium text-gray-700">{alert.expectedValue}</span>
                    </span>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1 ml-2">
                <button
                  onClick={() => toggleExpand(alert.id)}
                  className="p-1 hover:bg-black/5 transition-colors"
                >
                  {expandedItems.has(alert.id) ? (
                    <ChevronUp className="w-4 h-4 text-gray-400" />
                  ) : (
                    <ChevronDown className="w-4 h-4 text-gray-400" />
                  )}
                </button>
                <button
                  onClick={() => dismissAlert(alert.id)}
                  className="p-1 hover:bg-black/5 transition-colors"
                >
                  <X className="w-4 h-4 text-gray-400" />
                </button>
              </div>
            </div>

            {/* 展开的详情 */}
            {expandedItems.has(alert.id) && (
              <div className="pt-2 mt-2 border-t border-black/5">
                <div className="grid grid-cols-2 gap-2 text-xs">
                  <div>
                    <span className="text-gray-500">{t('anomalyId')}:</span>
                    <span className="ml-1 font-mono text-gray-700">{alert.id}</span>
                  </div>
                  <div>
                    <span className="text-gray-500">{t('duration')}:</span>
                    <span className="ml-1 text-gray-700">
                      {alert.duration
                        ? t('minutes', { minutes: Math.floor(alert.duration / 60000) })
                        : t('ongoing')}
                    </span>
                  </div>
                  {alert.oracle && (
                    <div className="col-span-2">
                      <span className="text-gray-500">{t('affectedOracle')}:</span>
                      <div className="flex flex-wrap gap-1 mt-1">
                        <span className="px-1.5 py-0.5 bg-white/60 text-xs text-gray-700">
                          {alert.oracle}
                        </span>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

