  };

  if (
    viewType === 'table' &&
    !['chain', 'protocol', 'asset', 'pie', 'trend', 'bar'].includes(activeChart)
  ) {
    return (
      <div
        key={`table-${activeChart}`}
        className="will-change-transform gpu-accelerated animate-fade-in"
