'use client';

import { useMemo, useState, useCallback, useRef, useEffect } from 'react';

import { TrendingUp, Eye, EyeOff, Table, ChevronLeft, ChevronRight } from 'lucide-react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  ReferenceLine,
  Brush,
} from 'recharts';

import { ChartSkeleton } from '@/components/ui';
import { useTranslations } from '@/i18n';
import { chainNames } from '@/lib/constants';
import { formatPrice } from '@/lib/utils/chartSharedUtils';

import { type QueryResult } from '../constants';

import { ChartDataTable } from './ChartDataTable';
import { CustomTooltip } from './CustomTooltip';

export interface ChartDataPoint {
  timestamp: number;
  time: string;
  [key: string]: number | string | Record<string, unknown>;
}

interface PriceChartProps {
  chartData: ChartDataPoint[];
  queryResults: QueryResult[];
  hiddenSeries: Set<string>;
  onToggleSeries: (seriesName: string) => void;
  selectedTimeRange: number;
  selectedRow: string | null;
  compareMode?: boolean;
  compareChartData?: ChartDataPoint[];
  compareQueryResults?: QueryResult[];
  showBaseline?: boolean;
  avgPrice?: number;
}

/**
 * 价格图表组件
 *
 * @param props - 组件属性
 * @returns 价格图表 JSX 元素
 */
export function PriceChart({
  chartData,
  queryResults,
  hiddenSeries,
  onToggleSeries,
  selectedTimeRange,
  selectedRow,
  compareMode = false,
  compareChartData = [],
  compareQueryResults = [],
  showBaseline = false,
  avgPrice = 0,
}: PriceChartProps) {
  const t = useTranslations();

  const [cursorPosition, setCursorPosition] = useState<{
    x: number;
    y: number;
    visible: boolean;
  }>({ x: 0, y: 0, visible: false });

  const [focusedDataIndex, setFocusedDataIndex] = useState<number>(0);
  const [showDataTable, setShowDataTable] = useState(false);
  const chartContainerRef = useRef<HTMLDivElement>(null);

  // 获取系列名称
  const seriesNames = useMemo(() => {
    const names = new Set<string>();
    chartData.forEach((point) => {
      Object.keys(point).forEach((key) => {
        if (key !== 'timestamp' && key !== 'time' && !key.startsWith('_')) {
          names.add(key);
        }
      });
    });
    return Array.from(names);
  }, [chartData]);

  // 构建数据源信息映射
  const oracleInfoMap = useMemo(() => {
    const map: Record<string, { chain?: string; provider?: string }> = {};
    queryResults.forEach((result) => {
      const key = `${result.provider}_${result.chain}`;
      map[key] = {
        provider: result.provider,
        chain: chainNames[result.chain],
      };
    });
    return map;
  }, [queryResults]);

  // 处理图表数据，添加 Tooltip 所需的额外信息
  const enhancedChartData = useMemo(() => {
    if (chartData.length === 0) return [];

    return chartData.map((point, index) => {
      const prevPoint = index > 0 ? chartData[index - 1] : null;
      const prevValues: Record<string, number> = {};

      // 计算前一个时间点的值
      if (prevPoint) {
        seriesNames.forEach((name) => {
          const prevValue = prevPoint[name];
          if (typeof prevValue === 'number') {
            prevValues[name] = prevValue;
          }
        });
      }

      return {
        ...point,
        _avgPrice: avgPrice,
        _prevValues: prevValues,
        _oracleInfo: oracleInfoMap,
      };
    });
  }, [chartData, seriesNames, avgPrice, oracleInfoMap]);

  // 获取对比系列名称
  const compareSeriesNames = useMemo(() => {
    if (!compareMode || compareChartData.length === 0) return [];
    const names = new Set<string>();
    compareChartData.forEach((point) => {
      Object.keys(point).forEach((key) => {
        if (key !== 'timestamp' && key !== 'time' && !key.startsWith('_')) {
          names.add(key);
        }
      });
    });
    return Array.from(names);
  }, [compareMode, compareChartData]);

  // 生成系列颜色
  const getSeriesColor = (index: number, isCompare = false) => {
    const colors = [
      '#3b82f6', // blue-500
      '#10b981', // emerald-500
      '#f59e0b', // amber-500
      '#ef4444', // red-500
      '#8b5cf6', // violet-500
      '#06b6d4', // cyan-500
      '#f97316', // orange-500
      '#ec4899', // pink-500
    ];
    const baseColor = colors[index % colors.length];
    if (isCompare) {
      // 对比模式使用更浅的色调
      return baseColor + '80'; // 50% opacity
    }
    return baseColor;
  };

  // 格式化时间标签
  const formatXAxisLabel = (timestamp: number) => {
    const date = new Date(timestamp);
    if (selectedTimeRange <= 1) {
      // 1小时内，显示分钟
      return date.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
    } else if (selectedTimeRange <= 24) {
      // 24小时内，显示小时
      return date.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
    } else {
      // 超过24小时，显示日期
      return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
    }
  };

  // 计算 Y 轴范围
  const yAxisDomain = useMemo(() => {
    if (enhancedChartData.length === 0) return ['auto', 'auto'];

    let min = Infinity;
    let max = -Infinity;

    enhancedChartData.forEach((point) => {
      seriesNames.forEach((name) => {
        if (!hiddenSeries.has(name)) {
          const value = (point as Record<string, unknown>)[name] as number;
          if (typeof value === 'number' && !isNaN(value)) {
            min = Math.min(min, value);
            max = Math.max(max, value);
          }
        }
      });
    });

    if (compareMode && compareChartData.length > 0) {
      compareChartData.forEach((point) => {
        compareSeriesNames.forEach((name) => {
          if (!hiddenSeries.has(name + '_compare')) {
            const value = point[name] as number;
            if (typeof value === 'number' && !isNaN(value)) {
              min = Math.min(min, value);
              max = Math.max(max, value);
            }
          }
        });
      });
    }

    if (min === Infinity || max === -Infinity) return ['auto', 'auto'];

    // 添加一些边距
    const padding = (max - min) * 0.1;
    return [min - padding, max + padding];
  }, [
    enhancedChartData,
    compareChartData,
    seriesNames,
    compareSeriesNames,
    hiddenSeries,
    compareMode,
  ]);

  // 鼠标移动处理 - 更新十字准星位置
  const handleMouseMove = useCallback(
    (e: { activeCoordinate?: { x: number; y: number }; activePayload?: unknown[] }) => {
      if (e.activeCoordinate && e.activePayload && e.activePayload.length > 0) {
        setCursorPosition({
          x: e.activeCoordinate.x,
          y: e.activeCoordinate.y,
          visible: true,
        });
      }
    },
    []
  );

  // 鼠标离开处理 - 隐藏十字准星
  const handleMouseLeave = useCallback(() => {
    setCursorPosition((prev) => ({ ...prev, visible: false }));
  }, []);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (enhancedChartData.length === 0) return;

      switch (e.key) {
        case 'ArrowLeft':
          e.preventDefault();
          setFocusedDataIndex((prev) => Math.max(0, prev - 1));
          break;
        case 'ArrowRight':
          e.preventDefault();
          setFocusedDataIndex((prev) => Math.min(enhancedChartData.length - 1, prev + 1));
          break;
        case 'Home':
          e.preventDefault();
          setFocusedDataIndex(0);
          break;
        case 'End':
          e.preventDefault();
          setFocusedDataIndex(enhancedChartData.length - 1);
          break;
      }
    },
    [enhancedChartData.length]
  );

  useEffect(() => {
    if (focusedDataIndex >= 0 && focusedDataIndex < enhancedChartData.length) {
      setCursorPosition({
        x: (focusedDataIndex / enhancedChartData.length) * 100,
        y: 0,
        visible: true,
      });
    }
  }, [focusedDataIndex, enhancedChartData.length]);

  const chartAriaLabel = useMemo(() => {
    if (enhancedChartData.length === 0 || seriesNames.length === 0) {
      return t('priceQuery.charts.priceHistory');
    }
    const firstPoint = enhancedChartData[0];
    const lastPoint = enhancedChartData[enhancedChartData.length - 1];
    const startTime = new Date(firstPoint.timestamp).toLocaleString();
    const endTime = new Date(lastPoint.timestamp).toLocaleString();
    const seriesList = seriesNames.join(', ');
    return t('priceQuery.charts.chartAriaLabel', {
      series: seriesList,
      startTime,
      endTime,
      points: enhancedChartData.length,
    });
  }, [enhancedChartData, seriesNames, t]);

  const focusedDataPoint = enhancedChartData[focusedDataIndex];

  // 空状态
  if (enhancedChartData.length === 0) {
    return (
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
        <div className="flex items-center gap-2 mb-4">
          <TrendingUp className="w-5 h-5 text-gray-400" aria-hidden="true" />
          <h3 className="text-sm font-semibold text-gray-900">
            {t('priceQuery.charts.priceHistory')}
          </h3>
        </div>
        <ChartSkeleton height={300} variant="price" />
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
      <div className="px-4 py-3 bg-gray-50 border-b border-gray-200 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <TrendingUp className="w-4 h-4 text-gray-500" aria-hidden="true" />
          <h3 className="text-sm font-semibold text-gray-900">
            {t('priceQuery.charts.priceHistory')}
          </h3>
        </div>
        <div className="flex items-center gap-2">
          {compareMode && (
            <div className="flex items-center gap-2 text-xs">
              <span className="flex items-center gap-1">
                <span className="w-2 h-2 rounded-full bg-primary-500" />
                {t('priceQuery.charts.current')}
              </span>
              <span className="flex items-center gap-1">
                <span className="w-2 h-2 rounded-full bg-primary-500/50" />
                {t('priceQuery.charts.comparison')}
              </span>
            </div>
          )}
          <button
            onClick={() => setShowDataTable(!showDataTable)}
            className={`flex items-center gap-1.5 px-2.5 py-1.5 text-xs font-medium rounded-md transition-colors ${
              showDataTable
                ? 'bg-primary-50 text-primary-700 border border-primary-200'
                : 'bg-white text-gray-600 hover:text-gray-900 hover:bg-gray-100 border border-gray-200'
            }`}
            aria-pressed={showDataTable}
            aria-label={
              showDataTable
                ? t('priceQuery.charts.hideDataTable')
                : t('priceQuery.charts.showDataTable')
            }
          >
            <Table className="w-3.5 h-3.5" aria-hidden="true" />
            <span className="hidden sm:inline">{t('priceQuery.charts.tableView')}</span>
          </button>
        </div>
      </div>

      <div className="px-4 py-2 bg-white border-b border-gray-100 flex flex-wrap gap-2">
        {seriesNames.map((name, index) => {
          const isHidden = hiddenSeries.has(name);
          const color = getSeriesColor(index);
          return (
            <button
              key={name}
              onClick={() => onToggleSeries(name)}
              className={`flex items-center gap-1.5 px-2 py-1 text-xs font-medium rounded-md transition-all ${
                isHidden
                  ? 'bg-gray-100 text-gray-400'
                  : 'bg-gray-50 text-gray-700 hover:bg-gray-100'
              }`}
              title={isHidden ? t('priceQuery.charts.show') : t('priceQuery.charts.hide')}
              aria-pressed={!isHidden}
              aria-label={`${isHidden ? t('priceQuery.charts.show') : t('priceQuery.charts.hide')} ${name}`}
            >
              {isHidden ? (
                <EyeOff className="w-3 h-3" aria-hidden="true" />
              ) : (
                <Eye className="w-3 h-3" aria-hidden="true" />
              )}
              <span
                className="w-2 h-2 rounded-full"
                style={{ backgroundColor: isHidden ? '#9ca3af' : color }}
              />
              <span className="truncate max-w-[120px]">{name}</span>
            </button>
          );
        })}
      </div>

      <div className="p-4">
        <div
          ref={chartContainerRef}
          role="img"
          aria-label={chartAriaLabel}
          tabIndex={0}
          onKeyDown={handleKeyDown}
          className="outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2 rounded-lg"
        >
          <ResponsiveContainer width="100%" height={360}>
            <LineChart
              data={enhancedChartData}
              margin={{ top: 5, right: 5, left: 0, bottom: 65 }}
              onMouseMove={handleMouseMove}
              onMouseLeave={handleMouseLeave}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis
                dataKey="timestamp"
                tickFormatter={formatXAxisLabel}
                tick={{ fontSize: 11, fill: '#6b7280' }}
                axisLine={{ stroke: '#e5e7eb' }}
                tickLine={{ stroke: '#e5e7eb' }}
                minTickGap={30}
              />
              <YAxis
                domain={yAxisDomain}
                tick={{ fontSize: 11, fill: '#6b7280' }}
                axisLine={{ stroke: '#e5e7eb' }}
                tickLine={{ stroke: '#e5e7eb' }}
                tickFormatter={(value) => formatPrice(value)}
                width={70}
              />
              <Tooltip content={<CustomTooltip />} />

              {cursorPosition.visible && enhancedChartData.length > 0 && (
                <>
                  <ReferenceLine
                    x={
                      enhancedChartData[
                        Math.min(
                          Math.floor((cursorPosition.x / 100) * enhancedChartData.length),
                          enhancedChartData.length - 1
                        )
                      ]?.timestamp
                    }
                    stroke="#9ca3af"
                    strokeDasharray="3 3"
                    ifOverflow="hidden"
                  />
                </>
              )}

              {showBaseline && avgPrice > 0 && (
                <ReferenceLine
                  y={avgPrice}
                  stroke="#9ca3af"
                  strokeDasharray="5 5"
                  label={{
                    value: t('priceQuery.charts.avgPrice'),
                    position: 'right',
                    fill: '#6b7280',
                    fontSize: 11,
                  }}
                />
              )}

              {seriesNames.map((name, index) => (
                <Line
                  key={name}
                  type="monotone"
                  dataKey={name}
                  stroke={getSeriesColor(index)}
                  strokeWidth={selectedRow === name ? 3 : 2}
                  dot={false}
                  activeDot={{ r: 4, strokeWidth: 2 }}
                  hide={hiddenSeries.has(name)}
                  isAnimationActive={false}
                />
              ))}

              {compareMode &&
                compareSeriesNames.map((name, index) => (
                  <Line
                    key={`${name}_compare`}
                    type="monotone"
                    data={compareChartData}
                    dataKey={name}
                    stroke={getSeriesColor(index, true)}
                    strokeWidth={1.5}
                    strokeDasharray="4 4"
                    dot={false}
                    activeDot={{ r: 3, strokeWidth: 1 }}
                    hide={hiddenSeries.has(name + '_compare')}
                    isAnimationActive={false}
                  />
                ))}

              <Brush
                dataKey="timestamp"
                height={60}
                stroke="#6366f1"
                fill="#e0e7ff"
                travellerWidth={8}
                tickFormatter={formatXAxisLabel}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>

        <div className="sr-only" role="status" aria-live="polite" aria-atomic="true">
          {focusedDataPoint && (
            <>
              {t('priceQuery.charts.currentDataPoint')}:{' '}
              {new Date(focusedDataPoint.timestamp).toLocaleString()}
              {seriesNames
                .map((name) => {
                  const value = (focusedDataPoint as Record<string, unknown>)[name];
                  if (typeof value === 'number' && !hiddenSeries.has(name)) {
                    return `, ${name}: ${formatPrice(value)}`;
                  }
                  return null;
                })
                .filter(Boolean)
                .join('')}
            </>
          )}
        </div>

        <div className="flex items-center justify-center gap-2 mt-2 text-xs text-gray-500">
          <span className="flex items-center gap-1">
            <ChevronLeft className="w-3 h-3" aria-hidden="true" />
            <span>{t('priceQuery.charts.navigateLeft')}</span>
          </span>
          <span className="flex items-center gap-1">
            <span>{t('priceQuery.charts.navigateRight')}</span>
            <ChevronRight className="w-3 h-3" aria-hidden="true" />
          </span>
        </div>
      </div>

      {showDataTable && (
        <ChartDataTable
          chartData={chartData}
          seriesNames={seriesNames}
          selectedTimeRange={selectedTimeRange}
        />
      )}

      <div className="px-4 py-2 bg-gray-50 border-t border-gray-100 text-xs text-gray-500 flex items-center justify-between">
        <span>
          {t('priceQuery.charts.dataPoints')}: {enhancedChartData.length}
        </span>
        <span>
          {t('priceQuery.charts.timeRange')}: {selectedTimeRange}h
        </span>
      </div>
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';

import { Search, ArrowUpDown, ArrowUp, ArrowDown, Filter, X } from 'lucide-react';

import { useTranslations } from '@/i18n';
import { OracleProvider, Blockchain } from '@/lib/oracles';

import { type QueryResult, type PriceData, oracleI18nKeys } from '../constants';

interface PriceResultsTableProps {
  results: QueryResult[];
  filteredResults: QueryResult[];
  filterText: string;
  setFilterText: (text: string) => void;
  sortField: 'oracle' | 'blockchain' | 'price' | 'timestamp';
  sortDirection: 'asc' | 'desc';
  onSort: (field: 'oracle' | 'blockchain' | 'price' | 'timestamp') => void;
  avgPrice: number;
  selectedRow: string | null;
  onRowSelect: (row: string | null) => void;
  historicalData: Partial<Record<string, PriceData[]>>;
  filterInputRef?: React.RefObject<HTMLInputElement | null>;
}

/**
 * 价格结果表格组件
 *
 * @param props - 组件属性
 * @returns 价格结果表格 JSX 元素
 */
export function PriceResultsTable({
  results,
  filteredResults,
  filterText,
  setFilterText,
  sortField,
  sortDirection,
  onSort,
  avgPrice,
  selectedRow,
  onRowSelect,
  historicalData: _historicalData,
  filterInputRef,
}: PriceResultsTableProps) {
  const t = useTranslations();
  const [showFilters, setShowFilters] = useState(false);
  const [sortAnnouncement, setSortAnnouncement] = useState<string>('');

  const getSortIcon = (field: 'oracle' | 'blockchain' | 'price' | 'timestamp') => {
    if (sortField !== field) {
      return <ArrowUpDown className="w-3.5 h-3.5 text-gray-400" aria-hidden="true" />;
    }
    return sortDirection === 'asc' ? (
      <ArrowUp className="w-3.5 h-3.5 text-primary-600" aria-hidden="true" />
    ) : (
      <ArrowDown className="w-3.5 h-3.5 text-primary-600" aria-hidden="true" />
    );
  };

  const getAriaSort = (
    field: 'oracle' | 'blockchain' | 'price' | 'timestamp'
  ): 'ascending' | 'descending' | 'none' => {
    if (sortField !== field) return 'none';
    return sortDirection === 'asc' ? 'ascending' : 'descending';
  };

  const handleSort = (field: 'oracle' | 'blockchain' | 'price' | 'timestamp') => {
    onSort(field);
    const fieldName = t(`priceQuery.results.${field}`);
    const newDirection = sortField === field && sortDirection === 'asc' ? 'desc' : 'asc';
    const directionText =
      newDirection === 'asc'
        ? t('priceQuery.results.sortAscending')
        : t('priceQuery.results.sortDescending');
    setSortAnnouncement(`${fieldName} ${directionText}`);
  };

  // 计算价格偏差
  const getPriceDeviation = (
    price: number
  ): {
    value: string;
    textColor: string;
    bgColor: string;
    indicatorColor: string;
  } => {
    if (avgPrice === 0) {
      return {
        value: '-',
        textColor: 'text-gray-400',
        bgColor: '',
        indicatorColor: '',
      };
    }
    const deviation = ((price - avgPrice) / avgPrice) * 100;
    const formatted = deviation >= 0 ? `+${deviation.toFixed(2)}%` : `${deviation.toFixed(2)}%`;
    const absDeviation = Math.abs(deviation);

    if (absDeviation < 0.1) {
      return {
        value: formatted,
        textColor: 'text-emerald-600',
        bgColor: 'bg-emerald-50/60',
        indicatorColor: 'border-l-emerald-500',
      };
    }
    if (absDeviation < 0.5) {
      return {
        value: formatted,
        textColor: 'text-amber-600',
        bgColor: 'bg-amber-50/60',
        indicatorColor: 'border-l-amber-500',
      };
    }
    return {
      value: formatted,
      textColor: 'text-red-600',
      bgColor: 'bg-red-50/60',
      indicatorColor: 'border-l-red-500',
    };
  };

  // 格式化时间
  const formatTimestamp = (timestamp: number): string => {
    const date = new Date(timestamp);
    return date.toLocaleString(undefined, {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  // 获取行唯一标识
  const getRowKey = (result: QueryResult): string => {
    return `${result.provider}-${result.chain}-${result.priceData.timestamp}`;
  };

  // 处理行点击
  const handleRowClick = (result: QueryResult) => {
    const key = getRowKey(result);
    onRowSelect(selectedRow === key ? null : key);
  };

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
      <div className="sr-only" role="status" aria-live="polite" aria-atomic="true">
        {sortAnnouncement}
      </div>
      <div className="px-4 py-3 bg-gray-50 border-b border-gray-200 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <h3 className="text-sm font-semibold text-gray-900">{t('priceQuery.results.title')}</h3>
          <span
            className="px-2 py-0.5 text-xs font-medium bg-gray-200 text-gray-700 rounded-full"
            aria-label={`${filteredResults.length} ${t('priceQuery.results.resultsCount')}`}
          >
            {filteredResults.length}
          </span>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowFilters(!showFilters)}
            className={`flex items-center gap-1.5 px-2.5 py-1.5 text-xs font-medium rounded-md transition-colors ${
              showFilters
                ? 'bg-primary-50 text-primary-700 border border-primary-200'
                : 'bg-white text-gray-600 hover:text-gray-900 hover:bg-gray-100 border border-gray-200'
            }`}
            aria-expanded={showFilters}
            aria-controls="filter-panel"
            aria-label={
              showFilters
                ? t('priceQuery.results.hideFilters')
                : t('priceQuery.results.showFilters')
            }
          >
            <Filter className="w-3.5 h-3.5" aria-hidden="true" />
            {t('filter')}
          </button>
        </div>
      </div>

      {showFilters && (
        <div id="filter-panel" className="px-4 py-3 bg-gray-50 border-b border-gray-200">
          <div className="relative">
            <Search
              className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400"
              aria-hidden="true"
            />
            <input
              ref={filterInputRef}
              type="text"
              value={filterText}
              onChange={(e) => setFilterText(e.target.value)}
              placeholder={t('priceQuery.results.filterPlaceholder')}
              aria-label={t('priceQuery.results.filterLabel')}
              className="w-full pl-9 pr-9 py-2 text-sm bg-white border border-gray-200 rounded-md focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent"
            />
            {filterText && (
              <button
                onClick={() => setFilterText('')}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                aria-label={t('clear')}
              >
                <X className="w-4 h-4" aria-hidden="true" />
              </button>
            )}
          </div>
        </div>
      )}

      <div className="overflow-x-auto">
        <table
          className="w-full text-sm"
          role="grid"
          aria-label={t('priceQuery.results.tableLabel')}
        >
          <thead>
            <tr className="bg-gray-50 border-b border-gray-200">
              <th
                scope="col"
                aria-sort={getAriaSort('oracle')}
                className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100 transition-colors"
                onClick={() => handleSort('oracle')}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    handleSort('oracle');
                  }
                }}
                tabIndex={0}
                role="columnheader"
              >
                <div className="flex items-center gap-1">
                  {t('priceQuery.results.oracle')}
                  {getSortIcon('oracle')}
                </div>
              </th>
              <th
                scope="col"
                aria-sort={getAriaSort('blockchain')}
                className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100 transition-colors"
                onClick={() => handleSort('blockchain')}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    handleSort('blockchain');
                  }
                }}
                tabIndex={0}
                role="columnheader"
              >
                <div className="flex items-center gap-1">
                  {t('priceQuery.results.blockchain')}
                  {getSortIcon('blockchain')}
                </div>
              </th>
              <th
                scope="col"
                aria-sort={getAriaSort('price')}
                className="px-4 py-3 text-right text-xs font-semibold text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100 transition-colors"
                onClick={() => handleSort('price')}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    handleSort('price');
                  }
                }}
                tabIndex={0}
                role="columnheader"
              >
                <div className="flex items-center justify-end gap-1">
                  {t('priceQuery.results.price')}
                  {getSortIcon('price')}
                </div>
              </th>
              <th
                scope="col"
                className="px-4 py-3 text-right text-xs font-semibold text-gray-500 uppercase tracking-wider"
                role="columnheader"
              >
                {t('priceQuery.results.deviation')}
              </th>
              <th
                scope="col"
                aria-sort={getAriaSort('timestamp')}
                className="px-4 py-3 text-right text-xs font-semibold text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100 transition-colors"
                onClick={() => handleSort('timestamp')}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    handleSort('timestamp');
                  }
                }}
                tabIndex={0}
                role="columnheader"
              >
                <div className="flex items-center justify-end gap-1">
                  {t('priceQuery.results.timestamp')}
                  {getSortIcon('timestamp')}
                </div>
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filteredResults.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-4 py-8 text-center text-sm text-gray-500">
                  {t('priceQuery.results.noMatchingData')}
                </td>
              </tr>
            ) : (
              filteredResults.map((result) => {
                const rowKey = getRowKey(result);
                const isSelected = selectedRow === rowKey;
                const deviation = getPriceDeviation(result.priceData.price);

                return (
                  <tr
                    key={rowKey}
                    onClick={() => handleRowClick(result)}
                    className={`cursor-pointer transition-colors ${
                      isSelected ? 'bg-primary-50 hover:bg-primary-100' : 'hover:bg-gray-50'
                    }`}
                    role="row"
                    tabIndex={0}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        handleRowClick(result);
                      }
                    }}
                    aria-selected={isSelected}
                  >
                    <td className="px-4 py-3" role="gridcell">
                      <div className="flex items-center gap-2">
                        <span
                          className={`w-2 h-2 rounded-full ${
                            result.provider === 'chainlink'
                              ? 'bg-blue-500'
                              : result.provider === 'pyth'
                                ? 'bg-emerald-500'
                                : result.provider === 'band-protocol'
                                  ? 'bg-amber-500'
                                  : result.provider === 'api3'
                                    ? 'bg-violet-500'
                                    : result.provider === 'uma'
                                      ? 'bg-red-500'
                                      : result.provider === 'redstone'
                                        ? 'bg-cyan-500'
                                        : result.provider === 'dia'
                                          ? 'bg-orange-500'
                                          : result.provider === 'tellor'
                                            ? 'bg-pink-500'
                                            : result.provider === 'chronicle'
                                              ? 'bg-indigo-500'
                                              : 'bg-gray-500'
                          }`}
                          aria-hidden="true"
                        />
                        <span className="font-medium text-gray-900">
                          {t(`navbar.${oracleI18nKeys[result.provider]}`)}
                        </span>
                      </div>
                    </td>
                    <td className="px-4 py-3" role="gridcell">
                      <span className="text-gray-700">
                        {t(`blockchain.${result.chain.toLowerCase()}`)}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right" role="gridcell">
                      <span className="font-medium font-tabular text-gray-900">
                        $
                        {result.priceData.price.toLocaleString(undefined, {
                          minimumFractionDigits: 2,
                          maximumFractionDigits: 4,
                        })}
                      </span>
                    </td>
                    <td
                      className={`px-4 py-3 text-right relative border-l-[3px] ${deviation.indicatorColor} ${
                        !isSelected && deviation.bgColor ? deviation.bgColor : ''
                      }`}
                      role="gridcell"
                    >
                      <span className={`text-xs font-medium ${deviation.textColor}`}>
                        {deviation.value}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right" role="gridcell">
                      <span className="text-xs text-gray-500">
                        {formatTimestamp(result.priceData.timestamp)}
                      </span>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      <div className="px-4 py-2 bg-gray-50 border-t border-gray-100 text-xs text-gray-500 flex items-center justify-between">
        <span aria-live="polite">
          {t('priceQuery.results.showing', {
            filtered: filteredResults.length,
            total: results.length,
          })}
        </span>
        {filterText && (
          <button
            onClick={() => setFilterText('')}
            className="text-primary-600 hover:text-primary-700 font-medium"
          >
            {t('clearFilter')}
          </button>
        )}
      </div>
    </div>
  );
}

'use client';

/**
 * @fileoverview 价格查询页面头部组件
 * @description 包含页面标题、收藏夹、历史记录和导出功能
 */

import { useState } from 'react';

import { useRouter } from 'next/navigation';

import { History, Download, FileSpreadsheet, FileJson, Settings2 } from 'lucide-react';

import { FavoriteButton } from '@/components/favorites';
import { type FavoriteConfig } from '@/hooks';
import { useTranslations } from '@/i18n';
import { type OracleProvider, type Blockchain } from '@/lib/oracles';
import { useUser } from '@/stores/authStore';
import { type QueryHistoryItem } from '@/utils/queryHistory';

interface QueryHeaderProps {
  showHistory: boolean;
  setShowHistory: (show: boolean) => void;
  historyItems: QueryHistoryItem[];
  onSelectHistory: (item: QueryHistoryItem) => void;
  onClearHistory: () => void;
  loading: boolean;
  queryResultsLength: number;
  onExportCSV: () => void;
  onExportJSON: () => void;
  onOpenExportConfig: () => void;
  selectedOracles: OracleProvider[];
  selectedChains: Blockchain[];
  selectedSymbol: string;
  selectedTimeRange: number;
  setSelectedOracles: (oracles: OracleProvider[]) => void;
  setSelectedChains: (chains: Blockchain[]) => void;
  setSelectedSymbol: (symbol: string) => void;
  setSelectedTimeRange: (timeRange: number) => void;
  // Favorites
  symbolFavorites: { id?: string; name: string; config_data: Record<string, unknown> }[];
  currentFavoriteConfig: FavoriteConfig;
  showFavoritesDropdown: boolean;
  setShowFavoritesDropdown: (show: boolean) => void;
  favoritesDropdownRef: React.RefObject<HTMLDivElement | null>;
  handleApplyFavorite: (config: FavoriteConfig) => void;
}

/**
 * 价格查询页面头部组件
 *
 * @param props - 组件属性
 * @returns 页面头部 JSX 元素
 */
export function QueryHeader({
  showHistory,
  setShowHistory,
  historyItems,
  onSelectHistory,
  onClearHistory,
  loading,
  queryResultsLength,
  onExportCSV,
  onExportJSON,
  onOpenExportConfig,
  selectedOracles,
  selectedChains,
  selectedSymbol,
  selectedTimeRange,
  setSelectedOracles,
  setSelectedChains,
  setSelectedSymbol,
  setSelectedTimeRange,
  symbolFavorites,
  currentFavoriteConfig,
  showFavoritesDropdown,
  setShowFavoritesDropdown,
  favoritesDropdownRef,
  handleApplyFavorite,
}: QueryHeaderProps) {
  const t = useTranslations();
  const router = useRouter();
  const user = useUser();
  const [showExportMenu, setShowExportMenu] = useState(false);

  const handleHistorySelect = (item: QueryHistoryItem) => {
    onSelectHistory(item);
    setShowHistory(false);
  };

  const handleClearHistory = () => {
    onClearHistory();
    setShowHistory(false);
  };

  return (
    <header className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
      {/* 标题区域 */}
      <div>
        <h1 className="text-2xl font-semibold text-gray-900">{t('navbar.priceQuery')}</h1>
        <p className="text-sm text-gray-500 mt-1">
          {loading
            ? t('priceQuery.loadingData')
            : queryResultsLength > 0
              ? t('priceQuery.results.count', { count: queryResultsLength })
              : t('priceQuery.subtitle')}
        </p>
      </div>

      {/* 操作按钮区域 */}
      <nav className="flex items-center gap-2" aria-label="页面操作">
        {/* 收藏夹按钮 */}
        {user && (
          <FavoriteButton
            configType="symbol"
            configData={currentFavoriteConfig}
            name={`${selectedSymbol} - ${selectedOracles.length} oracles, ${selectedChains.length} chains`}
            variant="button"
            showLabel
          />
        )}

        {/* 收藏夹下拉菜单 */}
        {user && symbolFavorites && symbolFavorites.length > 0 && (
          <div className="relative" ref={favoritesDropdownRef}>
            <button
              onClick={() => setShowFavoritesDropdown(!showFavoritesDropdown)}
              className="flex items-center gap-2 px-3 py-2 text-sm font-medium bg-white text-gray-600 rounded-md hover:text-gray-900 hover:bg-gray-50 transition-all border border-gray-200 shadow-sm"
              aria-expanded={showFavoritesDropdown}
              aria-haspopup="listbox"
            >
              <svg
                className="w-4 h-4 text-gray-600"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
                aria-hidden="true"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z"
                />
              </svg>
              <span>{t('crossOracle.favorites.button')}</span>
              <span className="px-1.5 py-0.5 text-xs bg-gray-100 text-gray-600 rounded-full">
                {symbolFavorites.length}
              </span>
              <svg
                className={`w-4 h-4 transition-transform ${showFavoritesDropdown ? 'rotate-180' : ''}`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
                aria-hidden="true"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M19 9l-7 7-7-7"
                />
              </svg>
            </button>

            {showFavoritesDropdown && (
              <div
                className="absolute right-0 top-full mt-2 w-72 bg-white rounded-lg shadow-lg border border-gray-200 z-50 max-h-96 overflow-y-auto"
                role="listbox"
              >
                <div className="p-2 border-b border-gray-100">
                  <h3 className="text-sm font-semibold text-gray-900">
                    {t('crossOracle.favorites.quickAccess')}
                  </h3>
                </div>
                <div className="p-1">
                  {symbolFavorites.map((favorite) => {
                    const config = favorite.config_data as FavoriteConfig;
                    return (
                      <button
                        key={favorite.id}
                        onClick={() => handleApplyFavorite(config)}
                        className="w-full text-left px-3 py-2 hover:bg-gray-50 transition-colors rounded-md"
                        role="option"
                      >
                        <div className="flex items-center justify-between">
                          <span className="text-sm font-medium text-gray-900 truncate">
                            {favorite.name}
                          </span>
                          <span className="text-xs text-gray-500">{config.symbol}</span>
                        </div>
                        <div className="flex flex-wrap gap-1 mt-1">
                          {config.selectedOracles?.slice(0, 2).map((oracle) => (
                            <span
                              key={oracle}
                              className="px-1.5 py-0.5 text-xs bg-primary-50 text-primary-700 border border-primary-100 rounded"
                            >
                              {oracle}
                            </span>
                          ))}
                          {(config.selectedOracles?.length || 0) > 2 && (
                            <span className="px-1.5 py-0.5 text-xs bg-gray-100 text-gray-600 border border-gray-200 rounded">
                              +{(config.selectedOracles?.length || 0) - 2}
                            </span>
                          )}
                        </div>
                      </button>
                    );
                  })}
                </div>
                <div className="p-2 border-t border-gray-100">
                  <button
                    onClick={() => {
                      setShowFavoritesDropdown(false);
                      router.push('/favorites');
                    }}
                    className="w-full text-center text-sm text-primary-600 hover:text-primary-700 font-medium"
                  >
                    {t('crossOracle.favorites.viewAll')}
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {/* 历史记录按钮 */}
        <div className="relative">
          <button
            onClick={() => setShowHistory(!showHistory)}
            className={`flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-md transition-all border shadow-sm ${
              showHistory
                ? 'bg-primary-50 text-primary-700 border-primary-200'
                : 'bg-white text-gray-600 hover:text-gray-900 hover:bg-gray-50 border-gray-200'
            }`}
            aria-expanded={showHistory}
            aria-haspopup="listbox"
          >
            <History className="w-4 h-4" aria-hidden="true" />
            {t('priceQuery.history.title')}
            {historyItems.length > 0 && (
              <span className="ml-1 px-1.5 py-0.5 text-xs bg-gray-100 text-gray-600 rounded-full">
                {historyItems.length}
              </span>
            )}
          </button>

          {/* 历史记录下拉菜单 */}
          {showHistory && (
            <div
              className="absolute right-0 top-full mt-2 w-80 bg-white rounded-lg shadow-lg border border-gray-200 z-50 overflow-hidden"
              role="listbox"
            >
              <div className="px-4 py-3 bg-gray-50 border-b border-gray-200 flex items-center justify-between">
                <span className="text-sm font-medium text-gray-900">
                  {t('priceQuery.history.title')}
                </span>
                {historyItems.length > 0 && (
                  <button
                    onClick={handleClearHistory}
                    className="text-xs text-danger-600 hover:text-danger-700 font-medium"
                  >
                    {t('clear')}
                  </button>
                )}
              </div>
              <div className="max-h-64 overflow-y-auto">
                {historyItems.length === 0 ? (
                  <div className="px-4 py-8 text-center text-sm text-gray-500">
                    {t('priceQuery.history.empty')}
                  </div>
                ) : (
                  historyItems.map((item, index) => (
                    <button
                      key={index}
                      onClick={() => handleHistorySelect(item)}
                      className="w-full px-4 py-3 text-left hover:bg-gray-50 transition-colors border-b border-gray-100 last:border-0"
                      role="option"
                    >
                      <div className="flex items-center justify-between">
                        <span className="font-medium text-gray-900">{item.symbol}</span>
                        <span className="text-xs text-gray-500">{item.timeRange}h</span>
                      </div>
                      <div className="text-xs text-gray-500 mt-1">
                        {item.oracles.length} {t('priceQuery.oracles')} · {item.chains.length}{' '}
                        {t('priceQuery.chains')}
                      </div>
                    </button>
                  ))
                )}
              </div>
            </div>
          )}
        </div>

        {/* 导出下拉菜单 */}
        <div className="relative">
          <button
            onClick={() => setShowExportMenu(!showExportMenu)}
            disabled={loading || queryResultsLength === 0}
            className="flex items-center gap-2 px-3 py-2 text-sm font-medium bg-white text-gray-600 rounded-md hover:text-gray-900 hover:bg-gray-50 transition-all disabled:opacity-50 disabled:cursor-not-allowed border border-gray-200 shadow-sm"
            aria-expanded={showExportMenu}
            aria-haspopup="listbox"
          >
            <Download className="w-4 h-4" aria-hidden="true" />
            {t('export.export')}
          </button>

          {showExportMenu && (
            <div
              className="absolute right-0 top-full mt-2 w-48 bg-white rounded-lg shadow-lg border border-gray-200 z-50 overflow-hidden"
              role="listbox"
            >
              <button
                onClick={() => {
                  onExportCSV();
                  setShowExportMenu(false);
                }}
                className="w-full px-4 py-3 text-left text-sm text-gray-700 hover:bg-gray-50 transition-colors flex items-center gap-2"
                role="option"
              >
                <FileSpreadsheet className="w-4 h-4 text-success-600" aria-hidden="true" />
                {t('priceQuery.export.csv')}
              </button>
              <button
                onClick={() => {
                  onExportJSON();
                  setShowExportMenu(false);
                }}
                className="w-full px-4 py-3 text-left text-sm text-gray-700 hover:bg-gray-50 transition-colors flex items-center gap-2"
                role="option"
              >
                <FileJson className="w-4 h-4 text-primary-600" aria-hidden="true" />
                {t('priceQuery.export.json')}
              </button>
              <button
                onClick={() => {
                  onOpenExportConfig();
                  setShowExportMenu(false);
                }}
                className="w-full px-4 py-3 text-left text-sm text-gray-700 hover:bg-gray-50 transition-colors flex items-center gap-2 border-t border-gray-100"
                role="option"
              >
                <Settings2 className="w-4 h-4 text-purple-600" aria-hidden="true" />
                {t('priceQuery.export.advanced')}
              </button>
            </div>
          )}
        </div>
      </nav>

      {/* 点击外部关闭下拉菜单 */}
      {(showHistory || showExportMenu) && (
        <div
          className="fixed inset-0 z-40"
          onClick={() => {
            setShowHistory(false);
            setShowExportMenu(false);
          }}
          aria-hidden="true"
        />
      )}
    </header>
  );
}

'use client';

/**
 * @fileoverview 查询结果展示组件
 * @description 展示价格查询的结果，包括统计、图表和表格
 */

import { TrendingUp } from 'lucide-react';

import { type TimeComparisonConfig, type TimePeriod } from '@/components/comparison/types';
import { ChartSkeleton, EmptyStateEnhanced, ProgressBar, SegmentedControl } from '@/components/ui';
import { useTranslations } from '@/i18n';
import { type OracleProvider, type Blockchain } from '@/lib/oracles';

import { type QueryResult, type PriceData } from '../constants';
import { type QueryError } from '../hooks/usePriceQuery';

import {
  StatsGrid,
  PriceResultsTable,
  PriceChart,
  QuickLinks,
  DataQualityPanel,
  DataSourceSection,
  UnifiedExportSection,
  TimeComparisonSection,
  ErrorBanner,
} from './index';

interface ChartDataPoint {
  timestamp: number;
  time: string;
  [key: string]: number | string;
}

interface QueryResultsProps {
  isLoading: boolean;
  queryResults: QueryResult[];
  filteredQueryResults: QueryResult[];
  historicalData: Partial<Record<string, PriceData[]>>;
  isCompareMode: boolean;
  compareQueryResults: QueryResult[];
  compareHistoricalData: Partial<Record<string, PriceData[]>>;
  showBaseline: boolean;
  avgPrice: number;
  compareAvgPrice: number;
  maxPrice: number;
  minPrice: number;
  compareMaxPrice: number;
  compareMinPrice: number;
  priceRange: number;
  comparePriceRange: number;
  standardDeviation: number;
  standardDeviationPercent: number;
  avgChange24hPercent?: number;
  compareAvgChange24hPercent?: number;
  validPrices: number[];
  compareValidPrices: number[];
  chartData: ChartDataPoint[];
  compareChartData: ChartDataPoint[];
  queryDuration: number | null;
  queryProgress: { completed: number; total: number };
  currentQueryTarget: { oracle: OracleProvider | null; chain: Blockchain | null };
  filterText: string;
  setFilterText: (text: string) => void;
  sortField: 'oracle' | 'blockchain' | 'price' | 'timestamp';
  sortDirection: 'asc' | 'desc';
  onSort: (field: 'oracle' | 'blockchain' | 'price' | 'timestamp') => void;
  selectedRow: string | null;
  onRowSelect: (row: string | null) => void;
  hiddenSeries: Set<string>;
  onToggleSeries: (seriesName: string) => void;
  selectedTimeRange: number;
  selectedSymbol: string;
  setSelectedSymbol: (symbol: string) => void;
  onRefresh: () => void;
  chartContainerRef: React.RefObject<HTMLDivElement | null>;
  timeComparisonConfig: TimeComparisonConfig;
  onTimeConfigChange: (config: TimeComparisonConfig) => void;
  filterInputRef?: React.RefObject<HTMLInputElement | null>;
  queryErrors: QueryError[];
  onRetryDataSource: (provider: OracleProvider, chain: Blockchain) => void;
  onRetryAllErrors: () => void;
  onClearErrors: () => void;
}

/**
 * 查询结果展示组件
 *
 * @param props - 组件属性
 * @returns 查询结果 JSX 元素
 */
export function QueryResults({
  isLoading,
  queryResults,
  filteredQueryResults,
  historicalData,
  isCompareMode,
  compareQueryResults,
  compareHistoricalData,
  showBaseline,
  avgPrice,
  compareAvgPrice,
  maxPrice,
  minPrice,
  compareMaxPrice,
  compareMinPrice,
  priceRange,
  comparePriceRange,
  standardDeviation,
  standardDeviationPercent,
  avgChange24hPercent,
  compareAvgChange24hPercent,
  validPrices,
  compareValidPrices,
  chartData,
  compareChartData,
  queryDuration,
  queryProgress,
  currentQueryTarget,
  filterText,
  setFilterText,
  sortField,
  sortDirection,
  onSort,
  selectedRow,
  onRowSelect,
  hiddenSeries,
  onToggleSeries,
  selectedTimeRange,
  selectedSymbol,
  setSelectedSymbol,
  onRefresh,
  chartContainerRef,
  timeComparisonConfig,
  onTimeConfigChange,
  filterInputRef,
  queryErrors,
  onRetryDataSource,
  onRetryAllErrors,
  onClearErrors,
}: QueryResultsProps) {
  const t = useTranslations();

  // 加载状态
  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-semibold text-gray-900">{t('priceQuery.loadingData')}</h3>
            <span className="text-xs text-gray-500">
              {queryProgress.completed} / {queryProgress.total}
            </span>
          </div>
          <ProgressBar
            progress={queryProgress.completed}
            total={queryProgress.total}
            showPercentage={true}
            size="md"
            variant="default"
          />
          <p className="text-xs text-gray-500 mt-2">
            {t('priceQuery.querying')}{' '}
            {currentQueryTarget.oracle && t(`navbar.${currentQueryTarget.oracle.toLowerCase()}`)}{' '}
            {currentQueryTarget.chain && t(`blockchain.${currentQueryTarget.chain.toLowerCase()}`)}
          </p>
        </div>
        <ChartSkeleton height={300} variant="price" showToolbar={true} />
      </div>
    );
  }

  // 空状态
  if (queryResults.length === 0) {
    return (
      <EmptyStateEnhanced
        type="search"
        title={t('priceQuery.noResults.title', { symbol: selectedSymbol })}
        description={t('priceQuery.noResults.description')}
        size="lg"
        variant="page"
      >
        <div className="mt-8 pt-6 border-t border-gray-100 w-full max-w-md">
          <p className="text-xs text-gray-400 mb-4 flex items-center justify-center gap-1">
            <TrendingUp className="w-3 h-3" aria-hidden="true" />
            {t('priceQuery.noResults.popularTokens')}
          </p>
          <div className="flex items-center justify-center">
            <SegmentedControl
              options={['BTC', 'ETH', 'SOL', 'AVAX', 'LINK', 'UNI'].map((token) => ({
                value: token,
                label: token,
              }))}
              value={selectedSymbol}
              onChange={(value) => setSelectedSymbol(value as string)}
              size="sm"
            />
          </div>
        </div>
      </EmptyStateEnhanced>
    );
  }

  return (
    <div className="space-y-6">
      {/* 错误提示横幅 */}
      {queryErrors.length > 0 && (
        <ErrorBanner
          errors={queryErrors}
          onRetry={onRetryDataSource}
          onRetryAll={onRetryAllErrors}
          onDismiss={onClearErrors}
        />
      )}

      {/* 统计网格 */}
      <StatsGrid
        avgPrice={avgPrice}
        maxPrice={maxPrice}
        minPrice={minPrice}
        priceRange={priceRange}
        standardDeviation={standardDeviation}
        standardDeviationPercent={standardDeviationPercent}
        dataPoints={queryResults.length}
        queryDuration={queryDuration}
        avgChange24hPercent={avgChange24hPercent}
        prices={validPrices}
        compareMode={isCompareMode}
        compareAvgPrice={compareAvgPrice}
        compareMaxPrice={compareMaxPrice}
        compareMinPrice={compareMinPrice}
        comparePriceRange={comparePriceRange}
        compareAvgChange24hPercent={compareAvgChange24hPercent}
        comparePrices={compareValidPrices}
      />

      {/* 数据质量面板 */}
      <DataQualityPanel results={queryResults} historicalData={historicalData} />

      {/* 数据源和导出区域 */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <DataSourceSection
          results={queryResults}
          lastUpdated={
            queryResults.length > 0
              ? new Date(Math.max(...queryResults.map((r) => r.priceData.timestamp)))
              : null
          }
          onRefresh={onRefresh}
          isLoading={isLoading}
        />
        <UnifiedExportSection
          loading={isLoading}
          queryResults={queryResults}
          chartContainerRef={chartContainerRef}
          selectedSymbol={selectedSymbol}
          avgPrice={avgPrice}
          maxPrice={maxPrice}
          minPrice={minPrice}
          priceRange={priceRange}
          standardDeviation={standardDeviation}
          standardDeviationPercent={standardDeviationPercent}
        />
      </div>

      {/* 图表和表格区域 - 2xl以上使用3:2比例布局 */}
      <div className="grid grid-cols-1 2xl:grid-cols-5 gap-6">
        {/* 价格图表 - 占3/5 */}
        <div ref={chartContainerRef} className="min-w-0 2xl:col-span-3 order-1 2xl:order-1">
          <PriceChart
            chartData={chartData}
            queryResults={queryResults}
            hiddenSeries={hiddenSeries}
            onToggleSeries={onToggleSeries}
            selectedTimeRange={selectedTimeRange}
            selectedRow={selectedRow}
            compareMode={isCompareMode}
            compareChartData={compareChartData}
            compareQueryResults={compareQueryResults}
            showBaseline={showBaseline}
            avgPrice={avgPrice}
          />
        </div>

        {/* 价格结果表格 - 占2/5 */}
        <div className="2xl:col-span-2 order-2 2xl:order-2">
          <PriceResultsTable
            results={queryResults}
            filteredResults={filteredQueryResults}
            filterText={filterText}
            setFilterText={setFilterText}
            sortField={sortField}
            sortDirection={sortDirection}
            onSort={onSort}
            avgPrice={avgPrice}
            selectedRow={selectedRow}
            onRowSelect={onRowSelect}
            historicalData={historicalData}
            filterInputRef={filterInputRef}
          />
        </div>
      </div>

      {/* 时间对比区域 */}
      {isCompareMode && chartData.length > 0 && compareChartData.length > 0 && (
        <TimeComparisonSection
          chartData={chartData}
          compareChartData={compareChartData}
          queryResults={queryResults}
          compareQueryResults={compareQueryResults}
          timeConfig={timeComparisonConfig}
          onTimeConfigChange={onTimeConfigChange}
          hiddenSeries={hiddenSeries}
        />
      )}

      {/* 快速链接 */}
      <QuickLinks />
    </div>
  );
}

