'use client';

import { useState, useCallback, useEffect } from 'react';

import { type OracleProvider, type Blockchain } from '@/lib/oracles';
import { getQueryHistory, clearQueryHistory, type QueryHistoryItem } from '@/utils/queryHistory';

export interface UsePriceQueryHistoryParams {
  setSelectedOracles: (oracles: OracleProvider[]) => void;
  setSelectedChains: (chains: Blockchain[]) => void;
  setSelectedSymbol: (symbol: string) => void;
  setSelectedTimeRange: (timeRange: number) => void;
}

export interface UsePriceQueryHistoryReturn {
  showHistory: boolean;
  setShowHistory: (show: boolean) => void;
  historyItems: QueryHistoryItem[];
  handleHistorySelect: (item: QueryHistoryItem) => void;
  handleClearHistory: () => void;
}

export function usePriceQueryHistory(
  params: UsePriceQueryHistoryParams
): UsePriceQueryHistoryReturn {
  const { setSelectedOracles, setSelectedChains, setSelectedSymbol, setSelectedTimeRange } = params;

  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<QueryHistoryItem[]>([]);

  const handleHistorySelect = useCallback(
    (item: QueryHistoryItem) => {
      setSelectedOracles(item.oracles);
      setSelectedChains(item.chains);
      setSelectedSymbol(item.symbol);
      setSelectedTimeRange(item.timeRange);
    },
    [setSelectedOracles, setSelectedChains, setSelectedSymbol, setSelectedTimeRange]
  );

  const handleClearHistory = useCallback(() => {
    clearQueryHistory();
    setHistoryItems([]);
  }, []);

  useEffect(() => {
    setHistoryItems(getQueryHistory());
  }, []);

  return {
    showHistory,
    setShowHistory,
    historyItems,
    handleHistorySelect,
    handleClearHistory,
  };
}

'use client';

import { useState, useCallback, useEffect, useRef } from 'react';

import { usePreferences } from '@/hooks';
import { OracleProvider, Blockchain } from '@/lib/oracles';
import { parseQueryParams, updateUrlParams, type QueryConfig } from '@/utils/urlParams';

export interface TimeComparisonConfig {
  primaryPeriod: {
    id: string;
    label: string;
    startDate: Date;
    endDate: Date;
    range: '1h' | '24h' | '7d' | '30d' | '90d' | '1y' | 'custom';
  };
  comparisonPeriod: {
    id: string;
    label: string;
    startDate: Date;
    endDate: Date;
    range: '1h' | '24h' | '7d' | '30d' | '90d' | '1y' | 'custom';
  };
  comparisonType: 'previous' | 'custom' | 'year_over_year';
}

export interface UsePriceQueryStateReturn {
  selectedOracles: OracleProvider[];
  setSelectedOracles: (oracles: OracleProvider[]) => void;
  selectedChains: Blockchain[];
  setSelectedChains: (chains: Blockchain[]) => void;
  selectedSymbol: string;
  setSelectedSymbol: (symbol: string) => void;
  selectedTimeRange: number;
  setSelectedTimeRange: (timeRange: number) => void;
  filterText: string;
  setFilterText: (text: string) => void;
  sortField: 'oracle' | 'blockchain' | 'price' | 'timestamp';
  sortDirection: 'asc' | 'desc';
  hiddenSeries: Set<string>;
  setHiddenSeries: (series: Set<string>) => void;
  isCompareMode: boolean;
  setIsCompareMode: (mode: boolean) => void;
  compareTimeRange: number;
  setCompareTimeRange: (timeRange: number) => void;
  showBaseline: boolean;
  setShowBaseline: (show: boolean) => void;
  timeComparisonConfig: TimeComparisonConfig;
  setTimeComparisonConfig: (config: TimeComparisonConfig) => void;
  urlParamsParsed: boolean;
  selectedRow: string | null;
  setSelectedRow: (row: string | null) => void;
  toggleSeries: (seriesName: string) => void;
  handleSort: (field: 'oracle' | 'blockchain' | 'price' | 'timestamp') => void;
  selectedOraclesRef: React.MutableRefObject<OracleProvider[]>;
  selectedChainsRef: React.MutableRefObject<Blockchain[]>;
  selectedSymbolRef: React.MutableRefObject<string>;
  selectedTimeRangeRef: React.MutableRefObject<number>;
  isCompareModeRef: React.MutableRefObject<boolean>;
  compareTimeRangeRef: React.MutableRefObject<number>;
}

export function usePriceQueryState(): UsePriceQueryStateReturn {
  const { preferences, isLoading: isPrefsLoading } = usePreferences();

  const [selectedOracles, setSelectedOracles] = useState<OracleProvider[]>([
    OracleProvider.CHAINLINK,
  ]);
  const [selectedChains, setSelectedChains] = useState<Blockchain[]>([Blockchain.ETHEREUM]);
  const [selectedSymbol, setSelectedSymbol] = useState<string>('BTC');
  const [selectedTimeRange, setSelectedTimeRange] = useState<number>(24);
  const [filterText, setFilterText] = useState<string>('');
  const [sortField, setSortField] = useState<'oracle' | 'blockchain' | 'price' | 'timestamp'>(
    'oracle'
  );
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');
  const [hiddenSeries, setHiddenSeries] = useState<Set<string>>(new Set());
  const [isCompareMode, setIsCompareMode] = useState<boolean>(false);
  const [compareTimeRange, setCompareTimeRange] = useState<number>(24);
  const [showBaseline, setShowBaseline] = useState<boolean>(false);
  const [selectedRow, setSelectedRow] = useState<string | null>(null);
  const [urlParamsParsed, setUrlParamsParsed] = useState(false);

  const [timeComparisonConfig, setTimeComparisonConfig] = useState<TimeComparisonConfig>(() => {
    const now = new Date();
    const start = new Date(now.getTime() - 24 * 60 * 60 * 1000);
    return {
      primaryPeriod: {
        id: 'primary-24h',
        label: 'Last 24h',
        startDate: start,
        endDate: now,
        range: '24h',
      },
      comparisonPeriod: {
        id: 'comparison-24h',
        label: 'Previous Period',
        startDate: new Date(start.getTime() - 24 * 60 * 60 * 1000),
        endDate: start,
        range: '24h',
      },
      comparisonType: 'previous',
    };
  });

  const selectedOraclesRef = useRef<OracleProvider[]>(selectedOracles);
  const selectedChainsRef = useRef<Blockchain[]>(selectedChains);
  const selectedSymbolRef = useRef<string>(selectedSymbol);
  const selectedTimeRangeRef = useRef<number>(selectedTimeRange);
  const isCompareModeRef = useRef<boolean>(isCompareMode);
  const compareTimeRangeRef = useRef<number>(compareTimeRange);

  const applyPreferences = useCallback(() => {
    if (isPrefsLoading) return;

    const oracleMapping: Record<string, OracleProvider> = {
      chainlink: OracleProvider.CHAINLINK,
      'band-protocol': OracleProvider.BAND_PROTOCOL,
      uma: OracleProvider.UMA,
      pyth: OracleProvider.PYTH,
      api3: OracleProvider.API3,
      redstone: OracleProvider.REDSTONE,
      dia: OracleProvider.DIA,
      tellor: OracleProvider.TELLOR,
      chronicle: OracleProvider.CHRONICLE,
      winklink: OracleProvider.WINKLINK,
    };

    const timeRangeMapping: Record<string, number> = {
      '1h': 1,
      '6h': 6,
      '24h': 24,
      '7d': 168,
      '30d': 720,
    };

    const defaultOracle = oracleMapping[preferences.defaultOracle] || OracleProvider.CHAINLINK;
    const defaultTimeRange = timeRangeMapping[preferences.defaultTimeRange] || 24;
    const defaultSymbol = preferences.defaultSymbol.split('/')[0] || 'BTC';

    setSelectedOracles([defaultOracle]);
    setSelectedSymbol(defaultSymbol);
    setSelectedTimeRange(defaultTimeRange);
  }, [preferences, isPrefsLoading]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const config = parseQueryParams(window.location.search);

    const hasUrlParams =
      config.oracles?.length || config.chains?.length || config.symbol || config.timeRange;

    if (!hasUrlParams) {
      applyPreferences();
    } else {
      setSelectedOracles((prev) =>
        config.oracles && config.oracles.length > 0 ? config.oracles : prev
      );
      setSelectedChains((prev) =>
        config.chains && config.chains.length > 0 ? config.chains : prev
      );
      setSelectedSymbol((prev) => (config.symbol ? config.symbol : prev));
      setSelectedTimeRange((prev) => (config.timeRange ? config.timeRange : prev));
    }
    setUrlParamsParsed(true);
  }, [applyPreferences]);

  useEffect(() => {
    selectedOraclesRef.current = selectedOracles;
    selectedChainsRef.current = selectedChains;
    selectedSymbolRef.current = selectedSymbol;
    selectedTimeRangeRef.current = selectedTimeRange;
    isCompareModeRef.current = isCompareMode;
    compareTimeRangeRef.current = compareTimeRange;
  }, [
    selectedOracles,
    selectedChains,
    selectedSymbol,
    selectedTimeRange,
    isCompareMode,
    compareTimeRange,
  ]);

  useEffect(() => {
    if (!urlParamsParsed) return;
    const config: QueryConfig = {
      oracles: selectedOracles,
      chains: selectedChains,
      symbol: selectedSymbol,
      timeRange: selectedTimeRange,
    };
    updateUrlParams(config);
  }, [selectedOracles, selectedChains, selectedSymbol, selectedTimeRange, urlParamsParsed]);

  const toggleSeries = useCallback((seriesName: string) => {
    setHiddenSeries((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(seriesName)) {
        newSet.delete(seriesName);
      } else {
        newSet.add(seriesName);
      }
      return newSet;
    });
  }, []);

  const handleSort = useCallback((field: 'oracle' | 'blockchain' | 'price' | 'timestamp') => {
    setSortField((prev) => {
      if (prev === field) {
        setSortDirection((dir) => (dir === 'asc' ? 'desc' : 'asc'));
        return prev;
      } else {
        setSortDirection('asc');
        return field;
      }
    });
  }, []);

  return {
    selectedOracles,
    setSelectedOracles,
    selectedChains,
    setSelectedChains,
    selectedSymbol,
    setSelectedSymbol,
    selectedTimeRange,
    setSelectedTimeRange,
    filterText,
    setFilterText,
    sortField,
    sortDirection,
    hiddenSeries,
    setHiddenSeries,
    isCompareMode,
    setIsCompareMode,
    compareTimeRange,
    setCompareTimeRange,
    showBaseline,
    setShowBaseline,
    timeComparisonConfig,
    setTimeComparisonConfig,
    urlParamsParsed,
    selectedRow,
    setSelectedRow,
    toggleSeries,
    handleSort,
    selectedOraclesRef,
    selectedChainsRef,
    selectedSymbolRef,
    selectedTimeRangeRef,
    isCompareModeRef,
    compareTimeRangeRef,
  };
}

'use client';

import {
  useQuery,
  useQueries,
  useQueryClient,
  type UseQueryOptions,
  type UseQueryResult,
} from '@tanstack/react-query';

import { getOracleClient } from '@/lib/oracles';
import { STALE_TIME_CONFIG, GC_TIME_CONFIG } from '@/providers/ReactQueryProvider';
import type { OracleProvider, Blockchain, PriceData } from '@/types/oracle';

import { CACHE_CONFIG, historicalCache, createCacheKey } from '../utils/cacheUtils';

import { priceQueryKeys } from './queryKeys';

export interface UseHistoricalDataOptions {
  provider: OracleProvider;
  chain: Blockchain;
  symbol: string;
  timeRange: number;
  enabled?: boolean;
  staleTime?: number;
  gcTime?: number;
  retry?: number;
}

export interface UseHistoricalDataReturn {
  data: PriceData[] | undefined;
  isLoading: boolean;
  isError: boolean;
  error: Error | null;
  refetch: () => Promise<void>;
  isFetching: boolean;
  dataUpdatedAt: number | undefined;
  clearCache: () => void;
  cacheStats: { size: number; remainingTTL: number };
}

export function useHistoricalData(options: UseHistoricalDataOptions): UseHistoricalDataReturn {
  const {
    provider,
    chain,
    symbol,
    timeRange,
    enabled = true,
    staleTime = CACHE_CONFIG.HISTORICAL_TTL,
    gcTime = GC_TIME_CONFIG.history,
    retry = 2,
  } = options;

  const queryClient = useQueryClient();
  const cacheKey = createCacheKey('historical', provider, chain, symbol, timeRange);

  const queryResult = useQuery({
    queryKey: priceQueryKeys.historicalData(provider, chain, symbol, timeRange),
    queryFn: async (): Promise<PriceData[]> => {
      const cachedData = historicalCache.get(cacheKey) as PriceData[] | undefined;
      if (cachedData) {
        return cachedData;
      }

      const client = getOracleClient(provider);
      const historicalData = await client.getHistoricalPrices(symbol, chain, timeRange);
      const result = historicalData.map((data) => ({
        ...data,
        provider,
        chain,
      }));

      historicalCache.set(cacheKey, result, CACHE_CONFIG.HISTORICAL_TTL);

      return result;
    },
    enabled,
    staleTime,
    gcTime,
    retry,
    refetchOnWindowFocus: false,
  });

  const clearCache = () => {
    historicalCache.clear(cacheKey);
    queryClient.removeQueries({
      queryKey: priceQueryKeys.historicalData(provider, chain, symbol, timeRange),
    });
  };

  const cacheStats = {
    size: historicalCache.getSize(),
    remainingTTL: historicalCache.getRemainingTTL(cacheKey),
  };

  return {
    data: queryResult.data,
    isLoading: queryResult.isLoading,
    isError: queryResult.isError,
    error: queryResult.error,
    refetch: async () => {
      historicalCache.clear(cacheKey);
      await queryResult.refetch();
    },
    isFetching: queryResult.isFetching,
    dataUpdatedAt: queryResult.dataUpdatedAt,
    clearCache,
    cacheStats,
  };
}

export interface HistoricalDataQuery {
  provider: OracleProvider;
  chain: Blockchain;
  symbol: string;
  timeRange: number;
}

export interface UseMultiHistoricalDataOptions {
  queries: HistoricalDataQuery[];
  enabled?: boolean;
  staleTime?: number;
  gcTime?: number;
  retry?: number;
}

export function useMultiHistoricalData(
  options: UseMultiHistoricalDataOptions
): UseQueryResult<PriceData[], Error>[] {
  const {
    queries,
    enabled = true,
    staleTime = CACHE_CONFIG.HISTORICAL_TTL,
    gcTime = GC_TIME_CONFIG.history,
    retry = 2,
  } = options;

  return useQueries({
    queries: queries.map((query): UseQueryOptions<PriceData[], Error, PriceData[]> => {
      const cacheKey = createCacheKey(
        'historical',
        query.provider,
        query.chain,
        query.symbol,
        query.timeRange
      );

      return {
        queryKey: priceQueryKeys.historicalData(
          query.provider,
          query.chain,
          query.symbol,
          query.timeRange
        ),
        queryFn: async (): Promise<PriceData[]> => {
          const cachedData = historicalCache.get(cacheKey) as PriceData[] | undefined;
          if (cachedData) {
            return cachedData;
          }

          const client = getOracleClient(query.provider);
          const historicalData = await client.getHistoricalPrices(
            query.symbol,
            query.chain,
            query.timeRange
          );
          const result = historicalData.map((data) => ({
            ...data,
            provider: query.provider,
            chain: query.chain,
          }));

          historicalCache.set(cacheKey, result, CACHE_CONFIG.HISTORICAL_TTL);

          return result;
        },
        enabled,
        staleTime,
        gcTime,
        retry,
        refetchOnWindowFocus: false,
      };
    }),
  });
}

export interface UseComparisonDataOptions {
  symbol: string;
  providers: OracleProvider[];
  chains: Blockchain[];
  primaryTimeRange: number;
  compareTimeRange?: number;
  enabled?: boolean;
}

export interface ComparisonDataSet {
  provider: OracleProvider;
  chain: Blockchain;
  primaryData: PriceData[] | undefined;
  compareData: PriceData[] | undefined;
  isPrimaryLoading: boolean;
  isCompareLoading: boolean;
}

export function useComparisonData(options: UseComparisonDataOptions): ComparisonDataSet[] {
  const { symbol, providers, chains, primaryTimeRange, compareTimeRange, enabled = true } = options;

  const primaryQueries: HistoricalDataQuery[] = [];
  const compareQueries: HistoricalDataQuery[] = [];

  for (const provider of providers) {
    const client = getOracleClient(provider);
    const supportedChains = client.supportedChains;

    for (const chain of chains) {
      if (supportedChains.includes(chain)) {
        primaryQueries.push({ provider, chain, symbol, timeRange: primaryTimeRange });

        if (compareTimeRange) {
          compareQueries.push({ provider, chain, symbol, timeRange: compareTimeRange });
        }
      }
    }
  }

  const primaryResults = useMultiHistoricalData({ queries: primaryQueries, enabled });
  const compareResults = useMultiHistoricalData({
    queries: compareQueries,
    enabled: enabled && !!compareTimeRange,
  });

  const result: ComparisonDataSet[] = [];

  primaryQueries.forEach((query, index) => {
    const compareIndex = compareQueries.findIndex(
      (cq) => cq.provider === query.provider && cq.chain === query.chain
    );

    result.push({
      provider: query.provider,
      chain: query.chain,
      primaryData: primaryResults[index]?.data,
      compareData: compareIndex >= 0 ? compareResults[compareIndex]?.data : undefined,
      isPrimaryLoading: primaryResults[index]?.isLoading ?? false,
      isCompareLoading:
        compareIndex >= 0 ? (compareResults[compareIndex]?.isLoading ?? false) : false,
    });
  });

  return result;
}

