      });

      it('should reject non-array input', () => {
        const result = validateTimeSeries('not an array' as unknown as PriceData[]);

        expect(result.isValid).toBe(false);
        expect(result.errors).toContain('数据必须是数组');
      });

      it('should warn about empty array', () => {
        const result = validateTimeSeries([]);

        expect(result.isValid).toBe(true);
        expect(result.warnings).toContain('时间序列数据为空');
      });
    });

    describe('价格验证', () => {
      it('should validate all prices in series', () => {
        const now = Date.now();
        const data: PriceData[] = [
          createPriceData(100, now - 2000),
          createPriceData(-50, now - 1000),
          createPriceData(102, now),
        ];

        const result = validateTimeSeries(data);

        expect(result.isValid).toBe(false);
        expect(result.errors.some((e) => e.includes('价格必须为正数'))).toBe(true);
      });
    });

    describe('时间戳验证', () => {
      it('should validate all timestamps in series', () => {
        const now = Date.now();
        const data: PriceData[] = [
          createPriceData(100, now - 2000),
          createPriceData(101, now + 10000),
          createPriceData(102, now),
        ];

        const result = validateTimeSeries(data);

        expect(result.isValid).toBe(false);
        expect(result.errors.some((e) => e.includes('时间戳不能在未来'))).toBe(true);
      });
    });

    describe('数据间隙检测', () => {
      it('should detect gap in data', () => {
        const now = Date.now();
        const data: PriceData[] = [
          createPriceData(100, now - 30 * 60 * 1000),
          createPriceData(101, now),
        ];

        const result = validateTimeSeries(data);

        expect(result.anomalies.some((a) => a.type === 'gap_in_data')).toBe(true);
        expect(result.warnings.some((w) => w.includes('数据间隙'))).toBe(true);
      });

      it('should not flag normal intervals', () => {
        const now = Date.now();
        const data: PriceData[] = [createPriceData(100, now - 5000), createPriceData(101, now)];

        const result = validateTimeSeries(data);

        expect(result.anomalies.some((a) => a.type === 'gap_in_data')).toBe(false);
      });

      it('should assign correct severity for gaps', () => {
        const now = Date.now();
        const data1: PriceData[] = [
          createPriceData(100, now - 15 * 60 * 1000),
          createPriceData(101, now),
        ];
        const result1 = validateTimeSeries(data1);
        const gapAnomaly1 = result1.anomalies.find((a) => a.type === 'gap_in_data');
        expect(gapAnomaly1?.severity).toBe('low');

        const data2: PriceData[] = [
          createPriceData(100, now - 40 * 60 * 1000),
          createPriceData(101, now),
        ];
        const result2 = validateTimeSeries(data2);
        const gapAnomaly2 = result2.anomalies.find((a) => a.type === 'gap_in_data');
        expect(gapAnomaly2?.severity).toBe('medium');

        const data3: PriceData[] = [
          createPriceData(100, now - 70 * 60 * 1000),
          createPriceData(101, now),
        ];
        const result3 = validateTimeSeries(data3);
        const gapAnomaly3 = result3.anomalies.find((a) => a.type === 'gap_in_data');
        expect(gapAnomaly3?.severity).toBe('high');
      });
    });

    describe('价格变化检测', () => {
      it('should detect price anomalies in series', () => {
        const now = Date.now();
        const data: PriceData[] = [
          createPriceData(100, now - 2000),
          createPriceData(200, now - 1000),
          createPriceData(102, now),
        ];

        const result = validateTimeSeries(data);

        expect(
          result.anomalies.some((a) => a.type === 'price_spike' || a.type === 'price_drop')
        ).toBe(true);
      });
    });

    describe('数据排序', () => {
      it('should handle unsorted data', () => {
        const now = Date.now();
        const data: PriceData[] = [
          createPriceData(102, now),
          createPriceData(100, now - 2000),
          createPriceData(101, now - 1000),
        ];

        const result = validateTimeSeries(data);

        expect(result.isValid).toBe(true);
      });
    });
  });

  describe('detectAnomalies', () => {
    describe('基本功能', () => {
      it('should detect anomalies in price array', () => {
        const prices = [100, 101, 102, 500, 103, 104];
        const anomalies = detectAnomalies(prices);

        expect(anomalies.length).toBeGreaterThan(0);
        expect(anomalies).toContain(3);
      });

      it('should return empty array for small arrays', () => {
        expect(detectAnomalies([1, 2, 3])).toEqual([]);
        expect(detectAnomalies([1])).toEqual([]);
        expect(detectAnomalies([])).toEqual([]);
      });
    });

    describe('无效数据处理', () => {
      it('should filter out invalid prices', () => {
        const prices = [100, NaN, 102, -50, 104, Infinity, 106];
        const anomalies = detectAnomalies(prices);

        expect(anomalies).toBeDefined();
      });

      it('should return empty for all invalid prices', () => {
        const prices = [NaN, -1, Infinity, -Infinity];
        const anomalies = detectAnomalies(prices);

        expect(anomalies).toEqual([]);
      });
    });

    describe('异常检测算法', () => {
      it('should detect outliers using IQR method', () => {
        const prices = [10, 11, 12, 13, 14, 15, 16, 17, 18, 100];
        const anomalies = detectAnomalies(prices);

        expect(anomalies).toContain(9);
      });

      it('should detect outliers using Z-Score method', () => {
        const normalPrices = Array.from({ length: 20 }, (_, i) => 100 + i);
        const prices = [...normalPrices, 1000];
        const anomalies = detectAnomalies(prices);

        expect(anomalies.length).toBeGreaterThan(0);
      });

      it('should not flag normal prices as anomalies', () => {
        const prices = Array.from({ length: 50 }, (_, i) => 100 + Math.random() * 10);
        const anomalies = detectAnomalies(prices);

        expect(anomalies.length).toBe(0);
      });
    });

    describe('边界情况', () => {
      it('should handle all identical values', () => {
        const prices = [100, 100, 100, 100, 100];
        const anomalies = detectAnomalies(prices);

        expect(anomalies).toEqual([]);
      });

      it('should handle prices with zero standard deviation', () => {
        const prices = [100, 100, 100, 100, 200];
        const anomalies = detectAnomalies(prices);

        expect(anomalies).toBeDefined();
      });
    });
  });

  describe('calculatePriceStatistics', () => {
    it('should calculate statistics correctly', () => {
      const prices = [10, 20, 30, 40, 50];
      const stats = calculatePriceStatistics(prices);

      expect(stats).not.toBeNull();
      expect(stats!.mean).toBe(30);
      expect(stats!.median).toBe(30);
      expect(stats!.stdDev).toBeCloseTo(14.14, 1);
      expect(stats!.q1).toBe(20);
      expect(stats!.q3).toBe(40);
      expect(stats!.iqr).toBe(20);
    });

    it('should handle empty array', () => {
      const stats = calculatePriceStatistics([]);

      expect(stats).toBeNull();
    });

    it('should handle single element', () => {
      const stats = calculatePriceStatistics([42]);

      expect(stats!.mean).toBe(42);
      expect(stats!.median).toBe(42);
      expect(stats!.stdDev).toBe(0);
    });

    it('should filter out invalid prices', () => {
      const prices = [10, NaN, 20, -5, 30, Infinity, 40, 50];
      const stats = calculatePriceStatistics(prices);

      expect(stats).not.toBeNull();
      expect(stats!.mean).toBe(30);
    });

    it('should calculate median for even length correctly', () => {
      const prices = [10, 20, 30, 40];
      const stats = calculatePriceStatistics(prices);

      expect(stats!.median).toBe(25);
    });

    it('should calculate median for odd length correctly', () => {
      const prices = [10, 20, 30, 40, 50];
      const stats = calculatePriceStatistics(prices);

      expect(stats!.median).toBe(30);
    });
  });

  describe('isPriceWithinBounds', () => {
    it('should return true for price within bounds', () => {
      expect(isPriceWithinBounds(50, 0, 100)).toBe(true);
      expect(isPriceWithinBounds(0, 0, 100)).toBe(true);
      expect(isPriceWithinBounds(100, 0, 100)).toBe(true);
    });

    it('should return false for price outside bounds', () => {
      expect(isPriceWithinBounds(-1, 0, 100)).toBe(false);
      expect(isPriceWithinBounds(101, 0, 100)).toBe(false);
    });

    it('should handle equal bounds', () => {
      expect(isPriceWithinBounds(50, 50, 50)).toBe(true);
      expect(isPriceWithinBounds(49, 50, 50)).toBe(false);
    });
  });

  describe('getPriceDeviation', () => {
    it('should calculate deviation correctly', () => {
      const deviation = getPriceDeviation(110, 100);

      expect(deviation.absolute).toBe(10);
      expect(deviation.percent).toBe(10);
    });

    it('should handle zero reference price', () => {
      const deviation = getPriceDeviation(100, 0);

      expect(deviation.absolute).toBe(100);
      expect(deviation.percent).toBe(0);
    });

    it('should always return positive values', () => {
      const deviation = getPriceDeviation(90, 100);

      expect(deviation.absolute).toBe(10);
      expect(deviation.percent).toBe(10);
    });

    it('should handle equal prices', () => {
      const deviation = getPriceDeviation(100, 100);

      expect(deviation.absolute).toBe(0);
      expect(deviation.percent).toBe(0);
    });
  });
});

'use client';

import { useMemo, useState, useEffect, useCallback, useRef } from 'react';

import {
  X,
  Activity,
  TrendingUp,
  Clock,
  Shield,
  CheckCircle,
  AlertCircle,
  Zap,
  RefreshCw,
  Wifi,
  WifiOff,
} from 'lucide-react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  ResponsiveContainer,
  AreaChart,
  Area,
} from 'recharts';

import { ConfidenceIntervalChart } from '@/components/oracle/charts/ConfidenceIntervalChart';
import { useTranslations, useLocale } from '@/i18n';
import { isChineseLocale } from '@/i18n/routing';
import { chartColors } from '@/lib/config/colors';
import { PYTH_PRICE_FEED_IDS } from '@/lib/oracles/pythConstants';
import {
  getPythDataService,
  type PublisherData,
  type WebSocketConnectionState,
} from '@/lib/oracles/pythDataService';
import {
  generatePriceHistory,
  getBasePrice,
  type PriceHistoryPoint,
} from '@/lib/oracles/pythMockData';
import { cn } from '@/lib/utils';
import type { PriceData, ConfidenceInterval } from '@/types/oracle';
import { type TooltipProps } from '@/types/ui/recharts';

import { type PriceFeed, type RealtimeState } from '../types';

interface PriceFeedDetailModalProps {
  priceFeed: PriceFeed;
  isOpen: boolean;
  onClose: () => void;
}

interface Publisher {
  id: string;
  name: string;
  stake: number;
  accuracy: number;
  lastUpdate: string;
  status: 'active' | 'inactive';
}

const CustomTooltip = ({ active, payload, label }: TooltipProps) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white p-3 rounded-lg border border-gray-200 shadow-sm">
        <p className="text-sm font-medium text-gray-900 mb-1">{label}</p>
        {payload.map((entry, index: number) => (
          <p key={index} className="text-sm">
            <span className="text-gray-500">{entry.name}:</span>
            <span className="ml-2 font-medium" style={{ color: entry.color }}>
              ${entry.value.toLocaleString()}
            </span>
          </p>
        ))}
      </div>
    );
  }
  return null;
};

export function PriceFeedDetailModal({ priceFeed, isOpen, onClose }: PriceFeedDetailModalProps) {
  const t = useTranslations();
  const locale = useLocale();

  const [realtimePrice, setRealtimePrice] = useState<PriceData | null>(null);
  const [realtimeState, setRealtimeState] = useState<RealtimeState>({
    isConnected: false,
    connectionStatus: 'disconnected',
    lastUpdateLatency: 0,
    priceUpdateAnimation: 'none',
  });
  const [publishers, setPublishers] = useState<Publisher[]>([]);
  const [isLoadingPublishers, setIsLoadingPublishers] = useState(false);
  const [historicalConfidence, setHistoricalConfidence] = useState<number[]>([]);

  const unsubscribePriceRef = useRef<(() => void) | null>(null);
  const unsubscribeConnectionRef = useRef<(() => void) | null>(null);
  const previousPriceRef = useRef<number | null>(null);
  const animationTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const lastUpdateTimeRef = useRef<number>(Date.now());

  const basePrice = useMemo(() => getBasePrice(priceFeed.name), [priceFeed.name]);
  const priceHistory = useMemo(() => generatePriceHistory(basePrice), [basePrice]);

  const currentPrice =
    realtimePrice?.price ?? priceHistory[priceHistory.length - 1]?.price ?? basePrice;
  const previousPrice = priceHistory[priceHistory.length - 2]?.price || basePrice;
  const priceChange =
    realtimePrice?.change24hPercent ?? ((currentPrice - previousPrice) / previousPrice) * 100;
  const isPositive = priceChange >= 0;

  const confidenceInterval: ConfidenceInterval = useMemo(() => {
    if (realtimePrice?.confidenceInterval) {
      return realtimePrice.confidenceInterval;
    }
    const bid = currentPrice * (1 - 0.0001);
    const ask = currentPrice * (1 + 0.0001);
    return {
      bid,
      ask,
      widthPercentage: ((ask - bid) / currentPrice) * 100,
    };
  }, [realtimePrice, currentPrice]);

  const clearAnimationTimeout = useCallback(() => {
    if (animationTimeoutRef.current) {
      clearTimeout(animationTimeoutRef.current);
      animationTimeoutRef.current = null;
    }
  }, []);

  const updatePriceAnimation = useCallback(
    (newPrice: number) => {
      clearAnimationTimeout();

      if (previousPriceRef.current !== null) {
        if (newPrice > previousPriceRef.current) {
          setRealtimeState((prev) => ({ ...prev, priceUpdateAnimation: 'up' }));
        } else if (newPrice < previousPriceRef.current) {
          setRealtimeState((prev) => ({ ...prev, priceUpdateAnimation: 'down' }));
        } else {
          setRealtimeState((prev) => ({ ...prev, priceUpdateAnimation: 'none' }));
        }

        animationTimeoutRef.current = setTimeout(() => {
          setRealtimeState((prev) => ({ ...prev, priceUpdateAnimation: 'none' }));
        }, 500);
      }

      previousPriceRef.current = newPrice;
    },
    [clearAnimationTimeout]
  );

  const handlePriceUpdate = useCallback(
    (updatedPrice: PriceData) => {
      const now = Date.now();
      const latency = now - lastUpdateTimeRef.current;
      lastUpdateTimeRef.current = now;

      setRealtimePrice(updatedPrice);
      setRealtimeState((prev) => ({
        ...prev,
        isConnected: true,
        connectionStatus: 'connected',
        lastUpdateLatency: latency,
      }));

      updatePriceAnimation(updatedPrice.price);

      setHistoricalConfidence((prev) => {
        const newConfidence = updatedPrice.confidence ?? 85;
        const updated = [...prev, newConfidence];
        if (updated.length > 20) {
          return updated.slice(-20);
        }
        return updated;
      });
    },
    [updatePriceAnimation]
  );

  useEffect(() => {
    if (!isOpen) return;

    const pythService = getPythDataService();
    const priceId = PYTH_PRICE_FEED_IDS[priceFeed.name];

    unsubscribeConnectionRef.current = pythService.subscribeToConnectionState(
      (state: WebSocketConnectionState) => {
        setRealtimeState((prev) => ({
          ...prev,
          isConnected: state.isConnected,
          connectionStatus: state.status,
          lastUpdateLatency: state.lastUpdateLatency,
        }));
      }
    );

    if (priceId) {
      try {
        unsubscribePriceRef.current = pythService.subscribeToPriceUpdates(
          priceFeed.name,
          handlePriceUpdate
        );
      } catch (error) {
        console.error('Failed to subscribe to price updates:', error);
      }
    }

    return () => {
      if (unsubscribePriceRef.current) {
        unsubscribePriceRef.current();
        unsubscribePriceRef.current = null;
      }
      if (unsubscribeConnectionRef.current) {
        unsubscribeConnectionRef.current();
        unsubscribeConnectionRef.current = null;
      }
      clearAnimationTimeout();
    };
  }, [isOpen, priceFeed.name, handlePriceUpdate, clearAnimationTimeout]);

  useEffect(() => {
    if (!isOpen) return;

    const fetchPublishers = async () => {
      setIsLoadingPublishers(true);
      try {
        const pythService = getPythDataService();
        const publisherData = await pythService.getPublishers();

        const dateLocale = isChineseLocale(locale) ? 'zh-CN' : 'en-US';
        const formattedPublishers: Publisher[] = publisherData.map((p: PublisherData) => ({
          id: p.id,
          name: p.name,
          stake: p.submissionCount ?? 0,
          accuracy: (p.reliabilityScore ?? 0.95) * 100,
          lastUpdate: new Date(p.lastUpdate ?? Date.now()).toLocaleTimeString(dateLocale),
          status: p.status === 'active' ? 'active' : 'inactive',
        }));

        setPublishers(formattedPublishers);
      } catch (error) {
        console.error('Failed to fetch publishers:', error);
        const dateLocale = isChineseLocale(locale) ? 'zh-CN' : 'en-US';
        const fallbackPublishers: Publisher[] = [
          {
            id: '1',
            name: 'Binance',
            stake: 50000000,
            accuracy: 99.2,
            lastUpdate: new Date().toLocaleTimeString(dateLocale),
            status: 'active',
          },
          {
            id: '2',
            name: 'OKX',
            stake: 45000000,
            accuracy: 99.1,
            lastUpdate: new Date().toLocaleTimeString(dateLocale),
            status: 'active',
          },
          {
            id: '3',
            name: 'Coinbase',
            stake: 40000000,
            accuracy: 99.0,
            lastUpdate: new Date().toLocaleTimeString(dateLocale),
            status: 'active',
          },
          {
            id: '4',
            name: 'Kraken',
            stake: 35000000,
            accuracy: 98.9,
            lastUpdate: new Date().toLocaleTimeString(dateLocale),
            status: 'active',
          },
          {
            id: '5',
            name: 'Bybit',
            stake: 30000000,
            accuracy: 98.8,
            lastUpdate: new Date().toLocaleTimeString(dateLocale),
            status: 'active',
          },
        ];
        setPublishers(fallbackPublishers);
      } finally {
        setIsLoadingPublishers(false);
      }
    };

    fetchPublishers();
  }, [isOpen, locale]);

  const getStatusDisplay = (status: string) => {
    switch (status) {
      case 'active':
        return {
          label: t('pyth.priceFeeds.statusActive'),
          color: 'text-emerald-600',
          bgColor: 'bg-emerald-50',
          icon: <CheckCircle className="w-4 h-4" />,
        };
      case 'paused':
        return {
          label: t('pyth.priceFeeds.statusPaused'),
          color: 'text-amber-600',
          bgColor: 'bg-amber-50',
          icon: <AlertCircle className="w-4 h-4" />,
        };
      case 'deprecated':
        return {
          label: t('pyth.priceFeeds.statusDeprecated'),
          color: 'text-red-600',
          bgColor: 'bg-red-50',
          icon: <AlertCircle className="w-4 h-4" />,
        };
      default:
        return {
          label: status,
          color: 'text-gray-600',
          bgColor: 'bg-gray-50',
          icon: <Activity className="w-4 h-4" />,
        };
    }
  };

  const getCategoryLabel = (category: string) => {
    const labels: Record<string, string> = {
      crypto: t('pyth.priceFeeds.categories.crypto'),
      forex: t('pyth.priceFeeds.categories.forex'),
      commodities: t('pyth.priceFeeds.categories.commodities'),
      equities: t('pyth.priceFeeds.categories.equities'),
    };
    return labels[category] || category;
  };

  const statusDisplay = getStatusDisplay(priceFeed.status);

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
      onClick={onClose}
    >
      <div
        className="bg-white max-w-4xl w-full max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 z-10">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-violet-100 rounded-lg flex items-center justify-center">
                <TrendingUp className="w-5 h-5 text-violet-600" />
              </div>
              <div>
                <h2 className="text-lg font-semibold text-gray-900">{priceFeed.name}</h2>
                <p className="text-sm text-gray-500">
                  {t('pyth.priceFeeds.id')}: {priceFeed.id}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <div className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-gray-100">
                {realtimeState.isConnected ? (
                  <>
                    <Wifi className="w-4 h-4 text-emerald-600" />
                    <span className="text-xs font-medium text-emerald-600">
                      {t('pyth.priceFeeds.realtimeConnected')}
                    </span>
                  </>
                ) : (
                  <>
                    <WifiOff className="w-4 h-4 text-gray-400" />
                    <span className="text-xs font-medium text-gray-500">
                      {realtimeState.connectionStatus === 'connecting'
                        ? t('pyth.priceFeeds.connecting')
                        : t('pyth.priceFeeds.disconnected')}
                    </span>
                  </>
                )}
              </div>
              <button
                onClick={onClose}
                className="p-2 hover:bg-gray-100 rounded-md transition-colors"
              >
                <X className="w-5 h-5 text-gray-500" />
              </button>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-8">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="bg-gray-50 p-4 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <TrendingUp className="w-4 h-4 text-gray-400" />
                <span className="text-sm text-gray-500">{t('pyth.priceFeeds.currentPrice')}</span>
              </div>
              <p
                className={cn(
                  'text-2xl font-bold text-gray-900 transition-colors duration-300',
                  realtimeState.priceUpdateAnimation === 'up' && 'text-emerald-600',
                  realtimeState.priceUpdateAnimation === 'down' && 'text-red-600'
                )}
              >
                $
                {currentPrice.toLocaleString(undefined, {
                  minimumFractionDigits: 2,
                  maximumFractionDigits: 2,
                })}
              </p>
              <p
                className={`text-xs font-medium mt-1 ${isPositive ? 'text-emerald-600' : 'text-red-600'}`}
              >
                {isPositive ? '+' : ''}
                {priceChange.toFixed(4)}%
              </p>
              {realtimeState.isConnected && (
                <p className="text-xs text-gray-400 mt-1 flex items-center gap-1">
                  <RefreshCw className="w-3 h-3 animate-spin" />
                  {realtimeState.lastUpdateLatency}ms
                </p>
              )}
            </div>

            <div className="bg-gray-50 p-4 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <Activity className="w-4 h-4 text-gray-400" />
                <span className="text-sm text-gray-500">
                  {t('pyth.priceFeeds.confidenceInterval')}
                </span>
              </div>
              <p className="text-lg font-bold text-gray-900">
                {confidenceInterval.widthPercentage.toFixed(4)}%
              </p>
              <div className="flex gap-2 mt-1 text-xs text-gray-500">
                <span>Bid: ${confidenceInterval.bid.toFixed(4)}</span>
                <span>Ask: ${confidenceInterval.ask.toFixed(4)}</span>
              </div>
            </div>

            <div className="bg-gray-50 p-4 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <Clock className="w-4 h-4 text-gray-400" />
                <span className="text-sm text-gray-500">
                  {t('pyth.priceFeeds.updateFrequency')}
                </span>
              </div>
              <p className="text-2xl font-bold text-gray-900">{priceFeed.updateFrequency}</p>
              <p className="text-xs text-gray-400 mt-1">{t('pyth.priceFeeds.realTime')}</p>
            </div>

            <div className="bg-gray-50 p-4 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <Shield className="w-4 h-4 text-gray-400" />
                <span className="text-sm text-gray-500">{t('pyth.priceFeeds.reliability')}</span>
              </div>
              <p className="text-2xl font-bold text-emerald-600">{priceFeed.reliability}%</p>
              <p className="text-xs text-gray-400 mt-1">{t('pyth.priceFeeds.last30Days')}</p>
