'use client';

import { useState, useMemo, useRef } from 'react';

import { useVirtualizer } from '@tanstack/react-virtual';
import { Activity, Shield, Clock, Award, ArrowUpDown } from 'lucide-react';

import { useTranslations } from '@/i18n';

import { type PythValidatorsViewProps } from '../types';

type SortField = 'stake' | 'uptime' | 'name' | 'rewards';
type SortOrder = 'asc' | 'desc';

export function PythValidatorsView({ validators, isLoading }: PythValidatorsViewProps) {
  const t = useTranslations();
  const [sortField, setSortField] = useState<SortField>('stake');
  const [sortOrder, setSortOrder] = useState<SortOrder>('desc');

  const sortedValidators = useMemo(() => {
    return [...validators].sort((a, b) => {
      let comparison = 0;
      switch (sortField) {
        case 'stake':
          comparison = (a.stake ?? 0) - (b.stake ?? 0);
          break;
        case 'uptime':
          comparison = (a.uptime ?? 0) - (b.uptime ?? 0);
          break;
        case 'name':
          comparison = a.name.localeCompare(b.name);
          break;
        case 'rewards':
          comparison = (a.rewards ?? 0) - (b.rewards ?? 0);
          break;
      }
      return sortOrder === 'asc' ? comparison : -comparison;
    });
  }, [validators, sortField, sortOrder]);

  const totalValidators = validators.length;
  const activeValidators = validators.filter((v) => v.status === 'active').length;
  const totalStake = validators.reduce((sum, v) => sum + (v.stake ?? 0), 0);
  const avgUptime = validators.length
    ? (validators.reduce((sum, v) => sum + (v.uptime ?? 0), 0) / validators.length).toFixed(1)
    : 0;

  const parentRef = useRef<HTMLDivElement>(null);
  const shouldUseVirtualScroll = sortedValidators.length > 50;

  const virtualizer = useVirtualizer({
    count: sortedValidators.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 53,
    overscan: 5,
  });

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('desc');
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'text-emerald-700 bg-emerald-50';
      case 'inactive':
        return 'text-gray-600 bg-gray-100';
      case 'jailed':
        return 'text-red-700 bg-red-50';
      default:
        return 'text-gray-600 bg-gray-100';
    }
  };

  const getUptimeColor = (uptime: number) => {
    if (uptime >= 99) return 'text-emerald-600';
    if (uptime >= 95) return 'text-amber-600';
    return 'text-red-600';
  };

  return (
    <div className="space-y-8">
      {/* 统计概览 - 行内展示 */}
      <div className="flex flex-wrap items-center gap-6 py-4 border-b border-gray-100">
        <div className="flex items-center gap-2">
          <Activity className="w-4 h-4 text-gray-400" />
          <span className="text-sm text-gray-500">{t('pyth.validators.total')}</span>
          <span className="text-lg font-semibold text-gray-900">{totalValidators}</span>
        </div>
        <div className="w-px h-4 bg-gray-200" />
        <div className="flex items-center gap-2">
          <Shield className="w-4 h-4 text-emerald-500" />
          <span className="text-sm text-gray-500">{t('pyth.validators.active')}</span>
          <span className="text-lg font-semibold text-emerald-600">{activeValidators}</span>
        </div>
        <div className="w-px h-4 bg-gray-200" />
        <div className="flex items-center gap-2">
          <Award className="w-4 h-4 text-gray-400" />
          <span className="text-sm text-gray-500">{t('pyth.validators.totalStaked')}</span>
          <span className="text-lg font-semibold text-gray-900">
            {(totalStake / 1e9).toFixed(2)}B PYTH
          </span>
        </div>
        <div className="w-px h-4 bg-gray-200" />
        <div className="flex items-center gap-2">
          <Clock className="w-4 h-4 text-gray-400" />
          <span className="text-sm text-gray-500">{t('pyth.validators.avgUptime')}</span>
          <span className="text-lg font-semibold text-gray-900">{avgUptime}%</span>
        </div>
      </div>

      {/* 排序控制 */}
      <div className="flex gap-2">
        <button
          onClick={() => handleSort('name')}
          className={`inline-flex items-center gap-1.5 px-3 py-2 text-sm font-medium rounded-md border transition-colors ${
            sortField === 'name'
              ? 'bg-gray-900 text-white border-gray-900'
              : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300'
          }`}
        >
          {t('pyth.validators.sortByName')}
          <ArrowUpDown className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={() => handleSort('stake')}
          className={`inline-flex items-center gap-1.5 px-3 py-2 text-sm font-medium rounded-md border transition-colors ${
            sortField === 'stake'
              ? 'bg-gray-900 text-white border-gray-900'
              : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300'
          }`}
        >
          {t('pyth.validators.sortByStake')}
          <ArrowUpDown className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={() => handleSort('uptime')}
          className={`inline-flex items-center gap-1.5 px-3 py-2 text-sm font-medium rounded-md border transition-colors ${
            sortField === 'uptime'
              ? 'bg-gray-900 text-white border-gray-900'
              : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300'
          }`}
        >
          {t('pyth.validators.sortByUptime')}
          <ArrowUpDown className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={() => handleSort('rewards')}
          className={`inline-flex items-center gap-1.5 px-3 py-2 text-sm font-medium rounded-md border transition-colors ${
            sortField === 'rewards'
              ? 'bg-gray-900 text-white border-gray-900'
              : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300'
          }`}
        >
          {t('pyth.validators.sortByRewards')}
          <ArrowUpDown className="w-3.5 h-3.5" />
        </button>
      </div>

      {/* 数据表格 */}
      <div className="border border-gray-200 rounded-lg overflow-hidden">
        <table className="w-full">
          <thead>
            <tr className="border-b border-gray-200 bg-gray-50">
              <th className="text-left py-3 px-4 font-semibold text-gray-700 text-sm">
                {t('pyth.validators.name')}
              </th>
              <th className="text-left py-3 px-4 font-semibold text-gray-700 text-sm">
                {t('pyth.validators.status')}
              </th>
              <th className="text-right py-3 px-4 font-semibold text-gray-700 text-sm">
                {t('pyth.validators.stake')}
              </th>
              <th className="text-right py-3 px-4 font-semibold text-gray-700 text-sm">
                {t('pyth.validators.uptime')}
              </th>
              <th className="text-right py-3 px-4 font-semibold text-gray-700 text-sm">
                {t('pyth.validators.rewards')}
              </th>
            </tr>
          </thead>
          <tbody>
            {sortedValidators.map((validator) => (
              <tr
                key={validator.id}
                className="border-b border-gray-100 hover:bg-gray-50 transition-colors"
              >
                <td className="py-3 px-4 font-medium text-gray-900">{validator.name}</td>
                <td className="py-3 px-4">
                  <span
                    className={`inline-flex items-center px-2 py-1 rounded-md text-xs font-medium ${getStatusColor(
                      validator.status
                    )}`}
                  >
                    {validator.status === 'active'
                      ? t('pyth.validators.statusActive')
                      : validator.status === 'inactive'
                        ? t('pyth.validators.statusInactive')
                        : t('pyth.validators.statusJailed')}
                  </span>
                </td>
                <td className="py-3 px-4 text-right text-sm">
                  {((validator.stake ?? 0) / 1e6).toFixed(1)}M PYTH
                </td>
                <td className="py-3 px-4 text-right">
                  <span className={`text-sm font-medium ${getUptimeColor(validator.uptime ?? 0)}`}>
                    {validator.uptime ?? 0}%
                  </span>
                </td>
                <td className="py-3 px-4 text-right text-sm">
                  {((validator.rewards ?? 0) / 1e3).toFixed(1)}K PYTH
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* 空状态 */}
      {sortedValidators.length === 0 && (
        <div className="text-center py-12">
          <p className="text-sm text-gray-500">{t('pyth.validators.noResults')}</p>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';

import {
  LoadingState,
  ErrorFallback,
  MobileMenuButton,
  OracleErrorBoundary,
} from '@/components/oracle';
import { MobileSidebar } from '@/components/ui/MobileSidebar';
import { useTranslations } from '@/i18n';

import {
  PythSidebar,
  PythMarketView,
  PythNetworkView,
  PythPublishersView,
  PythValidatorsView,
  PythPriceFeedsView,
  PythRiskView,
  PythCrossChainView,
  PythHero,
} from './components';
import { usePythPage } from './hooks/usePythPage';
import { type PythTabId } from './types';

export default function PythPage() {
  const {
    activeTab,
    config,
    price,
    historicalData,
    networkStats,
    publishers,
    validators,
    isLoading,
    isError,
    error,
    lastUpdated,
    isRefreshing,

    setActiveTab,
    refresh,
    exportData,
    t,
  } = usePythPage();

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const isInitialLoading = isLoading && !price && !historicalData.length && !networkStats;
  const hasCriticalError = isError && !price && error;

  if (isInitialLoading) {
    return <LoadingState themeColor={config.themeColor} />;
  }

  if (hasCriticalError) {
    return <ErrorFallback error={error} onRetry={refresh} themeColor={config.themeColor} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'market':
        return (
          <PythMarketView
            config={config}
            price={price}
            historicalData={historicalData}
            networkStats={networkStats}
            isLoading={isLoading}
          />
        );
      case 'network':
        return (
          <PythNetworkView config={config} networkStats={networkStats} isLoading={isLoading} />
        );
      case 'publishers':
        return <PythPublishersView publishers={publishers} isLoading={isLoading} />;
      case 'validators':
        return <PythValidatorsView validators={validators} isLoading={isLoading} />;
      case 'price-feeds':
        return <PythPriceFeedsView isLoading={isLoading} />;
      case 'risk':
        return <PythRiskView isLoading={isLoading} />;
      case 'cross-chain':
        return <PythCrossChainView isLoading={isLoading} />;
      default:
        return null;
    }
  };

  return (
    <OracleErrorBoundary themeColor={config.themeColor} onReset={refresh}>
      <div className="min-h-screen bg-insight">
        <PythHero
          config={config}
          price={price ?? null}
          historicalData={historicalData}
          networkStats={networkStats}
          publishers={publishers}
          validators={validators}
          isLoading={isLoading}
          isError={isError}
          isRefreshing={isRefreshing}
          lastUpdated={lastUpdated}
          onRefresh={refresh}
          onExport={exportData}
        />

        <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex flex-col lg:flex-row gap-6">
            <div className="hidden lg:block w-64 flex-shrink-0">
              <div className="sticky top-6">
                <PythSidebar
                  activeTab={activeTab}
                  onTabChange={(tab) => setActiveTab(tab as PythTabId)}
                />
              </div>
            </div>

            <div className="lg:hidden">
              <MobileMenuButton
                isOpen={isMobileMenuOpen}
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                themeColor={config.themeColor}
                label={t('pyth.menu.title')}
              />
            </div>

            <MobileSidebar
              isOpen={isMobileMenuOpen}
              onClose={() => setIsMobileMenuOpen(false)}
              title={t('pyth.navigation.title')}
            >
              <PythSidebar
                activeTab={activeTab}
                onTabChange={(tab) => {
                  setActiveTab(tab as PythTabId);
                  setIsMobileMenuOpen(false);
                }}
              />
            </MobileSidebar>

            <div className="flex-1 min-w-0">{renderContent()}</div>
          </div>
        </div>
      </div>
    </OracleErrorBoundary>
  );
}

'use client';

import { useState, useCallback, useRef } from 'react';

import { motion, AnimatePresence } from 'framer-motion';
import {
  Download,
  FileJson,
  FileText,
  Table,
  ChevronDown,
  X,
  Loader2,
  Image,
  Layers,
  Check,
} from 'lucide-react';

import { Button } from '@/components/ui/Button';
import { useTranslations, useLocale } from '@/i18n';
import { createLogger } from '@/lib/utils/logger';

const logger = createLogger('AdvancedDataExport');

export type ExportFormat = 'csv' | 'json' | 'pdf';
export type DateRangePreset = '1h' | '24h' | '7d' | '30d' | 'custom';
export type DataType = 'price' | 'network' | 'providers' | 'all';

export interface ExportField {
  key: string;
  label: string;
  labelZh: string;
  selected: boolean;
}

export interface ExportConfig {
  format: ExportFormat;
  dateRange: {
    preset: DateRangePreset;
    start?: Date;
    end?: Date;
  };
  dataTypes: DataType[];
  fields: ExportField[];
  includeChart: boolean;
  includeMetadata: boolean;
  batchExport: boolean;
}

export interface ExportResult {
  success: boolean;
  fileName?: string;
  fileSize?: number;
  error?: string;
}

interface AdvancedDataExportProps {
  data: {
    price?: unknown;
    historical?: unknown[];
    network?: unknown;
    providers?: unknown[];
    metrics?: unknown;
  };
  chartRef?: React.RefObject<HTMLDivElement>;
  onExport?: (config: ExportConfig) => Promise<ExportResult>;
  disabled?: boolean;
  compact?: boolean;
}

const FORMAT_CONFIGS = [
  {
    value: 'csv' as ExportFormat,
    label: 'CSV',
    labelZh: 'CSV',
    icon: <Table className="w-4 h-4" />,
    description: '表格格式，适合数据分析',
    descriptionZh: '表格格式，适合数据分析',
  },
  {
    value: 'json' as ExportFormat,
    label: 'JSON',
    labelZh: 'JSON',
    icon: <FileJson className="w-4 h-4" />,
    description: '结构化数据，适合开发',
    descriptionZh: '结构化数据，适合开发',
  },
  {
    value: 'pdf' as ExportFormat,
    label: 'PDF',
    labelZh: 'PDF',
    icon: <FileText className="w-4 h-4" />,
    description: '报告格式，适合分享',
    descriptionZh: '报告格式，适合分享',
  },
];

const DATE_RANGE_PRESETS = [
  { value: '1h' as DateRangePreset, label: '1 Hour', labelZh: '1小时' },
  { value: '24h' as DateRangePreset, label: '24 Hours', labelZh: '24小时' },
  { value: '7d' as DateRangePreset, label: '7 Days', labelZh: '7天' },
  { value: '30d' as DateRangePreset, label: '30 Days', labelZh: '30天' },
  { value: 'custom' as DateRangePreset, label: 'Custom', labelZh: '自定义' },
];

const DATA_TYPE_OPTIONS = [
  { value: 'price' as DataType, label: 'Price Data', labelZh: '价格数据' },
  { value: 'network' as DataType, label: 'Network Stats', labelZh: '网络统计' },
  { value: 'providers' as DataType, label: 'Providers', labelZh: '数据提供者' },
  { value: 'all' as DataType, label: 'All Data', labelZh: '全部数据' },
];

const DEFAULT_FIELDS: ExportField[] = [
  { key: 'timestamp', label: 'Timestamp', labelZh: '时间戳', selected: true },
  { key: 'price', label: 'Price', labelZh: '价格', selected: true },
  { key: 'volume', label: 'Volume', labelZh: '交易量', selected: true },
  { key: 'change24h', label: '24h Change', labelZh: '24h变化', selected: true },
  { key: 'marketCap', label: 'Market Cap', labelZh: '市值', selected: false },
];

export function AdvancedDataExport({
  data: _data,
  chartRef: _chartRef,
  onExport,
  disabled = false,
  compact = false,
}: AdvancedDataExportProps) {
  const t = useTranslations();
  const locale = useLocale();
  const isZh = locale === 'zh-CN';

  const [isOpen, setIsOpen] = useState(false);
  const [currentStep, setCurrentStep] = useState<'format' | 'options' | 'exporting'>('format');
  const [config, setConfig] = useState<ExportConfig>({
    format: 'csv',
    dateRange: { preset: '24h' },
    dataTypes: ['all'],
    fields: DEFAULT_FIELDS,
    includeChart: false,
    includeMetadata: true,
    batchExport: false,
  });
  const [exportProgress, setExportProgress] = useState(0);
  const [exportResult, setExportResult] = useState<ExportResult | null>(null);

  const dropdownRef = useRef<HTMLDivElement>(null);

  const handleFormatSelect = useCallback((format: ExportFormat) => {
    setConfig((prev) => ({ ...prev, format }));
    setCurrentStep('options');
  }, []);

  const handleDateRangeChange = useCallback((preset: DateRangePreset) => {
    setConfig((prev) => ({
      ...prev,
      dateRange: { preset },
    }));
  }, []);

  const handleCustomDateChange = useCallback((type: 'start' | 'end', value: string) => {
    setConfig((prev) => ({
      ...prev,
      dateRange: {
        ...prev.dateRange,
        preset: 'custom',
        [type]: value ? new Date(value) : undefined,
      },
    }));
  }, []);

  const handleDataTypeToggle = useCallback((dataType: DataType) => {
    setConfig((prev) => {
      if (dataType === 'all') {
        return { ...prev, dataTypes: ['all'] };
      }
      const newDataTypes = prev.dataTypes.includes(dataType)
        ? prev.dataTypes.filter((t) => t !== dataType && t !== 'all')
        : [...prev.dataTypes.filter((t) => t !== 'all'), dataType];
      return { ...prev, dataTypes: newDataTypes.length > 0 ? newDataTypes : ['all'] };
    });
  }, []);

  const handleFieldToggle = useCallback((key: string) => {
    setConfig((prev) => ({
      ...prev,
      fields: prev.fields.map((f) => (f.key === key ? { ...f, selected: !f.selected } : f)),
    }));
  }, []);

  const handleExport = useCallback(async () => {
    setCurrentStep('exporting');
    setExportProgress(0);
    setExportResult(null);

    const progressInterval = setInterval(() => {
      setExportProgress((prev) => Math.min(prev + 10, 90));
    }, 100);

    try {
      const result = await onExport?.(config);
      clearInterval(progressInterval);
      setExportProgress(100);
      setExportResult(result || { success: true });

      setTimeout(() => {
        setIsOpen(false);
        setCurrentStep('format');
        setExportProgress(0);
      }, 1000);
    } catch (error) {
      clearInterval(progressInterval);
      logger.error('Export failed', error as Error);
      setExportResult({ success: false, error: (error as Error).message });
    }
  }, [config, onExport]);

  const handleBack = useCallback(() => {
    setCurrentStep('format');
  }, []);

  const selectedFieldsCount = config.fields.filter((f) => f.selected).length;

  const getFormatConfig = (format: ExportFormat) => FORMAT_CONFIGS.find((f) => f.value === format);

  const renderFormatSelection = () => (
    <div className="p-3">
      <p className="text-xs text-gray-500 px-2 py-1 mb-2">
        {t('redstone.export.selectFormat') || '选择导出格式'}
      </p>
      {FORMAT_CONFIGS.map((format) => (
        <button
          key={format.value}
          onClick={() => handleFormatSelect(format.value)}
          className="w-full flex items-start gap-3 px-3 py-3 text-left hover:bg-gray-50 transition-colors rounded-lg"
        >
          <div className="p-2 rounded-lg bg-gray-100 text-gray-600">{format.icon}</div>
          <div className="flex-1">
            <div className="text-sm font-medium text-gray-900">
              {isZh ? format.labelZh : format.label}
            </div>
            <div className="text-xs text-gray-500">
              {isZh ? format.descriptionZh : format.description}
            </div>
          </div>
          <ChevronDown className="w-4 h-4 text-gray-400 rotate-[-90deg] mt-2" />
        </button>
      ))}
    </div>
  );

  const renderOptions = () => {
    const formatConfig = getFormatConfig(config.format);
    return (
      <div className="w-96">
        <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100">
          <div className="flex items-center gap-2">
            <div className="p-1.5 rounded bg-gray-100">{formatConfig?.icon}</div>
            <span className="font-medium text-gray-900">
              {isZh ? formatConfig?.labelZh : formatConfig?.label}{' '}
              {t('redstone.export.config') || '导出配置'}
            </span>
          </div>
          <button onClick={() => setIsOpen(false)} className="text-gray-400 hover:text-gray-600">
            <X className="w-4 h-4" />
          </button>
        </div>

        <div className="p-4 space-y-4 max-h-[60vh] overflow-y-auto">
          <div>
            <label className="text-sm font-medium text-gray-700 mb-2 block">
              {t('redstone.export.dateRange') || '日期范围'}
            </label>
