'use client';

import { useState, useCallback, useMemo, useEffect } from 'react';

import { motion, AnimatePresence, Reorder } from 'framer-motion';
import {
  Settings,
  Pin,
  PinOff,
  GripVertical,
  RotateCcw,
  Check,
  X,
  Eye,
  EyeOff,
  Sparkles,
} from 'lucide-react';

import { Button } from '@/components/ui/Button';
import { useTranslations } from '@/i18n';
import { createLogger } from '@/lib/utils/logger';

const logger = createLogger('DashboardCustomizer');

export interface MetricItem {
  id: string;
  key: string;
  labelKey: string;
  labelZh: string;
  labelEn: string;
  icon: React.ReactNode;
  category: 'price' | 'network' | 'provider' | 'token';
  defaultVisible: boolean;
  defaultPinned: boolean;
}

export interface DashboardPreferences {
  pinnedMetrics: string[];
  hiddenMetrics: string[];
  metricOrder: string[];
  lastUpdated: string;
}

const STORAGE_KEY = 'redstone_dashboard_preferences';

const DEFAULT_METRICS: MetricItem[] = [
  {
    id: 'price',
    key: 'price',
    labelKey: 'redstone.stats.price',
    labelZh: '价格',
    labelEn: 'Price',
    icon: <Sparkles className="w-4 h-4" />,
    category: 'price',
    defaultVisible: true,
    defaultPinned: true,
  },
  {
    id: 'marketCap',
    key: 'marketCap',
    labelKey: 'redstone.stats.marketCap',
    labelZh: '市值',
    labelEn: 'Market Cap',
    icon: <Sparkles className="w-4 h-4" />,
    category: 'price',
    defaultVisible: true,
    defaultPinned: false,
  },
  {
    id: 'volume24h',
    key: 'volume24h',
    labelKey: 'redstone.stats.volume24h',
    labelZh: '24h交易量',
    labelEn: '24h Volume',
    icon: <Sparkles className="w-4 h-4" />,
    category: 'price',
    defaultVisible: true,
    defaultPinned: false,
  },
  {
    id: 'activeNodes',
    key: 'activeNodes',
    labelKey: 'redstone.stats.activeNodes',
    labelZh: '活跃节点',
    labelEn: 'Active Nodes',
    icon: <Sparkles className="w-4 h-4" />,
    category: 'network',
    defaultVisible: true,
    defaultPinned: true,
  },
  {
    id: 'dataFeeds',
    key: 'dataFeeds',
    labelKey: 'redstone.stats.dataFeeds',
    labelZh: '数据源',
    labelEn: 'Data Feeds',
    icon: <Sparkles className="w-4 h-4" />,
    category: 'network',
    defaultVisible: true,
    defaultPinned: false,
  },
  {
    id: 'avgResponse',
    key: 'avgResponse',
    labelKey: 'redstone.stats.avgResponse',
    labelZh: '平均响应',
    labelEn: 'Avg Response',
    icon: <Sparkles className="w-4 h-4" />,
    category: 'network',
    defaultVisible: true,
    defaultPinned: false,
  },
  {
    id: 'networkUptime',
    key: 'networkUptime',
    labelKey: 'redstone.stats.networkUptime',
    labelZh: '网络正常运行',
    labelEn: 'Network Uptime',
    icon: <Sparkles className="w-4 h-4" />,
    category: 'network',
    defaultVisible: true,
    defaultPinned: false,
  },
  {
    id: 'circulatingSupply',
    key: 'circulatingSupply',
    labelKey: 'redstone.stats.circulatingSupply',
    labelZh: '流通供应量',
    labelEn: 'Circulating Supply',
