                      />
                      {chain.status === 'active'
                        ? t('redstone.crossChain.active')
                        : t('redstone.crossChain.inactive')}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

