interface ChainStatus {
  chain: Blockchain;
  status: 'healthy' | 'degraded' | 'down';
  blockHeight: number;
  avgLatency: number;
  reporterCount: number;
  dataFeeds: number;
}

function generateChainStatuses(): ChainStatus[] {
  const chains = [
    Blockchain.ETHEREUM,
    Blockchain.ARBITRUM,
    Blockchain.POLYGON,
    Blockchain.OPTIMISM,
    Blockchain.BASE,
  ];

  return chains.map((chain, index) => ({
    chain,
    status: ['healthy', 'healthy', 'healthy', 'healthy', 'degraded'][index] as
      | 'healthy'
      | 'degraded'
      | 'down',
    blockHeight: 18500000 + Math.floor(Math.random() * 10000),
    avgLatency: [120, 85, 95, 110, 100][index],
    reporterCount: [28, 22, 18, 15, 12][index],
    dataFeeds: [150, 120, 95, 80, 70][index],
  }));
}

