  const totalWeight = distributions.reduce((sum, d) => sum + d.totalWeight, 0);

  const typeIcons = {
    institution: <Building2 className="w-4 h-4" />,
    community: <Users className="w-4 h-4" />,
    independent: <UserCircle className="w-4 h-4" />,
  };

