                t={t}
              />
            </div>

            <div className="p-3 rounded-xl bg-gray-50/50 border border-gray-100 flex-1">
              <MiniPriceChart
                historicalData={historicalData}
                currentPrice={price}
                themeColor={themeColor}
                t={t}
              />
            </div>
          </div>
        </div>
      </div>

      <LatestUpdates t={t} />
    </div>
  );
}

