        label: t('winklink.hero.gasMedium'),
        color: 'text-yellow-600',
        bg: 'bg-yellow-500',
        width: '50%',
      };
    return {
      label: t('winklink.hero.gasHigh'),
      color: 'text-red-600',
      bg: 'bg-red-500',
      width: '80%',
    };
