    switch (status) {
      case 'low':
        return 'bg-emerald-50';
      case 'medium':
        return 'bg-amber-50';
      case 'high':
        return 'bg-red-50';
      default:
        return 'bg-gray-50';
    }
  };

  const overallRiskStatus =
    riskData.overallRisk <= 3 ? 'low' : riskData.overallRisk <= 6 ? 'medium' : 'high';

  return (
    <div className="space-y-8">
      {/* Risk Metrics */}
