            <Server className="w-4 h-4 text-gray-500" />
            <h2 className="text-base font-medium text-gray-900">
              {t('winklink.staking.nodeList')}
            </h2>
          </div>
          <WinklinkDataTable
            data={nodes}
            columns={columns}
            sortConfig={sortConfig}
            onSort={handleSort}
            isLoading={isLoading}
          />
        </div>

        {/* 右侧边栏 */}
        <div className="space-y-8">
          {/* 质押计算器 */}
          <section>
            <StakingRewardsCalculator winPrice={winPrice} />
          </section>

          {/* 质押等级分布 - 紧凑进度条 */}
