'use client';

import React, { Component, type ReactNode, type ErrorInfo } from 'react';

import {
  isAppError,
  ValidationError,
  NotFoundError,
  PriceFetchError,
  RateLimitError,
  AuthenticationError,
  AuthorizationError,
  NetworkError,
  classifyError,
} from '@/lib/errors';
import { captureException, addBreadcrumb, setUser } from '@/lib/monitoring';
import { createLogger } from '@/lib/utils/logger';
import { useAuthStore } from '@/stores/authStore';

const logger = createLogger('ErrorBoundary');

/**
 * 错误边界级别
 */
export type ErrorBoundaryLevel = 'global' | 'page' | 'section' | 'component';

/**
 * 错误边界属性
 */
export interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: ReactNode;
  fallbackRender?: (props: ErrorFallbackRenderProps) => ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
  onReset?: () => void;
  level?: ErrorBoundaryLevel;
  resetKeys?: unknown[];
  componentName?: string;
  captureInSentry?: boolean;
  showDetails?: boolean;
}

/**
 * 错误回退渲染属性
 */
export interface ErrorFallbackRenderProps {
  error: Error;
  reset: () => void;
  level: ErrorBoundaryLevel;
  componentName?: string;
  errorInfo?: ErrorInfo;
}

/**
 * 错误边界状态
 */
interface ErrorBoundaryState {
  hasError: boolean;
  error?: Error;
  errorInfo?: ErrorInfo;
}

/**
 * 增强的错误边界组件
 *
 * 功能特性：
 * 1. 多级错误边界支持（global/page/section/component）
 * 2. 自动错误分类和严重级别判断
 * 3. 集成 Sentry 错误追踪
 * 4. 支持重置和恢复
 * 5. 详细的错误日志记录
 * 6. 用户友好的错误界面
 */
export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidUpdate(prevProps: ErrorBoundaryProps) {
    const { resetKeys } = this.props;
    const { hasError } = this.state;

    // 当 resetKeys 变化时自动重置
    if (
      hasError &&
      resetKeys &&
      prevProps.resetKeys !== resetKeys &&
      this.hasResetKeysChanged(prevProps.resetKeys, resetKeys)
    ) {
      this.reset();
    }
  }

  private hasResetKeysChanged(prevKeys: unknown[] | undefined, nextKeys: unknown[]): boolean {
    if (!prevKeys || prevKeys.length !== nextKeys.length) {
      return true;
    }
    return prevKeys.some((key, index) => key !== nextKeys[index]);
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    const { onError, level = 'component', componentName, captureInSentry = true } = this.props;

    this.setState({ errorInfo });

    // 构建错误上下文
    const errorContext = this.buildErrorContext(error, level, componentName, errorInfo);

    // 记录错误日志
    this.logError(error, errorContext);

    // 发送到 Sentry
    if (captureInSentry) {
      this.captureInSentry(error, errorContext);
    }

    // 调用自定义错误处理器
    if (onError) {
      try {
        onError(error, errorInfo);
      } catch (callbackError) {
        logger.error('Error in onError callback', callbackError as Error);
      }
    }
  }

  /**
   * 构建错误上下文
   */
  private buildErrorContext(
    error: Error,
    level: ErrorBoundaryLevel,
    componentName?: string,
    errorInfo?: ErrorInfo
  ): Record<string, unknown> {
    const classification = classifyError(error);

    const context: Record<string, unknown> = {
      level,
      componentName,
      classification,
      timestamp: new Date().toISOString(),
      userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : 'unknown',
      url: typeof window !== 'undefined' ? window.location.href : 'unknown',
    };

    if (isAppError(error)) {
      context.errorCode = error.code;
      context.statusCode = error.statusCode;
      context.isOperational = error.isOperational;
      context.severity = error.severity;
      context.category = error.category;
      context.retryable = error.retryable;
      context.requestId = error.requestId;
    }

    if (errorInfo?.componentStack) {
      context.componentStack = errorInfo.componentStack;
    }

    return context;
  }

  /**
   * 记录错误日志
   */
  private logError(error: Error, context: Record<string, unknown>): void {
    const { level = 'component', componentName } = this.props;

    const logMessage = componentName
      ? `[${level.toUpperCase()}] Error in ${componentName}: ${error.message}`
      : `[${level.toUpperCase()}] Error caught: ${error.message}`;

    if (isAppError(error)) {
      logger.error(logMessage, error, {
        ...context,
        details: error.details,
      });
    } else {
      logger.error(logMessage, error, context);
    }
  }

  /**
   * 发送到 Sentry
   */
  private captureInSentry(error: Error, context: Record<string, unknown>): void {
    // 添加面包屑
    addBreadcrumb({
      category: 'error-boundary',
      message: `Error caught at ${context.level} level`,
      level: 'error',
      data: {
        componentName: context.componentName,
        errorCode: context.errorCode,
        category: context.category,
      },
    });

    // 捕获异常
    captureException(error, context);
  }

  /**
   * 重置错误状态
   */
  reset = () => {
    const { onReset } = this.props;

    this.setState({ hasError: false, error: undefined, errorInfo: undefined });

    if (onReset) {
      try {
        onReset();
      } catch (error) {
        logger.error('Error in onReset callback', error as Error);
      }
    }

    logger.info('Error boundary reset', {
      level: this.props.level,
      componentName: this.props.componentName,
    });
  };

  render() {
    const { hasError, error, errorInfo } = this.state;
    const {
      children,
      fallback,
      fallbackRender,
      level = 'component',
      componentName,
      showDetails,
    } = this.props;

    if (!hasError || !error) {
      return children;
    }

    // 使用自定义 fallbackRender
    if (fallbackRender) {
      return (
        <>
          {fallbackRender({
            error,
            reset: this.reset,
            level,
            componentName,
            errorInfo,
          })}
        </>
      );
    }

    // 使用自定义 fallback
    if (fallback) {
      return <>{fallback}</>;
    }

    // 使用默认错误回退UI
    return (
      <DefaultErrorFallback
        error={error}
        reset={this.reset}
        level={level}
        componentName={componentName}
        showDetails={showDetails}
      />
    );
  }
}

/**
 * 默认错误回退UI
 */
interface DefaultErrorFallbackProps {
  error: Error;
  reset: () => void;
  level: ErrorBoundaryLevel;
  componentName?: string;
  showDetails?: boolean;
}

function DefaultErrorFallback({
  error,
  reset,
  level,
  componentName,
  showDetails = process.env.NODE_ENV === 'development',
}: DefaultErrorFallbackProps) {
  const config = getErrorConfig(error, level);
  const isDev = showDetails;

  return (
    <div
      className={`
        flex flex-col items-center justify-center text-center
        ${level === 'global' ? 'min-h-screen p-8' : ''}
        ${level === 'page' ? 'min-h-[60vh] p-8' : ''}
        ${level === 'section' ? 'min-h-[300px] p-6' : ''}
        ${level === 'component' ? 'min-h-[200px] p-4' : ''}
      `}
      role="alert"
      aria-live="assertive"
    >
      <div
        className={`
          flex items-center justify-center rounded-full mb-4
          ${config.bgColor}
          ${level === 'global' || level === 'page' ? 'w-20 h-20' : ''}
          ${level === 'section' ? 'w-16 h-16' : ''}
          ${level === 'component' ? 'w-12 h-12' : ''}
        `}
      >
        <span
          className={`
            ${level === 'global' || level === 'page' ? 'text-4xl' : ''}
            ${level === 'section' ? 'text-3xl' : ''}
            ${level === 'component' ? 'text-2xl' : ''}
          `}
        >
          {config.icon}
        </span>
      </div>

      <h2
        className={`
          font-semibold text-gray-900 mb-2
          ${level === 'global' ? 'text-2xl' : ''}
          ${level === 'page' ? 'text-xl' : ''}
          ${level === 'section' ? 'text-lg' : ''}
          ${level === 'component' ? 'text-base' : ''}
        `}
      >
        {config.title}
      </h2>

      <p
        className={`
          text-gray-600 max-w-md mb-4
          ${level === 'global' || level === 'page' ? 'text-base' : 'text-sm'}
        `}
      >
        {config.message}
      </p>

      {componentName && isDev && (
        <p className="text-xs text-gray-400 mb-2">Component: {componentName}</p>
      )}

      {isDev && error.message && (
        <div className="mb-4 p-3 bg-gray-100 rounded text-left max-w-md overflow-auto">
          <p className="text-xs text-gray-500 font-mono break-all">{error.message}</p>
          {isAppError(error) && (
            <div className="mt-2 text-xs text-gray-400 space-y-1">
              <p>Code: {error.code}</p>
              <p>Category: {error.category}</p>
              <p>Severity: {error.severity}</p>
              <p>Request ID: {error.requestId}</p>
            </div>
          )}
        </div>
      )}

      <div className="flex gap-3">
        <button
          onClick={reset}
          className={`
            inline-flex items-center gap-2 font-medium transition-colors
            ${config.buttonClass}
            ${level === 'global' || level === 'page' ? 'px-6 py-3 rounded-md' : ''}
            ${level === 'section' ? 'px-4 py-2 rounded-md text-sm' : ''}
            ${level === 'component' ? 'px-3 py-1.5 rounded text-sm' : ''}
          `}
        >
          <span>🔄</span>
          {level === 'global' || level === 'page' ? 'Try Again' : 'Retry'}
        </button>

        {level === 'global' && (
          <a
            href="/"
            className="inline-flex items-center gap-2 px-6 py-3 border border-gray-300 text-gray-700 font-medium hover:bg-gray-50 transition-colors rounded-md"
          >
            <span>🏠</span>
            Back to Home
          </a>
        )}
      </div>
    </div>
  );
}

/**
 * 获取错误配置
 */
function getErrorConfig(
  error: Error,
  level: ErrorBoundaryLevel
): {
  icon: string;
  title: string;
  message: string;
  bgColor: string;
  buttonClass: string;
} {
  // 根据错误类型返回不同配置
  if (error instanceof ValidationError) {
    return {
      icon: '📝',
      title: 'Validation Error',
      message: error.message,
      bgColor: 'bg-yellow-100',
      buttonClass: 'bg-yellow-600 text-white hover:bg-yellow-700',
    };
  }

  if (error instanceof NotFoundError) {
    return {
      icon: '🔍',
      title: 'Not Found',
      message: 'The requested resource was not found.',
      bgColor: 'bg-blue-100',
      buttonClass: 'bg-blue-600 text-white hover:bg-blue-700',
    };
  }

  if (error instanceof AuthenticationError) {
    return {
      icon: '🔐',
      title: 'Authentication Required',
      message: 'Please sign in to access this feature.',
      bgColor: 'bg-orange-100',
      buttonClass: 'bg-orange-600 text-white hover:bg-orange-700',
    };
  }

  if (error instanceof AuthorizationError) {
    return {
      icon: '🚫',
      title: 'Access Denied',
      message: "You don't have permission to access this resource.",
      bgColor: 'bg-red-100',
      buttonClass: 'bg-red-600 text-white hover:bg-red-700',
    };
  }

  if (error instanceof PriceFetchError) {
    return {
      icon: '📈',
      title: 'Price Data Unavailable',
      message: error.retryable
        ? 'Failed to fetch price data. Please try again.'
        : 'Unable to retrieve price data at this time.',
      bgColor: 'bg-purple-100',
      buttonClass: 'bg-purple-600 text-white hover:bg-purple-700',
    };
  }

  if (error instanceof RateLimitError) {
    return {
      icon: '⏱️',
      title: 'Rate Limit Exceeded',
      message: 'Too many requests. Please try again later.',
      bgColor: 'bg-indigo-100',
      buttonClass: 'bg-indigo-600 text-white hover:bg-indigo-700',
    };
  }

  if (error instanceof NetworkError) {
    return {
      icon: '🌐',
      title: 'Network Error',
      message: 'Connection failed. Please check your internet connection.',
      bgColor: 'bg-cyan-100',
      buttonClass: 'bg-cyan-600 text-white hover:bg-cyan-700',
    };
  }

  if (isAppError(error)) {
    return {
      icon: '⚠️',
      title: level === 'global' ? 'Something Went Wrong' : 'Error',
      message: error.isOperational ? error.message : 'An unexpected error occurred.',
      bgColor: 'bg-red-100',
      buttonClass: 'bg-primary-600 text-white hover:bg-primary-700',
    };
  }

  // 默认配置
  return {
    icon: '⚠️',
    title: level === 'global' ? 'Something Went Wrong' : 'Error',
    message:
      level === 'global'
        ? "We're sorry, but something unexpected happened. Please try again."
        : 'An error occurred while loading this component.',
    bgColor: 'bg-red-100',
    buttonClass: 'bg-primary-600 text-white hover:bg-primary-700',
  };
}

/**
 * 全局错误边界 Hook
 */
export function useSentryUserContext() {
  const user = useAuthStore((state) => state.user);
  const profile = useAuthStore((state) => state.profile);

  React.useEffect(() => {
    if (user) {
      setUser({
        id: user.id,
        email: user.email,
        username: profile?.display_name || user.user_metadata?.display_name,
      });
    } else {
      setUser(null);
    }
  }, [user, profile]);
}

/**
 * 便捷的错误边界组件
 */

export function GlobalErrorBoundary({ children, ...props }: Omit<ErrorBoundaryProps, 'level'>) {
  useSentryUserContext();
  return (
    <ErrorBoundary level="global" captureInSentry {...props}>
      {children}
    </ErrorBoundary>
  );
}

export function PageErrorBoundary({ children, ...props }: Omit<ErrorBoundaryProps, 'level'>) {
  return (
    <ErrorBoundary level="page" captureInSentry {...props}>
      {children}
    </ErrorBoundary>
  );
}

export function SectionErrorBoundary({ children, ...props }: Omit<ErrorBoundaryProps, 'level'>) {
  return (
    <ErrorBoundary level="section" {...props}>
      {children}
    </ErrorBoundary>
  );
}

export function ComponentErrorBoundary({ children, ...props }: Omit<ErrorBoundaryProps, 'level'>) {
  return (
    <ErrorBoundary level="component" {...props}>
      {children}
    </ErrorBoundary>
  );
}

export default ErrorBoundary;

'use client';

import React, { useState, useCallback } from 'react';

import {
  AlertTriangle,
  RefreshCw,
  Home,
  FileText,
  ChevronDown,
  ChevronUp,
  Copy,
  Check,
  X,
  Info,
  WifiOff,
  Lock,
  Search,
  Clock,
  Server,
  ShieldAlert,
} from 'lucide-react';

import { Button } from '@/components/ui/Button';
import type { AppError } from '@/lib/errors';
import {
  isAppError,
  ValidationError,
  NotFoundError,
  AuthenticationError,
  AuthorizationError,
  RateLimitError,
  NetworkError,
  PriceFetchError,
  getErrorMessage,
  classifyError,
} from '@/lib/errors';
import { cn } from '@/lib/utils';

/**
 * 错误显示类型
 */
export type ErrorDisplayType = 'inline' | 'card' | 'page' | 'toast' | 'modal';

/**
 * 错误显示变体
 */
export type ErrorDisplayVariant = 'default' | 'destructive' | 'warning' | 'info';

/**
 * 错误显示属性
 */
export interface ErrorDisplayProps {
  error?: Error | AppError | string | null;
  type?: ErrorDisplayType;
  variant?: ErrorDisplayVariant;
  title?: string;
  description?: string;
  onRetry?: () => void | Promise<void>;
  onDismiss?: () => void;
  onHome?: () => void;
  showDetails?: boolean;
  showReport?: boolean;
  className?: string;
  retryText?: string;
  dismissText?: string;
  homeText?: string;
  reportText?: string;
  maxRetries?: number;
  children?: React.ReactNode;
}

/**
 * 错误报告数据
 */
interface ErrorReportData {
  errorId: string | undefined;
  timestamp: string;
  userAgent: string;
  url: string;
  error: {
    name: string;
    message: string;
    stack?: string;
    code?: string;
    category?: string;
    severity?: string;
  };
}

/**
 * 错误显示组件
 *
 * 功能特性：
 * 1. 多种显示类型（inline/card/page/toast/modal）
 * 2. 智能错误类型识别和图标
 * 3. 支持重试机制（带最大重试次数）
 * 4. 错误详情展开/收起
 * 5. 错误报告生成和复制
 * 6. 响应式设计
 */
export function ErrorDisplay({
  error,
  type = 'card',
  variant = 'default',
  title: customTitle,
  description: customDescription,
  onRetry,
  onDismiss,
  onHome,
  showDetails = process.env.NODE_ENV === 'development',
  showReport = true,
  className,
  retryText = '重试',
  dismissText = '关闭',
  homeText = '返回首页',
  reportText = '复制错误信息',
  maxRetries = 3,
  children,
}: ErrorDisplayProps) {
  const [isRetrying, setIsRetrying] = useState(false);
  const [retryCount, setRetryCount] = useState(0);
  const [showErrorDetails, setShowErrorDetails] = useState(false);
  const [copied, setCopied] = useState(false);

  // 如果没有错误，不显示任何内容
  if (!error) {
    return null;
  }

  const errorMessage = getErrorMessage(error);
  const errorConfig = getErrorConfig(error, variant);
  const classification = classifyError(error);

  const title = customTitle || errorConfig.title;
  const description = customDescription || errorConfig.description;

  /**
   * 处理重试
   */
  const handleRetry = useCallback(async () => {
    if (!onRetry || retryCount >= maxRetries || isRetrying) {
      return;
    }

    setIsRetrying(true);
    try {
      await onRetry();
      setRetryCount(0);
    } catch {
      setRetryCount((prev) => prev + 1);
    } finally {
      setIsRetrying(false);
    }
  }, [onRetry, retryCount, maxRetries, isRetrying]);

  /**
   * 生成错误报告
   */
  const generateErrorReport = useCallback((): ErrorReportData => {
    const isAppErr = isAppError(error);

    return {
      errorId:
        isAppErr && error instanceof Error ? (error as AppError).requestId : `err-${Date.now()}`,
      timestamp: new Date().toISOString(),
      userAgent: navigator.userAgent,
      url: window.location.href,
      error: {
        name: error instanceof Error ? error.name : 'Error',
        message: errorMessage,
        stack: error instanceof Error ? error.stack : undefined,
        code: isAppErr && error instanceof Error ? (error as AppError).code : undefined,
        category: classification.category,
        severity: classification.severity,
      },
    };
  }, [error, errorMessage, classification]);

  /**
   * 复制错误报告到剪贴板
   */
  const handleCopyReport = useCallback(async () => {
    const report = generateErrorReport();
    const reportText = JSON.stringify(report, null, 2);

    try {
      await navigator.clipboard.writeText(reportText);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      console.error('Failed to copy error report');
    }
  }, [generateErrorReport]);

  /**
   * 渲染图标
   */
  const renderIcon = () => {
    const Icon = errorConfig.icon;
    return (
      <div
        className={cn(
          'flex items-center justify-center rounded-full',
          errorConfig.bgColor,
          type === 'page' && 'w-24 h-24',
          type === 'card' && 'w-16 h-16',
          type === 'inline' && 'w-10 h-10',
          type === 'toast' && 'w-8 h-8',
          type === 'modal' && 'w-20 h-20'
        )}
      >
        <Icon
          className={cn(
            errorConfig.iconColor,
            type === 'page' && 'w-12 h-12',
            type === 'card' && 'w-8 h-8',
            type === 'inline' && 'w-5 h-5',
            type === 'toast' && 'w-4 h-4',
            type === 'modal' && 'w-10 h-10'
          )}
        />
      </div>
    );
  };

  /**
   * 渲染操作按钮
   */
  const renderActions = () => {
    const canRetry = onRetry && retryCount < maxRetries;
    const isRateLimited = error instanceof RateLimitError;

    return (
      <div className="flex flex-wrap gap-3">
        {canRetry && !isRateLimited && (
          <Button
            variant="primary"
            onClick={handleRetry}
            disabled={isRetrying}
            leftIcon={<RefreshCw className={cn('w-4 h-4', isRetrying && 'animate-spin')} />}
          >
            {isRetrying ? '重试中...' : retryText}
            {retryCount > 0 && ` (${retryCount}/${maxRetries})`}
          </Button>
        )}

        {isRateLimited && (
          <Button
            variant="primary"
            onClick={handleRetry}
            disabled={isRetrying}
            leftIcon={<Clock className="w-4 h-4" />}
          >
            {retryText}
            {error.retryAfter && ` (${error.retryAfter}s)`}
          </Button>
        )}

        {onHome && type !== 'inline' && type !== 'toast' && (
          <Button variant="secondary" onClick={onHome} leftIcon={<Home className="w-4 h-4" />}>
            {homeText}
          </Button>
        )}

        {onDismiss && type === 'toast' && (
          <Button variant="ghost" onClick={onDismiss} leftIcon={<X className="w-4 h-4" />}>
            {dismissText}
          </Button>
        )}

        {showReport && type !== 'toast' && (
          <Button
            variant="ghost"
            onClick={handleCopyReport}
            leftIcon={copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
          >
            {copied ? '已复制' : reportText}
          </Button>
        )}
      </div>
    );
  };

  /**
   * 渲染错误详情
   */
  const renderDetails = () => {
    if (!showDetails) return null;

    const isAppErr = isAppError(error);

    return (
      <div className="mt-4 border-t border-gray-200 pt-4">
        <button
          onClick={() => setShowErrorDetails(!showErrorDetails)}
          className="flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 transition-colors"
        >
          <FileText className="w-4 h-4" />
          错误详情
          {showErrorDetails ? (
            <ChevronUp className="w-4 h-4" />
          ) : (
            <ChevronDown className="w-4 h-4" />
          )}
        </button>

        {showErrorDetails && (
          <div className="mt-3 p-3 bg-gray-50 rounded-lg text-left">
            <div className="space-y-2 text-sm">
              <p className="font-mono text-gray-600 break-all">{errorMessage}</p>

              {isAppErr && (
                <div className="grid grid-cols-2 gap-2 text-xs text-gray-500">
                  <div>
                    <span className="font-medium">错误代码:</span> {error.code}
                  </div>
                  <div>
                    <span className="font-medium">分类:</span> {error.category}
                  </div>
                  <div>
                    <span className="font-medium">严重级别:</span> {error.severity}
                  </div>
                  <div>
                    <span className="font-medium">请求ID:</span>{' '}
                    <code className="bg-gray-200 px-1 rounded">{error.requestId}</code>
                  </div>
                  {error.retryable && (
                    <div>
                      <span className="font-medium">可重试:</span> 是
                    </div>
                  )}
                </div>
              )}

              {error instanceof Error && error.stack && (
                <details className="mt-2">
                  <summary className="cursor-pointer text-xs text-gray-500 hover:text-gray-700">
                    堆栈跟踪
                  </summary>
                  <pre className="mt-2 p-2 bg-gray-100 rounded text-xs text-gray-600 overflow-auto max-h-40">
                    {error.stack}
                  </pre>
                </details>
              )}
            </div>
          </div>
        )}
      </div>
    );
  };

  /**
   * 根据类型渲染不同样式
   */
  switch (type) {
    case 'page':
      return (
        <div
          className={cn('min-h-screen flex items-center justify-center p-8 bg-gray-50', className)}
        >
          <div className="text-center max-w-lg">
            {renderIcon()}
            <h1 className="text-2xl font-bold text-gray-900 mt-6 mb-3">{title}</h1>
            <p className="text-gray-600 mb-6">{description}</p>
            {children}
            {renderActions()}
            {renderDetails()}
          </div>
        </div>
      );

    case 'card':
      return (
        <div
          className={cn('bg-white border border-gray-200 rounded-lg p-6 shadow-sm', className)}
          role="alert"
        >
          <div className="flex flex-col items-center text-center">
            {renderIcon()}
            <h3 className="text-lg font-semibold text-gray-900 mt-4 mb-2">{title}</h3>
            <p className="text-gray-600 text-sm mb-4 max-w-sm">{description}</p>
            {children}
            {renderActions()}
            {renderDetails()}
          </div>
        </div>
      );

    case 'inline':
      return (
        <div
          className={cn('flex items-start gap-3 p-3 rounded-lg', errorConfig.bgColor, className)}
          role="alert"
        >
          <div className="flex-shrink-0 mt-0.5">
            <errorConfig.icon className={cn('w-5 h-5', errorConfig.iconColor)} />
          </div>
          <div className="flex-1 min-w-0">
            <p className={cn('text-sm font-medium', errorConfig.textColor)}>{title}</p>
            <p className="text-sm text-gray-600 mt-1">{description}</p>
            {children}
            {(onRetry || onDismiss) && (
              <div className="flex gap-2 mt-3">
                {onRetry && (
                  <button
                    onClick={handleRetry}
                    disabled={isRetrying}
                    className="text-sm text-primary-600 hover:text-primary-700 font-medium disabled:opacity-50"
                  >
                    {isRetrying ? '重试中...' : retryText}
                  </button>
                )}
                {onDismiss && (
                  <button onClick={onDismiss} className="text-sm text-gray-500 hover:text-gray-700">
                    {dismissText}
                  </button>
                )}
              </div>
            )}
          </div>
        </div>
      );

    case 'toast':
      return (
        <div
          className={cn(
            'flex items-start gap-3 p-4 rounded-lg shadow-lg max-w-md',
            errorConfig.bgColor,
            className
          )}
          role="alert"
        >
          <div className="flex-shrink-0">{renderIcon()}</div>
          <div className="flex-1 min-w-0">
            <p className={cn('text-sm font-medium', errorConfig.textColor)}>{title}</p>
            <p className="text-sm text-gray-600 mt-1">{description}</p>
          </div>
          {renderActions()}
          {onDismiss && (
            <button onClick={onDismiss} className="flex-shrink-0 text-gray-400 hover:text-gray-600">
              <X className="w-4 h-4" />
            </button>
          )}
        </div>
      );

    case 'modal':
      return (
        <div
          className={cn(
            'fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50',
            className
          )}
        >
          <div className="bg-white rounded-lg shadow-xl max-w-md w-full p-6">
            <div className="flex flex-col items-center text-center">
              {renderIcon()}
              <h3 className="text-xl font-semibold text-gray-900 mt-4 mb-2">{title}</h3>
              <p className="text-gray-600 mb-6">{description}</p>
              {children}
              {renderActions()}
              {renderDetails()}
            </div>
          </div>
        </div>
      );

    default:
      return null;
  }
}

/**
 * 获取错误配置
 */
function getErrorConfig(
  error: Error | AppError | string,
  variant: ErrorDisplayVariant
): {
  icon: React.ComponentType<{ className?: string }>;
  title: string;
  description: string;
  bgColor: string;
  iconColor: string;
  textColor: string;
} {
  // 根据错误类型返回配置
  if (error instanceof ValidationError) {
    return {
      icon: Info,
      title: '验证错误',
      description: getErrorMessage(error),
      bgColor: 'bg-yellow-50',
      iconColor: 'text-yellow-500',
      textColor: 'text-yellow-800',
    };
  }

  if (error instanceof NotFoundError) {
    return {
      icon: Search,
      title: '未找到',
      description: '请求的资源不存在或已被移除。',
      bgColor: 'bg-blue-50',
      iconColor: 'text-blue-500',
      textColor: 'text-blue-800',
    };
  }

  if (error instanceof AuthenticationError) {
    return {
      icon: Lock,
      title: '需要登录',
      description: '请先登录以访问此功能。',
      bgColor: 'bg-orange-50',
      iconColor: 'text-orange-500',
      textColor: 'text-orange-800',
    };
  }

  if (error instanceof AuthorizationError) {
    return {
      icon: ShieldAlert,
      title: '访问被拒绝',
      description: '您没有权限执行此操作。',
      bgColor: 'bg-red-50',
      iconColor: 'text-red-500',
      textColor: 'text-red-800',
    };
  }

  if (error instanceof RateLimitError) {
    return {
      icon: Clock,
      title: '请求过于频繁',
      description: '请稍后再试。',
      bgColor: 'bg-indigo-50',
      iconColor: 'text-indigo-500',
      textColor: 'text-indigo-800',
    };
  }

  if (error instanceof NetworkError) {
    return {
      icon: WifiOff,
      title: '网络错误',
      description: '网络连接失败，请检查您的网络设置。',
      bgColor: 'bg-cyan-50',
      iconColor: 'text-cyan-500',
      textColor: 'text-cyan-800',
    };
  }

  if (error instanceof PriceFetchError) {
    return {
      icon: Server,
      title: '价格数据不可用',
      description: error.retryable
        ? '暂时无法获取价格数据，请稍后重试。'
        : '无法获取价格数据，请稍后再试。',
      bgColor: 'bg-purple-50',
      iconColor: 'text-purple-500',
      textColor: 'text-purple-800',
    };
  }

  if (isAppError(error)) {
    const isOperational = error.isOperational;
    return {
      icon: AlertTriangle,
      title: isOperational ? '操作失败' : '系统错误',
      description: isOperational ? error.message : '发生了一个意外错误，请稍后重试或联系支持团队。',
      bgColor: variant === 'destructive' ? 'bg-red-50' : 'bg-gray-50',
      iconColor: variant === 'destructive' ? 'text-red-500' : 'text-gray-500',
      textColor: variant === 'destructive' ? 'text-red-800' : 'text-gray-800',
    };
  }

  // 默认配置
  return {
    icon: AlertTriangle,
    title: '出错了',
    description: typeof error === 'string' ? error : '发生了一个错误，请稍后重试。',
    bgColor: variant === 'destructive' ? 'bg-red-50' : 'bg-gray-50',
    iconColor: variant === 'destructive' ? 'text-red-500' : 'text-gray-500',
    textColor: variant === 'destructive' ? 'text-red-800' : 'text-gray-800',
  };
}

export default ErrorDisplay;

'use client';

import React, { useState, useMemo, useCallback, memo } from 'react';

import { Search, ChevronDown, X } from 'lucide-react';

import { oracleConfigs } from '@/lib/config/oracles';
import { chainNames, chainColors, getChainsByCategory, getChainCategory } from '@/lib/constants';
import { cn } from '@/lib/utils';
import { type Blockchain, OracleProvider, BLOCKCHAIN_VALUES } from '@/types/oracle';

export interface ChainSelectorProps {
  selectedChains: Blockchain[];
  onChainsChange: (chains: Blockchain[]) => void;
  supportedChains?: Blockchain[];
  allowMultiSelect?: boolean;
  filterByType?: 'all' | 'l1' | 'l2' | 'cosmos';
  showOracleCount?: boolean;
  className?: string;
  placeholder?: string;
}

const categoryLabels: Record<string, string> = {
  all: '全部',
  l1: 'Layer 1',
  l2: 'Layer 2',
  cosmos: 'Cosmos',
};

// Custom comparison function for ChainSelector props
function arePropsEqual(prevProps: ChainSelectorProps, nextProps: ChainSelectorProps): boolean {
  // Compare primitive props
  if (prevProps.allowMultiSelect !== nextProps.allowMultiSelect) return false;
  if (prevProps.filterByType !== nextProps.filterByType) return false;
  if (prevProps.showOracleCount !== nextProps.showOracleCount) return false;
  if (prevProps.className !== nextProps.className) return false;
  if (prevProps.placeholder !== nextProps.placeholder) return false;
  if (prevProps.onChainsChange !== nextProps.onChainsChange) return false;

  // Compare arrays by length and content
  if (prevProps.selectedChains.length !== nextProps.selectedChains.length) return false;
  for (let i = 0; i < prevProps.selectedChains.length; i++) {
    if (prevProps.selectedChains[i] !== nextProps.selectedChains[i]) {
      return false;
    }
  }

  // Compare supportedChains
  if (prevProps.supportedChains !== nextProps.supportedChains) {
    if (!prevProps.supportedChains || !nextProps.supportedChains) return false;
    if (prevProps.supportedChains.length !== nextProps.supportedChains.length) return false;
    for (let i = 0; i < prevProps.supportedChains.length; i++) {
      if (prevProps.supportedChains[i] !== nextProps.supportedChains[i]) {
        return false;
      }
    }
  }

  return true;
}

function ChainSelectorComponent({
  selectedChains,
  onChainsChange,
  supportedChains,
  allowMultiSelect = false,
  filterByType = 'all',
  showOracleCount = false,
  className,
  placeholder = '选择链...',
}: ChainSelectorProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState<'all' | 'l1' | 'l2' | 'cosmos'>(filterByType);

  // 获取可用的链列表
  const availableChains = useMemo(() => {
    let chains = supportedChains || BLOCKCHAIN_VALUES;
    if (activeFilter !== 'all') {
      const filteredByCategory = getChainsByCategory(activeFilter);
      chains = chains.filter((chain) => filteredByCategory.includes(chain));
    }
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      chains = chains.filter(
        (chain) =>
          chainNames[chain].toLowerCase().includes(query) || chain.toLowerCase().includes(query)
      );
    }
    return chains;
  }, [supportedChains, activeFilter, searchQuery]);

  // 计算每条链支持的预言机数量
  const getOracleCountForChain = (chain: Blockchain): number => {
    return Object.values(oracleConfigs).filter((config) => config.supportedChains.includes(chain))
      .length;
  };

  // 处理链选择
  const handleChainSelect = useCallback(
    (chain: Blockchain) => {
      if (allowMultiSelect) {
        if (selectedChains.includes(chain)) {
          onChainsChange(selectedChains.filter((c) => c !== chain));
        } else {
          onChainsChange([...selectedChains, chain]);
        }
      } else {
        onChainsChange([chain]);
        setIsOpen(false);
      }
    },
    [allowMultiSelect, selectedChains, onChainsChange]
  );

  // 清除选择
  const handleClear = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      onChainsChange([]);
    },
    [onChainsChange]
  );

  // 获取选中链的显示文本
  const getSelectedLabel = (): string => {
    if (selectedChains.length === 0) return placeholder;
    if (selectedChains.length === 1) return chainNames[selectedChains[0]];
    return `已选择 ${selectedChains.length} 条链`;
  };

  return (
    <div className={cn('relative', className)}>
      {/* 触发按钮 */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={cn(
          'flex items-center justify-between w-full px-4 py-2.5',
          'bg-white border border-gray-200 rounded-lg',
          'hover:border-gray-300 transition-colors',
          'focus:outline-none focus:ring-2 focus:ring-blue-500/20',
          isOpen && 'border-blue-500 ring-2 ring-blue-500/20'
        )}
      >
        <div className="flex items-center gap-2 overflow-hidden">
          {selectedChains.length > 0 && !allowMultiSelect && (
            <span
              className="w-2 h-2 rounded-full flex-shrink-0"
              style={{ backgroundColor: chainColors[selectedChains[0]] }}
            />
          )}
          <span className={cn('text-sm truncate', selectedChains.length === 0 && 'text-gray-400')}>
            {getSelectedLabel()}
          </span>
        </div>
        <div className="flex items-center gap-1 flex-shrink-0">
          {selectedChains.length > 0 && allowMultiSelect && (
            <button
              onClick={handleClear}
              className="p-0.5 hover:bg-gray-100 rounded-full transition-colors"
            >
              <X className="w-4 h-4 text-gray-400" />
            </button>
          )}
          <ChevronDown
            className={cn('w-4 h-4 text-gray-400 transition-transform', isOpen && 'rotate-180')}
          />
        </div>
      </button>

      {/* 下拉面板 */}
      {isOpen && (
        <div className="absolute z-50 w-full mt-1 bg-white border border-gray-200 rounded-lg shadow-lg">
          {/* 搜索框 */}
          <div className="p-3 border-b border-gray-100">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="搜索链..."
                className="w-full pl-9 pr-3 py-2 text-sm bg-gray-50 border border-gray-200 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500/20"
              />
            </div>
          </div>

          {/* 类型筛选 */}
          <div className="flex gap-1 p-2 border-b border-gray-100 overflow-x-auto">
            {(['all', 'l1', 'l2', 'cosmos'] as const).map((type) => (
              <button
                key={type}
                onClick={() => setActiveFilter(type)}
                className={cn(
                  'px-3 py-1 text-xs font-medium rounded-full whitespace-nowrap transition-colors',
                  activeFilter === type
                    ? 'bg-blue-100 text-blue-700'
                    : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                )}
              >
                {categoryLabels[type]}
              </button>
            ))}
          </div>

          {/* 链列表 */}
          <div className="max-h-64 overflow-y-auto py-1">
            {availableChains.length === 0 ? (
              <div className="px-4 py-3 text-sm text-gray-400 text-center">未找到匹配的链</div>
            ) : (
              availableChains.map((chain) => {
                const isSelected = selectedChains.includes(chain);
                const oracleCount = showOracleCount ? getOracleCountForChain(chain) : 0;
                const category = getChainCategory(chain);

                return (
                  <button
                    key={chain}
                    onClick={() => handleChainSelect(chain)}
                    className={cn(
                      'flex items-center justify-between w-full px-4 py-2.5',
                      'hover:bg-gray-50 transition-colors',
                      isSelected && 'bg-blue-50/50'
                    )}
                  >
                    <div className="flex items-center gap-3">
                      <span
                        className="w-3 h-3 rounded-full"
                        style={{ backgroundColor: chainColors[chain] }}
                      />
                      <div className="flex flex-col items-start">
                        <span className={cn('text-sm font-medium', isSelected && 'text-blue-700')}>
                          {chainNames[chain]}
                        </span>
                        <span className="text-xs text-gray-400">{category.toUpperCase()}</span>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      {showOracleCount && oracleCount > 0 && (
                        <span className="text-xs text-gray-400">{oracleCount} 个预言机</span>
                      )}
                      {isSelected && allowMultiSelect && (
                        <div className="w-4 h-4 bg-blue-500 rounded flex items-center justify-center">
                          <svg
                            className="w-3 h-3 text-white"
                            fill="currentColor"
                            viewBox="0 0 20 20"
                          >
                            <path
                              fillRule="evenodd"
                              d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
                              clipRule="evenodd"
                            />
                          </svg>
                        </div>
                      )}
                    </div>
                  </button>
                );
              })
            )}
          </div>

          {/* 底部操作栏（多选模式） */}
          {allowMultiSelect && selectedChains.length > 0 && (
            <div className="flex items-center justify-between px-4 py-2 border-t border-gray-100 bg-gray-50 rounded-b-lg">
              <span className="text-xs text-gray-500">已选择 {selectedChains.length} 条链</span>
              <button
                onClick={() => onChainsChange([])}
                className="text-xs text-blue-600 hover:text-blue-700 font-medium"
              >
                清除全部
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// Export memoized component
export const ChainSelector = memo(ChainSelectorComponent, arePropsEqual);
export default ChainSelector;

'use client';

import { useState, useRef, useEffect, useCallback } from 'react';

import { Bell, X, CheckCircle, AlertTriangle, AlertCircle, Info, ChevronRight } from 'lucide-react';

import type { API3Alert } from '@/lib/oracles/api3';
import {
  formatAlertTime,
  getAlertSeverityColor,
  getAlertSeverityBgColor,
} from '@/lib/oracles/api3AlertDetection';
import { cn } from '@/lib/utils';

interface API3AlertBadgeProps {
  unreadCount: number;
  criticalCount: number;
  warningCount: number;
  alerts: API3Alert[];
  onMarkRead?: (id: string) => void;
  onResolve?: (id: string) => void;
  onViewAll?: () => void;
  compact?: boolean;
}

export function API3AlertBadge({
  unreadCount,
  criticalCount,
  warningCount,
  alerts,
  onMarkRead,
  onResolve,
  onViewAll,
  compact = false,
}: API3AlertBadgeProps) {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const hasAlerts = unreadCount > 0;
  const isCritical = criticalCount > 0;

  const getBadgeColor = () => {
    if (criticalCount > 0) return 'bg-red-500';
    if (warningCount > 0) return 'bg-yellow-500';
    return 'bg-blue-500';
  };

  const recentAlerts = alerts.slice(0, 5);

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={cn(
          'relative flex items-center gap-2 px-3 py-2 rounded-lg transition-all',
          'hover:bg-gray-100 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2',
          isOpen && 'bg-gray-100'
        )}
        aria-label={`告警 (${unreadCount} 条未读)`}
      >
        <div className="relative">
          <Bell
            className={cn(
              'w-5 h-5 transition-colors',
              hasAlerts ? (isCritical ? 'text-red-500' : 'text-yellow-500') : 'text-gray-400'
            )}
          />
          {hasAlerts && (
            <span
              className={cn(
                'absolute -top-1 -right-1 min-w-[18px] h-[18px] flex items-center justify-center',
                'text-[10px] font-bold text-white rounded-full px-1',
                getBadgeColor()
              )}
            >
              {unreadCount > 99 ? '99+' : unreadCount}
            </span>
          )}
        </div>
        {!compact && (
          <span className="text-sm font-medium text-gray-700">
            {hasAlerts ? `${unreadCount} 条告警` : '无告警'}
          </span>
        )}
      </button>

      {isOpen && (
        <div
          className={cn(
            'absolute right-0 mt-2 w-80 sm:w-96 rounded-lg shadow-lg bg-white border border-gray-200',
            'z-50 animate-fade-in-down'
          )}
        >
          <div className="p-3 border-b border-gray-100">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-semibold text-gray-900">告警通知</h3>
              {hasAlerts && (
                <div className="flex items-center gap-2 text-xs">
                  {criticalCount > 0 && (
                    <span className="flex items-center gap-1 text-red-600">
                      <AlertCircle className="w-3 h-3" />
                      {criticalCount} 严重
                    </span>
                  )}
                  {warningCount > 0 && (
                    <span className="flex items-center gap-1 text-yellow-600">
                      <AlertTriangle className="w-3 h-3" />
                      {warningCount} 警告
                    </span>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="max-h-80 overflow-y-auto">
            {recentAlerts.length === 0 ? (
              <div className="p-6 text-center">
                <CheckCircle className="w-8 h-8 text-green-500 mx-auto mb-2" />
                <p className="text-sm text-gray-500">暂无告警</p>
              </div>
            ) : (
              <div className="divide-y divide-gray-50">
                {recentAlerts.map((alert) => (
                  <AlertBadgeItem
                    key={alert.id}
                    alert={alert}
                    onMarkRead={onMarkRead}
                    onResolve={onResolve}
                    onClose={() => {}}
                  />
                ))}
              </div>
            )}
          </div>

          {alerts.length > 5 && (
            <div className="p-2 border-t border-gray-100">
              <button
                onClick={() => {
                  setIsOpen(false);
                  onViewAll?.();
                }}
                className="w-full flex items-center justify-center gap-1 py-2 text-sm text-primary-600 hover:text-primary-700 hover:bg-gray-50 rounded-lg transition-colors"
              >
                查看全部 {alerts.length} 条告警
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

