export function API3AlertStatusIndicator({
  criticalCount,
  warningCount,
}: {
  criticalCount: number;
  warningCount: number;
}) {
  if (criticalCount === 0 && warningCount === 0) {
    return (
      <div className="flex items-center gap-1.5 px-2 py-1 rounded-full bg-green-50 border border-green-200">
        <CheckCircle className="w-3.5 h-3.5 text-green-500" />
        <span className="text-xs font-medium text-green-700">正常</span>
      </div>
    );
  }

  if (criticalCount > 0) {
    return (
      <div className="flex items-center gap-1.5 px-2 py-1 rounded-full bg-red-50 border border-red-200 animate-pulse">
        <AlertCircle className="w-3.5 h-3.5 text-red-500" />
        <span className="text-xs font-medium text-red-700">{criticalCount} 严重告警</span>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-1.5 px-2 py-1 rounded-full bg-yellow-50 border border-yellow-200">
      <AlertTriangle className="w-3.5 h-3.5 text-yellow-500" />
      <span className="text-xs font-medium text-yellow-700">{warningCount} 警告</span>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';

import { X, AlertTriangle, AlertCircle, Info, CheckCircle, Bell } from 'lucide-react';

import type { API3Alert } from '@/lib/oracles/api3';
import { formatAlertTime, getAlertSeverityColor } from '@/lib/oracles/api3AlertDetection';
import { cn } from '@/lib/utils';

interface API3AlertNotificationProps {
  alert: API3Alert;
  onMarkRead?: (id: string) => void;
  onResolve?: (id: string) => void;
  onDismiss?: (id: string) => void;
  autoClose?: boolean;
  autoCloseDelay?: number;
}

const severityIcons = {
  info: <Info className="w-5 h-5 text-blue-500" />,
  warning: <AlertTriangle className="w-5 h-5 text-yellow-500" />,
  critical: <AlertCircle className="w-5 h-5 text-red-500" />,
};

const severityStyles = {
  info: {
    bg: 'bg-blue-50 border-blue-200',
    iconBg: 'bg-blue-100',
    progress: 'bg-blue-500',
  },
  warning: {
    bg: 'bg-yellow-50 border-yellow-200',
    iconBg: 'bg-yellow-100',
    progress: 'bg-yellow-500',
  },
  critical: {
    bg: 'bg-red-50 border-red-200',
    iconBg: 'bg-red-100',
    progress: 'bg-red-500',
  },
};

export function API3AlertNotification({
  alert,
  onMarkRead,
  onResolve,
  onDismiss,
  autoClose = true,
  autoCloseDelay = 8000,
}: API3AlertNotificationProps) {
  const [isExiting, setIsExiting] = useState(false);
  const [progress, setProgress] = useState(100);
  const [isPaused, setIsPaused] = useState(false);

  const handleDismiss = useCallback(() => {
    setIsExiting(true);
    setTimeout(() => {
      onDismiss?.(alert.id);
    }, 300);
  }, [alert.id, onDismiss]);

  useEffect(() => {
    if (!autoClose || isPaused) return;

    const startTime = Date.now();
    const endTime = startTime + autoCloseDelay;

    const interval = setInterval(() => {
      const now = Date.now();
      const remaining = endTime - now;
      const newProgress = (remaining / autoCloseDelay) * 100;

      if (newProgress <= 0) {
        clearInterval(interval);
        handleDismiss();
      } else {
        setProgress(newProgress);
      }
    }, 50);

    return () => clearInterval(interval);
  }, [autoClose, autoCloseDelay, isPaused, handleDismiss]);

  const handleMarkRead = useCallback(() => {
    onMarkRead?.(alert.id);
  }, [alert.id, onMarkRead]);

  const handleResolve = useCallback(() => {
    onResolve?.(alert.id);
    handleDismiss();
  }, [alert.id, onResolve, handleDismiss]);

  const styles = severityStyles[alert.severity];

  return (
    <div
      className={cn(
        'relative overflow-hidden rounded-lg border shadow-lg transition-all duration-300',
        styles.bg,
        isExiting ? 'opacity-0 translate-x-4 scale-95' : 'opacity-100 translate-x-0 scale-100'
      )}
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
      role="alert"
    >
      <div className="p-4">
        <div className="flex items-start gap-3">
          <div className={cn('flex-shrink-0 p-2 rounded-full', styles.iconBg)}>
            {severityIcons[alert.severity]}
          </div>

          <div className="flex-1 min-w-0">
            <div className="flex items-start justify-between gap-2">
              <div className="flex-1">
                <h4 className="text-sm font-semibold text-gray-900">{alert.title}</h4>
                <p className="mt-1 text-sm text-gray-600">{alert.message}</p>
              </div>
              <button
                onClick={handleDismiss}
                className="flex-shrink-0 p-1 rounded hover:bg-black/5 transition-colors"
                aria-label="关闭"
              >
                <X className="w-4 h-4 text-gray-400" />
              </button>
            </div>

            {alert.metadata && (
              <div className="mt-2 flex flex-wrap gap-2 text-xs">
                {alert.metadata.symbol && (
                  <span className="px-2 py-0.5 bg-gray-100 rounded-full text-gray-600">
                    {alert.metadata.symbol}
                  </span>
                )}
                {alert.metadata.chain && (
                  <span className="px-2 py-0.5 bg-gray-100 rounded-full text-gray-600">
                    {alert.metadata.chain}
                  </span>
                )}
                {alert.metadata.currentValue !== undefined && (
                  <span className="px-2 py-0.5 bg-gray-100 rounded-full text-gray-600">
                    当前: {alert.metadata.currentValue.toFixed(2)}%
                  </span>
                )}
              </div>
            )}

            <div className="mt-3 flex items-center justify-between">
              <span className="text-xs text-gray-400">{formatAlertTime(alert.timestamp)}</span>
              <div className="flex items-center gap-2">
                {!alert.isRead && (
                  <button
                    onClick={handleMarkRead}
                    className="text-xs text-gray-500 hover:text-gray-700 transition-colors"
                  >
                    标记已读
                  </button>
                )}
                {!alert.isResolved && (
                  <button
                    onClick={handleResolve}
                    className="text-xs text-primary-600 hover:text-primary-700 font-medium transition-colors"
                  >
                    解决
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {autoClose && (
        <div className="absolute bottom-0 left-0 right-0 h-1 bg-gray-200/50">
          <div
            className={cn('h-full transition-all duration-100', styles.progress)}
            style={{ width: `${progress}%` }}
          />
        </div>
      )}
    </div>
  );
}

interface API3AlertNotificationContainerProps {
  alerts: API3Alert[];
  maxVisible?: number;
  onMarkRead?: (id: string) => void;
  onResolve?: (id: string) => void;
  onDismiss?: (id: string) => void;
}

export function API3AlertNotificationContainer({
  alerts,
  maxVisible = 3,
  onMarkRead,
  onResolve,
  onDismiss,
}: API3AlertNotificationContainerProps) {
  const [dismissedIds, setDismissedIds] = useState<Set<string>>(new Set());

  const visibleAlerts = alerts
    .filter((a) => !dismissedIds.has(a.id) && !a.isResolved)
    .slice(0, maxVisible);

  const handleDismiss = useCallback(
    (id: string) => {
      setDismissedIds((prev) => new Set([...prev, id]));
      onDismiss?.(id);
    },
    [onDismiss]
  );

  if (visibleAlerts.length === 0) return null;

  return (
    <div className="fixed top-4 right-4 z-50 flex flex-col gap-3 max-w-sm w-full pointer-events-none">
      {visibleAlerts.map((alert) => (
        <div key={alert.id} className="pointer-events-auto animate-slide-in-right">
          <API3AlertNotification
            alert={alert}
            onMarkRead={onMarkRead}
            onResolve={onResolve}
            onDismiss={handleDismiss}
          />
        </div>
      ))}
    </div>
  );
}

export function API3AlertToast({ alert, onClose }: { alert: API3Alert; onClose: () => void }) {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    requestAnimationFrame(() => {
      setIsVisible(true);
    });
  }, []);

  const handleClose = () => {
    setIsVisible(false);
    setTimeout(onClose, 300);
  };

  return (
    <div
      className={cn(
        'fixed bottom-4 right-4 z-50 max-w-sm w-full transition-all duration-300',
        isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'
      )}
    >
      <div className={cn('rounded-lg border shadow-lg p-4', getAlertSeverityColor(alert.severity))}>
        <div className="flex items-start gap-3">
          <div className="flex-shrink-0">
            <Bell className="w-5 h-5" />
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium">{alert.title}</p>
            <p className="text-xs mt-1 opacity-80">{formatAlertTime(alert.timestamp)}</p>
          </div>
          <button
            onClick={handleClose}
            className="flex-shrink-0 p-1 rounded hover:bg-black/5 transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useMemo, useCallback } from 'react';

import {
  Bell,
  Filter,
  CheckCircle,
  AlertTriangle,
  AlertCircle,
  Info,
  Clock,
  ChevronDown,
  Check,
  X,
  RefreshCw,
  Settings,
  TrendingUp,
  Server,
  Shield,
  Lock,
} from 'lucide-react';

import type { API3Alert, AlertThreshold } from '@/lib/oracles/api3';
import {
  formatAlertTime,
  getAlertSeverityColor,
  getAlertSeverityBgColor,
} from '@/lib/oracles/api3AlertDetection';
import { cn } from '@/lib/utils';

type AlertFilterType =
  | 'all'
  | 'price_deviation'
  | 'node_offline'
  | 'coverage_pool_risk'
  | 'security_event';
type AlertFilterSeverity = 'all' | 'info' | 'warning' | 'critical';
type AlertFilterStatus = 'all' | 'unread' | 'resolved' | 'unresolved';

interface API3AlertPanelProps {
  alerts: API3Alert[];
  thresholds?: AlertThreshold[];
  onMarkRead?: (id: string) => void;
  onResolve?: (id: string) => void;
  onMarkAllRead?: () => void;
  onResolveAll?: () => void;
  onRefresh?: () => void;
  isLoading?: boolean;
}

const typeIcons: Record<API3Alert['type'], React.ReactNode> = {
  price_deviation: <TrendingUp className="w-4 h-4" />,
  node_offline: <Server className="w-4 h-4" />,
  coverage_pool_risk: <Shield className="w-4 h-4" />,
  security_event: <Lock className="w-4 h-4" />,
};

const typeLabels: Record<API3Alert['type'], string> = {
  price_deviation: '价格偏差',
  node_offline: '节点离线',
  coverage_pool_risk: '覆盖池风险',
  security_event: '安全事件',
};

const severityIcons = {
  info: <Info className="w-4 h-4 text-blue-500" />,
  warning: <AlertTriangle className="w-4 h-4 text-yellow-500" />,
  critical: <AlertCircle className="w-4 h-4 text-red-500" />,
};

export function API3AlertPanel({
  alerts,
  thresholds = [],
  onMarkRead,
  onResolve,
  onMarkAllRead,
  onResolveAll,
  onRefresh,
  isLoading = false,
}: API3AlertPanelProps) {
  const [filterType, setFilterType] = useState<AlertFilterType>('all');
  const [filterSeverity, setFilterSeverity] = useState<AlertFilterSeverity>('all');
  const [filterStatus, setFilterStatus] = useState<AlertFilterStatus>('all');
  const [selectedAlerts, setSelectedAlerts] = useState<Set<string>>(new Set());
  const [showFilters, setShowFilters] = useState(false);

  const filteredAlerts = useMemo(() => {
    return alerts.filter((alert) => {
      if (filterType !== 'all' && alert.type !== filterType) return false;
      if (filterSeverity !== 'all' && alert.severity !== filterSeverity) return false;
      if (filterStatus === 'unread' && alert.isRead) return false;
      if (filterStatus === 'resolved' && !alert.isResolved) return false;
      if (filterStatus === 'unresolved' && alert.isResolved) return false;
      return true;
    });
  }, [alerts, filterType, filterSeverity, filterStatus]);

  const stats = useMemo(() => {
    return {
      total: alerts.length,
      unread: alerts.filter((a) => !a.isRead).length,
      critical: alerts.filter((a) => a.severity === 'critical' && !a.isResolved).length,
      warning: alerts.filter((a) => a.severity === 'warning' && !a.isResolved).length,
      info: alerts.filter((a) => a.severity === 'info' && !a.isResolved).length,
      resolved: alerts.filter((a) => a.isResolved).length,
    };
  }, [alerts]);

  const toggleSelect = useCallback((id: string) => {
    setSelectedAlerts((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }, []);

  const selectAll = useCallback(() => {
    setSelectedAlerts(new Set(filteredAlerts.map((a) => a.id)));
  }, [filteredAlerts]);

  const clearSelection = useCallback(() => {
    setSelectedAlerts(new Set());
  }, []);

  const handleBatchResolve = useCallback(() => {
    selectedAlerts.forEach((id) => {
      onResolve?.(id);
    });
    clearSelection();
  }, [selectedAlerts, onResolve, clearSelection]);

  const handleBatchMarkRead = useCallback(() => {
    selectedAlerts.forEach((id) => {
      onMarkRead?.(id);
    });
    clearSelection();
  }, [selectedAlerts, onMarkRead, clearSelection]);

  return (
    <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
      <div className="p-4 border-b border-gray-100">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-primary-50">
              <Bell className="w-5 h-5 text-primary-600" />
            </div>
            <div>
              <h2 className="text-lg font-semibold text-gray-900">告警中心</h2>
              <p className="text-sm text-gray-500">
                共 {stats.total} 条告警，{stats.unread} 条未读
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={() => setShowFilters(!showFilters)}
              className={cn(
                'flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium rounded-lg border transition-colors',
                showFilters
                  ? 'bg-primary-50 border-primary-200 text-primary-700'
                  : 'bg-white border-gray-200 text-gray-700 hover:bg-gray-50'
              )}
            >
              <Filter className="w-4 h-4" />
              筛选
              <ChevronDown
                className={cn('w-3 h-3 transition-transform', showFilters && 'rotate-180')}
              />
            </button>
            <button
              onClick={onRefresh}
              disabled={isLoading}
              className="flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-gray-700 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 disabled:opacity-50 transition-colors"
            >
              <RefreshCw className={cn('w-4 h-4', isLoading && 'animate-spin')} />
              刷新
            </button>
          </div>
        </div>

        {showFilters && (
          <div className="mt-4 pt-4 border-t border-gray-100">
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">告警类型</label>
                <select
                  value={filterType}
                  onChange={(e) => setFilterType(e.target.value as AlertFilterType)}
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
                >
                  <option value="all">全部类型</option>
                  <option value="price_deviation">价格偏差</option>
                  <option value="node_offline">节点离线</option>
                  <option value="coverage_pool_risk">覆盖池风险</option>
                  <option value="security_event">安全事件</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">严重程度</label>
                <select
                  value={filterSeverity}
                  onChange={(e) => setFilterSeverity(e.target.value as AlertFilterSeverity)}
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
                >
                  <option value="all">全部级别</option>
                  <option value="critical">严重</option>
                  <option value="warning">警告</option>
                  <option value="info">信息</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">状态</label>
                <select
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value as AlertFilterStatus)}
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
                >
                  <option value="all">全部状态</option>
                  <option value="unread">未读</option>
                  <option value="unresolved">未解决</option>
                  <option value="resolved">已解决</option>
                </select>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-gray-50 border-b border-gray-100">
        <div className="flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="text-xs font-medium text-gray-500">统计:</span>
            {stats.critical > 0 && (
              <span className="flex items-center gap-1 px-2 py-0.5 bg-red-100 text-red-700 rounded-full text-xs font-medium">
                <AlertCircle className="w-3 h-3" />
                {stats.critical} 严重
              </span>
            )}
            {stats.warning > 0 && (
              <span className="flex items-center gap-1 px-2 py-0.5 bg-yellow-100 text-yellow-700 rounded-full text-xs font-medium">
                <AlertTriangle className="w-3 h-3" />
                {stats.warning} 警告
              </span>
            )}
            {stats.info > 0 && (
              <span className="flex items-center gap-1 px-2 py-0.5 bg-blue-100 text-blue-700 rounded-full text-xs font-medium">
                <Info className="w-3 h-3" />
                {stats.info} 信息
              </span>
            )}
            {stats.resolved > 0 && (
              <span className="flex items-center gap-1 px-2 py-0.5 bg-green-100 text-green-700 rounded-full text-xs font-medium">
                <CheckCircle className="w-3 h-3" />
                {stats.resolved} 已解决
              </span>
            )}
          </div>

          <div className="flex items-center gap-2 ml-auto">
            {selectedAlerts.size > 0 && (
              <>
                <span className="text-xs text-gray-500">已选择 {selectedAlerts.size} 条</span>
                <button
                  onClick={handleBatchMarkRead}
                  className="text-xs text-primary-600 hover:text-primary-700 font-medium"
                >
                  标记已读
                </button>
                <button
                  onClick={handleBatchResolve}
                  className="text-xs text-primary-600 hover:text-primary-700 font-medium"
                >
                  批量解决
                </button>
                <button
                  onClick={clearSelection}
                  className="text-xs text-gray-500 hover:text-gray-700"
                >
                  取消选择
                </button>
              </>
            )}
            {selectedAlerts.size === 0 && stats.unread > 0 && (
              <button
                onClick={onMarkAllRead}
                className="text-xs text-primary-600 hover:text-primary-700 font-medium"
              >
                全部标记已读
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="divide-y divide-gray-100">
        {filteredAlerts.length === 0 ? (
          <div className="p-8 text-center">
            <Bell className="w-12 h-12 text-gray-300 mx-auto mb-3" />
            <p className="text-sm text-gray-500">暂无符合条件的告警</p>
          </div>
        ) : (
          filteredAlerts.map((alert) => (
            <AlertPanelItem
              key={alert.id}
              alert={alert}
              isSelected={selectedAlerts.has(alert.id)}
              onToggleSelect={() => toggleSelect(alert.id)}
              onMarkRead={onMarkRead}
              onResolve={onResolve}
            />
          ))
        )}
      </div>
    </div>
  );
}

interface AlertPanelItemProps {
  alert: API3Alert;
  isSelected: boolean;
  onToggleSelect: () => void;
  onMarkRead?: (id: string) => void;
  onResolve?: (id: string) => void;
