'use client';

import { useState, useEffect, useCallback } from 'react';

import { DashboardCard } from '@/components/oracle/data-display/DashboardCard';
import { useTranslations } from '@/i18n';
import { isDataStale, formatRelativeTime } from '@/lib/utils/riskUtils';

export interface DataFreshnessIndicatorProps {
  lastUpdated: Date;
  thresholdMinutes?: number;
  onRefresh?: () => void;
  isLoading?: boolean;
  className?: string;
}

export function DataFreshnessIndicator({
  lastUpdated,
  thresholdMinutes = 5,
  onRefresh,
  isLoading = false,
  className = '',
}: DataFreshnessIndicatorProps) {
  const t = useTranslations();
  const [displayTime, setDisplayTime] = useState<string>('');
  const [isStale, setIsStale] = useState<boolean>(false);

  const updateDisplay = useCallback(() => {
    setDisplayTime(formatRelativeTime(lastUpdated));
    setIsStale(isDataStale(lastUpdated, thresholdMinutes));
  }, [lastUpdated, thresholdMinutes]);

  useEffect(() => {
    updateDisplay();
    const interval = setInterval(updateDisplay, 1000);
    return () => clearInterval(interval);
  }, [updateDisplay]);

  const handleRefresh = () => {
    if (onRefresh && !isLoading) {
      onRefresh();
    }
  };

  const getStatusColor = () => {
    if (isStale) return 'text-danger-600';
    return 'text-success-600';
  };

  const getStatusBg = () => {
    if (isStale) return 'bg-danger-50';
    return 'bg-success-50';
  };

  const getStatusDot = () => {
    if (isStale) return 'bg-danger-500';
    return 'bg-success-500';
  };

  return (
    <DashboardCard
      title={t('oracleCommon.dataFreshness.title')}
      className={className}
      headerAction={
        onRefresh && (
          <button
            onClick={handleRefresh}
            disabled={isLoading}
            className="p-1.5 text-gray-500 hover:text-gray-700 hover:bg-gray-100 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            aria-label={t('oracleCommon.dataFreshness.refresh')}
          >
            <svg
              className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
              />
            </svg>
          </button>
        )
      }
    >
      <div className="flex items-center gap-3">
        <div className={`p-2 ${getStatusBg()}`}>
          <div className={`w-2 h-2 ${getStatusDot()} ${!isStale ? 'animate-pulse' : ''}`} />
        </div>
        <div className="flex-1">
          <p className="text-sm text-gray-600">{t('oracleCommon.dataFreshness.lastUpdated')}</p>
          <p className={`text-sm font-medium ${getStatusColor()}`}>{displayTime}</p>
        </div>
        {isStale && (
          <span className="px-2 py-1 bg-danger-100 text-danger-700 text-xs font-medium">
            {t('oracleCommon.dataFreshness.stale')}
          </span>
        )}
      </div>
    </DashboardCard>
  );
}

export default DataFreshnessIndicator;

'use client';

import { useState, useCallback, useMemo, useEffect } from 'react';

import {
  AlertTriangle,
  AlertCircle,
  Info,
  Download,
  Settings,
  Filter,
  TrendingUp,
  TrendingDown,
  BarChart3,
  FileText,
} from 'lucide-react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  ScatterChart,
  Scatter,
  ZAxis,
  ReferenceLine,
  BarChart,
  Bar,
} from 'recharts';

import useAPI3Analytics, { type DataPoint, type Anomaly } from '@/hooks/useAPI3Analytics';
import { useTranslations } from '@/i18n';
import { chartColors } from '@/lib/config/colors';

export interface AnomalyDetectionProps {
  data: DataPoint[];
  sensitivity: 'low' | 'medium' | 'high';
  onAnomalyDetected?: (anomalies: Anomaly[]) => void;
}

const sensitivityOptions = [
  { value: 'low', label: 'Low', description: 'Only detect extreme anomalies' },
  { value: 'medium', label: 'Medium', description: 'Balanced detection sensitivity' },
  { value: 'high', label: 'High', description: 'Detect subtle anomalies' },
];

export function AnomalyDetection({
  data,
  sensitivity: initialSensitivity,
  onAnomalyDetected,
}: AnomalyDetectionProps) {
  const t = useTranslations();
  const {
    detectAnomalies,
    detectAnomaliesByZScore,
    detectAnomaliesByIQR,
    calculateMean,
    calculateStandardDeviation,
  } = useAPI3Analytics();

  const [sensitivity, setSensitivity] = useState(initialSensitivity);
  const [showSettings, setShowSettings] = useState(false);
  const [selectedMethod, setSelectedMethod] = useState<'combined' | 'zscore' | 'iqr'>('combined');
  const [selectedSeverity, setSelectedSeverity] = useState<'all' | 'low' | 'medium' | 'high'>(
    'all'
  );
  const [selectedAnomaly, setSelectedAnomaly] = useState<Anomaly | null>(null);

  const anomalies = useMemo(() => {
    if (data.length < 3) return [];

    let detected: Anomaly[];
    switch (selectedMethod) {
      case 'zscore':
        detected = detectAnomaliesByZScore(
          data,
          sensitivity === 'low' ? 3.5 : sensitivity === 'medium' ? 2.5 : 1.5
        );
        break;
      case 'iqr':
        detected = detectAnomaliesByIQR(data);
        break;
      default:
        detected = detectAnomalies(data, sensitivity);
    }

    return detected;
  }, [
    data,
    sensitivity,
    selectedMethod,
    detectAnomalies,
    detectAnomaliesByZScore,
    detectAnomaliesByIQR,
  ]);

  useEffect(() => {
    if (anomalies.length > 0 && onAnomalyDetected) {
      onAnomalyDetected(anomalies);
    }
  }, [anomalies, onAnomalyDetected]);

  const filteredAnomalies = useMemo(() => {
    if (selectedSeverity === 'all') return anomalies;
    return anomalies.filter((a) => a.severity === selectedSeverity);
  }, [anomalies, selectedSeverity]);

  const chartData = useMemo(() => {
    return data.map((d, index) => {
      const anomaly = anomalies.find((a) => a.index === index);
      return {
        time: new Date(d.timestamp).toLocaleDateString(),
        timestamp: d.timestamp,
        value: d.value,
        isAnomaly: !!anomaly,
        anomalySeverity: anomaly?.severity,
        expectedValue: anomaly?.expectedValue,
      };
    });
  }, [data, anomalies]);

  const statistics = useMemo(() => {
    if (data.length === 0) return null;

    const values = data.map((d) => d.value);
    const mean = calculateMean(values);
    const std = calculateStandardDeviation(values);

    return {
      totalPoints: data.length,
      anomalyCount: anomalies.length,
      anomalyRate: (anomalies.length / data.length) * 100,
      mean,
      std,
      severityBreakdown: {
        high: anomalies.filter((a) => a.severity === 'high').length,
        medium: anomalies.filter((a) => a.severity === 'medium').length,
        low: anomalies.filter((a) => a.severity === 'low').length,
      },
    };
  }, [data, anomalies, calculateMean, calculateStandardDeviation]);

  const handleExport = useCallback(() => {
    const exportData = {
      anomalies: filteredAnomalies,
      statistics,
      config: {
        sensitivity,
        method: selectedMethod,
      },
      timestamp: new Date().toISOString(),
    };

    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `anomaly-report-${Date.now()}.json`;
    a.click();
    URL.revokeObjectURL(url);
  }, [filteredAnomalies, statistics, sensitivity, selectedMethod]);

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'high':
        return '#ef4444';
      case 'medium':
        return '#f59e0b';
      case 'low':
        return '#3b82f6';
      default:
        return '#6b7280';
    }
  };

  const getSeverityBgColor = (severity: string) => {
    switch (severity) {
      case 'high':
        return 'bg-red-50 text-red-700';
      case 'medium':
        return 'bg-amber-50 text-amber-700';
      case 'low':
        return 'bg-blue-50 text-blue-700';
