              </h3>
              <div className="space-y-2 text-sm">
                <div className="flex justify-between">
                  <span className="text-gray-500">Time</span>
                  <span className="text-gray-900">
                    {new Date(selectedAnomaly.timestamp).toLocaleString()}
                  </span>
                </div>
                <div className="flex justify-between">
