'use client';

import { useState, useCallback, useMemo } from 'react';

import {
  FileText,
  Download,
  Save,
  Eye,
  Plus,
  X,
  Calendar,
  BarChart3,
  LineChart,
  AreaChart,
  Filter,
  Settings,
  ChevronDown,
  Check,
} from 'lucide-react';
import {
  LineChart as RechartsLineChart,
  Line,
  BarChart as RechartsBarChart,
  Bar,
  AreaChart as RechartsAreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  ScatterChart,
  Scatter,
} from 'recharts';

import { type MetricDefinition, type ReportConfig, type DataPoint } from '@/hooks/useAPI3Analytics';
import { useTranslations } from '@/i18n';
import { chartColors } from '@/lib/config/colors';

export interface CustomReportGeneratorProps {
  availableMetrics: MetricDefinition[];
  onGenerate: (config: ReportConfig) => void;
  data?: DataPoint[];
}

const chartTypeOptions = [
  { id: 'line', label: 'Line Chart', icon: LineChart },
  { id: 'bar', label: 'Bar Chart', icon: BarChart3 },
  { id: 'area', label: 'Area Chart', icon: AreaChart },
  { id: 'scatter', label: 'Scatter Plot', icon: BarChart3 },
];

const quickTimeRanges = [
  { label: 'Last 7 Days', days: 7 },
  { label: 'Last 30 Days', days: 30 },
  { label: 'Last 90 Days', days: 90 },
  { label: 'Last Year', days: 365 },
];

export function CustomReportGenerator({
  availableMetrics,
  onGenerate,
  data = [],
}: CustomReportGeneratorProps) {
  const t = useTranslations();

  const [title, setTitle] = useState('Custom Report');
  const [selectedMetrics, setSelectedMetrics] = useState<string[]>([]);
  const [chartType, setChartType] = useState<ReportConfig['chartType']>('line');
  const [timeRange, setTimeRange] = useState<{ start: Date; end: Date }>({
    start: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000),
    end: new Date(),
  });
  const [filters, setFilters] = useState<Record<string, unknown>>({});
  const [showPreview, setShowPreview] = useState(false);
  const [showMetricSelector, setShowMetricSelector] = useState(false);
  const [savedTemplates, setSavedTemplates] = useState<ReportConfig[]>([]);

  const handleMetricToggle = useCallback((metricId: string) => {
    setSelectedMetrics((prev) =>
      prev.includes(metricId) ? prev.filter((id) => id !== metricId) : [...prev, metricId]
    );
  }, []);

  const handleQuickTimeRange = useCallback((days: number) => {
    setTimeRange({
      start: new Date(Date.now() - days * 24 * 60 * 60 * 1000),
      end: new Date(),
    });
  }, []);

  const handleGenerate = useCallback(() => {
    const config: ReportConfig = {
      title,
      metrics: selectedMetrics,
      timeRange,
      chartType,
      filters,
    };
    onGenerate(config);
    setShowPreview(true);
  }, [title, selectedMetrics, timeRange, chartType, filters, onGenerate]);

  const handleSaveTemplate = useCallback(() => {
    const config: ReportConfig = {
      title,
      metrics: selectedMetrics,
      timeRange,
      chartType,
      filters,
    };
    setSavedTemplates((prev) => [...prev, config]);
  }, [title, selectedMetrics, timeRange, chartType, filters]);

  const handleExportPDF = useCallback(() => {}, []);

  const handleExportImage = useCallback(() => {}, []);

  const previewData = useMemo(() => {
    if (!showPreview || data.length === 0) return [];
    return data
      .filter(
        (d) => d.timestamp >= timeRange.start.getTime() && d.timestamp <= timeRange.end.getTime()
      )
      .map((d) => ({
        ...d,
        time: new Date(d.timestamp).toLocaleDateString(),
      }));
  }, [showPreview, data, timeRange]);

  const groupedMetrics = useMemo(() => {
    const groups: Record<string, MetricDefinition[]> = {};
    availableMetrics.forEach((metric) => {
      if (!groups[metric.category]) {
        groups[metric.category] = [];
      }
      groups[metric.category].push(metric);
    });
    return groups;
  }, [availableMetrics]);

  const renderChart = () => {
    if (previewData.length === 0) return null;

    const commonProps = {
      data: previewData,
    };

    switch (chartType) {
      case 'line':
        return (
          <ResponsiveContainer width="100%" height={300}>
            <RechartsLineChart data={previewData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis dataKey="time" tick={{ fontSize: 11, fill: '#6b7280' }} />
              <YAxis tick={{ fontSize: 11, fill: '#6b7280' }} />
              <Tooltip />
              <Legend />
              <Line
                type="monotone"
                dataKey="value"
                stroke={chartColors.oracle.api3}
                strokeWidth={2}
                dot={false}
              />
            </RechartsLineChart>
          </ResponsiveContainer>
        );
      case 'bar':
        return (
          <ResponsiveContainer width="100%" height={300}>
            <RechartsBarChart data={previewData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis dataKey="time" tick={{ fontSize: 11, fill: '#6b7280' }} />
              <YAxis tick={{ fontSize: 11, fill: '#6b7280' }} />
              <Tooltip />
              <Legend />
              <Bar dataKey="value" fill={chartColors.oracle.api3} />
            </RechartsBarChart>
          </ResponsiveContainer>
        );
      case 'area':
        return (
          <ResponsiveContainer width="100%" height={300}>
            <RechartsAreaChart data={previewData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis dataKey="time" tick={{ fontSize: 11, fill: '#6b7280' }} />
              <YAxis tick={{ fontSize: 11, fill: '#6b7280' }} />
              <Tooltip />
              <Legend />
              <Area
                type="monotone"
                dataKey="value"
                stroke={chartColors.oracle.api3}
                fill={chartColors.oracle.api3}
                fillOpacity={0.3}
              />
            </RechartsAreaChart>
          </ResponsiveContainer>
        );
      case 'scatter':
        return (
          <ResponsiveContainer width="100%" height={300}>
            <ScatterChart>
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis dataKey="time" tick={{ fontSize: 11, fill: '#6b7280' }} />
              <YAxis tick={{ fontSize: 11, fill: '#6b7280' }} />
              <Tooltip />
              <Legend />
              <Scatter data={previewData} fill={chartColors.oracle.api3} />
            </ScatterChart>
          </ResponsiveContainer>
        );
      default:
        return null;
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-gray-900">
            {t('api3.analytics.reportGenerator.title') || 'Custom Report Generator'}
          </h2>
          <p className="text-sm text-gray-500 mt-1">
            {t('api3.analytics.reportGenerator.subtitle') ||
              'Create custom reports with selected metrics and time ranges'}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={handleSaveTemplate}
            className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50"
          >
            <Save className="w-4 h-4" />
            {t('api3.analytics.reportGenerator.saveTemplate') || 'Save Template'}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white border border-gray-200 rounded-lg p-4">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              {t('api3.analytics.reportGenerator.reportTitle') || 'Report Title'}
            </label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
              placeholder="Enter report title..."
            />
          </div>

          <div className="bg-white border border-gray-200 rounded-lg p-4">
            <div className="flex items-center justify-between mb-3">
              <label className="text-sm font-medium text-gray-700">
                {t('api3.analytics.reportGenerator.selectMetrics') || 'Select Metrics'}
              </label>
              <button
                onClick={() => setShowMetricSelector(!showMetricSelector)}
                className="flex items-center gap-1 text-sm text-emerald-600 hover:text-emerald-700"
              >
                <Plus className="w-4 h-4" />
                {t('api3.analytics.reportGenerator.addMetric') || 'Add Metric'}
              </button>
            </div>

            {selectedMetrics.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-3">
                {selectedMetrics.map((metricId) => {
                  const metric = availableMetrics.find((m) => m.id === metricId);
                  return metric ? (
                    <span
                      key={metricId}
                      className="inline-flex items-center gap-1 px-2 py-1 bg-emerald-50 text-emerald-700 rounded-md text-sm"
                    >
                      {metric.name}
                      <button
                        onClick={() => handleMetricToggle(metricId)}
                        className="hover:text-emerald-900"
                      >
                        <X className="w-3 h-3" />
                      </button>
                    </span>
                  ) : null;
                })}
              </div>
            )}

            {showMetricSelector && (
              <div className="border border-gray-200 rounded-md max-h-60 overflow-y-auto">
                {Object.entries(groupedMetrics).map(([category, metrics]) => (
                  <div key={category} className="border-b border-gray-100 last:border-0">
                    <div className="px-3 py-2 bg-gray-50 text-xs font-medium text-gray-500 uppercase">
                      {category}
                    </div>
                    {metrics.map((metric) => (
                      <button
                        key={metric.id}
                        onClick={() => handleMetricToggle(metric.id)}
                        className={`w-full px-3 py-2 flex items-center justify-between hover:bg-gray-50 ${
                          selectedMetrics.includes(metric.id) ? 'bg-emerald-50' : ''
                        }`}
                      >
                        <div className="text-left">
                          <div className="text-sm text-gray-900">{metric.name}</div>
                          {metric.description && (
                            <div className="text-xs text-gray-500">{metric.description}</div>
                          )}
                        </div>
                        {selectedMetrics.includes(metric.id) && (
                          <Check className="w-4 h-4 text-emerald-600" />
                        )}
                      </button>
                    ))}
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="bg-white border border-gray-200 rounded-lg p-4">
            <label className="block text-sm font-medium text-gray-700 mb-3">
              {t('api3.analytics.reportGenerator.timeRange') || 'Time Range'}
            </label>
            <div className="flex flex-wrap gap-2 mb-3">
              {quickTimeRanges.map((range) => (
                <button
                  key={range.label}
                  onClick={() => handleQuickTimeRange(range.days)}
                  className="px-3 py-1.5 text-sm border border-gray-300 rounded-md hover:bg-gray-50"
                >
                  {range.label}
                </button>
              ))}
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs text-gray-500 mb-1">Start Date</label>
                <input
                  type="date"
                  value={timeRange.start.toISOString().split('T')[0]}
                  onChange={(e) =>
                    setTimeRange((prev) => ({ ...prev, start: new Date(e.target.value) }))
                  }
                  className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm"
                />
              </div>
              <div>
                <label className="block text-xs text-gray-500 mb-1">End Date</label>
                <input
                  type="date"
                  value={timeRange.end.toISOString().split('T')[0]}
                  onChange={(e) =>
                    setTimeRange((prev) => ({ ...prev, end: new Date(e.target.value) }))
                  }
                  className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm"
                />
              </div>
            </div>
          </div>

          <div className="bg-white border border-gray-200 rounded-lg p-4">
            <label className="block text-sm font-medium text-gray-700 mb-3">
              {t('api3.analytics.reportGenerator.chartType') || 'Chart Type'}
            </label>
            <div className="grid grid-cols-4 gap-2">
              {chartTypeOptions.map((option) => {
                const Icon = option.icon;
                return (
                  <button
                    key={option.id}
                    onClick={() => setChartType(option.id as ReportConfig['chartType'])}
                    className={`flex flex-col items-center gap-1 p-3 border rounded-md transition-colors ${
                      chartType === option.id
                        ? 'border-emerald-500 bg-emerald-50 text-emerald-700'
                        : 'border-gray-300 hover:bg-gray-50'
                    }`}
                  >
                    <Icon className="w-5 h-5" />
                    <span className="text-xs">{option.label}</span>
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white border border-gray-200 rounded-lg p-4">
            <h3 className="text-sm font-medium text-gray-700 mb-3">
              {t('api3.analytics.reportGenerator.savedTemplates') || 'Saved Templates'}
            </h3>
            {savedTemplates.length > 0 ? (
              <div className="space-y-2">
                {savedTemplates.map((template, index) => (
                  <button
                    key={index}
                    className="w-full text-left px-3 py-2 border border-gray-200 rounded-md hover:bg-gray-50 text-sm"
                    onClick={() => {
                      setTitle(template.title);
                      setSelectedMetrics(template.metrics);
                      setTimeRange(template.timeRange);
                      setChartType(template.chartType);
                      setFilters(template.filters);
                    }}
                  >
                    {template.title}
                  </button>
                ))}
              </div>
            ) : (
              <p className="text-sm text-gray-500">
                {t('api3.analytics.reportGenerator.noTemplates') || 'No saved templates'}
              </p>
            )}
          </div>

          <div className="bg-white border border-gray-200 rounded-lg p-4">
            <h3 className="text-sm font-medium text-gray-700 mb-3">
              {t('api3.analytics.reportGenerator.filters') || 'Filters'}
            </h3>
            <div className="space-y-2">
              <button className="w-full flex items-center justify-between px-3 py-2 border border-gray-200 rounded-md hover:bg-gray-50 text-sm">
                <span className="text-gray-600">Add Filter</span>
                <Plus className="w-4 h-4 text-gray-400" />
              </button>
            </div>
          </div>

          <div className="flex flex-col gap-2">
            <button
              onClick={handleGenerate}
              disabled={selectedMetrics.length === 0}
              className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-md hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Eye className="w-4 h-4" />
              {t('api3.analytics.reportGenerator.preview') || 'Preview Report'}
            </button>
            <button
              onClick={handleExportPDF}
              disabled={!showPreview}
              className="w-full flex items-center justify-center gap-2 px-4 py-2 border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Download className="w-4 h-4" />
              {t('api3.analytics.reportGenerator.exportPDF') || 'Export PDF'}
            </button>
            <button
              onClick={handleExportImage}
              disabled={!showPreview}
              className="w-full flex items-center justify-center gap-2 px-4 py-2 border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Download className="w-4 h-4" />
              {t('api3.analytics.reportGenerator.exportImage') || 'Export Image'}
            </button>
          </div>
        </div>
      </div>

      {showPreview && previewData.length > 0 && (
        <div className="bg-white border border-gray-200 rounded-lg p-4">
          <h3 className="text-sm font-medium text-gray-700 mb-4">
            {t('api3.analytics.reportGenerator.previewTitle') || 'Report Preview'}
          </h3>
          {renderChart()}
          <div className="mt-4 grid grid-cols-4 gap-4">
            <div className="text-center">
              <div className="text-xs text-gray-500">Data Points</div>
              <div className="text-lg font-semibold text-gray-900">{previewData.length}</div>
            </div>
            <div className="text-center">
              <div className="text-xs text-gray-500">Min Value</div>
              <div className="text-lg font-semibold text-gray-900">
                {Math.min(...previewData.map((d) => d.value)).toFixed(2)}
              </div>
            </div>
            <div className="text-center">
              <div className="text-xs text-gray-500">Max Value</div>
              <div className="text-lg font-semibold text-gray-900">
                {Math.max(...previewData.map((d) => d.value)).toFixed(2)}
              </div>
            </div>
            <div className="text-center">
              <div className="text-xs text-gray-500">Average</div>
              <div className="text-lg font-semibold text-gray-900">
                {(previewData.reduce((sum, d) => sum + d.value, 0) / previewData.length).toFixed(2)}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default CustomReportGenerator;

'use client';

import { useState, useCallback, useMemo } from 'react';

import {
  GitCompare,
  Download,
  TrendingUp,
  TrendingDown,
  Minus,
  AlertCircle,
  CheckCircle,
  Info,
} from 'lucide-react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  BarChart,
  Bar,
  ReferenceLine,
  Cell,
} from 'recharts';

import useAPI3Analytics, {
  type DataSource,
  type TimeRange,
  type ComparisonResult,
} from '@/hooks/useAPI3Analytics';
import { useTranslations } from '@/i18n';
import { chartColors } from '@/lib/config/colors';

export interface DataComparisonToolProps {
  dataSources: DataSource[];
  metrics: string[];
  timeRange: TimeRange;
}

const mockChains = [
  { id: 'ethereum', name: 'Ethereum' },
  { id: 'polygon', name: 'Polygon' },
  { id: 'arbitrum', name: 'Arbitrum' },
  { id: 'optimism', name: 'Optimism' },
  { id: 'base', name: 'Base' },
];

const mockDapis = [
  { id: 'eth-usd', name: 'ETH/USD' },
  { id: 'btc-usd', name: 'BTC/USD' },
  { id: 'api3-usd', name: 'API3/USD' },
  { id: 'usdc-usd', name: 'USDC/USD' },
];

export function DataComparisonTool({
  dataSources: initialDataSources,
  metrics,
  timeRange,
}: DataComparisonToolProps) {
  const t = useTranslations();
  const { compareDataSources, calculateCorrelation } = useAPI3Analytics();

  const [source1Id, setSource1Id] = useState<string>('');
  const [source2Id, setSource2Id] = useState<string>('');
  const [selectedMetric, setSelectedMetric] = useState<string>(metrics[0] || 'price');
  const [comparisonType, setComparisonType] = useState<'dapi' | 'chain' | 'timeframe'>('dapi');
  const [comparisonResult, setComparisonResult] = useState<ComparisonResult | null>(null);

  const availableSources = useMemo(() => {
    if (comparisonType === 'dapi') {
      return mockDapis.map((d) => ({
        id: d.id,
        name: d.name,
        type: 'dapi' as const,
        data: initialDataSources.find((s) => s.id === d.id)?.data || [],
      }));
    } else if (comparisonType === 'chain') {
      return mockChains.map((c) => ({
        id: c.id,
        name: c.name,
        type: 'chain' as const,
        data: initialDataSources.find((s) => s.id === c.id)?.data || [],
      }));
    }
    return initialDataSources;
  }, [comparisonType, initialDataSources]);

  const handleCompare = useCallback(() => {
    const source1 = availableSources.find((s) => s.id === source1Id);
    const source2 = availableSources.find((s) => s.id === source2Id);

    if (source1 && source2) {
      const result = compareDataSources(source1, source2, selectedMetric);
      setComparisonResult(result);
    }
  }, [source1Id, source2Id, selectedMetric, availableSources, compareDataSources]);

  const chartData = useMemo(() => {
    const source1 = availableSources.find((s) => s.id === source1Id);
    const source2 = availableSources.find((s) => s.id === source2Id);

    if (!source1 || !source2) return [];

    const maxLength = Math.max(source1.data.length, source2.data.length);
    const data = [];

    for (let i = 0; i < maxLength; i++) {
      const d1 = source1.data[i];
      const d2 = source2.data[i];
      if (d1 && d2) {
        data.push({
          time: new Date(d1.timestamp).toLocaleDateString(),
          [source1.name]: d1.value,
          [source2.name]: d2.value,
          difference: d1.value - d2.value,
        });
      }
    }

    return data;
  }, [source1Id, source2Id, availableSources]);

  const correlationData = useMemo(() => {
    const source1 = availableSources.find((s) => s.id === source1Id);
    const source2 = availableSources.find((s) => s.id === source2Id);

    if (!source1 || !source2) return null;

    const values1 = source1.data.map((d) => d.value);
    const values2 = source2.data.map((d) => d.value);
    const minLength = Math.min(values1.length, values2.length);

    return calculateCorrelation(values1.slice(0, minLength), values2.slice(0, minLength));
  }, [source1Id, source2Id, availableSources, calculateCorrelation]);

  const getCorrelationColor = (strength: string) => {
    switch (strength) {
      case 'very_strong':
        return 'text-emerald-600';
      case 'strong':
        return 'text-blue-600';
      case 'moderate':
        return 'text-amber-600';
      case 'weak':
        return 'text-orange-600';
      default:
        return 'text-gray-600';
    }
  };

  const getTrendIcon = (direction: string) => {
    switch (direction) {
      case 'positive':
        return <TrendingUp className="w-4 h-4 text-emerald-500" />;
      case 'negative':
        return <TrendingDown className="w-4 h-4 text-red-500" />;
      default:
        return <Minus className="w-4 h-4 text-gray-400" />;
    }
  };

  const handleExport = useCallback(() => {
    if (!comparisonResult) return;

    const exportData = {
      comparison: comparisonResult,
      chartData,
      correlation: correlationData,
      timestamp: new Date().toISOString(),
    };

    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `comparison-${source1Id}-${source2Id}-${Date.now()}.json`;
    a.click();
    URL.revokeObjectURL(url);
  }, [comparisonResult, chartData, correlationData, source1Id, source2Id]);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-gray-900">
            {t('api3.analytics.comparison.title') || 'Data Comparison Tool'}
          </h2>
          <p className="text-sm text-gray-500 mt-1">
            {t('api3.analytics.comparison.subtitle') ||
              'Compare data across different dAPIs, chains, or timeframes'}
          </p>
        </div>
        <button
          onClick={handleExport}
          disabled={!comparisonResult}
          className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <Download className="w-4 h-4" />
          {t('api3.analytics.comparison.export') || 'Export Results'}
        </button>
      </div>

      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              {t('api3.analytics.comparison.comparisonType') || 'Comparison Type'}
            </label>
            <select
              value={comparisonType}
              onChange={(e) => {
                setComparisonType(e.target.value as 'dapi' | 'chain' | 'timeframe');
                setSource1Id('');
                setSource2Id('');
                setComparisonResult(null);
              }}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
            >
              <option value="dapi">{t('api3.analytics.comparison.dapi') || 'dAPI'}</option>
              <option value="chain">{t('api3.analytics.comparison.chain') || 'Chain'}</option>
              <option value="timeframe">
                {t('api3.analytics.comparison.timeframe') || 'Timeframe'}
              </option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              {t('api3.analytics.comparison.source1') || 'Source 1'}
            </label>
            <select
              value={source1Id}
              onChange={(e) => setSource1Id(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
            >
              <option value="">Select source...</option>
              {availableSources.map((source) => (
                <option key={source.id} value={source.id}>
                  {source.name}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              {t('api3.analytics.comparison.source2') || 'Source 2'}
            </label>
            <select
              value={source2Id}
              onChange={(e) => setSource2Id(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
            >
              <option value="">Select source...</option>
              {availableSources
                .filter((s) => s.id !== source1Id)
                .map((source) => (
                  <option key={source.id} value={source.id}>
                    {source.name}
                  </option>
                ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              {t('api3.analytics.comparison.metric') || 'Metric'}
            </label>
            <select
              value={selectedMetric}
              onChange={(e) => setSelectedMetric(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
            >
              {metrics.map((metric) => (
                <option key={metric} value={metric}>
                  {metric}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div className="mt-4 flex justify-end">
          <button
            onClick={handleCompare}
            disabled={!source1Id || !source2Id}
            className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-md hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <GitCompare className="w-4 h-4" />
            {t('api3.analytics.comparison.compare') || 'Compare'}
          </button>
        </div>
      </div>

      {comparisonResult && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white border border-gray-200 rounded-lg p-4">
            <h3 className="text-sm font-medium text-gray-700 mb-4">
              {t('api3.analytics.comparison.comparisonChart') || 'Comparison Chart'}
            </h3>
            {chartData.length > 0 && (
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
                  <XAxis dataKey="time" tick={{ fontSize: 11, fill: '#6b7280' }} />
                  <YAxis tick={{ fontSize: 11, fill: '#6b7280' }} />
                  <Tooltip />
                  <Legend />
                  <Line
                    type="monotone"
                    dataKey={Object.keys(chartData[0])[1]}
                    stroke={chartColors.oracle.api3}
                    strokeWidth={2}
                    dot={false}
                  />
                  <Line
                    type="monotone"
                    dataKey={Object.keys(chartData[0])[2]}
                    stroke={chartColors.oracle.chainlink}
                    strokeWidth={2}
                    dot={false}
                  />
                </LineChart>
              </ResponsiveContainer>
            )}
          </div>

          <div className="space-y-4">
            <div className="bg-white border border-gray-200 rounded-lg p-4">
              <h3 className="text-sm font-medium text-gray-700 mb-3">
                {t('api3.analytics.comparison.summary') || 'Comparison Summary'}
              </h3>
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-gray-600">{comparisonResult.dataSource1}</span>
                  <span className="text-sm font-medium text-gray-900">
                    {comparisonResult.value1.toFixed(4)}
                  </span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm text-gray-600">{comparisonResult.dataSource2}</span>
                  <span className="text-sm font-medium text-gray-900">
                    {comparisonResult.value2.toFixed(4)}
                  </span>
                </div>
                <div className="border-t border-gray-200 pt-3">
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">
                      {t('api3.analytics.comparison.difference') || 'Difference'}
                    </span>
                    <span
                      className={`text-sm font-medium ${
                        comparisonResult.difference >= 0 ? 'text-emerald-600' : 'text-red-600'
                      }`}
                    >
                      {comparisonResult.difference >= 0 ? '+' : ''}
                      {comparisonResult.difference.toFixed(4)}
                    </span>
                  </div>
                  <div className="flex items-center justify-between mt-2">
                    <span className="text-sm text-gray-600">
                      {t('api3.analytics.comparison.percentChange') || 'Percent Change'}
                    </span>
                    <span
                      className={`text-sm font-medium ${
                        comparisonResult.percentChange >= 0 ? 'text-emerald-600' : 'text-red-600'
                      }`}
                    >
                      {comparisonResult.percentChange >= 0 ? '+' : ''}
                      {comparisonResult.percentChange.toFixed(2)}%
                    </span>
                  </div>
                </div>
              </div>
            </div>

            {correlationData && (
              <div className="bg-white border border-gray-200 rounded-lg p-4">
                <h3 className="text-sm font-medium text-gray-700 mb-3">
                  {t('api3.analytics.comparison.correlation') || 'Correlation Analysis'}
                </h3>
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">
                      {t('api3.analytics.comparison.coefficient') || 'Coefficient'}
                    </span>
                    <span
                      className={`text-sm font-medium ${getCorrelationColor(correlationData.strength)}`}
                    >
                      {correlationData.coefficient.toFixed(4)}
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">
                      {t('api3.analytics.comparison.strength') || 'Strength'}
                    </span>
                    <div className="flex items-center gap-1">
                      {getTrendIcon(correlationData.direction)}
                      <span
                        className={`text-sm font-medium ${getCorrelationColor(correlationData.strength)}`}
                      >
                        {correlationData.strength.replace('_', ' ')}
                      </span>
                    </div>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">
                      {t('api3.analytics.comparison.direction') || 'Direction'}
                    </span>
                    <span className="text-sm font-medium text-gray-900 capitalize">
                      {correlationData.direction}
                    </span>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {chartData.length > 0 && comparisonResult && (
        <div className="bg-white border border-gray-200 rounded-lg p-4">
          <h3 className="text-sm font-medium text-gray-700 mb-4">
            {t('api3.analytics.comparison.differenceChart') || 'Difference Analysis'}
          </h3>
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis dataKey="time" tick={{ fontSize: 11, fill: '#6b7280' }} />
              <YAxis tick={{ fontSize: 11, fill: '#6b7280' }} />
              <Tooltip />
              <ReferenceLine y={0} stroke="#6b7280" />
              <Bar dataKey="difference">
                {chartData.map((entry, index) => (
                  <Cell
                    key={`cell-${index}`}
                    fill={entry.difference >= 0 ? chartColors.oracle.api3 : '#ef4444'}
                  />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}

      {comparisonResult && (
        <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-4">
          <div className="flex items-start gap-3">
            <Info className="w-5 h-5 text-emerald-600 mt-0.5" />
            <div>
              <h4 className="text-sm font-medium text-emerald-800">
                {t('api3.analytics.comparison.analysisTitle') || 'Analysis Insight'}
              </h4>
              <p className="text-sm text-emerald-700 mt-1">
                {comparisonResult.percentChange > 5
                  ? t('api3.analytics.comparison.highDeviation') ||
                    'Significant deviation detected between sources. This may indicate market inefficiency or data quality issues.'
                  : comparisonResult.percentChange > 1
                    ? t('api3.analytics.comparison.moderateDeviation') ||
                      'Moderate deviation between sources. Values are within acceptable range.'
                    : t('api3.analytics.comparison.lowDeviation') ||
                      'Low deviation between sources. Data is consistent and reliable.'}
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default DataComparisonTool;

'use client';

import { useState, useCallback, useMemo } from 'react';

import {
  TrendingUp,
  TrendingDown,
  Minus,
  AlertTriangle,
  Info,
  Settings,
  Calendar,
  Target,
  Activity,
} from 'lucide-react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  Area,
  ComposedChart,
  ReferenceLine,
} from 'recharts';

import useAPI3Analytics, { type DataPoint, type PredictionResult } from '@/hooks/useAPI3Analytics';
import { useTranslations } from '@/i18n';
import { chartColors } from '@/lib/config/colors';

export interface TrendPredictionProps {
  historicalData: DataPoint[];
  predictionDays: number;
  confidenceLevel: number;
}

const confidenceOptions = [
  { value: 0.9, label: '90%' },
  { value: 0.95, label: '95%' },
  { value: 0.99, label: '99%' },
];

const predictionHorizons = [
  { value: 7, label: '7 Days' },
  { value: 14, label: '14 Days' },
  { value: 30, label: '30 Days' },
  { value: 60, label: '60 Days' },
];

export function TrendPrediction({
  historicalData,
  predictionDays: initialDays,
  confidenceLevel: initialConfidence,
}: TrendPredictionProps) {
  const t = useTranslations();
  const { predictTrend, calculateMovingAverage, calculateTrendDirection, calculateVolatility } =
    useAPI3Analytics();

  const [predictionDays, setPredictionDays] = useState(initialDays);
  const [confidenceLevel, setConfidenceLevel] = useState(initialConfidence);
  const [showSettings, setShowSettings] = useState(false);
  const [movingAverageWindow, setMovingAverageWindow] = useState(7);

  const predictions = useMemo(() => {
    if (historicalData.length < 2) return [];
    return predictTrend(historicalData, predictionDays, confidenceLevel);
  }, [historicalData, predictionDays, confidenceLevel, predictTrend]);

  const trendDirection = useMemo(() => {
    return calculateTrendDirection(historicalData);
  }, [historicalData, calculateTrendDirection]);

  const volatility = useMemo(() => {
    return calculateVolatility(historicalData);
  }, [historicalData, calculateVolatility]);

  const movingAverageData = useMemo(() => {
    const values = historicalData.map((d) => d.value);
    const ma = calculateMovingAverage(values, movingAverageWindow);
    return historicalData.map((d, i) => ({
      ...d,
      ma: ma[i],
      time: new Date(d.timestamp).toLocaleDateString(),
    }));
  }, [historicalData, movingAverageWindow, calculateMovingAverage]);

  const chartData = useMemo(() => {
    const historical = movingAverageData.map((d) => ({
      time: d.time,
      timestamp: d.timestamp,
      actual: d.value,
      ma: d.ma,
      predicted: null,
      lowerBound: null,
      upperBound: null,
    }));

    const future = predictions.map((p) => ({
      time: new Date(p.timestamp).toLocaleDateString(),
      timestamp: p.timestamp,
      actual: null,
      ma: null,
      predicted: p.predicted,
      lowerBound: p.lowerBound,
      upperBound: p.upperBound,
    }));

    return [...historical, ...future];
  }, [movingAverageData, predictions]);

  const statistics = useMemo(() => {
    if (historicalData.length === 0) return null;

    const values = historicalData.map((d) => d.value);
    const lastValue = values[values.length - 1];
    const predictedValue =
      predictions.length > 0 ? predictions[predictions.length - 1].predicted : null;
    const change = predictedValue ? ((predictedValue - lastValue) / lastValue) * 100 : null;

    return {
      lastValue,
      predictedValue,
      change,
      volatility,
      trendDirection,
    };
  }, [historicalData, predictions, volatility, trendDirection]);

  const getTrendIcon = (direction: string) => {
    switch (direction) {
      case 'up':
        return <TrendingUp className="w-5 h-5 text-emerald-500" />;
      case 'down':
        return <TrendingDown className="w-5 h-5 text-red-500" />;
      default:
        return <Minus className="w-5 h-5 text-gray-400" />;
    }
  };

  const getTrendColor = (direction: string) => {
    switch (direction) {
      case 'up':
        return 'text-emerald-600';
      case 'down':
        return 'text-red-600';
      default:
        return 'text-gray-600';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-gray-900">
            {t('api3.analytics.prediction.title') || 'Trend Prediction'}
          </h2>
          <p className="text-sm text-gray-500 mt-1">
            {t('api3.analytics.prediction.subtitle') ||
              'Historical trend analysis and price prediction'}
          </p>
        </div>
        <button
          onClick={() => setShowSettings(!showSettings)}
          className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50"
        >
          <Settings className="w-4 h-4" />
          {t('api3.analytics.prediction.settings') || 'Settings'}
        </button>
      </div>

      {showSettings && (
        <div className="bg-white border border-gray-200 rounded-lg p-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                {t('api3.analytics.prediction.predictionHorizon') || 'Prediction Horizon'}
              </label>
              <select
                value={predictionDays}
                onChange={(e) => setPredictionDays(Number(e.target.value))}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
              >
                {predictionHorizons.map((option) => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                {t('api3.analytics.prediction.confidenceLevel') || 'Confidence Level'}
              </label>
              <select
                value={confidenceLevel}
                onChange={(e) => setConfidenceLevel(Number(e.target.value))}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
              >
                {confidenceOptions.map((option) => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                {t('api3.analytics.prediction.maWindow') || 'Moving Average Window'}
              </label>
              <input
                type="number"
                value={movingAverageWindow}
                onChange={(e) => setMovingAverageWindow(Number(e.target.value))}
                min={2}
                max={30}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
              />
            </div>
          </div>
        </div>
      )}

      {statistics && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="bg-white border border-gray-200 rounded-lg p-4">
            <div className="flex items-center gap-2 mb-2">
              <Activity className="w-4 h-4 text-gray-400" />
              <span className="text-xs text-gray-500">
                {t('api3.analytics.prediction.currentPrice') || 'Current Price'}
              </span>
            </div>
            <div className="text-xl font-bold text-gray-900">
              ${statistics.lastValue.toFixed(2)}
            </div>
          </div>

          <div className="bg-white border border-gray-200 rounded-lg p-4">
            <div className="flex items-center gap-2 mb-2">
              <Target className="w-4 h-4 text-gray-400" />
              <span className="text-xs text-gray-500">
                {t('api3.analytics.prediction.predictedPrice') || 'Predicted Price'}
              </span>
            </div>
            <div className="text-xl font-bold text-gray-900">
              ${statistics.predictedValue?.toFixed(2) || '-'}
            </div>
          </div>

          <div className="bg-white border border-gray-200 rounded-lg p-4">
            <div className="flex items-center gap-2 mb-2">
              {getTrendIcon(statistics.trendDirection)}
              <span className="text-xs text-gray-500">
                {t('api3.analytics.prediction.trend') || 'Trend'}
              </span>
            </div>
            <div className={`text-xl font-bold ${getTrendColor(statistics.trendDirection)}`}>
              {statistics.trendDirection.toUpperCase()}
            </div>
          </div>

          <div className="bg-white border border-gray-200 rounded-lg p-4">
            <div className="flex items-center gap-2 mb-2">
              <Calendar className="w-4 h-4 text-gray-400" />
              <span className="text-xs text-gray-500">
                {t('api3.analytics.prediction.expectedChange') || 'Expected Change'}
              </span>
            </div>
            <div
              className={`text-xl font-bold ${
                statistics.change && statistics.change >= 0 ? 'text-emerald-600' : 'text-red-600'
              }`}
            >
              {statistics.change
                ? `${statistics.change >= 0 ? '+' : ''}${statistics.change.toFixed(2)}%`
                : '-'}
            </div>
          </div>
        </div>
      )}

      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-sm font-medium text-gray-700 mb-4">
          {t('api3.analytics.prediction.chartTitle') || 'Historical Data & Prediction'}
        </h3>
        {chartData.length > 0 && (
          <ResponsiveContainer width="100%" height={350}>
            <ComposedChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis
                dataKey="time"
                tick={{ fontSize: 10, fill: '#6b7280' }}
                interval="preserveStartEnd"
              />
              <YAxis tick={{ fontSize: 11, fill: '#6b7280' }} />
              <Tooltip
                content={({ active, payload, label }) => {
                  if (active && payload && payload.length) {
                    return (
                      <div className="bg-white border border-gray-200 rounded-lg shadow-lg p-3">
                        <p className="text-xs text-gray-500 mb-2">{label as string}</p>
                        {payload.map((entry, index) => {
                          const value = entry.value as number | undefined;
                          const name = entry.name as string | undefined;
                          const color = entry.color as string | undefined;
                          return value !== null && value !== undefined ? (
                            <p key={index} className="text-sm" style={{ color: color || '#666' }}>
                              {name}: {value.toFixed(4)}
                            </p>
                          ) : null;
                        })}
                      </div>
                    );
                  }
                  return null;
                }}
              />
              <Legend />
              <Line
                type="monotone"
                dataKey="actual"
                stroke={chartColors.oracle.api3}
                strokeWidth={2}
                dot={false}
                name="Actual"
              />
              <Line
                type="monotone"
                dataKey="ma"
                stroke="#94a3b8"
                strokeWidth={1.5}
                strokeDasharray="5 5"
                dot={false}
                name={`MA(${movingAverageWindow})`}
              />
              <Area
                type="monotone"
                dataKey="upperBound"
                stroke="none"
                fill={chartColors.oracle.api3}
                fillOpacity={0.1}
                name="Upper Bound"
              />
              <Area
                type="monotone"
                dataKey="lowerBound"
                stroke="none"
                fill={chartColors.oracle.api3}
                fillOpacity={0.1}
                name="Lower Bound"
              />
              <Line
                type="monotone"
                dataKey="predicted"
                stroke="#f59e0b"
                strokeWidth={2}
                strokeDasharray="5 5"
                dot={false}
                name="Predicted"
              />
              <ReferenceLine
                x={
                  (
                    chartData as Array<{
                      time: string;
                      actual: number | null;
                      predicted: number | null;
                    }>
                  ).find((d) => d.actual !== null && d.predicted !== null)?.time || undefined
                }
                stroke="#6b7280"
                strokeDasharray="3 3"
              />
            </ComposedChart>
          </ResponsiveContainer>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white border border-gray-200 rounded-lg p-4">
          <h3 className="text-sm font-medium text-gray-700 mb-4">
            {t('api3.analytics.prediction.predictionDetails') || 'Prediction Details'}
          </h3>
          {predictions.length > 0 && (
            <div className="space-y-2 max-h-60 overflow-y-auto">
              {predictions.map((pred, index) => (
                <div
                  key={index}
                  className="flex items-center justify-between py-2 border-b border-gray-100 last:border-0"
                >
                  <span className="text-sm text-gray-600">
                    {new Date(pred.timestamp).toLocaleDateString()}
                  </span>
                  <div className="flex items-center gap-4">
                    <span className="text-sm font-medium text-gray-900">
                      ${pred.predicted.toFixed(2)}
                    </span>
                    <span className="text-xs text-gray-400">
                      (${pred.lowerBound.toFixed(2)} - ${pred.upperBound.toFixed(2)})
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="bg-white border border-gray-200 rounded-lg p-4">
          <h3 className="text-sm font-medium text-gray-700 mb-4">
            {t('api3.analytics.prediction.accuracyMetrics') || 'Accuracy Metrics'}
          </h3>
          <div className="space-y-4">
            <div>
              <div className="flex items-center justify-between mb-1">
                <span className="text-sm text-gray-600">
                  {t('api3.analytics.prediction.volatility') || 'Annualized Volatility'}
                </span>
                <span className="text-sm font-medium text-gray-900">
                  {(volatility * 100).toFixed(2)}%
                </span>
              </div>
              <div className="w-full bg-gray-100 rounded-full h-1.5">
                <div
                  className="h-1.5 rounded-full"
                  style={{
                    width: `${Math.min(volatility * 100, 100)}%`,
                    backgroundColor:
                      volatility < 0.3 ? '#10b981' : volatility < 0.6 ? '#f59e0b' : '#ef4444',
                  }}
                />
              </div>
            </div>

            <div>
              <div className="flex items-center justify-between mb-1">
                <span className="text-sm text-gray-600">
                  {t('api3.analytics.prediction.confidenceWidth') || 'Confidence Interval Width'}
                </span>
                <span className="text-sm font-medium text-gray-900">
                  {predictions.length > 0
                    ? (
                        ((predictions[predictions.length - 1].upperBound -
                          predictions[predictions.length - 1].lowerBound) /
                          predictions[predictions.length - 1].predicted) *
                        100
                      ).toFixed(2)
                    : 0}
                  %
                </span>
              </div>
            </div>

            <div className="bg-amber-50 border border-amber-200 rounded-md p-3">
              <div className="flex items-start gap-2">
                <AlertTriangle className="w-4 h-4 text-amber-600 mt-0.5" />
                <p className="text-xs text-amber-700">
                  {t('api3.analytics.prediction.disclaimer') ||
                    'Predictions are based on historical linear regression and should not be used as financial advice. Market conditions can change rapidly.'}
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default TrendPrediction;

'use client';

import { useMemo } from 'react';

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  ResponsiveContainer,
  ReferenceLine,
  ReferenceDot,
  Area,
} from 'recharts';

import { useTranslations } from '@/i18n';
import { chartColors, baseColors, semanticColors } from '@/lib/config/colors';
import { calculateCDF, type CDFResult } from '@/lib/utils/statistics';

interface CDFChartProps {
  data: number[];
  oracleName?: string;
  className?: string;
  height?: number;
  showPercentileLabels?: boolean;
  showGrid?: boolean;
  color?: string;
}

interface CDFTooltipProps {
  active?: boolean;
  payload?: Array<{
    payload: {
      value: number;
      probability: number;
      count: number;
    };
  }>;
}

export function CDFChart({
  data,
  oracleName,
  className = '',
  height = 350,
  showPercentileLabels = true,
  showGrid = true,
  color = chartColors.recharts.primaryLight,
}: CDFChartProps) {
  const t = useTranslations();

  const cdfResult: CDFResult = useMemo(() => calculateCDF(data, 100), [data]);

  const percentileConfig = useMemo(
    () => [
      {
        key: 'p50',
        value: cdfResult.p50,
        label: 'P50',
        color: semanticColors.success.DEFAULT,
        description: t('cdfChart.p50Desc') || '50% 的数据低于此值',
      },
      {
        key: 'p95',
        value: cdfResult.p95,
        label: 'P95',
        color: semanticColors.warning.DEFAULT,
        description: t('cdfChart.p95Desc') || '95% 的数据低于此值',
      },
      {
        key: 'p99',
        value: cdfResult.p99,
        label: 'P99',
        color: semanticColors.danger.DEFAULT,
        description: t('cdfChart.p99Desc') || '99% 的数据低于此值',
      },
    ],
    [cdfResult, t]
  );

  const stats = useMemo(
    () => [
      {
        label: t('cdfChart.samples') || '样本数',
        value: cdfResult.totalCount.toLocaleString(),
        icon: '🔢',
      },
      {
        label: t('cdfChart.mean') || '平均值',
        value: `${cdfResult.mean}ms`,
        icon: '📊',
      },
      {
        label: t('cdfChart.min') || '最小值',
        value: `${cdfResult.min}ms`,
        icon: '⬇️',
      },
      {
        label: t('cdfChart.max') || '最大值',
        value: `${cdfResult.max}ms`,
        icon: '⬆️',
      },
      {
        label: t('cdfChart.stdDev') || '标准差',
        value: `${cdfResult.stdDev}ms`,
        icon: '📐',
      },
    ],
    [cdfResult, t]
  );

  const CustomTooltip = ({ active, payload }: CDFTooltipProps) => {
    if (!active || !payload || payload.length === 0) return null;

    const point = payload[0].payload;
    const percentile = percentileConfig.find(
      (p) => Math.abs(p.value - point.value) < (cdfResult.max - cdfResult.min) / 100
    );

    return (
      <div className="bg-white border border-gray-200 rounded-lg p-3 min-w-[180px]">
        <p className="text-xs text-gray-500 font-medium mb-2">{t('cdfChart.latency') || '延迟'}</p>
        <div className="space-y-2">
          <div className="flex justify-between items-center">
            <span className="text-xs text-gray-500">{t('cdfChart.value') || '数值'}:</span>
            <span className="text-sm font-semibold text-gray-900">{point.value.toFixed(1)}ms</span>
          </div>
          <div className="flex justify-between items-center">
            <span className="text-xs text-gray-500">
              {t('cdfChart.probability') || '累积概率'}:
            </span>
            <span className="text-sm font-semibold text-primary-600">
              {point.probability.toFixed(1)}%
            </span>
          </div>
          <div className="flex justify-between items-center">
            <span className="text-xs text-gray-500">{t('cdfChart.count') || '数据点'}:</span>
            <span className="text-sm font-mono text-gray-700">{point.count}</span>
          </div>
          {percentile && (
            <div className="mt-2 pt-2 border-t border-gray-100">
              <span
                className="text-xs font-medium px-2 py-0.5 rounded"
                style={{ backgroundColor: `${percentile.color}20`, color: percentile.color }}
              >
                {percentile.label}: {percentile.description}
              </span>
            </div>
          )}
        </div>
      </div>
    );
  };

  if (data.length === 0) {
    return (
      <div className={`bg-white border border-gray-200 rounded p-5 ${className}`}>
        <div className="text-center py-10">
          <p className="text-gray-500">{t('cdfChart.noData') || '暂无数据'}</p>
        </div>
      </div>
    );
  }

  return (
    <div className={`space-y-4 ${className}`}>
      {oracleName && (
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-lg font-semibold text-gray-900">
              {t('cdfChart.title') || '累积分布函数 (CDF)'} - {oracleName}
            </h3>
            <p className="text-sm text-gray-500 mt-1">
              {t('cdfChart.subtitle') || '显示延迟值的累积概率分布'}
            </p>
          </div>
        </div>
      )}

      {/* Percentile Cards */}
      <div className="grid grid-cols-3 gap-4">
        {percentileConfig.map((item) => (
          <div
            key={item.key}
            className="bg-white border border-gray-200 rounded-lg p-4"
            style={{ borderLeftColor: item.color, borderLeftWidth: 3 }}
          >
            <div className="flex items-center justify-between mb-2">
              <span
                className="text-xs uppercase tracking-wider font-medium"
                style={{ color: item.color }}
              >
                {item.label}
              </span>
            </div>
            <div className="flex items-baseline gap-1">
              <span className="text-2xl font-bold text-gray-900">{Math.round(item.value)}</span>
              <span className="text-sm text-gray-500">ms</span>
            </div>
            <p className="text-xs text-gray-400 mt-2">{item.description}</p>
          </div>
        ))}
      </div>

      {/* Statistics Grid */}
      <div className="grid grid-cols-5 gap-3">
        {stats.map((item) => (
          <div
            key={item.label}
            className="bg-white border border-gray-200 rounded-lg p-3 text-center"
          >
            <span className="text-xl mb-1 block">{item.icon}</span>
            <p className="text-xs text-gray-500 mb-1">{item.label}</p>
            <p className="text-sm font-semibold text-gray-900">{item.value}</p>
          </div>
        ))}
      </div>

      {/* CDF Chart */}
      <div className="bg-white border border-gray-200 rounded-lg p-5">
        <div className="mb-4">
          <h4 className="text-sm font-semibold text-gray-900">
            {t('cdfChart.chartTitle') || 'CDF 曲线'}
          </h4>
          <p className="text-xs text-gray-500 mt-1">
            {t('cdfChart.chartDesc') || '累积分布函数显示小于等于特定延迟值的概率'}
          </p>
        </div>

        <ResponsiveContainer width="100%" height={height}>
          <LineChart data={cdfResult.points} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
            {showGrid && <CartesianGrid strokeDasharray="3 3" stroke={chartColors.recharts.grid} />}
            <XAxis
              dataKey="value"
              type="number"
              domain={[cdfResult.min, cdfResult.max]}
              stroke={chartColors.recharts.axis}
              tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
              tickLine={false}
              axisLine={{ stroke: chartColors.recharts.grid }}
              label={{
                value: t('cdfChart.xAxisLabel') || '延迟 (ms)',
                position: 'insideBottom',
                offset: -10,
                fill: chartColors.recharts.tick,
                fontSize: 11,
              }}
            />
            <YAxis
              dataKey="probability"
              domain={[0, 100]}
              stroke={chartColors.recharts.axis}
              tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
              tickLine={false}
              axisLine={{ stroke: chartColors.recharts.grid }}
              tickFormatter={(value) => `${value}%`}
              label={{
                value: t('cdfChart.yAxisLabel') || '累积概率 (%)',
                angle: -90,
                position: 'insideLeft',
                fill: chartColors.recharts.tick,
                fontSize: 11,
              }}
            />
            <RechartsTooltip content={<CustomTooltip />} />

            {/* Area under curve */}
            <Area
              type="monotone"
              dataKey="probability"
              stroke="none"
              fill={color}
              fillOpacity={0.1}
            />

            {/* CDF Line */}
            <Line
              type="monotone"
              dataKey="probability"
              stroke={color}
              strokeWidth={2.5}
              dot={false}
              activeDot={{ r: 5, fill: color, stroke: baseColors.gray[50], strokeWidth: 2 }}
            />

            {/* Percentile Reference Lines */}
            {showPercentileLabels && (
              <>
                <ReferenceLine
                  x={cdfResult.p50}
                  stroke={semanticColors.success.DEFAULT}
                  strokeDasharray="5 5"
                  strokeWidth={2}
                  label={{
                    value: 'P50',
                    position: 'top',
                    fill: semanticColors.success.DEFAULT,
                    fontSize: 11,
                    fontWeight: 600,
                  }}
                />
                <ReferenceLine
                  x={cdfResult.p95}
                  stroke={semanticColors.warning.DEFAULT}
                  strokeDasharray="5 5"
                  strokeWidth={2}
                  label={{
                    value: 'P95',
                    position: 'top',
                    fill: semanticColors.warning.DEFAULT,
                    fontSize: 11,
                    fontWeight: 600,
                  }}
                />
                <ReferenceLine
                  x={cdfResult.p99}
                  stroke={semanticColors.danger.DEFAULT}
                  strokeDasharray="5 5"
                  strokeWidth={2}
                  label={{
                    value: 'P99',
                    position: 'top',
                    fill: semanticColors.danger.DEFAULT,
                    fontSize: 11,
                    fontWeight: 600,
                  }}
                />

                {/* Reference dots at percentile intersections */}
                <ReferenceDot
                  x={cdfResult.p50}
                  y={50}
                  r={5}
                  fill={semanticColors.success.DEFAULT}
                  stroke={baseColors.gray[50]}
                  strokeWidth={2}
                />
                <ReferenceDot
                  x={cdfResult.p95}
                  y={95}
                  r={5}
                  fill={semanticColors.warning.DEFAULT}
                  stroke={baseColors.gray[50]}
                  strokeWidth={2}
                />
                <ReferenceDot
                  x={cdfResult.p99}
                  y={99}
                  r={5}
                  fill={semanticColors.danger.DEFAULT}
                  stroke={baseColors.gray[50]}
                  strokeWidth={2}
                />
              </>
            )}

            {/* 50% reference line */}
            <ReferenceLine
              y={50}
              stroke={chartColors.recharts.secondaryAxis}
              strokeDasharray="3 3"
              strokeOpacity={0.5}
            />
            <ReferenceLine
              y={95}
              stroke={chartColors.recharts.secondaryAxis}
              strokeDasharray="3 3"
              strokeOpacity={0.5}
            />
          </LineChart>
        </ResponsiveContainer>

        {/* Legend */}
        <div className="flex items-center justify-center gap-6 mt-4">
          <div className="flex items-center gap-2">
            <span className="w-4 h-0.5 bg-primary-500 rounded" style={{ backgroundColor: color }} />
            <span className="text-xs text-gray-500">{t('cdfChart.cdfCurve') || 'CDF 曲线'}</span>
          </div>
          <div className="flex items-center gap-2">
            <span
              className="w-3 h-3 rounded"
              style={{ backgroundColor: semanticColors.success.DEFAULT }}
            />
            <span className="text-xs text-gray-500">P50 (中位数)</span>
          </div>
          <div className="flex items-center gap-2">
            <span
              className="w-3 h-3 rounded"
              style={{ backgroundColor: semanticColors.warning.DEFAULT }}
            />
            <span className="text-xs text-gray-500">P95</span>
          </div>
          <div className="flex items-center gap-2">
            <span
              className="w-3 h-3 rounded"
              style={{ backgroundColor: semanticColors.danger.DEFAULT }}
            />
            <span className="text-xs text-gray-500">P99</span>
          </div>
        </div>
      </div>

      {/* CDF Explanation */}
      <div className="bg-primary-50 rounded p-4">
        <h4 className="text-sm font-medium text-primary-900 mb-2">
          {t('cdfChart.aboutTitle') || '关于累积分布函数 (CDF)'}
        </h4>
        <p className="text-xs text-primary-800 leading-relaxed">
          {t('cdfChart.aboutDesc') ||
            'CDF(x) 表示延迟值小于等于 x 的概率。例如，CDF(100ms) = 80% 表示 80% 的请求延迟不超过 100ms。P50（中位数）表示 50% 的数据点低于该值，P95 表示 95% 的数据点低于该值。CDF 曲线越陡峭，表示延迟分布越集中；曲线越平缓，表示延迟波动越大。'}
        </p>
      </div>
    </div>
  );
}

export type { CDFChartProps };

'use client';

import { useState, useMemo, useCallback } from 'react';

import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  ResponsiveContainer,
  Cell,
  Legend,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  Radar,
} from 'recharts';

import { DashboardCard } from '@/components/oracle/data-display/DashboardCard';
import { useTranslations } from '@/i18n';
import { chainColors, chartColors, animationColors } from '@/lib/config/colors';
import type { ChainDataRequest } from '@/lib/oracles/bandProtocol';
import { formatNumber as formatNumberCompact } from '@/lib/utils/format';

type TimeRangeKey = '24h' | '7d' | '30d';

interface ChainComparisonProps {
  chains: ChainDataRequest[];
  selectedChains?: ChainDataRequest[];
  onSelectionChange?: (chains: ChainDataRequest[]) => void;
}

interface ExtendedChainData extends ChainDataRequest {
  avgResponseTime: number;
  reliability: number;
}

const getTimeRangeConfig = (
  t: (key: string) => string
): Record<TimeRangeKey, { label: string; field: keyof ChainDataRequest }> => ({
  '24h': { label: t('chainComparison.timeRange.24h'), field: 'requestCount24h' },
  '7d': { label: t('chainComparison.timeRange.7d'), field: 'requestCount7d' },
  '30d': { label: t('chainComparison.timeRange.30d'), field: 'requestCount30d' },
});

const CHAIN_COLORS: Record<string, string> = {
  'Cosmos Hub': chainColors.cosmosHub,
  Osmosis: chainColors.osmosis,
  Ethereum: chainColors.ethereum,
  Polygon: chainColors.polygon,
  Avalanche: chainColors.avalanche,
  Fantom: chainColors.fantom,
  Cronos: chainColors.cronos,
  Juno: chainColors.juno,
};

const DEFAULT_COLORS = chartColors.sequence;

const MAX_SELECTION = 5;

function getChainColor(chainName: string, index: number): string {
  return CHAIN_COLORS[chainName] || DEFAULT_COLORS[index % DEFAULT_COLORS.length];
}

function formatNumber(num: number): string {
  return formatNumberCompact(num, true);
}

function generateExtendedData(chain: ChainDataRequest, index: number): ExtendedChainData {
  return {
    ...chain,
    avgResponseTime: Math.round(80 + Math.random() * 120 + index * 15),
    reliability: Number((98.5 + Math.random() * 1.5).toFixed(2)),
  };
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    dataKey: string;
    value: number;
    payload: { name: string; value: number; color: string; chainName: string };
  }>;
}

function CustomTooltip({ active, payload }: CustomTooltipProps) {
  if (!active || !payload || payload.length === 0) return null;

  const data = payload[0]?.payload;
  if (!data) return null;

  return (
    <div className="bg-white border border-gray-200 rounded-lg p-3">
      <p className="text-gray-600 text-xs mb-1 font-medium">{data.name}</p>
      <div className="flex items-center gap-2">
        <span className="w-2 h-2 rounded-full" style={{ backgroundColor: data.color }} />
        <span className="text-gray-900 font-mono font-semibold">{data.value.toLocaleString()}</span>
      </div>
    </div>
  );
}

interface GasTooltipProps {
  active?: boolean;
  payload?: Array<{
    payload: { name: string; gasCost: number; color: string };
  }>;
}

function GasTooltip({ active, payload }: GasTooltipProps) {
  if (!active || !payload || payload.length === 0) return null;

  const data = payload[0]?.payload;
  if (!data) return null;

  return (
    <div className="bg-white border border-gray-200 rounded-lg p-3">
      <p className="text-gray-600 text-xs mb-1 font-medium">{data.name}</p>
      <div className="flex items-center gap-2">
        <span className="w-2 h-2 rounded-full" style={{ backgroundColor: data.color }} />
        <span className="text-gray-900 font-mono font-semibold">
          {data.gasCost.toFixed(6)} BAND
        </span>
      </div>
    </div>
  );
}

interface ResponseTimeTooltipProps {
  active?: boolean;
  payload?: Array<{
    payload: { name: string; responseTime: number; color: string };
  }>;
}

function ResponseTimeTooltip({ active, payload }: ResponseTimeTooltipProps) {
  if (!active || !payload || payload.length === 0) return null;

  const data = payload[0]?.payload;
  if (!data) return null;

  return (
    <div className="bg-white border border-gray-200 rounded-lg p-3">
      <p className="text-gray-600 text-xs mb-1 font-medium">{data.name}</p>
      <div className="flex items-center gap-2">
        <span className="w-2 h-2 rounded-full" style={{ backgroundColor: data.color }} />
        <span className="text-gray-900 font-mono font-semibold">{data.responseTime}ms</span>
      </div>
    </div>
  );
}

export function ChainComparison({
  chains,
  selectedChains: externalSelectedChains,
  onSelectionChange,
}: ChainComparisonProps) {
  const t = useTranslations();
  const TIME_RANGE_CONFIG = useMemo(() => getTimeRangeConfig(t), [t]);
  const [internalSelectedChains, setInternalSelectedChains] = useState<ChainDataRequest[]>([]);
  const [timeRange, setTimeRange] = useState<TimeRangeKey>('24h');

  const selectedChains = externalSelectedChains ?? internalSelectedChains;

  const handleSelectionChange = useCallback(
    (newSelection: ChainDataRequest[]) => {
      if (onSelectionChange) {
        onSelectionChange(newSelection);
      } else {
        setInternalSelectedChains(newSelection);
      }
    },
    [onSelectionChange]
  );

  const toggleChain = useCallback(
    (chain: ChainDataRequest) => {
      const isSelected = selectedChains.some((c) => c.chainId === chain.chainId);
      if (isSelected) {
        handleSelectionChange(selectedChains.filter((c) => c.chainId !== chain.chainId));
      } else if (selectedChains.length < MAX_SELECTION) {
        handleSelectionChange([...selectedChains, chain]);
      }
    },
    [selectedChains, handleSelectionChange]
  );

  const selectAll = useCallback(() => {
    handleSelectionChange(chains.slice(0, MAX_SELECTION));
  }, [chains, handleSelectionChange]);

  const clearSelection = useCallback(() => {
    handleSelectionChange([]);
  }, [handleSelectionChange]);

  const extendedSelectedChains = useMemo<ExtendedChainData[]>(
    () => selectedChains.map((chain, index) => generateExtendedData(chain, index)),
    [selectedChains]
  );

  const requestChartData = useMemo(
    () =>
      extendedSelectedChains.map((chain, index) => ({
        name: chain.chainName,
        value: chain[TIME_RANGE_CONFIG[timeRange].field] as number,
        color: getChainColor(chain.chainName, index),
        chainName: chain.chainName,
      })),
    [extendedSelectedChains, timeRange, TIME_RANGE_CONFIG]
  );

  const gasChartData = useMemo(
    () =>
      extendedSelectedChains.map((chain, index) => ({
        name: chain.chainName,
        gasCost: chain.avgGasCost,
        color: getChainColor(chain.chainName, index),
      })),
    [extendedSelectedChains]
  );

  const responseTimeChartData = useMemo(
    () =>
      extendedSelectedChains.map((chain, index) => ({
        name: chain.chainName,
        responseTime: chain.avgResponseTime,
        color: getChainColor(chain.chainName, index),
      })),
    [extendedSelectedChains]
  );

  const tokenCountChartData = useMemo(
    () =>
      extendedSelectedChains.map((chain, index) => ({
        name: chain.chainName,
        tokenCount: chain.supportedSymbols.length,
        color: getChainColor(chain.chainName, index),
      })),
    [extendedSelectedChains]
  );

  const radarData = useMemo(() => {
    if (extendedSelectedChains.length === 0) return [];

    const maxRequests = Math.max(...extendedSelectedChains.map((c) => c.requestCount24h));
    const minGas = Math.min(...extendedSelectedChains.map((c) => c.avgGasCost));
    const maxGas = Math.max(...extendedSelectedChains.map((c) => c.avgGasCost));
    const maxTokens = Math.max(...extendedSelectedChains.map((c) => c.supportedSymbols.length));
    const minResponse = Math.min(...extendedSelectedChains.map((c) => c.avgResponseTime));
    const maxResponse = Math.max(...extendedSelectedChains.map((c) => c.avgResponseTime));

    return [
      {
        metric: t('chainComparison.metrics.requestVolume'),
        ...extendedSelectedChains.reduce(
          (acc, c) => {
            acc[c.chainName] = (c.requestCount24h / maxRequests) * 100;
            return acc;
          },
          {} as Record<string, number>
        ),
      },
      {
        metric: t('chainComparison.metrics.gasEfficiency'),
        ...extendedSelectedChains.reduce(
          (acc, c) => {
            const gasScore =
              maxGas > minGas ? ((maxGas - c.avgGasCost) / (maxGas - minGas)) * 100 : 50;
            acc[c.chainName] = gasScore;
            return acc;
          },
          {} as Record<string, number>
        ),
      },
      {
        metric: t('chainComparison.metrics.tokenSupport'),
        ...extendedSelectedChains.reduce(
          (acc, c) => {
            acc[c.chainName] = (c.supportedSymbols.length / maxTokens) * 100;
            return acc;
          },
          {} as Record<string, number>
        ),
      },
      {
        metric: t('chainComparison.metrics.responseSpeed'),
        ...extendedSelectedChains.reduce(
          (acc, c) => {
            const responseScore =
              maxResponse > minResponse
                ? ((maxResponse - c.avgResponseTime) / (maxResponse - minResponse)) * 100
                : 50;
            acc[c.chainName] = responseScore;
            return acc;
          },
          {} as Record<string, number>
        ),
      },
      {
        metric: t('chainComparison.metrics.reliability'),
        ...extendedSelectedChains.reduce(
          (acc, c) => {
            acc[c.chainName] = c.reliability;
            return acc;
          },
          {} as Record<string, number>
        ),
      },
    ];
  }, [extendedSelectedChains, t]);

  const exportToCSV = useCallback(() => {
    if (extendedSelectedChains.length === 0) return;

    const headers = [
      t('chainComparison.csv.chainName'),
      'Chain ID',
      t('chainComparison.csv.24hRequests'),
      t('chainComparison.csv.7dRequests'),
      t('chainComparison.csv.30dRequests'),
      t('chainComparison.csv.avgGasCost'),
      t('chainComparison.csv.tokenCount'),
      t('chainComparison.csv.supportedTokens'),
      t('chainComparison.csv.avgResponseTime'),
      t('chainComparison.csv.reliability'),
    ];

    const rows = extendedSelectedChains.map((chain) => [
      chain.chainName,
      chain.chainId,
      chain.requestCount24h,
      chain.requestCount7d,
      chain.requestCount30d,
      chain.avgGasCost.toFixed(6),
      chain.supportedSymbols.length,
      chain.supportedSymbols.join(';'),
      chain.avgResponseTime,
      chain.reliability,
    ]);

    const csvContent = [headers.join(','), ...rows.map((row) => row.join(','))].join('\n') + '\n';

    const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `chain-comparison-${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [extendedSelectedChains, t]);

  const comparisonStats = useMemo(() => {
    if (extendedSelectedChains.length === 0) return null;

    const totalRequests = extendedSelectedChains.reduce((sum, c) => {
      const value = c[TIME_RANGE_CONFIG[timeRange].field];
      return sum + (typeof value === 'number' ? value : 0);
    }, 0);
    const avgGas =
      extendedSelectedChains.reduce((sum, c) => sum + c.avgGasCost, 0) /
      extendedSelectedChains.length;
    const totalTokens = new Set(extendedSelectedChains.flatMap((c) => c.supportedSymbols)).size;
    const avgResponseTime =
      extendedSelectedChains.reduce((sum, c) => sum + c.avgResponseTime, 0) /
      extendedSelectedChains.length;

    return {
      totalRequests,
      avgGas,
      totalTokens,
      avgResponseTime: Math.round(avgResponseTime),
    };
  }, [extendedSelectedChains, timeRange, TIME_RANGE_CONFIG]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-gray-900">{t('chainComparison.title')}</h2>
          <p className="text-gray-500 text-sm mt-0.5">
            {t('chainComparison.selectUpTo', { max: MAX_SELECTION })}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={selectAll}
            disabled={selectedChains.length >= MAX_SELECTION}
            className="px-3 py-1.5 text-xs font-medium text-gray-600 bg-gray-100  hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {t('chainComparison.selectAll')}
          </button>
          <button
            onClick={clearSelection}
            disabled={selectedChains.length === 0}
            className="px-3 py-1.5 text-xs font-medium text-gray-600 bg-gray-100  hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {t('chainComparison.clear')}
          </button>
          <button
            onClick={exportToCSV}
            disabled={selectedChains.length === 0}
            className="px-3 py-1.5 text-xs font-medium text-white bg-primary-500  hover:bg-primary-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center gap-1.5"
          >
            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path
                strokeLinejoin="round"
                strokeWidth={2}
                d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
              />
            </svg>
            {t('chainComparison.exportCSV')}
          </button>
        </div>
      </div>

      <DashboardCard title={t('chainComparison.selectChains')}>
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
          {chains.map((chain, index) => {
            const isSelected = selectedChains.some((c) => c.chainId === chain.chainId);
            const isDisabled = !isSelected && selectedChains.length >= MAX_SELECTION;

            return (
              <label
                key={chain.chainId}
                className={`relative flex items-center gap-3 p-3  border-2 cursor-pointer transition-all duration-200 ${
                  isSelected
                    ? 'border-primary-500 bg-primary-50'
                    : isDisabled
                      ? 'border-gray-100 bg-gray-50 cursor-not-allowed opacity-50'
                      : 'border-gray-200 hover:border-gray-300 hover:bg-gray-50'
                }`}
              >
                <input
                  type="checkbox"
                  checked={isSelected}
                  disabled={isDisabled}
                  onChange={() => toggleChain(chain)}
                  className="sr-only"
                />
                <div
                  className="w-3 h-3  flex-shrink-0"
                  style={{ backgroundColor: getChainColor(chain.chainName, index) }}
                />
                <span
                  className={`text-sm font-medium truncate ${
                    isSelected ? 'text-primary-700' : 'text-gray-700'
                  }`}
                >
                  {chain.chainName}
                </span>
                {isSelected && (
                  <svg
                    className="w-4 h-4 text-primary-500 absolute top-1.5 right-1.5"
                    fill="currentColor"
                    viewBox="0 0 20 20"
                  >
                    <path
                      fillRule="evenodd"
                      d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"
                      clipRule="evenodd"
                    />
                  </svg>
                )}
              </label>
            );
          })}
        </div>
        <div className="mt-3 flex items-center justify-between text-xs text-gray-500">
          <span>
            {t('chainComparison.selectedCount', {
              selected: selectedChains.length,
              max: MAX_SELECTION,
            })}
          </span>
          {selectedChains.length >= MAX_SELECTION && (
            <span className="text-amber-600">{t('chainComparison.maxReached')}</span>
          )}
        </div>
      </DashboardCard>

      {selectedChains.length === 0 ? (
        <div className="bg-white border border-gray-200 rounded-lg p-12 text-center">
          <svg
            className="w-16 h-16 text-gray-300 mx-auto mb-4"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinejoin="round"
              strokeWidth={1.5}
              d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"
            />
          </svg>
