                />
                <Legend />
                {chains.map((chain) => {
                  const chainName = DIA_CHAIN_NAMES[chain] || chain;
                  return (
                    <Line
                      key={chain}
                      type="monotone"
                      dataKey={chainName}
                      stroke={CHAIN_COLORS[chain] || '#gray'}
                      strokeWidth={2}
                      dot={false}
                      activeDot={{ r: 4 }}
                    />
                  );
                })}
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}
    </div>
  );
}

