'use client';

import { useState, useEffect } from 'react';

interface CollapsiblePanelProps {
  title: string;
  children: React.ReactNode;
  defaultExpanded?: boolean;
  storageKey?: string;
  className?: string;
  headerClassName?: string;
  contentClassName?: string;
}

export function CollapsiblePanel({
  title,
  children,
  defaultExpanded = true,
  storageKey,
  className = '',
  headerClassName = '',
  contentClassName = '',
}: CollapsiblePanelProps) {
  const [isExpanded, setIsExpanded] = useState(defaultExpanded);
  const [isMounted, setIsMounted] = useState(false);

  // Load saved state from localStorage on mount
  useEffect(() => {
    setIsMounted(true);
    if (storageKey) {
      const savedState = localStorage.getItem(`collapsible-${storageKey}`);
      if (savedState !== null) {
        setIsExpanded(savedState === 'true');
      }
    }
  }, [storageKey]);

  const toggleExpanded = () => {
    const newState = !isExpanded;
    setIsExpanded(newState);
    if (storageKey) {
      localStorage.setItem(`collapsible-${storageKey}`, String(newState));
    }
  };

  if (!isMounted) {
    return (
      <div className={`border-b border-gray-200/60 ${className}`}>
        <div className={`py-3 flex items-center justify-between ${headerClassName}`}>
          <h3 className="text-sm font-medium text-gray-700">{title}</h3>
        </div>
        <div className={`${contentClassName}`}>{children}</div>
      </div>
    );
  }

  return (
    <div className={`border-b border-gray-200/60 ${className}`}>
      <button
        onClick={toggleExpanded}
        className={`w-full py-3 flex items-center justify-between hover:text-gray-900 transition-colors ${headerClassName}`}
      >
        <h3 className="text-sm font-medium text-gray-700">{title}</h3>
        <svg
          className={`w-4 h-4 text-gray-400 transition-transform duration-200 ${
            isExpanded ? 'rotate-180' : ''
          }`}
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
        </svg>
      </button>
      <div
        className={`overflow-hidden transition-all duration-200 ease-in-out ${
          isExpanded ? 'max-h-[2000px] opacity-100 pb-4' : 'max-h-0 opacity-0'
        }`}
      >
        <div className={`${contentClassName}`}>{children}</div>
      </div>
    </div>
  );
}

'use client';

import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  ResponsiveContainer,
  Cell,
} from 'recharts';

import { useTranslations } from '@/i18n';
import { baseColors, chartColors } from '@/lib/config/colors';
import { type OracleProvider } from '@/types/oracle';

import { oracleNames, oracleColors, type PriceComparisonData } from './crossOracleConfig';

interface PriceStats {
  avg: number;
  max: number;
  min: number;
  range: number;
  stdDev: number;
  median: number;
}

interface DeviationAlert {
  provider: OracleProvider;
  name: string;
  deviation: number;
  price: number;
}

interface OverviewTabProps {
  consistencyScore: number;
  priceStats: PriceStats | null;
  deviationAlerts: DeviationAlert[];
  priceData: PriceComparisonData[];
  selectedOracles: OracleProvider[];
  getConsistencyLabel: (score: number) => string;
  getConsistencyColor: (score: number) => string;
  extendedStats: {
    maxDeviation: number;
    maxPriceOracle?: { name: string };
    minPriceOracle?: { name: string };
    avgResponseTime: number;
  } | null;
}

export function OverviewTab({
  consistencyScore,
  priceStats,
  deviationAlerts,
  priceData,
  selectedOracles,
  getConsistencyLabel,
  getConsistencyColor,
  extendedStats,
}: OverviewTabProps) {
  const t = useTranslations();

  const chartData = priceData.map((data) => ({
    name: oracleNames[data.provider],
    price: data.price,
    color: oracleColors[data.provider],
  }));

  return (
    <div className="space-y-6">
      {/* 核心指标 - 卡片网格 */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {/* 一致性评分 */}
        <div className="bg-slate-50/50 p-5 transition-colors hover:bg-slate-50">
          <p className="text-xs font-normal text-gray-400 mb-2">
            {t('crossOracleComparison.consistencyScore')}
          </p>
          <p className={`text-3xl font-semibold ${getConsistencyColor(consistencyScore)}`}>
            {consistencyScore}
          </p>
          <p className="text-xs text-gray-400 mt-1">{getConsistencyLabel(consistencyScore)}</p>
        </div>

        {/* 平均价格 */}
        {priceStats && (
          <div className="bg-slate-50/50 p-5 transition-colors hover:bg-slate-50">
            <p className="text-xs font-normal text-gray-400 mb-2">
              {t('crossOracle.averagePrice')}
            </p>
            <p className="text-3xl font-semibold text-gray-900">${priceStats.avg.toFixed(2)}</p>
            <p className="text-xs text-gray-400 mt-1">
              {t('crossOracle.range')}: ${priceStats.range.toFixed(2)}
            </p>
          </div>
        )}

        {/* 价格范围 */}
        {priceStats && (
          <div className="bg-slate-50/50 p-5 transition-colors hover:bg-slate-50">
            <p className="text-xs font-normal text-gray-400 mb-2">{t('crossOracle.priceRange')}</p>
            <p className="text-3xl font-semibold text-gray-900">${priceStats.range.toFixed(2)}</p>
            <p className="text-xs text-gray-400 mt-1">
              {((priceStats.range / priceStats.avg) * 100).toFixed(2)}%
            </p>
          </div>
        )}

        {/* 最大偏差 */}
        {extendedStats && (
          <div className="bg-slate-50/50 p-5 transition-colors hover:bg-slate-50">
            <p className="text-xs font-normal text-gray-400 mb-2">
              {t('crossOracle.stats.maxPriceDifference')}
            </p>
            <p className="text-3xl font-semibold text-amber-600">
              {extendedStats.maxDeviation.toFixed(3)}%
            </p>
            <p className="text-xs text-gray-400 mt-1">
              {t('crossOracle.stats.deviationFromAverage')}
            </p>
          </div>
        )}
      </div>

      {/* 偏差警告 */}
      {deviationAlerts.length > 0 && (
        <div className="bg-amber-50 border border-amber-200 p-4">
          <div className="flex items-start gap-3">
            <svg
              className="w-4 h-4 text-amber-500 flex-shrink-0 mt-0.5"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
              />
            </svg>
            <div className="flex-1 min-w-0">
              <h3 className="text-xs font-medium text-amber-800 mb-2">
                {t('crossOracle.priceDeviationAlert')} ({deviationAlerts.length})
              </h3>
              <div className="space-y-1.5">
                {deviationAlerts.slice(0, 3).map((alert) => (
                  <div key={alert.provider} className="flex items-center gap-2 text-xs">
                    <div
                      className="w-2 h-2 flex-shrink-0"
                      style={{ backgroundColor: oracleColors[alert.provider] }}
                    />
                    <span className="text-gray-700 truncate">{alert.name}</span>
                    <span className="text-gray-500">{alert.deviation.toFixed(3)}%</span>
                  </div>
                ))}
                {deviationAlerts.length > 3 && (
                  <p className="text-xs text-gray-500">
                    +{deviationAlerts.length - 3} {t('crossOracle.more')}
                  </p>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 价格对比图表 */}
      {chartData.length > 0 && (
        <div className="bg-slate-50/30 p-5">
          <h3 className="text-xs font-normal text-gray-500 mb-4">
            {t('crossOracle.currentPriceComparison')}
          </h3>
          <div className="h-56">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 5, right: 5, left: 5, bottom: 5 }}>
                <CartesianGrid
                  strokeDasharray="3 3"
                  stroke={baseColors.gray[200]}
                  vertical={false}
                />
                <XAxis
                  dataKey="name"
                  tick={{ fontSize: 11, fill: '#6b7280' }}
                  interval={0}
                  axisLine={false}
                  tickLine={false}
                />
                <YAxis
                  tickFormatter={(value) => `$${Number(value).toFixed(0)}`}
                  tick={{ fontSize: 11, fill: '#6b7280' }}
                  axisLine={false}
                  tickLine={false}
                />
                <RechartsTooltip
                  formatter={(value) => [`$${Number(value).toFixed(2)}`, t('crossOracle.price')]}
                  contentStyle={{
                    fontSize: 12,
                    border: 'none',
                    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
                  }}
                />
                <Bar dataKey="price" radius={[4, 4, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* 选中预言机列表 */}
      <div className="bg-slate-50/30 p-5">
        <h3 className="text-xs font-normal text-gray-500 mb-3">
          {t('crossOracle.selectedOracles')} ({selectedOracles.length}/5)
        </h3>
        <div className="flex flex-wrap gap-2">
          {selectedOracles.map((provider) => (
            <div
              key={provider}
              className="flex items-center gap-1.5 px-3 py-1.5 bg-white text-xs text-gray-700"
            >
              <div className="w-2 h-2" style={{ backgroundColor: oracleColors[provider] }} />
              <span>{oracleNames[provider]}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useTranslations } from '@/i18n';
import { OracleProvider } from '@/types/oracle';

import {
  type PriceComparisonData,
  type DeviationData,
  oracleNames,
  oracleColors,
} from './crossOracleConfig';
import { TrendIndicator } from './TrendIndicator';

interface PriceStats {
  avg: number;
  max: number;
  min: number;
  range: number;
  stdDev: number;
  median: number;
}

interface PriceComparisonTableProps {
  sortedPriceData: PriceComparisonData[];
  priceStats: PriceStats | null;
  deviationData: DeviationData[];
  handleSort: (field: 'price' | 'deviation' | 'confidence' | 'responseTime' | 'name') => void;
  getSortIcon: (
    field: 'price' | 'deviation' | 'confidence' | 'responseTime' | 'name'
  ) => React.ReactNode;
}

export function PriceComparisonTable({
  sortedPriceData,
  priceStats,
  deviationData,
  handleSort,
  getSortIcon,
}: PriceComparisonTableProps) {
  const t = useTranslations();

  return (
    <div className="py-4 border-b border-gray-100">
      <h3 className="text-sm font-semibold text-gray-900 mb-3">
        {t('crossOracle.priceComparisonDetails')}
      </h3>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-gray-100">
              <th
                className="px-3 py-3 text-left text-xs font-normal text-gray-400 uppercase tracking-wider cursor-pointer hover:text-gray-600"
                onClick={() => handleSort('name')}
              >
                <div className="flex items-center gap-1">
                  {t('crossOracle.oracle')}
                  {getSortIcon('name')}
                </div>
              </th>
              <th
                className="px-3 py-3 text-left text-xs font-normal text-gray-400 uppercase tracking-wider cursor-pointer hover:text-gray-600"
                onClick={() => handleSort('price')}
              >
                <div className="flex items-center gap-1">
                  {t('crossOracle.price')}
                  {getSortIcon('price')}
                </div>
              </th>
              <th
                className="px-3 py-3 text-left text-xs font-normal text-gray-400 uppercase tracking-wider cursor-pointer hover:text-gray-600"
                onClick={() => handleSort('deviation')}
              >
                <div className="flex items-center gap-1">
                  {t('crossOracle.deviation')}
                  {getSortIcon('deviation')}
                </div>
              </th>
              <th
                className="px-3 py-3 text-left text-xs font-normal text-gray-400 uppercase tracking-wider cursor-pointer hover:text-gray-600"
                onClick={() => handleSort('confidence')}
              >
                <div className="flex items-center gap-1">
                  {t('crossOracle.confidence')}
                  {getSortIcon('confidence')}
                </div>
              </th>
              <th
                className="px-3 py-3 text-left text-xs font-normal text-gray-400 uppercase tracking-wider cursor-pointer hover:text-gray-600"
                onClick={() => handleSort('responseTime')}
              >
                <div className="flex items-center gap-1">
                  {t('crossOracleComparison.avgResponseTime')}
                  {getSortIcon('responseTime')}
                </div>
              </th>
              <th className="px-3 py-3 text-left text-xs font-normal text-gray-400 uppercase tracking-wider">
                {t('crossOracle.trend')}
              </th>
            </tr>
          </thead>
          <tbody>
            {sortedPriceData.map((data, index) => {
              const deviation = priceStats
                ? ((data.price - priceStats.avg) / priceStats.avg) * 100
                : 0;
              const deviationAbs = Math.abs(deviation);
              const deviationColor =
                deviationAbs < 0.5
                  ? 'text-success-600'
                  : deviationAbs < 1
                    ? 'text-warning-600'
                    : 'text-danger-600';

              const shouldHighlight = deviationAbs > 1;
              const trendData = deviationData.find((d) => d.provider === data.provider);
              const trend = trendData?.trend || 'stable';

              return (
                <tr
                  key={data.provider}
                  className={`border-b border-gray-50 hover:bg-slate-50/50 transition-colors ${
                    shouldHighlight ? 'bg-amber-50/30' : index % 2 === 1 ? 'bg-slate-50/30' : ''
                  }`}
                >
                  <td className="px-3 py-3.5 whitespace-nowrap">
                    <div className="flex items-center">
                      <div
                        className="w-2.5 h-2.5 mr-2"
                        style={{ backgroundColor: oracleColors[data.provider] }}
                      />
                      <span className="font-medium text-gray-900">
                        {oracleNames[data.provider]}
                      </span>
                      {shouldHighlight && (
                        <span className="ml-2 inline-flex items-center px-1.5 py-0.5 text-xs font-medium bg-amber-100 text-amber-700">
                          {t('crossOracleComparison.highDeviation')}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-3 py-3.5 whitespace-nowrap text-gray-900 font-mono">
                    ${data.price.toFixed(2)}
                  </td>
                  <td className={`px-3 py-3.5 whitespace-nowrap font-mono ${deviationColor}`}>
                    {deviation > 0 ? '+' : ''}
                    {deviation.toFixed(3)}%
                  </td>
                  <td className="px-3 py-3.5 whitespace-nowrap text-gray-500">
                    {data.confidence ? `${(data.confidence * 100).toFixed(1)}%` : '-'}
                  </td>
                  <td className="px-3 py-3.5 whitespace-nowrap text-gray-500">
                    {data.responseTime}ms
                  </td>
                  <td className="px-3 py-3.5 whitespace-nowrap">
                    <TrendIndicator trend={trend} />
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

