          <SegmentedControl
            options={[
              { value: '5', label: `5 ${t('charts.latency.points')}` },
              { value: '10', label: `10 ${t('charts.latency.points')}` },
              { value: '20', label: `20 ${t('charts.latency.points')}` },
            ]}
            value={predictionPeriod.toString()}
