              style={{ borderTop: `2px dashed ${semanticColors.danger.DEFAULT}` }}
            />
            <span className="text-xs text-gray-500">{t('charts.trend.threshold')}</span>
          </div>
        </div>
      </div>

      {/* Anomaly Summary */}
      {stats.anomalyCount > 0 && (
        <div className="bg-danger-50 border border-danger-200 p-4">
          <div className="flex items-start gap-3">
            <svg
              className="w-5 h-5 text-danger-600 flex-shrink-0 mt-0.5"
              fill="currentColor"
              viewBox="0 0 20 20"
            >
              <path
                fillRule="evenodd"
                d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z"
                clipRule="evenodd"
              />
            </svg>
            <div>
              <h4 className="text-sm font-semibold text-danger-800 mb-1">
                {t('charts.trend.anomalyAlert')}
              </h4>
              <p className="text-xs text-danger-700">
                {t('charts.trend.anomalyDesc', {
                  count: stats.anomalyCount,
                  percent: stats.anomalyPercent,
                  threshold: anomalyThreshold,
                })}
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export type { LatencyTrendMiniChartProps, LatencyDataPoint };

'use client';

import { useMemo, useState } from 'react';

import {
  ComposedChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  Legend,
  ResponsiveContainer,
  Area,
} from 'recharts';

import { DashboardCard } from '@/components/oracle/data-display/DashboardCard';
import { DropdownSelect } from '@/components/ui';
import { useTranslations } from '@/i18n';
import { chartColors, baseColors, semanticColors } from '@/lib/config/colors';
import {
  calculateSMA,
  calculateEMA,
  calculateBollingerBands,
  calculateRollingStdDev,
} from '@/lib/indicators';
import { OracleProvider } from '@/types/oracle';
import type { PriceDataForTechnicalAnalysis } from '@/types/oracle/price';

export interface OraclePriceHistory {
  oracle: OracleProvider;
  prices: PriceDataForTechnicalAnalysis[];
}

export interface MovingAverageConfig {
  window: number;
  label: string;
  color: string;
}

export interface MovingAverageChartProps {
  data: OraclePriceHistory[];
  oracleNames?: Partial<Record<OracleProvider, string>>;
  className?: string;
  showBollingerBands?: boolean;
  showRollingStdDev?: boolean;
}

const DEFAULT_ORACLE_NAMES: Record<OracleProvider, string> = {
  [OracleProvider.CHAINLINK]: 'Chainlink',
  [OracleProvider.BAND_PROTOCOL]: 'Band Protocol',
  [OracleProvider.UMA]: 'UMA',
  [OracleProvider.PYTH]: 'Pyth',
  [OracleProvider.API3]: 'API3',
  [OracleProvider.REDSTONE]: 'RedStone',
  [OracleProvider.DIA]: 'DIA',
  [OracleProvider.TELLOR]: 'Tellor',
  [OracleProvider.CHRONICLE]: 'Chronicle',
  [OracleProvider.WINKLINK]: 'WINkLink',
};

const ORACLE_COLORS: Record<OracleProvider, string> = {
  [OracleProvider.CHAINLINK]: chartColors.oracle.chainlink,
  [OracleProvider.BAND_PROTOCOL]: chartColors.oracle['band-protocol'],
  [OracleProvider.UMA]: chartColors.oracle.uma,
  [OracleProvider.PYTH]: chartColors.oracle['pyth'],
  [OracleProvider.API3]: chartColors.oracle.api3,
  [OracleProvider.REDSTONE]: chartColors.oracle.redstone,
  [OracleProvider.DIA]: chartColors.oracle.dia,
  [OracleProvider.TELLOR]: chartColors.oracle.tellor,
  [OracleProvider.CHRONICLE]: chartColors.oracle.chronicle,
  [OracleProvider.WINKLINK]: chartColors.oracle.winklink,
};

const MA_CONFIGS: MovingAverageConfig[] = [
  { window: 5, label: 'MA5', color: chartColors.recharts.warning },
  { window: 10, label: 'MA10', color: chartColors.recharts.success },
  { window: 20, label: 'MA20', color: chartColors.recharts.purple },
];

interface ChartDataPoint {
  timestamp: string;
  rawTimestamp: number;
  [key: string]: string | number;
}

export function MovingAverageChart({
  data,
  oracleNames: customOracleNames,
  className,
  showBollingerBands: initialShowBollingerBands = true,
  showRollingStdDev = true,
}: MovingAverageChartProps) {
  const t = useTranslations();
  const oracleNames = { ...DEFAULT_ORACLE_NAMES, ...customOracleNames };
  const [selectedOracle, setSelectedOracle] = useState<OracleProvider>(
    data[0]?.oracle || OracleProvider.CHAINLINK
  );
  const [selectedMA, setSelectedMA] = useState<number[]>([5, 10, 20]);
  const [showEMA, setShowEMA] = useState(false);
  const [showBollingerBands, setShowBollingerBands] = useState(initialShowBollingerBands);

  const selectedOracleData = useMemo(() => {
    return data.find((d) => d.oracle === selectedOracle);
  }, [data, selectedOracle]);

  const chartData = useMemo(() => {
    if (!selectedOracleData) return [];

    const sortedPrices = [...selectedOracleData.prices].sort((a, b) => a.timestamp - b.timestamp);
    const prices = sortedPrices.map((p) => p.price);

    const bollinger = showBollingerBands ? calculateBollingerBands(prices) : null;
    const rollingStdDev = showRollingStdDev ? calculateRollingStdDev(prices, 20) : null;

    return sortedPrices.map((point, index) => {
      const dataPoint: ChartDataPoint = {
        timestamp: new Date(point.timestamp).toLocaleTimeString('zh-CN', {
          hour: '2-digit',
          minute: '2-digit',
        }),
        rawTimestamp: point.timestamp,
        price: point.price,
      };

      selectedMA.forEach((window) => {
        const sma = calculateSMA(prices.slice(0, index + 1), window);
        dataPoint[`SMA${window}`] = sma[index];
      });

      if (showEMA) {
        selectedMA.forEach((window) => {
          const ema = calculateEMA(prices.slice(0, index + 1), window);
          dataPoint[`EMA${window}`] = ema[index];
        });
      }

      if (bollinger) {
        dataPoint.bbUpper = bollinger.upper[index];
        dataPoint.bbMiddle = bollinger.middle[index];
        dataPoint.bbLower = bollinger.lower[index];
      }

      if (rollingStdDev) {
        dataPoint.rollingStdDev = rollingStdDev[index];
      }

      return dataPoint;
    });
  }, [selectedOracleData, selectedMA, showEMA, showBollingerBands, showRollingStdDev]);

  const stats = useMemo(() => {
    if (!selectedOracleData || selectedOracleData.prices.length === 0) {
      return null;
    }

    const prices = selectedOracleData.prices.map((p) => p.price);
    const currentPrice = prices[prices.length - 1];

    const sma5 = calculateSMA(prices, 5);
    const sma10 = calculateSMA(prices, 10);
    const sma20 = calculateSMA(prices, 20);

    const currentSMA5 = sma5[sma5.length - 1];
    const currentSMA10 = sma10[sma10.length - 1];
    const currentSMA20 = sma20[sma20.length - 1];

    let trend: 'bullish' | 'bearish' | 'neutral' = 'neutral';
    if (currentSMA5 > currentSMA10 && currentSMA10 > currentSMA20) {
      trend = 'bullish';
    } else if (currentSMA5 < currentSMA10 && currentSMA10 < currentSMA20) {
      trend = 'bearish';
    }

    const bb = calculateBollingerBands(prices);
    const lastIdx = prices.length - 1;
    const bbPosition = (currentPrice - bb.lower[lastIdx]) / (bb.upper[lastIdx] - bb.lower[lastIdx]);

    return {
      currentPrice,
      sma5: currentSMA5,
      sma10: currentSMA10,
      sma20: currentSMA20,
      trend,
      bbPosition: bbPosition * 100,
      volatility: calculateRollingStdDev(prices, 20)[lastIdx],
    };
  }, [selectedOracleData]);

  const CustomTooltip = ({
    active,
    payload,
    label,
  }: {
    active?: boolean;
    payload?: Array<{ name: string; value: number | string; color: string }>;
    label?: string;
  }) => {
    if (!active || !payload || payload.length === 0) return null;

    return (
      <div className="bg-white p-4 border border-gray-200 rounded-lg min-w-[220px]">
        <p className="text-sm font-semibold mb-2" style={{ color: baseColors.gray[900] }}>
          {label}
        </p>
        <div className="space-y-1.5">
          {payload.map((entry, index: number) => (
            <div key={index} className="flex justify-between items-center">
              <span className="text-xs" style={{ color: baseColors.gray[600] }}>
                {entry.name}
              </span>
              <span className="text-sm font-medium font-mono" style={{ color: entry.color }}>
                {typeof entry.value === 'number' ? `$${entry.value.toFixed(2)}` : entry.value}
              </span>
            </div>
          ))}
        </div>
      </div>
    );
  };

  if (!selectedOracleData) {
    return (
      <DashboardCard title={t('charts.movingAverage.title')} className={className}>
        <div className="h-80 flex items-center justify-center text-gray-400">
          {t('charts.movingAverage.noData')}
        </div>
      </DashboardCard>
    );
  }

  return (
    <div className="space-y-6">
      <DashboardCard title={t('charts.movingAverage.title')} className={className}>
        <div className="space-y-6">
          <div className="flex flex-wrap items-center gap-4">
            <div className="flex items-center gap-2">
              <span className="text-sm" style={{ color: baseColors.gray[600] }}>
                {t('charts.movingAverage.oracle')}:
              </span>
              <DropdownSelect
                options={data.map((oracleData) => ({
                  value: oracleData.oracle,
                  label: oracleNames[oracleData.oracle],
                }))}
                value={selectedOracle}
                onChange={(value) => setSelectedOracle(value as OracleProvider)}
                className="text-sm"
              />
            </div>

            <div className="flex items-center gap-2">
              <span className="text-sm" style={{ color: baseColors.gray[600] }}>
                {t('charts.movingAverage.ma')}:
              </span>
              <div className="flex gap-1">
                {[5, 10, 20].map((window) => (
                  <button
                    key={window}
                    onClick={() => {
                      setSelectedMA((prev) =>
                        prev.includes(window) ? prev.filter((w) => w !== window) : [...prev, window]
                      );
                    }}
                    className={`px-2 py-1 text-xs rounded transition-colors ${
                      selectedMA.includes(window) ? 'bg-primary-600 text-white' : ''
                    }`}
                    style={
                      !selectedMA.includes(window)
                        ? { backgroundColor: baseColors.gray[100], color: baseColors.gray[600] }
                        : {}
                    }
                  >
                    MA{window}
                  </button>
                ))}
              </div>
            </div>

            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={showEMA}
                onChange={(e) => setShowEMA(e.target.checked)}
                className="w-4 h-4 text-primary-600 rounded focus:ring-primary-500"
              />
              <span className="text-sm" style={{ color: baseColors.gray[600] }}>
                {t('charts.movingAverage.showEMA')}
              </span>
            </label>

            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={showBollingerBands}
                onChange={(e) => setShowBollingerBands(e.target.checked)}
                className="w-4 h-4 text-primary-600 rounded focus:ring-primary-500"
              />
              <span className="text-sm" style={{ color: baseColors.gray[600] }}>
                {t('charts.movingAverage.bollingerBands')}
              </span>
            </label>
          </div>

          {stats && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div
                className="border p-4 rounded-lg"
                style={{ backgroundColor: baseColors.gray[100], borderColor: baseColors.gray[200] }}
              >
                <p className="text-xs mb-1" style={{ color: baseColors.gray[600] }}>
                  {t('charts.movingAverage.currentPrice')}
                </p>
                <p className="text-xl font-bold" style={{ color: semanticColors.info.DEFAULT }}>
                  ${stats.currentPrice.toFixed(2)}
                </p>
              </div>
              <div
                className="border p-4 rounded-lg"
                style={{ backgroundColor: baseColors.gray[100], borderColor: baseColors.gray[200] }}
              >
                <p className="text-xs mb-1" style={{ color: baseColors.gray[600] }}>
                  MA5
                </p>
                <p className="text-xl font-bold" style={{ color: semanticColors.warning.DEFAULT }}>
                  ${stats.sma5.toFixed(2)}
                </p>
              </div>
              <div
                className="border p-4 rounded-lg"
                style={{ backgroundColor: baseColors.gray[100], borderColor: baseColors.gray[200] }}
              >
                <p className="text-xs mb-1" style={{ color: baseColors.gray[600] }}>
                  MA10
                </p>
                <p className="text-xl font-bold" style={{ color: semanticColors.success.DEFAULT }}>
                  ${stats.sma10.toFixed(2)}
                </p>
              </div>
              <div
                className="border p-4 rounded-lg"
                style={{ backgroundColor: baseColors.gray[100], borderColor: baseColors.gray[200] }}
              >
                <p className="text-xs mb-1" style={{ color: baseColors.gray[600] }}>
                  MA20
                </p>
                <p className="text-xl font-bold" style={{ color: baseColors.primary[600] }}>
                  ${stats.sma20.toFixed(2)}
                </p>
              </div>
            </div>
          )}

          {stats && (
            <div className="flex items-center gap-4">
              <div
                className="px-4 py-2 text-sm font-medium"
                style={
                  stats.trend === 'bullish'
                    ? {
                        backgroundColor: semanticColors.success.light,
                        color: semanticColors.success.DEFAULT,
                      }
                    : stats.trend === 'bearish'
                      ? {
                          backgroundColor: semanticColors.danger.light,
                          color: semanticColors.danger.DEFAULT,
                        }
                      : { backgroundColor: baseColors.gray[100], color: baseColors.gray[700] }
                }
              >
                {t('charts.movingAverage.trend')}:{' '}
                {stats.trend === 'bullish'
                  ? t('charts.movingAverage.bullish')
                  : stats.trend === 'bearish'
                    ? t('charts.movingAverage.bearish')
                    : t('charts.movingAverage.neutral')}
              </div>
              <div className="text-sm" style={{ color: baseColors.gray[600] }}>
                {t('charts.movingAverage.bbPosition')}:{' '}
                <span className="font-medium">{stats.bbPosition.toFixed(1)}%</span>
              </div>
              <div className="text-sm" style={{ color: baseColors.gray[600] }}>
                {t('charts.movingAverage.rollingStdDev')}:{' '}
                <span className="font-medium">${stats.volatility.toFixed(4)}</span>
              </div>
            </div>
          )}

          <div>
            <h4 className="text-sm font-medium text-gray-700 mb-3">
              {t('charts.movingAverage.priceAndMA')}
            </h4>
            <div style={{ height: 350 }}>
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke={chartColors.recharts.grid} />
                  <XAxis
                    dataKey="timestamp"
                    stroke={chartColors.recharts.axis}
                    tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
                    minTickGap={40}
                  />
                  <YAxis
                    stroke={chartColors.recharts.axis}
                    tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
                    tickFormatter={(value) => `$${value.toFixed(0)}`}
                    domain={['auto', 'auto']}
                  />
                  <RechartsTooltip content={<CustomTooltip />} />
                  <Legend />

                  {showBollingerBands && (
                    <>
                      <Area
                        type="monotone"
                        dataKey="bbUpper"
                        stroke="none"
                        fill={chartColors.recharts.indigo}
                        fillOpacity={0.3}
                        name={t('charts.movingAverage.bbUpper')}
                      />
                      <Area
                        type="monotone"
                        dataKey="bbLower"
                        stroke="none"
                        fill={chartColors.recharts.white}
                        fillOpacity={1}
                        name={t('charts.movingAverage.bbLower')}
                      />
                      <Line
                        type="monotone"
                        dataKey="bbMiddle"
                        stroke={chartColors.recharts.indigo}
                        strokeWidth={1}
                        strokeDasharray="5 5"
                        dot={false}
                        name={t('charts.movingAverage.bbMiddle')}
                      />
                    </>
                  )}

                  <Line
                    type="monotone"
                    dataKey="price"
                    stroke={ORACLE_COLORS[selectedOracle]}
                    strokeWidth={2}
                    dot={false}
                    name={t('charts.movingAverage.price')}
                  />

                  {selectedMA.map((window) => {
                    const config = MA_CONFIGS.find((c) => c.window === window);
                    return (
                      <Line
                        key={`SMA${window}`}
                        type="monotone"
                        dataKey={`SMA${window}`}
                        stroke={config?.color || baseColors.gray[500]}
                        strokeWidth={1.5}
                        dot={false}
                        name={`MA${window}`}
                      />
                    );
                  })}

                  {showEMA &&
                    selectedMA.map((window) => (
                      <Line
                        key={`EMA${window}`}
                        type="monotone"
                        dataKey={`EMA${window}`}
                        stroke={chartColors.recharts.pink}
                        strokeWidth={1.5}
                        strokeDasharray="3 3"
                        dot={false}
                        name={`EMA${window}`}
                      />
                    ))}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </div>

          {showRollingStdDev && (
            <div>
              <h4 className="text-sm font-medium text-gray-700 mb-3">
                {t('charts.movingAverage.rollingStdDevTitle')}
              </h4>
              <div style={{ height: 200 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart
                    data={chartData}
                    margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke={chartColors.recharts.grid} />
                    <XAxis
                      dataKey="timestamp"
                      stroke={chartColors.recharts.axis}
                      tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
                      minTickGap={40}
                    />
                    <YAxis
                      stroke={chartColors.recharts.axis}
                      tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
                      tickFormatter={(value) => `$${value.toFixed(2)}`}
                    />
                    <RechartsTooltip content={<CustomTooltip />} />
                    <Area
                      type="monotone"
                      dataKey="rollingStdDev"
                      stroke={chartColors.recharts.warning}
                      fill={chartColors.recharts.warning}
                      fillOpacity={0.3}
                      name={t('charts.movingAverage.rollingStdDev')}
                    />
                  </ComposedChart>
                </ResponsiveContainer>
              </div>
            </div>
          )}

          <div className="p-4" style={{ backgroundColor: semanticColors.info.light }}>
            <h4 className="text-sm font-medium mb-2" style={{ color: semanticColors.info.DEFAULT }}>
              指标说明
            </h4>
            <ul className="text-sm space-y-1" style={{ color: semanticColors.info.DEFAULT }}>
              <li>
                • <strong>SMA (简单移动平均线)</strong>: n周期内价格的算术平均值，用于平滑价格波动
              </li>
              <li>
                • <strong>EMA (指数移动平均线)</strong>:
                给予近期价格更高权重的移动平均线，对价格变化更敏感
              </li>
              <li>
                • <strong>布林带 (Bollinger Bands)</strong>: 由中轨(MA20)和上下轨(MA20 ±
                2σ)组成，用于衡量价格波动范围
              </li>
              <li>
                • <strong>滚动标准差</strong>: 动态计算n周期内的价格标准差，反映价格波动性变化
              </li>
              <li>
                • <strong>趋势判断</strong>: MA5 &gt; MA10 &gt; MA20 为看涨排列，反之为看跌排列
              </li>
            </ul>
          </div>
        </div>
      </DashboardCard>
    </div>
  );
}

'use client';

import { useState, useEffect, useMemo, useCallback } from 'react';

import {
  ComposedChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  ResponsiveContainer,
  Legend,
} from 'recharts';

import { DashboardCard } from '@/components/oracle/data-display/DashboardCard';
import { ChartSkeleton } from '@/components/ui';
import { useTranslations } from '@/i18n';
import { chartColors, baseColors, semanticColors, shadowColors } from '@/lib/config/colors';
import {
  type BandProtocolClient,
  type ValidatorInfo,
  type HistoryPeriod,
} from '@/lib/oracles/bandProtocol';
import { formatNumber } from '@/lib/utils/format';

type MetricType = 'uptime' | 'staked' | 'commission';
type TimeRange = '7D' | '30D' | '90D';

interface ValidatorHistoryData {
  timestamp: number;
  uptime: number;
  stakedAmount: number;
  commissionRate: number;
}

export interface MultiValidatorComparisonProps {
  validators: ValidatorInfo[];
  client: BandProtocolClient;
}

interface ChartDataPoint {
  time: string;
  timestamp: number;
  [key: string]: string | number;
}

function getTimeRangeConfig(
  t: (key: string) => string
): Record<TimeRange, { period: HistoryPeriod; label: string }> {
  return {
    '7D': { period: 7, label: t('charts.multiValidator.days7') },
    '30D': { period: 30, label: t('charts.multiValidator.days30') },
    '90D': { period: 90, label: t('charts.multiValidator.days90') },
  };
}

function getMetricConfig(
  t: (key: string) => string
): Record<MetricType, { label: string; unit: string; color: string }> {
  return {
    uptime: {
      label: t('charts.multiValidator.uptime'),
      unit: '%',
      color: semanticColors.success.DEFAULT,
    },
    staked: {
      label: t('charts.multiValidator.staked'),
      unit: ' BAND',
      color: chartColors.recharts.primary,
    },
    commission: {
      label: t('charts.multiValidator.commission'),
      unit: '%',
      color: chartColors.recharts.purple,
    },
  };
}

const VALIDATOR_COLORS = [
  chartColors.recharts.primary,
  semanticColors.success.DEFAULT,
  semanticColors.warning.DEFAULT,
  semanticColors.danger.DEFAULT,
];

function CustomTooltip({
  active,
  payload,
  label,
  metricType,
  validators,
  t,
}: {
  active?: boolean;
  payload?: Array<{ dataKey: string; value: number; color: string }>;
  label?: string;
  metricType: MetricType;
  validators: ValidatorInfo[];
  t: (key: string) => string;
}) {
  if (!active || !payload || payload.length === 0) return null;

  const config = getMetricConfig(t)[metricType];

  return (
    <div
      className="p-3 min-w-[180px]"
      style={{
        backgroundColor: baseColors.gray[50],
        border: `1px solid ${baseColors.gray[200]}`,
        boxShadow: shadowColors.tooltip,
      }}
    >
      <p className="text-xs mb-2 font-medium" style={{ color: baseColors.gray[600] }}>
        {label}
      </p>
      <div className="space-y-1.5">
        {payload.map((entry, index) => {
          const validator = validators[index];
          if (!validator) return null;

          let value = entry.value;
          if (metricType === 'staked') {
            value = Number((value / 1000000).toFixed(2));
          } else {
            value = Number(value.toFixed(2));
          }

          return (
            <div key={entry.dataKey} className="flex items-center justify-between gap-4 text-xs">
              <div className="flex items-center gap-2">
                <span className="w-2 h-2" style={{ backgroundColor: entry.color }} />
                <span className="truncate max-w-[100px]" style={{ color: baseColors.gray[600] }}>
                  {validator.moniker}
                </span>
              </div>
              <span className="font-mono font-medium" style={{ color: entry.color }}>
                {value}
                {config.unit}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ComparisonTable({
  validators,
  historyData,
  t,
}: {
  validators: ValidatorInfo[];
  historyData: Map<string, ValidatorHistoryData[]>;
  t: (key: string) => string;
}) {
  const getTrendIcon = (change: number) => {
    if (change > 0.1) return '↗';
    if (change < -0.1) return '↘';
    return '→';
  };

  const getTrendColor = (change: number) => {
    if (change > 0.1) return `text-[${semanticColors.success.dark}]`;
    if (change < -0.1) return `text-[${semanticColors.danger.dark}]`;
    return `text-[${baseColors.gray[500]}]`;
  };

  return (
    <div className="overflow-x-auto mt-6">
      <table className="w-full text-sm">
        <thead>
          <tr style={{ backgroundColor: baseColors.gray[50], textAlign: 'left' }}>
            <th
              className="py-3 px-4 text-xs font-medium uppercase tracking-wider"
              style={{ color: baseColors.gray[500] }}
            >
              {t('charts.multiValidator.validator')}
            </th>
            <th
              className="py-3 px-4 text-xs font-medium uppercase tracking-wider text-right"
              style={{ color: baseColors.gray[500] }}
            >
              {t('charts.multiValidator.avgUptime')}
            </th>
            <th
              className="py-3 px-4 text-xs font-medium uppercase tracking-wider text-right"
              style={{ color: baseColors.gray[500] }}
            >
              {t('charts.multiValidator.latestStaked')}
            </th>
            <th
              className="py-3 px-4 text-xs font-medium uppercase tracking-wider text-right"
              style={{ color: baseColors.gray[500] }}
            >
              {t('charts.multiValidator.commissionRate')}
            </th>
            <th
              className="py-3 px-4 text-xs font-medium uppercase tracking-wider text-center"
              style={{ color: baseColors.gray[500] }}
            >
              {t('charts.multiValidator.trend')}
            </th>
          </tr>
        </thead>
        <tbody style={{ borderTop: `1px solid ${baseColors.gray[100]}` }}>
          {validators.map((validator, index) => {
            const history = historyData.get(validator.operatorAddress) || [];
            const avgUptime =
              history.length > 0
                ? history.reduce((sum, h) => sum + h.uptime, 0) / history.length
                : validator.uptime;

            const firstUptime = history[0]?.uptime || validator.uptime;
            const lastUptime = history[history.length - 1]?.uptime || validator.uptime;
            const uptimeChange = lastUptime - firstUptime;

            return (
              <tr
                key={validator.operatorAddress}
                style={{ borderBottom: `1px solid ${baseColors.gray[100]}` }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.backgroundColor = baseColors.gray[50];
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.backgroundColor = 'transparent';
                }}
              >
                <td className="py-3 px-4">
                  <div className="flex items-center gap-2">
                    <span
                      className="w-3 h-3"
                      style={{ backgroundColor: VALIDATOR_COLORS[index % VALIDATOR_COLORS.length] }}
                    />
                    <span className="font-medium" style={{ color: baseColors.gray[900] }}>
                      {validator.moniker}
                    </span>
                    <span className="text-xs" style={{ color: baseColors.gray[400] }}>
                      #{validator.rank}
                    </span>
                  </div>
                </td>
                <td className="py-3 px-4 text-right">
                  <span className="font-mono font-medium" style={{ color: baseColors.gray[900] }}>
                    {avgUptime.toFixed(2)}%
                  </span>
                </td>
                <td className="py-3 px-4 text-right">
                  <span className="font-mono font-medium" style={{ color: baseColors.gray[900] }}>
                    {formatNumber(validator.tokens, true)} BAND
                  </span>
                </td>
                <td className="py-3 px-4 text-right">
                  <span className="font-mono font-medium" style={{ color: baseColors.gray[900] }}>
                    {(validator.commissionRate * 100).toFixed(2)}%
                  </span>
                </td>
                <td className="py-3 px-4 text-center">
                  <span className={`font-medium ${getTrendColor(uptimeChange)}`}>
                    {getTrendIcon(uptimeChange)} {Math.abs(uptimeChange).toFixed(2)}%
                  </span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export function MultiValidatorComparison({ validators, client }: MultiValidatorComparisonProps) {
  const t = useTranslations();
  const [metricType, setMetricType] = useState<MetricType>('uptime');
  const [timeRange, setTimeRange] = useState<TimeRange>('30D');
  const [historyData, setHistoryData] = useState<Map<string, ValidatorHistoryData[]>>(new Map());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const TIME_RANGE_CONFIG = getTimeRangeConfig(t);
  const METRIC_CONFIG = getMetricConfig(t);

  const fetchHistoryData = useCallback(async () => {
    if (validators.length < 2) return;

    setLoading(true);
    setError(null);

    try {
      const timeRangeConfig = getTimeRangeConfig(t);
      const period = timeRangeConfig[timeRange].period;
      const newHistoryData = new Map<string, ValidatorHistoryData[]>();

      await Promise.all(
        validators.map(async (validator) => {
          const history = await client.getValidatorHistory(validator.operatorAddress, period);
          newHistoryData.set(validator.operatorAddress, history);
        })
      );

      setHistoryData(newHistoryData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch validator history');
    } finally {
      setLoading(false);
    }
  }, [validators, client, timeRange]);

  useEffect(() => {
    fetchHistoryData();
  }, [fetchHistoryData]);

  const chartData = useMemo((): ChartDataPoint[] => {
    if (historyData.size === 0 || validators.length === 0) return [];

    const firstValidator = validators[0];
    const firstHistory = historyData.get(firstValidator.operatorAddress) || [];

    return firstHistory.map((point, index) => {
      const date = new Date(point.timestamp);
      const timeLabel = date.toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' });

      const dataPoint: ChartDataPoint = {
        time: timeLabel,
        timestamp: point.timestamp,
      };

      validators.forEach((validator, vIndex) => {
        const history = historyData.get(validator.operatorAddress);
        if (history && history[index]) {
          const key = `validator_${vIndex}`;
          switch (metricType) {
            case 'uptime':
              dataPoint[key] = history[index].uptime;
              break;
            case 'staked':
              dataPoint[key] = history[index].stakedAmount;
              break;
            case 'commission':
              dataPoint[key] = history[index].commissionRate * 100;
              break;
          }
        }
      });

      return dataPoint;
    });
  }, [historyData, validators, metricType]);

  const yAxisConfig = useMemo(() => {
    if (chartData.length === 0) {
      switch (metricType) {
        case 'uptime':
          return { min: 95, max: 100, tickFormatter: (v: number) => `${v}%` };
        case 'staked':
          return {
            min: 0,
            max: 10000000,
            tickFormatter: (v: number) => `${(v / 1000000).toFixed(1)}M`,
          };
        case 'commission':
          return { min: 0, max: 30, tickFormatter: (v: number) => `${v}%` };
      }
    }

    const values: number[] = [];
    validators.forEach((_, vIndex) => {
      const key = `validator_${vIndex}`;
      chartData.forEach((d) => {
        if (typeof d[key] === 'number') {
          values.push(d[key] as number);
        }
      });
    });

    const min = Math.min(...values);
    const max = Math.max(...values);
    const padding = (max - min) * 0.1;

    switch (metricType) {
      case 'uptime':
        return {
          min: Math.max(0, min - padding),
          max: Math.min(100, max + padding),
          tickFormatter: (v: number) => `${v.toFixed(0)}%`,
        };
      case 'staked':
        return {
          min: Math.max(0, min - padding),
          max: max + padding,
          tickFormatter: (v: number) => `${(v / 1000000).toFixed(1)}M`,
        };
      case 'commission':
        return {
          min: Math.max(0, min - padding),
          max: Math.min(100, max + padding),
          tickFormatter: (v: number) => `${v.toFixed(1)}%`,
        };
    }
  }, [chartData, metricType, validators.length]);

  if (validators.length < 2) return null;

  return (
    <DashboardCard
      title={t('charts.multiValidator.title')}
      headerAction={
        <div className="flex items-center gap-2">
          <div
            className="flex items-center gap-1 p-1"
            style={{ backgroundColor: baseColors.gray[100] }}
          >
            {(Object.keys(TIME_RANGE_CONFIG) as TimeRange[]).map((range) => (
              <button
                key={range}
                onClick={() => setTimeRange(range)}
                className="px-2 py-1 text-xs font-medium rounded-md transition-colors"
                style={{
                  backgroundColor: timeRange === range ? baseColors.gray[50] : 'transparent',
                  color: timeRange === range ? baseColors.primary[600] : baseColors.gray[600],
                }}
                onMouseEnter={(e) => {
                  if (timeRange !== range) {
                    e.currentTarget.style.color = baseColors.gray[900];
                  }
                }}
                onMouseLeave={(e) => {
                  if (timeRange !== range) {
                    e.currentTarget.style.color = baseColors.gray[600];
                  }
                }}
              >
                {TIME_RANGE_CONFIG[range].label}
              </button>
            ))}
          </div>
        </div>
      }
    >
      <div className="space-y-4">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-xs mr-1" style={{ color: baseColors.gray[500] }}>
            {t('charts.multiValidator.metric')}:
          </span>
          {(Object.keys(METRIC_CONFIG) as MetricType[]).map((type) => (
            <button
              key={type}
              onClick={() => setMetricType(type)}
              className="px-3 py-1.5 text-xs font-medium transition-all"
              style={{
                backgroundColor:
                  metricType === type ? baseColors.primary[600] : baseColors.gray[100],
                color: metricType === type ? baseColors.gray[50] : baseColors.gray[600],
              }}
              onMouseEnter={(e) => {
                if (metricType !== type) {
                  e.currentTarget.style.backgroundColor = baseColors.gray[200];
                }
              }}
              onMouseLeave={(e) => {
                if (metricType !== type) {
                  e.currentTarget.style.backgroundColor = baseColors.gray[100];
                }
              }}
            >
              {METRIC_CONFIG[type].label}
            </button>
          ))}
        </div>

        {loading ? (
          <ChartSkeleton height={300} showToolbar={false} variant="line" />
        ) : error ? (
          <div
            className="p-6"
            style={{
              height: 300,
              backgroundColor: semanticColors.danger.light,
              border: `1px solid ${baseColors.primary[200]}`,
            }}
          >
            <div className="flex items-center gap-3" style={{ color: semanticColors.danger.dark }}>
              <svg
                className="w-5 h-5"
                fill="none"
                stroke={semanticColors.danger.dark}
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                />
              </svg>
              <span className="text-sm">{error}</span>
            </div>
          </div>
        ) : (
          <>
            <div className="p-4" style={{ height: 300, backgroundColor: baseColors.gray[50] }}>
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                  <CartesianGrid
                    strokeDasharray="3 3"
                    stroke={chartColors.recharts.grid}
                    strokeOpacity={0.5}
                    vertical={false}
                  />
                  <XAxis
                    dataKey="time"
                    stroke={chartColors.recharts.axis}
                    tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
                    tickLine={false}
                    axisLine={{ stroke: chartColors.recharts.grid, strokeOpacity: 0.5 }}
                    minTickGap={30}
                  />
                  <YAxis
                    stroke={chartColors.recharts.secondaryAxis}
                    tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
                    tickLine={false}
                    axisLine={{ stroke: chartColors.recharts.grid, strokeOpacity: 0.5 }}
                    domain={[yAxisConfig.min, yAxisConfig.max]}
                    tickFormatter={yAxisConfig.tickFormatter}
                    width={50}
                  />
                  <RechartsTooltip
                    content={
                      <CustomTooltip metricType={metricType} validators={validators} t={t} />
                    }
                  />
                  <Legend
                    verticalAlign="top"
                    height={30}
                    iconType="line"
                    wrapperStyle={{ paddingBottom: '10px' }}
                    formatter={(value, entry) => {
                      const index = parseInt(value.replace('validator_', ''));
                      const validator = validators[index];
                      return validator ? validator.moniker : value;
                    }}
                  />
                  {validators.map((validator, index) => (
                    <Line
                      key={validator.operatorAddress}
                      type="monotone"
                      dataKey={`validator_${index}`}
                      name={validator.moniker}
                      stroke={VALIDATOR_COLORS[index % VALIDATOR_COLORS.length]}
                      strokeWidth={2}
                      dot={false}
                      activeDot={{ r: 4, strokeWidth: 0 }}
                    />
                  ))}
                </ComposedChart>
              </ResponsiveContainer>
            </div>

            <div className="flex items-center justify-center gap-4 flex-wrap">
              {validators.map((validator, index) => (
                <div key={validator.operatorAddress} className="flex items-center gap-2">
                  <span
                    className="w-3 h-3"
                    style={{ backgroundColor: VALIDATOR_COLORS[index % VALIDATOR_COLORS.length] }}
                  />
                  <span className="text-xs" style={{ color: baseColors.gray[600] }}>
                    {validator.moniker}
                  </span>
                </div>
              ))}
            </div>

            <ComparisonTable validators={validators} historyData={historyData} t={t} />
          </>
        )}
      </div>
    </DashboardCard>
  );
}

'use client';

import { useState, useEffect, useMemo, useCallback } from 'react';

import { TrendingUp, TrendingDown, RefreshCw, ExternalLink, Info } from 'lucide-react';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  Cell,
} from 'recharts';

import { Skeleton } from '@/components/ui';
import { getDIADataService } from '@/lib/oracles';
import { Blockchain } from '@/types/oracle';

const DIA_CHAIN_NAMES: Partial<Record<Blockchain, string>> = {
  [Blockchain.ETHEREUM]: 'Ethereum',
  [Blockchain.POLYGON]: 'Polygon',
  [Blockchain.AVALANCHE]: 'Avalanche',
  [Blockchain.ARBITRUM]: 'Arbitrum',
  [Blockchain.BASE]: 'Base',
};

const CHAIN_COLORS: Partial<Record<Blockchain, string>> = {
  [Blockchain.ETHEREUM]: '#627eea',
  [Blockchain.POLYGON]: '#8247e5',
  [Blockchain.AVALANCHE]: '#e84142',
  [Blockchain.ARBITRUM]: '#28a0f0',
  [Blockchain.BASE]: '#0052ff',
};

interface NFTCollection {
  address: string;
  name: string;
  chain: Blockchain;
  imageUrl?: string;
}

interface NFTFloorPriceData {
  collection: string;
  floorPrice: number;
  floorPriceUSD: number;
  floorPriceYesterday: number;
  volumeYesterday: number;
  timestamp: number;
  chain: Blockchain;
  change24h: number;
  change24hPercent: number;
}

interface FloorPricePoint {
  timestamp: number;
  date: string;
  floorPrice: number;
  floorPriceUSD: number;
}

interface VolumePoint {
  date: string;
  volume: number;
  color: string;
}

interface NFTFloorPriceHistoryProps {
  collection: NFTCollection;
  days?: 7 | 14 | 30;
  showVolume?: boolean;
  onRefresh?: () => void;
}

export function NFTFloorPriceHistory({
  collection,
  days = 14,
  showVolume = true,
  onRefresh,
}: NFTFloorPriceHistoryProps) {
  const [floorPriceData, setFloorPriceData] = useState<NFTFloorPriceData | null>(null);
  const [historicalData, setHistoricalData] = useState<FloorPricePoint[]>([]);
  const [volumeData, setVolumeData] = useState<VolumePoint[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedPeriod, setSelectedPeriod] = useState<7 | 14 | 30>(days);

  const diaService = useMemo(() => getDIADataService(), []);

  const generateMockHistoricalData = useCallback(
    (basePrice: number, periodDays: number): FloorPricePoint[] => {
      const data: FloorPricePoint[] = [];
      const now = Date.now();
      const pointsPerDay = 4;
      const totalPoints = periodDays * pointsPerDay;

      for (let i = totalPoints; i >= 0; i--) {
        const timestamp = now - i * ((24 * 60 * 60 * 1000) / pointsPerDay);
        const randomVariation = (Math.random() - 0.5) * 0.1;
        const trendFactor = Math.sin(i / 10) * 0.05;
        const price = basePrice * (1 + randomVariation + trendFactor);

        data.push({
          timestamp,
          date: new Date(timestamp).toLocaleDateString('en-US', {
            month: 'short',
            day: 'numeric',
          }),
          floorPrice: price,
          floorPriceUSD: price * 1800,
        });
      }

      return data;
    },
    []
  );

  const generateMockVolumeData = useCallback(
    (baseVolume: number, periodDays: number): VolumePoint[] => {
      const data: VolumePoint[] = [];
      const now = Date.now();

      for (let i = periodDays; i >= 0; i--) {
        const timestamp = now - i * 24 * 60 * 60 * 1000;
        const randomVariation = Math.random() * 0.8 + 0.6;
        const volume = baseVolume * randomVariation;
        const isHighVolume = volume > baseVolume * 0.9;

        data.push({
          date: new Date(timestamp).toLocaleDateString('en-US', {
            month: 'short',
            day: 'numeric',
          }),
          volume,
          color: isHighVolume ? '#10b981' : '#6b7280',
        });
      }

      return data;
    },
    []
  );

  const fetchData = async () => {
    setIsRefreshing(true);
    setError(null);

    try {
      const nftData = await diaService.getNFTFloorPrice(collection.address, collection.chain);

      if (nftData) {
        const change24h = nftData.FloorPrice - (nftData.FloorPriceYesterday || nftData.FloorPrice);
        const change24hPercent = nftData.FloorPriceYesterday
          ? (change24h / nftData.FloorPriceYesterday) * 100
          : 0;

        setFloorPriceData({
          collection: nftData.Collection || collection.name,
          floorPrice: nftData.FloorPrice,
          floorPriceUSD: nftData.FloorPriceUSD || nftData.FloorPrice * 1800,
          floorPriceYesterday: nftData.FloorPriceYesterday || nftData.FloorPrice,
          volumeYesterday: nftData.VolumeYesterday || 0,
          timestamp: new Date(nftData.Time).getTime(),
          chain: collection.chain,
          change24h,
          change24hPercent,
        });

        setHistoricalData(generateMockHistoricalData(nftData.FloorPrice, selectedPeriod));
        setVolumeData(generateMockVolumeData(nftData.VolumeYesterday || 100, selectedPeriod));
      } else {
        const mockFloorPrice = 0.5 + Math.random() * 2;
        setFloorPriceData({
          collection: collection.name,
          floorPrice: mockFloorPrice,
          floorPriceUSD: mockFloorPrice * 1800,
          floorPriceYesterday: mockFloorPrice * (0.95 + Math.random() * 0.1),
          volumeYesterday: 50 + Math.random() * 200,
          timestamp: Date.now(),
          chain: collection.chain,
          change24h: (Math.random() - 0.5) * 0.1,
          change24hPercent: (Math.random() - 0.5) * 10,
        });

        setHistoricalData(generateMockHistoricalData(mockFloorPrice, selectedPeriod));
        setVolumeData(generateMockVolumeData(100, selectedPeriod));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch NFT data');
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
      onRefresh?.();
    }
  };

  useEffect(() => {
    fetchData();
  }, [collection.address, collection.chain, selectedPeriod]);

  const stats = useMemo(() => {
    if (!floorPriceData || historicalData.length === 0) return null;

    const prices = historicalData.map((d) => d.floorPrice);
    const minPrice = Math.min(...prices);
    const maxPrice = Math.max(...prices);
    const avgPrice = prices.reduce((a, b) => a + b, 0) / prices.length;
    const volatility = Math.sqrt(
      prices.reduce((sum, p) => sum + Math.pow(p - avgPrice, 2), 0) / prices.length
    );

    return {
      minPrice,
      maxPrice,
      avgPrice,
      volatility,
      volatilityPercent: (volatility / avgPrice) * 100,
    };
  }, [floorPriceData, historicalData]);

  if (isLoading) {
    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <Skeleton className="h-6 w-48" />
          <Skeleton className="h-8 w-24" />
        </div>
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-lg p-4">
        <p className="text-red-700">{error}</p>
        <button
          onClick={fetchData}
          className="mt-2 text-sm text-red-600 hover:text-red-800 underline"
        >
          Retry
        </button>
      </div>
    );
  }

  if (!floorPriceData) return null;

  const isPositive = floorPriceData.change24hPercent >= 0;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-base font-semibold text-gray-900">Floor Price History</h3>
          <p className="text-sm text-gray-500 mt-0.5">
            {collection.name} • {DIA_CHAIN_NAMES[collection.chain] || collection.chain}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-0.5">
            {[7, 14, 30].map((d) => (
              <button
                key={d}
                onClick={() => setSelectedPeriod(d as 7 | 14 | 30)}
                className={`px-2.5 py-1 text-xs font-medium rounded-md transition-colors ${
                  selectedPeriod === d
                    ? 'bg-white text-gray-900 shadow-sm'
                    : 'text-gray-600 hover:text-gray-900'
                }`}
              >
                {d}D
              </button>
            ))}
          </div>
          <button
            onClick={fetchData}
            disabled={isRefreshing}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-gray-700 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 disabled:opacity-50"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${isRefreshing ? 'animate-spin' : ''}`} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="p-4 bg-white rounded-lg border border-gray-200">
          <p className="text-xs text-gray-500 uppercase tracking-wide">Current Floor</p>
          <p className="text-xl font-semibold text-gray-900 mt-1">
            Ξ {floorPriceData.floorPrice.toFixed(4)}
          </p>
          <p className="text-xs text-gray-500 mt-0.5">
            ${floorPriceData.floorPriceUSD.toLocaleString()}
          </p>
        </div>
        <div className="p-4 bg-white rounded-lg border border-gray-200">
          <p className="text-xs text-gray-500 uppercase tracking-wide">24h Change</p>
          <p
