'use client';

import { useState, useEffect, useCallback } from 'react';

import {
  type ChartSettings,
  type ScreenSize,
  CHART_SETTINGS_STORAGE_KEY,
} from './priceChartConfig';
import { loadChartSettings, saveChartSettings } from './priceChartUtils';

const DEFAULT_CHART_SETTINGS: ChartSettings = {
  anomalyDetectionEnabled: true,
  showPredictionInterval: false,
  confidenceLevel: 95,
  comparisonEnabled: false,
};

export function useChartSettings() {
  const [settings, setSettings] = useState<ChartSettings>(DEFAULT_CHART_SETTINGS);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const saved = loadChartSettings(CHART_SETTINGS_STORAGE_KEY, null as ChartSettings | null);
    if (saved) {
      setSettings((prev) => ({ ...prev, ...saved }));
    }
    setIsLoaded(true);
  }, []);

  const updateSettings = useCallback((updates: Partial<ChartSettings>) => {
    setSettings((prev) => {
      const newSettings = { ...prev, ...updates };
      saveChartSettings(CHART_SETTINGS_STORAGE_KEY, newSettings);
      return newSettings;
    });
  }, []);

  return { settings, updateSettings, isLoaded };
}

export function useScreenSize(): ScreenSize {
  const [screenSize, setScreenSize] = useState<ScreenSize>('desktop');

  useEffect(() => {
    const checkScreenSize = () => {
      const width = window.innerWidth;
      if (width < 640) {
        setScreenSize('mobile');
      } else if (width < 1024) {
        setScreenSize('tablet');
      } else {
        setScreenSize('desktop');
      }
    };

    checkScreenSize();
    window.addEventListener('resize', checkScreenSize);
    return () => window.removeEventListener('resize', checkScreenSize);
  }, []);

  return screenSize;
}

'use client';

import { useState, useMemo } from 'react';

import { DashboardCard } from '@/components/oracle/data-display/DashboardCard';
import { useTranslations } from '@/i18n';
import { baseColors, semanticColors, chartColors } from '@/lib/config/colors';
import type { PriceDataForTechnicalAnalysis } from '@/types/oracle/price';

export interface OraclePriceSeries {
  oracleId: string;
  data: PriceDataForTechnicalAnalysis[];
}

interface PriceCorrelationMatrixProps {
  data: OraclePriceSeries[];
  oracleNames?: Record<string, string>;
  className?: string;
}

interface CorrelationCell {
  oracle1: string;
  oracle2: string;
  correlation: number;
}

const calculatePearsonCorrelation = (x: number[], y: number[]): number => {
  const n = Math.min(x.length, y.length);

  if (n < 2) {
    return 0;
  }

  const xSlice = x.slice(0, n);
  const ySlice = y.slice(0, n);

  const sumX = xSlice.reduce((a, b) => a + b, 0);
  const sumY = ySlice.reduce((a, b) => a + b, 0);
  const meanX = sumX / n;
  const meanY = sumY / n;

  let numerator = 0;
  let denominatorX = 0;
  let denominatorY = 0;

  for (let i = 0; i < n; i++) {
    const diffX = xSlice[i] - meanX;
    const diffY = ySlice[i] - meanY;
    numerator += diffX * diffY;
    denominatorX += diffX * diffX;
    denominatorY += diffY * diffY;
  }

  const denominator = Math.sqrt(denominatorX * denominatorY);

  if (denominator === 0) {
    return 0;
  }

  const correlation = numerator / denominator;

  return Math.max(-1, Math.min(1, correlation));
};

const getCorrelationColor = (correlation: number): string => {
  // 使用 colors.ts 中的颜色配置
  if (correlation >= 0.7) return semanticColors.success.DEFAULT;
  if (correlation >= 0.3) return baseColors.primary[400];
  if (correlation >= -0.3) return baseColors.gray[300];
  if (correlation >= -0.7) return semanticColors.warning.DEFAULT;
  return semanticColors.danger.DEFAULT;
};

const getCorrelationTextColor = (correlation: number): string => {
  const absCorrelation = Math.abs(correlation);
  if (absCorrelation > 0.7) {
    return 'text-white';
  }
  return `text-[${baseColors.gray[800]}]`;
};

const getCorrelationLevel = (correlation: number, t: (key: string) => string): string => {
  const absCorrelation = Math.abs(correlation);
  if (absCorrelation >= 0.9) return t('priceCorrelation.level.veryStrong');
  if (absCorrelation >= 0.7) return t('priceCorrelation.level.strong');
  if (absCorrelation >= 0.5) return t('priceCorrelation.level.moderate');
  if (absCorrelation >= 0.3) return t('priceCorrelation.level.weak');
  return t('priceCorrelation.level.veryWeak');
};

const getCorrelationLevelColor = (correlation: number): string => {
  const absCorrelation = Math.abs(correlation);
  if (absCorrelation >= 0.7) return `text-[${semanticColors.success.dark}]`;
  if (absCorrelation >= 0.5) return `text-[${baseColors.primary[600]}]`;
  if (absCorrelation >= 0.3) return `text-[${semanticColors.warning.dark}]`;
  return `text-[${baseColors.gray[600]}]`;
};

export function PriceCorrelationMatrix({
  data,
  oracleNames = {},
  className = '',
}: PriceCorrelationMatrixProps) {
  const [hoveredCell, setHoveredCell] = useState<CorrelationCell | null>(null);
  const t = useTranslations();

  const { correlationMatrix, oracleIds, priceArrays } = useMemo(() => {
    const ids = data.map((d) => d.oracleId);
    const priceArraysMap = new Map<string, number[]>();

    data.forEach((series) => {
      const sortedData = [...series.data].sort((a, b) => a.timestamp - b.timestamp);
      priceArraysMap.set(
        series.oracleId,
        sortedData.map((d) => d.price)
      );
    });

    const matrix: CorrelationCell[][] = [];

    ids.forEach((id1, i) => {
      const row: CorrelationCell[] = [];
      ids.forEach((id2, j) => {
        const prices1 = priceArraysMap.get(id1) || [];
        const prices2 = priceArraysMap.get(id2) || [];
        const correlation = calculatePearsonCorrelation(prices1, prices2);
        row.push({
          oracle1: id1,
          oracle2: id2,
          correlation,
        });
      });
      matrix.push(row);
    });

    return {
      correlationMatrix: matrix,
      oracleIds: ids,
      priceArrays: priceArraysMap,
    };
  }, [data]);

  const stats = useMemo(() => {
    const correlations: number[] = [];
    oracleIds.forEach((id1, i) => {
      oracleIds.forEach((id2, j) => {
        if (i < j) {
          correlations.push(correlationMatrix[i][j].correlation);
        }
      });
    });

    if (correlations.length === 0) {
      return {
        avgCorrelation: 0,
        maxCorrelation: 0,
        minCorrelation: 0,
        highCorrelationCount: 0,
      };
    }

    const avgCorrelation = correlations.reduce((a, b) => a + b, 0) / correlations.length;
    const maxCorrelation = Math.max(...correlations);
    const minCorrelation = Math.min(...correlations);
    const highCorrelationCount = correlations.filter((c) => Math.abs(c) >= 0.7).length;

    return {
      avgCorrelation,
      maxCorrelation,
      minCorrelation,
      highCorrelationCount,
    };
  }, [correlationMatrix, oracleIds]);

  const getOracleName = (id: string): string => {
    return oracleNames[id] || id;
  };

  const colorLegend = [
    {
      color: semanticColors.danger.DEFAULT,
      label: '-1.0',
      desc: t('priceCorrelation.legend.perfectNegative'),
    },
    {
      color: semanticColors.warning.DEFAULT,
      label: '-0.5',
      desc: t('priceCorrelation.legend.negative'),
    },
    { color: baseColors.gray[300], label: '0.0', desc: t('priceCorrelation.legend.none') },
    { color: baseColors.primary[400], label: '0.5', desc: t('priceCorrelation.legend.positive') },
    {
      color: semanticColors.success.DEFAULT,
      label: '1.0',
      desc: t('priceCorrelation.legend.perfectPositive'),
    },
  ];

  return (
    <DashboardCard
      title={t('priceCorrelation.title')}
      className={className}
      headerAction={
        <div className="flex items-center gap-4 text-xs text-gray-500">
          <span>
            {t('priceCorrelation.oracleCount')}: {oracleIds.length}
          </span>
          <span>
            {t('priceCorrelation.highCorrelationPairs')}: {stats.highCorrelationCount}
          </span>
        </div>
      }
    >
      <div className="space-y-4">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div className="p-3 text-center" style={{ backgroundColor: baseColors.primary[50] }}>
            <p className="text-xs mb-1" style={{ color: baseColors.primary[600] }}>
              {t('priceCorrelation.avgCorrelation')}
            </p>
            <p className="text-xl font-bold" style={{ color: baseColors.primary[700] }}>
              {stats.avgCorrelation.toFixed(3)}
            </p>
          </div>
          <div
            className="p-3 text-center"
            style={{ backgroundColor: semanticColors.success.light }}
          >
            <p className="text-xs mb-1" style={{ color: semanticColors.success.dark }}>
              {t('priceCorrelation.maxCorrelation')}
            </p>
            <p className="text-xl font-bold" style={{ color: semanticColors.success.text }}>
              {stats.maxCorrelation.toFixed(3)}
            </p>
          </div>
          <div className="p-3 text-center" style={{ backgroundColor: semanticColors.danger.light }}>
            <p className="text-xs mb-1" style={{ color: semanticColors.danger.dark }}>
              {t('priceCorrelation.minCorrelation')}
            </p>
            <p className="text-xl font-bold" style={{ color: semanticColors.danger.text }}>
              {stats.minCorrelation.toFixed(3)}
            </p>
          </div>
          <div className="p-3 text-center" style={{ backgroundColor: baseColors.slate[50] }}>
            <p className="text-xs mb-1" style={{ color: baseColors.slate[600] }}>
              {t('priceCorrelation.highCorrelationCount')}
            </p>
            <p className="text-xl font-bold" style={{ color: baseColors.slate[700] }}>
              {stats.highCorrelationCount}
            </p>
          </div>
        </div>

        <div className="relative overflow-x-auto">
          <div className="min-w-fit">
            <div className="flex">
              <div className="w-32 flex-shrink-0" />
              <div className="flex-1">
                <div className="flex gap-1 mb-2">
                  {oracleIds.map((id) => (
                    <div
                      key={id}
                      className="flex-1 min-w-[60px] text-center text-xs text-gray-500 font-medium"
                    >
                      <div className="transform -rotate-45 origin-left whitespace-nowrap">
                        {getOracleName(id)}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="space-y-1">
              {correlationMatrix.map((row, i) => (
                <div key={oracleIds[i]} className="flex items-center">
                  <div className="w-32 flex-shrink-0 pr-3 flex items-center">
                    <span className="text-sm text-gray-700 truncate font-medium">
                      {getOracleName(oracleIds[i])}
                    </span>
                  </div>
                  <div className="flex-1 flex gap-1">
                    {row.map((cell, j) => {
                      const isDiagonal = i === j;
                      const correlation = cell.correlation;

                      return (
                        <div
                          key={`${oracleIds[i]}-${oracleIds[j]}`}
                          className={`flex-1 min-w-[60px] aspect-square rounded-md flex items-center justify-center text-xs font-medium cursor-pointer transition-all hover:scale-110 hover:z-10 hover:ring-2 hover:ring-gray-400 ${getCorrelationTextColor(correlation)}`}
                          style={{
                            backgroundColor: isDiagonal
                              ? baseColors.gray[100]
                              : getCorrelationColor(correlation),
                          }}
                          onMouseEnter={() =>
                            !isDiagonal &&
                            setHoveredCell({
                              oracle1: oracleIds[i],
                              oracle2: oracleIds[j],
                              correlation,
                            })
                          }
                          onMouseLeave={() => setHoveredCell(null)}
                        >
                          {isDiagonal ? (
                            <span style={{ color: baseColors.gray[400] }}>-</span>
                          ) : (
                            <span className="font-mono">{correlation.toFixed(2)}</span>
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {hoveredCell && (
            <div
              className="absolute left-1/2 top-0 transform -translate-x-1/2 -translate-y-full mb-2 text-white text-xs px-4 py-3 z-20 min-w-[220px]"
              style={{ backgroundColor: baseColors.gray[900] }}
            >
              <div className="font-semibold text-sm mb-2">
                {getOracleName(hoveredCell.oracle1)} ↔ {getOracleName(hoveredCell.oracle2)}
              </div>
              <div className="space-y-1">
                <div className="flex justify-between">
                  <span style={{ color: baseColors.gray[400] }}>
                    {t('priceCorrelation.correlationCoefficient')}:
                  </span>
                  <span className="font-mono font-semibold">
                    {hoveredCell.correlation.toFixed(4)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span style={{ color: baseColors.gray[400] }}>
                    {t('priceCorrelation.correlationLevel')}:
                  </span>
                  <span className={getCorrelationLevelColor(hoveredCell.correlation)}>
                    {getCorrelationLevel(hoveredCell.correlation, t)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span style={{ color: baseColors.gray[400] }}>
                    {t('priceCorrelation.correlationDirection')}:
                  </span>
                  <span>
                    {hoveredCell.correlation > 0
                      ? t('priceCorrelation.positiveCorrelation')
                      : hoveredCell.correlation < 0
                        ? t('priceCorrelation.negativeCorrelation')
                        : t('priceCorrelation.noCorrelation')}
                  </span>
                </div>
              </div>
              <div className="absolute bottom-0 left-1/2 transform -translate-x-1/2 translate-y-full">
                <div
                  className="border-8 border-transparent"
                  style={{ borderTopColor: baseColors.gray[900] }}
                />
              </div>
            </div>
          )}
        </div>

        <div className="p-4" style={{ backgroundColor: baseColors.gray[50] }}>
          <div className="text-xs mb-2 font-medium" style={{ color: baseColors.gray[600] }}>
            {t('priceCorrelation.legend.title')}
          </div>
          <div className="flex items-center justify-center gap-2">
            <span className="text-xs" style={{ color: baseColors.gray[500] }}>
              -1.0
            </span>
            <div className="flex gap-0.5">
              {colorLegend.map((item, index) => (
                <div
                  key={index}
                  className="w-8 h-4 rounded"
                  style={{ backgroundColor: item.color }}
                  title={`${item.label}: ${item.desc}`}
                />
              ))}
            </div>
            <span className="text-xs" style={{ color: baseColors.gray[500] }}>
              1.0
            </span>
          </div>
          <div
            className="flex items-center justify-center gap-4 mt-2 text-xs"
            style={{ color: baseColors.gray[500] }}
          >
            <span>{t('priceCorrelation.legend.lowCorrelation')}</span>
            <span>|</span>
            <span>{t('priceCorrelation.legend.highCorrelation')}</span>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="p-4" style={{ backgroundColor: baseColors.gray[50] }}>
            <h4 className="text-sm font-semibold mb-3" style={{ color: baseColors.gray[700] }}>
              {t('priceCorrelation.distribution.title')}
            </h4>
            <div className="space-y-2">
              {[
                { range: '0.9 - 1.0', min: 0.9, max: 1.0 },
                { range: '0.7 - 0.9', min: 0.7, max: 0.9 },
                { range: '0.5 - 0.7', min: 0.5, max: 0.7 },
                { range: '0.3 - 0.5', min: 0.3, max: 0.5 },
                { range: '0.0 - 0.3', min: 0.0, max: 0.3 },
              ].map((item) => {
                const count = correlationMatrix.flat().filter((cell, idx) => {
                  const i = Math.floor(idx / oracleIds.length);
                  const j = idx % oracleIds.length;
                  const absCorr = Math.abs(cell.correlation);
                  return i < j && absCorr >= item.min && absCorr < item.max;
                }).length;
                const total = (oracleIds.length * (oracleIds.length - 1)) / 2 || 1;
                const percentage = ((count / total) * 100).toFixed(1);

                return (
                  <div key={item.range} className="flex items-center gap-2">
                    <div className="w-20 text-xs" style={{ color: baseColors.gray[600] }}>
                      {item.range}
                    </div>
                    <div
                      className="flex-1 h-2 overflow-hidden"
                      style={{ backgroundColor: baseColors.gray[200] }}
                    >
                      <div
                        className="h-full transition-all"
                        style={{
                          width: `${percentage}%`,
                          backgroundColor: baseColors.primary[500],
                        }}
                      />
                    </div>
                    <div
                      className="w-16 text-right text-xs"
                      style={{ color: baseColors.gray[500] }}
                    >
                      {count} ({percentage}%)
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="p-4" style={{ backgroundColor: baseColors.gray[50] }}>
            <h4 className="text-sm font-semibold mb-3" style={{ color: baseColors.gray[700] }}>
              {t('priceCorrelation.distribution.topPairs')}
            </h4>
            <div className="space-y-2">
              {correlationMatrix
                .flat()
                .filter((cell, idx) => {
                  const i = Math.floor(idx / oracleIds.length);
                  const j = idx % oracleIds.length;
                  return i < j;
                })
                .sort((a, b) => Math.abs(b.correlation) - Math.abs(a.correlation))
                .slice(0, 5)
                .map((cell, idx) => (
                  <div key={`${cell.oracle1}-${cell.oracle2}`} className="flex items-center gap-2">
                    <span
                      className="w-5 text-xs font-medium"
                      style={{ color: baseColors.gray[400] }}
                    >
                      {idx + 1}
                    </span>
                    <span
                      className="flex-1 text-sm truncate"
                      style={{ color: baseColors.gray[700] }}
                    >
                      {getOracleName(cell.oracle1)} ↔ {getOracleName(cell.oracle2)}
                    </span>
                    <span
                      className={`text-sm font-mono font-medium ${getCorrelationLevelColor(cell.correlation)}`}
                    >
                      {cell.correlation.toFixed(3)}
                    </span>
                  </div>
                ))}
            </div>
          </div>
        </div>

        <div
          className="p-4"
          style={{
            backgroundColor: baseColors.primary[50],
            borderColor: baseColors.primary[200],
            borderWidth: '1px',
          }}
        >
          <div className="flex items-start gap-3">
            <svg
              className="w-5 h-5 flex-shrink-0 mt-0.5"
              style={{ color: baseColors.primary[600] }}
              fill="currentColor"
              viewBox="0 0 20 20"
            >
              <path
                fillRule="evenodd"
                d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z"
                clipRule="evenodd"
              />
            </svg>
            <div>
              <h4 className="text-sm font-semibold mb-1" style={{ color: baseColors.primary[800] }}>
                {t('priceCorrelation.explanation.title')}
              </h4>
              <p className="text-xs" style={{ color: baseColors.primary[700] }}>
                {t('priceCorrelation.explanation.description')}
              </p>
            </div>
          </div>
        </div>
      </div>
    </DashboardCard>
  );
}

'use client';

import { useState, useMemo } from 'react';

import { DashboardCard } from '@/components/oracle/data-display/DashboardCard';
import { useTranslations } from '@/i18n';
import { heatmapColors, baseColors } from '@/lib/config/colors';
import { OracleProvider } from '@/types/oracle';

export interface PriceDeviationDataPoint {
  timestamp: number;
  oracleName: string;
  deviationPercent: number;
  price: number;
}

export interface TimeRange {
  start: number;
  end: number;
}

interface PriceDeviationHeatmapProps {
  data: PriceDeviationDataPoint[];
  timeRange?: TimeRange;
  className?: string;
  useAccessibleColors?: boolean;
}

const oracleColors: Record<string, string> = {
  Chainlink: heatmapColors.oracle.chainlink,
  'Band Protocol': heatmapColors.oracle.bandProtocol,
  UMA: heatmapColors.oracle.uma,
  'Pyth Network': heatmapColors.oracle.pythNetwork,
  API3: heatmapColors.oracle.api3,
};

// 色盲友好的预言机颜色
const accessibleOracleColors: Record<string, string> = {
  Chainlink: heatmapColors.accessible.chainlink,
  'Band Protocol': heatmapColors.accessible.bandProtocol,
  UMA: heatmapColors.accessible.uma,
  'Pyth Network': heatmapColors.accessible.pythNetwork,
  API3: heatmapColors.accessible.api3,
};

const getDeviationColor = (deviation: number): string => {
  const absDeviation = Math.abs(deviation);
  if (absDeviation < 0.1) return heatmapColors.deviation.extremelyLow;
  if (absDeviation < 0.25) return heatmapColors.deviation.low;
  if (absDeviation < 0.5) return heatmapColors.deviation.lower;
  if (absDeviation < 0.75) return heatmapColors.deviation.medium;
  if (absDeviation < 1) return heatmapColors.deviation.higher;
  if (absDeviation < 1.5) return heatmapColors.deviation.high;
  if (absDeviation < 2) return heatmapColors.deviation.veryHigh;
  if (absDeviation < 3) return heatmapColors.deviation.extremelyHigh;
  return heatmapColors.deviation.anomaly;
};

const getDeviationTextColor = (deviation: number): string => {
  const absDeviation = Math.abs(deviation);
  if (absDeviation < 0.75) return 'text-gray-800';
  return 'text-white';
};

const formatTimestamp = (timestamp: number): string => {
  const date = new Date(timestamp);
  return `${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;
};

const formatFullTimestamp = (timestamp: number): string => {
  const date = new Date(timestamp);
  return `${date.getFullYear()}-${(date.getMonth() + 1).toString().padStart(2, '0')}-${date.getDate().toString().padStart(2, '0')} ${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;
};

const getColorLegend = (t: (key: string) => string) => [
  {
    color: heatmapColors.deviation.extremelyLow,
    label: '< 0.1%',
    range: t('priceDeviationHeatmap.range.extremelyLow'),
  },
  {
    color: heatmapColors.deviation.low,
    label: '0.1-0.25%',
    range: t('priceDeviationHeatmap.range.low'),
  },
  {
    color: heatmapColors.deviation.lower,
    label: '0.25-0.5%',
    range: t('priceDeviationHeatmap.range.lower'),
  },
  {
    color: heatmapColors.deviation.medium,
    label: '0.5-0.75%',
    range: t('priceDeviationHeatmap.range.medium'),
  },
  {
    color: heatmapColors.deviation.higher,
    label: '0.75-1%',
    range: t('priceDeviationHeatmap.range.higher'),
  },
  {
    color: heatmapColors.deviation.high,
    label: '1-1.5%',
    range: t('priceDeviationHeatmap.range.high'),
  },
  {
    color: heatmapColors.deviation.veryHigh,
    label: '1.5-2%',
    range: t('priceDeviationHeatmap.range.veryHigh'),
  },
  {
    color: heatmapColors.deviation.extremelyHigh,
    label: '2-3%',
    range: t('priceDeviationHeatmap.range.extremelyHigh'),
  },
  {
    color: heatmapColors.deviation.anomaly,
    label: '> 3%',
    range: t('priceDeviationHeatmap.range.anomaly'),
  },
];

export function PriceDeviationHeatmap({
  data,
  timeRange,
  className = '',
  useAccessibleColors = false,
}: PriceDeviationHeatmapProps) {
  const t = useTranslations();
  const colorLegend = useMemo(() => getColorLegend(t), [t]);
  const [hoveredCell, setHoveredCell] = useState<{
    timestamp: number;
    oracleName: string;
    deviation: number;
    price: number;
  } | null>(null);

  const { heatmapData, oracles, timestamps, maxDeviation } = useMemo(() => {
    const filteredData = timeRange
      ? data.filter((d) => d.timestamp >= timeRange.start && d.timestamp <= timeRange.end)
      : data;

    const oracleSet = new Set<string>();
    const timestampSet = new Set<number>();

    filteredData.forEach((d) => {
      oracleSet.add(d.oracleName);
      timestampSet.add(d.timestamp);
    });

    const oracles = Array.from(oracleSet);
    const timestamps = Array.from(timestampSet).sort((a, b) => a - b);

    const heatmapMap = new Map<string, PriceDeviationDataPoint>();
    filteredData.forEach((d) => {
      heatmapMap.set(`${d.oracleName}-${d.timestamp}`, d);
    });

    const maxDev = Math.max(...filteredData.map((d) => Math.abs(d.deviationPercent)), 0.01);

    return {
      heatmapData: heatmapMap,
      oracles,
      timestamps,
      maxDeviation: maxDev,
    };
  }, [data, timeRange]);

  const stats = useMemo(() => {
    const filteredData = timeRange
      ? data.filter((d) => d.timestamp >= timeRange.start && d.timestamp <= timeRange.end)
      : data;

    if (filteredData.length === 0) {
      return {
        avgDeviation: 0,
        maxDeviation: 0,
        minDeviation: 0,
        anomalyCount: 0,
      };
    }

    const deviations = filteredData.map((d) => d.deviationPercent);
    const avgDeviation = deviations.reduce((a, b) => a + b, 0) / deviations.length;
    const maxDeviation = Math.max(...deviations.map(Math.abs));
    const minDeviation = Math.min(...deviations.map(Math.abs));
    const anomalyCount = deviations.filter((d) => Math.abs(d) > 1).length;

    return {
      avgDeviation,
      maxDeviation,
      minDeviation,
      anomalyCount,
    };
  }, [data, timeRange]);

  const getCellData = (oracle: string, timestamp: number) => {
    return heatmapData.get(`${oracle}-${timestamp}`);
  };

  return (
    <DashboardCard
      title={t('priceDeviationHeatmap.title')}
      className={className}
      headerAction={
        <div className="flex items-center gap-4 text-xs text-gray-500">
          <span>
            {t('priceDeviationHeatmap.timePoints')}: {timestamps.length}
          </span>
          <span>
            {t('priceDeviationHeatmap.oracles')}: {oracles.length}
          </span>
        </div>
      }
    >
      <div className="space-y-4">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div className="bg-primary-50  p-3 text-center">
            <p className="text-xs text-primary-600 mb-1">
              {t('priceDeviationHeatmap.avgDeviation')}
            </p>
            <p className="text-xl font-bold text-primary-700">{stats.avgDeviation.toFixed(3)}%</p>
          </div>
          <div className="bg-danger-50  p-3 text-center">
            <p className="text-xs text-danger-600 mb-1">
              {t('priceDeviationHeatmap.maxDeviation')}
            </p>
            <p className="text-xl font-bold text-danger-700">{stats.maxDeviation.toFixed(3)}%</p>
          </div>
          <div className="bg-success-50  p-3 text-center">
            <p className="text-xs text-success-600 mb-1">
              {t('priceDeviationHeatmap.minDeviation')}
            </p>
            <p className="text-xl font-bold text-success-700">{stats.minDeviation.toFixed(3)}%</p>
          </div>
          <div className="bg-warning-50  p-3 text-center">
            <p className="text-xs text-warning-600 mb-1">
              {t('priceDeviationHeatmap.anomalyDataPoints')}
            </p>
            <p className="text-xl font-bold text-warning-700">{stats.anomalyCount}</p>
          </div>
        </div>

        <div className="relative overflow-x-auto">
          <div className="min-w-fit">
            <div className="flex">
              <div className="w-28 flex-shrink-0" />
              <div className="flex-1">
                <div className="flex gap-1 mb-2">
                  {timestamps.map((ts) => (
                    <div key={ts} className="flex-1 min-w-[40px] text-center text-xs text-gray-500">
                      {formatTimestamp(ts)}
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="space-y-1">
              {oracles.map((oracle) => (
                <div key={oracle} className="flex items-center">
                  <div className="w-28 flex-shrink-0 pr-3 flex items-center">
                    <div
                      className="w-3 h-3  mr-2 flex-shrink-0"
                      style={{
                        backgroundColor:
                          (useAccessibleColors
                            ? accessibleOracleColors[oracle]
                            : oracleColors[oracle]) || baseColors.gray[500],
                      }}
                    />
                    <span className="text-sm text-gray-700 truncate">{oracle}</span>
                  </div>
                  <div className="flex-1 flex gap-1">
                    {timestamps.map((ts) => {
                      const cellData = getCellData(oracle, ts);
                      const deviation = cellData?.deviationPercent ?? 0;
                      const hasData = cellData !== undefined;

                      return (
                        <div
                          key={`${oracle}-${ts}`}
                          className={`flex-1 min-w-[40px] aspect-square rounded-md flex items-center justify-center text-xs font-medium cursor-pointer transition-all hover:scale-110 hover:z-10 hover:ring-2 hover:ring-gray-400 ${
                            hasData ? getDeviationTextColor(deviation) : 'bg-gray-100'
                          }`}
                          style={{
                            backgroundColor: hasData
                              ? getDeviationColor(deviation)
                              : heatmapColors.deviation.noData,
                          }}
                          onMouseEnter={() =>
                            hasData &&
                            setHoveredCell({
                              timestamp: ts,
                              oracleName: oracle,
                              deviation,
                              price: cellData.price,
                            })
                          }
                          onMouseLeave={() => setHoveredCell(null)}
                        >
                          {hasData && Math.abs(deviation) < 0.5 ? (
                            <span className="opacity-0">.</span>
                          ) : hasData ? (
                            deviation > 0 ? (
                              '+'
                            ) : (
                              ''
                            )
                          ) : (
                            '-'
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {hoveredCell && (
            <div className="absolute left-1/2 top-0 transform -translate-x-1/2 -translate-y-full mb-2 bg-gray-900 text-white text-xs  px-4 py-3 z-20  min-w-[200px]">
              <div className="font-semibold text-sm mb-2">{hoveredCell.oracleName}</div>
              <div className="space-y-1">
                <div className="flex justify-between">
                  <span className="text-gray-400">{t('priceDeviationHeatmap.time')}:</span>
                  <span>{formatFullTimestamp(hoveredCell.timestamp)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-400">{t('priceDeviationHeatmap.price')}:</span>
                  <span className="font-mono">${hoveredCell.price.toFixed(2)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-400">{t('priceDeviationHeatmap.deviation')}:</span>
                  <span
                    className={`font-mono font-semibold ${
                      Math.abs(hoveredCell.deviation) > 1 ? 'text-red-400' : 'text-green-400'
                    }`}
                  >
                    {hoveredCell.deviation > 0 ? '+' : ''}
                    {hoveredCell.deviation.toFixed(4)}%
                  </span>
                </div>
              </div>
              <div className="absolute bottom-0 left-1/2 transform -translate-x-1/2 translate-y-full">
                <div className="border-8 border-transparent border-t-gray-900" />
              </div>
            </div>
          )}
        </div>

        <div className="bg-gray-50  p-4">
          <div className="text-xs text-gray-600 mb-2 font-medium">
            {t('priceDeviationHeatmap.legend')}
          </div>
          <div className="flex flex-wrap items-center gap-2">
            {colorLegend.map((item) => (
              <div key={item.label} className="flex items-center gap-1">
                <div className="w-4 h-4 rounded" style={{ backgroundColor: item.color }} />
                <span className="text-xs text-gray-600">{item.label}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="bg-gray-50  p-4">
            <h4 className="text-sm font-semibold text-gray-700 mb-3">
              {t('priceDeviationHeatmap.deviationDistribution')}
            </h4>
            <div className="space-y-2">
              {colorLegend.map((item) => {
                const count = Array.from(heatmapData.values()).filter((d) => {
                  const abs = Math.abs(d.deviationPercent);
                  const ranges = [0, 0.1, 0.25, 0.5, 0.75, 1, 1.5, 2, 3];
                  const idx = colorLegend.indexOf(item);
                  return abs >= ranges[idx] && (idx === ranges.length - 1 || abs < ranges[idx + 1]);
                }).length;
                const total = heatmapData.size || 1;
                const percentage = ((count / total) * 100).toFixed(1);

                return (
                  <div key={item.label} className="flex items-center gap-2">
                    <div
                      className="w-3 h-3 rounded flex-shrink-0"
                      style={{ backgroundColor: item.color }}
                    />
                    <div className="flex-1 text-xs text-gray-600">{item.range}</div>
                    <div className="w-24 bg-gray-200  h-2 overflow-hidden">
                      <div
                        className="h-full  transition-all"
                        style={{
                          width: `${percentage}%`,
                          backgroundColor: item.color,
                        }}
                      />
                    </div>
                    <div className="w-16 text-right text-xs text-gray-500">
                      {count} ({percentage}%)
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="bg-gray-50  p-4">
            <h4 className="text-sm font-semibold text-gray-700 mb-3">
              {t('priceDeviationHeatmap.oracleDeviationRanking')}
            </h4>
            <div className="space-y-2">
              {oracles
                .map((oracle) => {
                  const oracleData = Array.from(heatmapData.values()).filter(
                    (d) => d.oracleName === oracle
                  );
                  const avgDev =
                    oracleData.reduce((sum, d) => sum + Math.abs(d.deviationPercent), 0) /
                    (oracleData.length || 1);
                  return { oracle, avgDev };
                })
                .sort((a, b) => b.avgDev - a.avgDev)
                .slice(0, 5)
                .map((item, idx) => (
                  <div key={item.oracle} className="flex items-center gap-2">
                    <span className="w-5 text-xs text-gray-400 font-medium">{idx + 1}</span>
                    <div
                      className="w-3 h-3  flex-shrink-0"
                      style={{
                        backgroundColor:
                          (useAccessibleColors
                            ? accessibleOracleColors[item.oracle]
                            : oracleColors[item.oracle]) || baseColors.gray[500],
                      }}
                    />
                    <span className="flex-1 text-sm text-gray-700 truncate">{item.oracle}</span>
                    <span
                      className={`text-sm font-mono font-medium ${
                        item.avgDev > 1 ? 'text-danger-600' : 'text-success-600'
                      }`}
                    >
                      {item.avgDev.toFixed(4)}%
                    </span>
                  </div>
                ))}
            </div>
          </div>
        </div>

        {stats.anomalyCount > 0 && (
          <div className="bg-danger-50 border border-danger-200  p-4">
            <div className="flex items-start gap-3">
              <svg
                className="w-5 h-5 text-danger-600 flex-shrink-0 mt-0.5"
                fill="currentColor"
                viewBox="0 0 20 20"
              >
                <path
                  fillRule="evenodd"
                  d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z"
                  clipRule="evenodd"
                />
              </svg>
              <div>
                <h4 className="text-sm font-semibold text-danger-800 mb-1">
                  {t('priceDeviationHeatmap.highDeviationDetected')}
                </h4>
                <p className="text-xs text-danger-700">
                  {t('priceDeviationHeatmap.anomalyWarning', { count: stats.anomalyCount })}
                </p>
              </div>
            </div>
          </div>
        )}
      </div>
    </DashboardCard>
  );
}

'use client';

import { useState, useMemo } from 'react';

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  Legend,
  ResponsiveContainer,
  ReferenceLine,
  AreaChart,
  Area,
} from 'recharts';

import { DashboardCard } from '@/components/oracle/data-display/DashboardCard';
import { SegmentedControl, DropdownSelect, MultiSelect } from '@/components/ui';
import { useTranslations } from '@/i18n';
import { chartColors, baseColors, semanticColors, shadowColors } from '@/lib/config/colors';
import { OracleProvider } from '@/types/oracle';

type BaselineType = 'average' | 'median' | 'chainlink';

interface DeviationDataPoint {
  timestamp: number;
  time: string;
  deviations: Record<OracleProvider, number>;
  baseline: number;
}

interface DeviationStats {
  avgDeviation: number;
  maxDeviation: number;
  maxDeviationTime: number;
  maxDeviationProvider: OracleProvider;
  stdDeviation: number;
  trend: 'increasing' | 'decreasing' | 'stable';
}

interface PriceDeviationHistoryChartProps {
  priceHistory: Partial<Record<OracleProvider, number[]>>;
  selectedOracles: OracleProvider[];
  oracleColors: Record<OracleProvider, string>;
  oracleNames: Record<OracleProvider, string>;
  chainlinkPrice?: number;
}

const DEVIATION_THRESHOLDS = {
  warning: 0.5,
  critical: 1.0,
};

function formatTime(index: number, t: (key: string) => string): string {
  const now = new Date();
  now.setMinutes(now.getMinutes() - (19 - index) * 3);
  return now.toLocaleTimeString(t('locale') || 'zh-CN', {
    hour: '2-digit',
    minute: '2-digit',
  });
}

function calculateTrend(data: number[]): 'increasing' | 'decreasing' | 'stable' {
  if (data.length < 5) return 'stable';
  const recent = data.slice(-5);
  const older = data.slice(-10, -5);
  const recentAvg = recent.reduce((a, b) => a + b, 0) / recent.length;
  const olderAvg = older.reduce((a, b) => a + b, 0) / older.length;
  const diff = recentAvg - olderAvg;
  if (Math.abs(diff) < 0.1) return 'stable';
  return diff > 0 ? 'increasing' : 'decreasing';
}

export function PriceDeviationHistoryChart({
  priceHistory,
  selectedOracles,
  oracleColors,
  oracleNames,
  chainlinkPrice,
}: PriceDeviationHistoryChartProps) {
  const t = useTranslations();
  const [baselineType, setBaselineType] = useState<BaselineType>('average');
  const [timeRange, setTimeRange] = useState<'all' | '10' | '5'>('all');

  const deviationHistory = useMemo(() => {
    const maxLength = Math.max(...Object.values(priceHistory).map((arr) => arr.length));
    if (maxLength === 0) return [];

    const data: DeviationDataPoint[] = [];

    for (let i = 0; i < maxLength; i++) {
      const prices: { provider: OracleProvider; price: number }[] = [];

      selectedOracles.forEach((provider) => {
        const history = priceHistory[provider] || [];
        if (history[i] !== undefined) {
          prices.push({ provider, price: history[i] });
        }
      });

      if (prices.length === 0) continue;

      let baseline: number;
      switch (baselineType) {
        case 'average': {
          const sum = prices.reduce((acc, p) => acc + p.price, 0);
          baseline = sum / prices.length;
          break;
        }
        case 'median': {
          const sorted = [...prices].sort((a, b) => a.price - b.price);
          const mid = Math.floor(sorted.length / 2);
          baseline =
            sorted.length % 2 !== 0
              ? sorted[mid].price
              : (sorted[mid - 1].price + sorted[mid].price) / 2;
          break;
        }
        case 'chainlink': {
          const chainlinkData = prices.find((p) => p.provider === OracleProvider.CHAINLINK);
          baseline = chainlinkData?.price || chainlinkPrice || prices[0].price;
          break;
        }
        default:
          baseline = prices.reduce((acc, p) => acc + p.price, 0) / prices.length;
      }

      const deviations: Record<OracleProvider, number> = {} as Record<OracleProvider, number>;
      prices.forEach(({ provider, price }) => {
        deviations[provider] = baseline > 0 ? ((price - baseline) / baseline) * 100 : 0;
      });

      data.push({
        timestamp: Date.now() - (maxLength - 1 - i) * 30000,
        time: formatTime(i, t),
        deviations,
        baseline,
      });
    }

    return data;
  }, [priceHistory, selectedOracles, baselineType, chainlinkPrice]);

  const filteredData = useMemo(() => {
    if (timeRange === 'all') return deviationHistory;
    const count = timeRange === '10' ? 10 : 5;
    return deviationHistory.slice(-count);
  }, [deviationHistory, timeRange]);

  const deviationStats = useMemo((): Record<OracleProvider, DeviationStats> => {
    const stats: Record<OracleProvider, DeviationStats> = {} as Record<
      OracleProvider,
      DeviationStats
    >;

    selectedOracles.forEach((provider) => {
      const deviations = deviationHistory
        .map((d) => d.deviations[provider])
        .filter((v) => v !== undefined);

      if (deviations.length === 0) {
        stats[provider] = {
          avgDeviation: 0,
          maxDeviation: 0,
          maxDeviationTime: 0,
          maxDeviationProvider: provider,
          stdDeviation: 0,
          trend: 'stable',
        };
        return;
      }

      const absDeviations = deviations.map(Math.abs);
      const avgDeviation = absDeviations.reduce((a, b) => a + b, 0) / absDeviations.length;
      const maxAbsDeviation = Math.max(...absDeviations);
      const maxIndex = absDeviations.indexOf(maxAbsDeviation);
      const maxDeviationTime = deviationHistory[maxIndex]?.timestamp || 0;

      const variance =
        deviations.reduce((sum, d) => sum + Math.pow(d - avgDeviation, 2), 0) / deviations.length;
      const stdDeviation = Math.sqrt(variance);

      stats[provider] = {
        avgDeviation,
        maxDeviation: deviations[maxIndex] || 0,
        maxDeviationTime,
        maxDeviationProvider: provider,
        stdDeviation,
        trend: calculateTrend(absDeviations),
      };
    });

    return stats;
  }, [deviationHistory, selectedOracles]);

  const chartData = useMemo(() => {
    return filteredData.map((d) => {
      const point: Record<string, number | string> = {
        time: d.time,
        timestamp: d.timestamp,
      };
      selectedOracles.forEach((provider) => {
        point[provider] = d.deviations[provider];
      });
      return point;
    });
  }, [filteredData, selectedOracles]);

  const getBaselineLabel = (type: BaselineType): string => {
    switch (type) {
      case 'average':
        return t('charts.priceDeviationHistory.baselineAverage');
      case 'median':
        return t('charts.priceDeviationHistory.baselineMedian');
      case 'chainlink':
        return t('charts.priceDeviationHistory.baselineChainlink');
      default:
        return type;
    }
  };

  const getTrendIcon = (trend: 'increasing' | 'decreasing' | 'stable') => {
    switch (trend) {
      case 'increasing':
        return (
          <svg
            className="w-4 h-4 text-danger-500"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" />
          </svg>
        );
      case 'decreasing':
        return (
          <svg
            className="w-4 h-4 text-success-500"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
        );
      default:
        return (
          <svg
            className="w-4 h-4 text-gray-500"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path strokeLinejoin="round" strokeWidth={2} d="M5 12h14" />
          </svg>
        );
    }
  };

  const getTrendLabel = (trend: 'increasing' | 'decreasing' | 'stable'): string => {
    switch (trend) {
      case 'increasing':
        return t('charts.priceDeviationHistory.trendIncreasing');
      case 'decreasing':
        return t('charts.priceDeviationHistory.trendDecreasing');
      default:
        return t('charts.priceDeviationHistory.trendStable');
    }
  };

  const formatMaxDeviationTime = (timestamp: number): string => {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleTimeString(t('locale') || 'zh-CN', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  };

  return (
    <div className="space-y-6">
      <DashboardCard
        title={t('charts.priceDeviationHistory.title')}
        headerAction={
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <label className="text-sm text-gray-600">
                {t('charts.priceDeviationHistory.baseline')}:
              </label>
              <SegmentedControl
                options={[
                  { value: 'average', label: t('charts.priceDeviationHistory.baselineAverage') },
                  { value: 'median', label: t('charts.priceDeviationHistory.baselineMedian') },
                  {
                    value: 'chainlink',
                    label: t('charts.priceDeviationHistory.baselineChainlink'),
                  },
                ]}
                value={baselineType}
                onChange={(value) => setBaselineType(value as BaselineType)}
                size="sm"
              />
            </div>
            <div className="flex items-center gap-2">
              <label className="text-sm text-gray-600">
                {t('charts.priceDeviationHistory.timeRange')}:
              </label>
              <div className="flex gap-1">
                {(['all', '10', '5'] as const).map((range) => (
                  <button
                    key={range}
                    onClick={() => setTimeRange(range)}
                    className={`px-3 py-1 text-sm  transition-colors ${
                      timeRange === range
                        ? 'bg-primary-600 text-white'
                        : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                    }`}
                  >
                    {range === 'all' ? t('charts.priceDeviationHistory.allData') : `${range}`}
                  </button>
                ))}
              </div>
            </div>
          </div>
        }
      >
        <div className="h-80">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={chartColors.recharts.grid} />
              <XAxis
                dataKey="time"
                stroke={chartColors.recharts.axis}
                tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
                minTickGap={30}
              />
              <YAxis
                stroke={chartColors.recharts.axis}
                tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
                tickFormatter={(value) => `${value.toFixed(2)}%`}
                domain={['auto', 'auto']}
              />
              <RechartsTooltip
                formatter={(value, name) => {
                  const numValue = typeof value === 'number' ? value : 0;
                  const strName = typeof name === 'string' ? name : '';
                  const provider = strName as OracleProvider;
                  return [
                    `${numValue >= 0 ? '+' : ''}${numValue.toFixed(4)}%`,
                    oracleNames[provider] || strName,
                  ];
                }}
                labelFormatter={(label) => `${t('charts.priceDeviationHistory.time')}: ${label}`}
                contentStyle={{
                  backgroundColor: baseColors.gray[50],
                  border: `1px solid ${chartColors.recharts.grid}`,
                  boxShadow: shadowColors.tooltip,
                }}
              />
              <Legend
                formatter={(value: string) => oracleNames[value as OracleProvider] || value}
              />
              <ReferenceLine
                y={DEVIATION_THRESHOLDS.warning}
                stroke={chartColors.recharts.warning}
                strokeDasharray="5 5"
                label={{ value: 'Warning', fill: chartColors.recharts.warning, fontSize: 10 }}
              />
              <ReferenceLine
                y={-DEVIATION_THRESHOLDS.warning}
                stroke={chartColors.recharts.warning}
                strokeDasharray="5 5"
              />
              <ReferenceLine
                y={DEVIATION_THRESHOLDS.critical}
                stroke={chartColors.recharts.danger}
                strokeDasharray="5 5"
                label={{ value: 'Critical', fill: chartColors.recharts.danger, fontSize: 10 }}
              />
              <ReferenceLine
                y={-DEVIATION_THRESHOLDS.critical}
                stroke={chartColors.recharts.danger}
                strokeDasharray="5 5"
              />
              <ReferenceLine y={0} stroke={baseColors.gray[500]} strokeWidth={1} />
              {selectedOracles.map((provider) => (
                <Line
                  key={provider}
                  type="monotone"
                  dataKey={provider}
                  stroke={oracleColors[provider]}
                  strokeWidth={2}
                  dot={false}
                  activeDot={{ r: 4 }}
                />
              ))}
            </LineChart>
          </ResponsiveContainer>
        </div>
        <div className="flex items-center justify-center gap-6 mt-4">
          <div className="flex items-center gap-2">
            <div
              className="w-8 h-0.5 bg-warning-500 border-dashed"
              style={{ borderTop: `2px dashed ${chartColors.recharts.warning}` }}
            />
            <span className="text-xs text-gray-600">
              {t('charts.priceDeviationHistory.warningThreshold')} (±0.5%)
            </span>
          </div>
          <div className="flex items-center gap-2">
            <div
              className="w-8 h-0.5 bg-danger-500 border-dashed"
              style={{ borderTop: `2px dashed ${chartColors.recharts.danger}` }}
            />
            <span className="text-xs text-gray-600">
              {t('charts.priceDeviationHistory.criticalThreshold')} (±1.0%)
            </span>
          </div>
        </div>
      </DashboardCard>

      <DashboardCard title={t('charts.priceDeviationHistory.statsPanel')}>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {selectedOracles.map((provider) => {
            const stats = deviationStats[provider];
            return (
              <div key={provider} className="bg-gray-50 border border-gray-200 rounded-lg p-4">
                <div className="flex items-center gap-2 mb-3">
                  <div className="w-3 h-3" style={{ backgroundColor: oracleColors[provider] }} />
                  <span className="font-medium text-gray-900">{oracleNames[provider]}</span>
                </div>
                <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600">
                      {t('charts.priceDeviationHistory.avgDeviation')}
                    </span>
                    <span
                      className={`text-sm font-medium ${
                        stats.avgDeviation >= DEVIATION_THRESHOLDS.critical
                          ? 'text-danger-600'
                          : stats.avgDeviation >= DEVIATION_THRESHOLDS.warning
                            ? 'text-warning-600'
                            : 'text-gray-900'
                      }`}
                    >
                      {stats.avgDeviation.toFixed(4)}%
                    </span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600">
                      {t('charts.priceDeviationHistory.maxDeviation')}
                    </span>
                    <span
                      className={`text-sm font-medium ${
                        Math.abs(stats.maxDeviation) >= DEVIATION_THRESHOLDS.critical
                          ? 'text-danger-600'
                          : Math.abs(stats.maxDeviation) >= DEVIATION_THRESHOLDS.warning
                            ? 'text-warning-600'
                            : 'text-gray-900'
                      }`}
                    >
                      {stats.maxDeviation >= 0 ? '+' : ''}
                      {stats.maxDeviation.toFixed(4)}%
                    </span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600">
                      {t('charts.priceDeviationHistory.maxDeviationTime')}
                    </span>
                    <span className="text-sm text-gray-500">
                      {formatMaxDeviationTime(stats.maxDeviationTime)}
                    </span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600">
                      {t('charts.priceDeviationHistory.stdDeviation')}
                    </span>
                    <span className="text-sm text-gray-900">{stats.stdDeviation.toFixed(4)}%</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600">
                      {t('charts.priceDeviationHistory.trend')}
                    </span>
                    <div className="flex items-center gap-1">
                      {getTrendIcon(stats.trend)}
                      <span
                        className={`text-sm ${
                          stats.trend === 'increasing'
                            ? 'text-danger-600'
                            : stats.trend === 'decreasing'
                              ? 'text-success-600'
                              : 'text-gray-600'
                        }`}
                      >
                        {getTrendLabel(stats.trend)}
                      </span>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </DashboardCard>

      <DashboardCard title={t('charts.priceDeviationHistory.deviationDistribution')}>
        <div className="h-64">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
