'use client';

import { useEffect, useState, useRef, useCallback } from 'react';

import { motion, AnimatePresence, useAnimation } from 'framer-motion';
import { TrendingUp, TrendingDown, Minus, Activity } from 'lucide-react';

import { semanticColors } from '@/lib/config/colors';
import { formatNumber } from '@/lib/utils/format';

export interface RealtimePriceAnimationProps {
  symbol: string;
  currentPrice: number;
  previousPrice: number;
  trend: 'up' | 'down' | 'stable';
  decimals?: number;
  showSparkline?: boolean;
  sparklineData?: number[];
}

function AnimatedDigit({
  digit,
  delay,
  isChanging,
}: {
  digit: string;
  delay: number;
  isChanging: boolean;
}) {
  return (
    <motion.span
      key={digit}
      initial={isChanging ? { y: -20, opacity: 0 } : false}
      animate={{ y: 0, opacity: 1 }}
      transition={{
        duration: 0.3,
        delay: delay * 0.03,
        ease: 'easeOut',
      }}
      className="inline-block tabular-nums"
    >
      {digit}
    </motion.span>
  );
}

function PriceFlash({ trend }: { trend: 'up' | 'down' | 'stable' }) {
  const color = trend === 'up' ? 'bg-emerald-500' : trend === 'down' ? 'bg-red-500' : 'bg-gray-400';

  return (
    <motion.div
      initial={{ opacity: 0.6 }}
      animate={{ opacity: 0 }}
      transition={{ duration: 0.8 }}
      className={`absolute inset-0 ${color} rounded-lg pointer-events-none`}
    />
  );
}

function TrendArrow({
  trend,
  size = 'md',
}: {
  trend: 'up' | 'down' | 'stable';
  size?: 'sm' | 'md' | 'lg';
}) {
  const sizeClasses = {
    sm: 'w-3 h-3',
    md: 'w-5 h-5',
    lg: 'w-7 h-7',
  };

  const colorClasses = {
    up: 'text-emerald-500',
    down: 'text-red-500',
    stable: 'text-gray-400',
  };

  const Icon = trend === 'up' ? TrendingUp : trend === 'down' ? TrendingDown : Minus;

  return (
    <motion.div
      initial={{ scale: 0.5, opacity: 0 }}
      animate={{ scale: 1, opacity: 1 }}
      transition={{ type: 'spring', stiffness: 500, damping: 25 }}
      className={`${sizeClasses[size]} ${colorClasses[trend]}`}
    >
      <Icon className={sizeClasses[size]} />
    </motion.div>
  );
}

function MiniSparkline({ data, trend }: { data: number[]; trend: 'up' | 'down' | 'stable' }) {
  if (data.length < 2) return null;

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;
  const height = 24;
  const width = 80;
  const points = data
    .map((v, i) => {
      const x = (i / (data.length - 1)) * width;
      const y = height - ((v - min) / range) * height;
      return `${x},${y}`;
    })
    .join(' ');

  const color =
    trend === 'up'
      ? semanticColors.success.DEFAULT
      : trend === 'down'
        ? semanticColors.danger.DEFAULT
        : '#9ca3af';

  return (
    <svg width={width} height={height} className="overflow-visible">
      <defs>
        <linearGradient id={`gradient-${trend}`} x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor={color} stopOpacity="0.3" />
          <stop offset="100%" stopColor={color} stopOpacity="0" />
        </linearGradient>
      </defs>
      <motion.polyline
        initial={{ pathLength: 0 }}
        animate={{ pathLength: 1 }}
        transition={{ duration: 0.5 }}
        fill="none"
        stroke={color}
        strokeWidth="2"
        points={points}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <motion.polygon
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.3, delay: 0.3 }}
        fill={`url(#gradient-${trend})`}
        points={`0,${height} ${points} ${width},${height}`}
      />
    </svg>
  );
}

export function RealtimePriceAnimation({
  symbol,
  currentPrice,
  previousPrice,
  trend,
  decimals = 2,
  showSparkline = true,
  sparklineData = [],
}: RealtimePriceAnimationProps) {
  const [displayPrice, setDisplayPrice] = useState(currentPrice);
  const [isAnimating, setIsAnimating] = useState(false);
  const [flashKey, setFlashKey] = useState(0);
  const controls = useAnimation();
  const animationRef = useRef<number | null>(null);

  const priceChange = currentPrice - previousPrice;
  const percentChange = previousPrice !== 0 ? (priceChange / previousPrice) * 100 : 0;

  const animatePriceChange = useCallback(() => {
    if (animationRef.current) {
      cancelAnimationFrame(animationRef.current);
    }

    setIsAnimating(true);
    setFlashKey((k) => k + 1);

    const startPrice = displayPrice;
    const endPrice = currentPrice;
    const duration = 500;
    const startTime = performance.now();

    const animate = (currentTime: number) => {
      const elapsed = currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);

      const easeOutQuart = 1 - Math.pow(1 - progress, 4);
      const currentDisplay = startPrice + (endPrice - startPrice) * easeOutQuart;

      setDisplayPrice(currentDisplay);

      if (progress < 1) {
        animationRef.current = requestAnimationFrame(animate);
      } else {
        setIsAnimating(false);
      }
    };

    animationRef.current = requestAnimationFrame(animate);
  }, [currentPrice, displayPrice]);

  useEffect(() => {
    if (currentPrice !== displayPrice && !isAnimating) {
      animatePriceChange();
    }
  }, [currentPrice, displayPrice, isAnimating, animatePriceChange]);

  useEffect(() => {
    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, []);

  const priceString = displayPrice.toFixed(decimals);
  const digits = priceString.split('');

  const trendColor =
    trend === 'up'
      ? 'text-emerald-500 dark:text-emerald-400'
      : trend === 'down'
        ? 'text-red-500 dark:text-red-400'
        : 'text-gray-500 dark:text-gray-400';

  const bgColor =
    trend === 'up'
      ? 'bg-emerald-50 dark:bg-emerald-900/20'
      : trend === 'down'
        ? 'bg-red-50 dark:bg-red-900/20'
        : 'bg-gray-50 dark:bg-gray-800';

  return (
    <div className="relative">
      <motion.div
        animate={controls}
        className={`relative overflow-hidden rounded-xl p-6 ${bgColor} border border-gray-200 dark:border-gray-700`}
      >
        <AnimatePresence>{isAnimating && <PriceFlash trend={trend} />}</AnimatePresence>

        <div className="relative z-10">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 flex items-center justify-center shadow-sm">
                <span className="text-sm font-bold text-gray-900 dark:text-white">
                  {symbol.slice(0, 2)}
                </span>
              </div>
              <div>
                <p className="text-lg font-semibold text-gray-900 dark:text-white">{symbol}</p>
                <div className="flex items-center gap-1.5">
                  <Activity className="w-3 h-3 text-emerald-500" />
                  <span className="text-xs text-gray-500 dark:text-gray-400">实时更新</span>
                </div>
              </div>
            </div>

            <TrendArrow trend={trend} size="lg" />
          </div>

          <div className="flex items-end justify-between">
            <div>
              <div className="flex items-baseline gap-1">
                <span className="text-sm text-gray-500 dark:text-gray-400 mr-1">$</span>
                <span className={`text-4xl font-bold tabular-nums ${trendColor}`}>
                  {digits.map((digit, index) => (
                    <AnimatedDigit
                      key={`${digit}-${index}`}
                      digit={digit}
                      delay={index}
                      isChanging={isAnimating}
                    />
                  ))}
                </span>
              </div>

              <div className="flex items-center gap-3 mt-2">
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className={`flex items-center gap-1 text-sm font-medium ${trendColor}`}
                >
                  <TrendArrow trend={trend} size="sm" />
                  <span>
                    {priceChange >= 0 ? '+' : ''}
                    {Math.abs(priceChange).toFixed(decimals)}
                  </span>
                </motion.div>
                <span
                  className={`text-sm font-medium px-2 py-0.5 rounded ${
                    trend === 'up'
                      ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400'
                      : trend === 'down'
                        ? 'bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400'
                        : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'
                  }`}
                >
                  {percentChange >= 0 ? '+' : ''}
                  {percentChange.toFixed(2)}%
                </span>
              </div>
            </div>

            {showSparkline && sparklineData.length > 0 && (
              <div className="flex-shrink-0">
                <MiniSparkline data={sparklineData} trend={trend} />
              </div>
            )}
          </div>
        </div>
      </motion.div>

      <AnimatePresence>
        {isAnimating && (
          <motion.div
            initial={{ opacity: 0, scale: 0.8, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.8, y: -20 }}
            className="absolute -bottom-8 left-1/2 -translate-x-1/2 px-3 py-1 bg-gray-900 dark:bg-gray-700 text-white text-xs rounded-full shadow-lg whitespace-nowrap"
          >
            价格更新中...
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export default RealtimePriceAnimation;

'use client';

import { useState, useEffect, useMemo } from 'react';

import {
  AlertTriangle,
  Shield,
  TrendingUp,
  TrendingDown,
  Activity,
  Clock,
  RefreshCw,
  AlertCircle,
  CheckCircle,
  XCircle,
} from 'lucide-react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  ResponsiveContainer,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  Radar,
} from 'recharts';

import { Skeleton } from '@/components/ui';

interface RiskFactor {
  id: string;
  name: string;
  score: number;
  weight: number;
  status: 'good' | 'warning' | 'critical';
  description: string;
  trend: 'up' | 'down' | 'stable';
}

interface RiskScore {
  overall: number;
  timestamp: number;
  factors: RiskFactor[];
}

interface RiskHistoryPoint {
  timestamp: number;
  date: string;
  score: number;
}

interface RiskAlert {
  id: string;
  type: 'warning' | 'critical' | 'info';
  message: string;
  timestamp: number;
  factor?: string;
}

const RISK_THRESHOLDS = {
  low: { min: 0, max: 30, color: '#10b981', label: 'Low Risk' },
  medium: { min: 30, max: 60, color: '#f59e0b', label: 'Medium Risk' },
  high: { min: 60, max: 80, color: '#f97316', label: 'High Risk' },
  critical: { min: 80, max: 100, color: '#ef4444', label: 'Critical Risk' },
};

const DEFAULT_RISK_FACTORS: RiskFactor[] = [
  {
    id: 'data_freshness',
    name: 'Data Freshness',
    score: 15,
    weight: 0.2,
    status: 'good',
    description: 'Time since last price update',
    trend: 'stable',
  },
  {
    id: 'source_diversity',
    name: 'Source Diversity',
    score: 25,
    weight: 0.15,
    status: 'warning',
    description: 'Number of independent data sources',
    trend: 'up',
  },
  {
    id: 'price_deviation',
    name: 'Price Deviation',
    score: 10,
    weight: 0.25,
    status: 'good',
    description: 'Deviation from median price across sources',
    trend: 'down',
  },
  {
    id: 'liquidity_depth',
    name: 'Liquidity Depth',
    score: 35,
    weight: 0.15,
    status: 'warning',
    description: 'Available liquidity for price feeds',
    trend: 'stable',
  },
  {
    id: 'network_health',
    name: 'Network Health',
    score: 20,
    weight: 0.15,
    status: 'good',
    description: 'Overall network and node health',
    trend: 'down',
  },
  {
    id: 'manipulation_risk',
    name: 'Manipulation Risk',
    score: 12,
    weight: 0.1,
    status: 'good',
    description: 'Risk of price manipulation attacks',
    trend: 'stable',
  },
];

interface RiskAssessmentDashboardProps {
  symbol?: string;
  refreshInterval?: number;
  onAlert?: (alert: RiskAlert) => void;
}

export function RiskAssessmentDashboard({
  symbol = 'DIA',
  refreshInterval = 60000,
  onAlert,
}: RiskAssessmentDashboardProps) {
  const [riskScore, setRiskScore] = useState<RiskScore | null>(null);
  const [riskHistory, setRiskHistory] = useState<RiskHistoryPoint[]>([]);
  const [alerts, setAlerts] = useState<RiskAlert[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const calculateOverallRisk = (factors: RiskFactor[]): number => {
    return factors.reduce((total, factor) => total + factor.score * factor.weight, 0);
  };

  const generateMockHistory = (): RiskHistoryPoint[] => {
    const history: RiskHistoryPoint[] = [];
    const now = Date.now();
    const baseScore = 20;

    for (let i = 24; i >= 0; i--) {
      const timestamp = now - i * 60 * 60 * 1000;
      const variation = (Math.random() - 0.5) * 15;
      const trend = Math.sin(i / 6) * 5;

      history.push({
        timestamp,
        date: new Date(timestamp).toLocaleTimeString('en-US', {
          hour: '2-digit',
          minute: '2-digit',
        }),
        score: Math.max(0, Math.min(100, baseScore + variation + trend)),
      });
    }

    return history;
  };

  const generateRiskFactors = (): RiskFactor[] => {
    return DEFAULT_RISK_FACTORS.map((factor) => {
      const variation = (Math.random() - 0.5) * 10;
      const newScore = Math.max(0, Math.min(100, factor.score + variation));

      let status: RiskFactor['status'] = 'good';
      if (newScore > 60) status = 'critical';
      else if (newScore > 30) status = 'warning';

      const trends: RiskFactor['trend'][] = ['up', 'down', 'stable'];
      const trend = trends[Math.floor(Math.random() * 3)];

      return {
        ...factor,
        score: newScore,
        status,
        trend,
      };
    });
  };

  const checkForAlerts = (factors: RiskFactor[], overallScore: number): RiskAlert[] => {
    const newAlerts: RiskAlert[] = [];
    const now = Date.now();

    factors.forEach((factor) => {
      if (factor.status === 'critical') {
        newAlerts.push({
          id: `${factor.id}-${now}`,
          type: 'critical',
          message: `${factor.name} has reached critical risk level (${factor.score.toFixed(1)})`,
          timestamp: now,
          factor: factor.id,
        });
      } else if (factor.status === 'warning' && factor.trend === 'up') {
        newAlerts.push({
          id: `${factor.id}-${now}`,
          type: 'warning',
          message: `${factor.name} is trending upward (${factor.score.toFixed(1)})`,
          timestamp: now,
          factor: factor.id,
        });
      }
    });

    if (overallScore > 60) {
      newAlerts.push({
        id: `overall-${now}`,
        type: 'critical',
        message: `Overall risk score is high (${overallScore.toFixed(1)})`,
        timestamp: now,
      });
    }

    return newAlerts;
  };

  const fetchData = async () => {
    setIsRefreshing(true);

    try {
      await new Promise((resolve) => setTimeout(resolve, 500));

      const factors = generateRiskFactors();
      const overall = calculateOverallRisk(factors);
      const newAlerts = checkForAlerts(factors, overall);

      setRiskScore({
        overall,
        timestamp: Date.now(),
        factors,
      });

      setRiskHistory((prev) => {
        const newHistory = [
          ...prev.slice(-23),
          {
            timestamp: Date.now(),
            date: new Date().toLocaleTimeString('en-US', {
              hour: '2-digit',
              minute: '2-digit',
            }),
            score: overall,
          },
        ];
        return newHistory.length > 0 ? newHistory : generateMockHistory();
      });

      if (newAlerts.length > 0) {
        setAlerts((prev) => [...newAlerts, ...prev].slice(0, 10));
        newAlerts.forEach((alert) => onAlert?.(alert));
      }
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    setRiskHistory(generateMockHistory());
    fetchData();

    const interval = setInterval(fetchData, refreshInterval);
    return () => clearInterval(interval);
  }, [refreshInterval]);

  const riskLevel = useMemo(() => {
    if (!riskScore) return RISK_THRESHOLDS.low;

    const score = riskScore.overall;
    if (score >= RISK_THRESHOLDS.critical.min) return RISK_THRESHOLDS.critical;
    if (score >= RISK_THRESHOLDS.high.min) return RISK_THRESHOLDS.high;
    if (score >= RISK_THRESHOLDS.medium.min) return RISK_THRESHOLDS.medium;
    return RISK_THRESHOLDS.low;
  }, [riskScore]);

  const radarData = useMemo(() => {
    if (!riskScore) return [];
    return riskScore.factors.map((factor) => ({
      factor: factor.name,
      score: factor.score,
      fullMark: 100,
    }));
  }, [riskScore]);

  const getStatusIcon = (status: RiskFactor['status']) => {
    switch (status) {
      case 'good':
        return <CheckCircle className="w-4 h-4 text-emerald-500" />;
      case 'warning':
        return <AlertTriangle className="w-4 h-4 text-amber-500" />;
      case 'critical':
        return <XCircle className="w-4 h-4 text-red-500" />;
    }
  };

  const getTrendIcon = (trend: RiskFactor['trend']) => {
    switch (trend) {
      case 'up':
        return <TrendingUp className="w-3 h-3 text-red-500" />;
      case 'down':
        return <TrendingDown className="w-3 h-3 text-emerald-500" />;
      case 'stable':
        return <Activity className="w-3 h-3 text-gray-400" />;
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <Skeleton className="h-6 w-48" />
          <Skeleton className="h-8 w-24" />
        </div>
        <div className="grid grid-cols-2 gap-4">
          <Skeleton className="h-48" />
          <Skeleton className="h-48" />
        </div>
      </div>
    );
  }

  if (!riskScore) return null;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
