'use client';

import { useMemo } from 'react';

import GaugeChart from '@/components/GaugeChart';
import { type AccuracyStats } from '@/hooks';
import { useTranslations } from '@/i18n';
import { semanticColors } from '@/lib/config/colors';

interface PriceAccuracyStatsProps {
  stats: AccuracyStats;
  recentTrend: 'improving' | 'stable' | 'declining';
}

export function PriceAccuracyStats({ stats, recentTrend }: PriceAccuracyStatsProps) {
  const t = useTranslations();

  const trendData = useMemo(() => {
    switch (recentTrend) {
      case 'improving':
        return {
          icon: (
            <svg
              className="w-5 h-5 text-success-500"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
            </svg>
          ),
          text: t('pyth.accuracy.trendImproving'),
          color: 'text-success-500',
        };
      case 'declining':
        return {
          icon: (
            <svg
              className="w-5 h-5 text-danger-500"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path strokeLinejoin="round" strokeWidth={2} d="M13 17h8m0 0V9m0 8l-8-8-4 4-6-6" />
            </svg>
          ),
          text: t('pyth.accuracy.trendDeclining'),
          color: 'text-danger-500',
        };
      default:
        return {
          icon: (
            <svg
              className="w-5 h-5 text-primary-500"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path strokeLinejoin="round" strokeWidth={2} d="M5 12h14" />
            </svg>
          ),
          text: t('pyth.accuracy.trendStable'),
          color: 'text-primary-500',
        };
    }
  }, [recentTrend, t]);

  const conditionCards = useMemo(
    () => [
      {
        title: t('pyth.accuracy.normalMarket'),
        accuracy: stats.normalAccuracy,
        color: 'bg-success-50 border-green-200',
        textColor: 'text-success-600',
        icon: (
          <svg
            className="w-5 h-5 text-success-500"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinejoin="round"
              strokeWidth={2}
              d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
            />
          </svg>
        ),
      },
      {
        title: t('pyth.accuracy.volatileMarket'),
        accuracy: stats.volatileAccuracy,
        color: 'bg-warning-50 border-yellow-200',
        textColor: 'text-warning-600',
        icon: (
          <svg
            className="w-5 h-5 text-warning-500"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
          </svg>
        ),
      },
      {
        title: t('pyth.accuracy.extremeMarket'),
        accuracy: stats.extremeAccuracy,
        color: 'bg-danger-50 border-danger-200',
        textColor: 'text-danger-600',
        icon: (
          <svg
            className="w-5 h-5 text-danger-500"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinejoin="round"
              strokeWidth={2}
              d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
            />
          </svg>
        ),
      },
    ],
    [stats, t]
  );

  return (
    <div className="bg-white  border border-gray-200 p-6">
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-semibold text-gray-900">{t('pyth.accuracy.title')}</h3>
        <div className="flex items-center gap-2">
          {trendData.icon}
          <span className={`text-sm font-medium ${trendData.color}`}>{trendData.text}</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="flex flex-col items-center justify-center p-6 bg-gray-50 ">
          <GaugeChart
            value={stats.overallAccuracy}
            maxValue={100}
            label={t('pyth.accuracy.overallScore')}
            size={180}
          />
          <div className="mt-4 text-center">
            <p className="text-sm text-gray-500">
              {t('pyth.accuracy.basedOn')} {stats.totalDataPoints} {t('pyth.accuracy.dataPoints')}
            </p>
          </div>
        </div>

        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="p-4 bg-gray-50 ">
              <p className="text-sm text-gray-600 mb-1">{t('pyth.accuracy.avgDeviation')}</p>
              <p className="text-xl font-bold text-gray-900">{stats.avgDeviation}%</p>
            </div>
            <div className="p-4 bg-gray-50 ">
              <p className="text-sm text-gray-600 mb-1">{t('pyth.accuracy.maxDeviation')}</p>
              <p className="text-xl font-bold text-warning-600">{stats.maxDeviation}%</p>
            </div>
          </div>

          <div className="space-y-3">
            {conditionCards.map((card, index) => (
              <div key={index} className={`p-4  border ${card.color} transition-all hover:`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    {card.icon}
                    <span className="text-sm font-medium text-gray-700">{card.title}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="w-24 h-2 bg-gray-200  overflow-hidden">
                      <div
                        className="h-full bg-current  transition-all duration-500"
                        style={{ width: `${card.accuracy}%` }}
                      />
                    </div>
                    <span className={`text-sm font-bold ${card.textColor}`}>
                      {card.accuracy.toFixed(1)}%
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="mt-6 pt-6 border-t border-gray-200">
        <h4 className="text-sm font-medium text-gray-700 mb-3">{t('pyth.accuracy.last7Days')}</h4>
        <div className="grid grid-cols-7 gap-2">
          {Array.from({ length: 7 }).map((_, i) => {
            const accuracy = 95 + Math.random() * 4;
            const day = new Date();
            day.setDate(day.getDate() - (6 - i));
            const dayName = day.toLocaleDateString('zh-CN', { weekday: 'short' });

            return (
              <div key={i} className="text-center">
                <div className="text-xs text-gray-500 mb-1">{dayName}</div>
                <div
                  className="h-16 rounded relative overflow-hidden"
                  style={{
                    background: `linear-gradient(to top, ${semanticColors.success.DEFAULT}${Math.round(accuracy)}, ${semanticColors.success.DEFAULT}${Math.round(accuracy / 2)})`,
                  }}
                >
                  <div className="absolute bottom-0 left-0 right-0 text-xs font-bold text-white p-1">
                    {accuracy.toFixed(0)}%
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useMemo } from 'react';

import { useTranslations } from '@/i18n';
import { chartColors, semanticColors } from '@/lib/config/colors';
import { type Publisher, type PublisherStats } from '@/types/oracle';

interface PublisherReliabilityScoreProps {
  publisher: Publisher;
  stats?: PublisherStats;
}

const mockStats: Record<string, PublisherStats> = {
  'pub-1': {
    publisherId: 'pub-1',
    historicalAccuracy: [98.5, 99.1, 99.3, 99.0, 99.2, 99.4, 99.2],
    priceDeviations: [0.02, 0.01, 0.03, 0.02, 0.01, 0.02, 0.02],
    submissionFrequency: 98.7,
    averageDeviation: 0.019,
    trend: 'improving',
  },
  'pub-2': {
    publisherId: 'pub-2',
    historicalAccuracy: [96.2, 96.8, 97.1, 96.9, 97.5, 97.8, 97.8],
    priceDeviations: [0.06, 0.05, 0.04, 0.05, 0.05, 0.04, 0.05],
    submissionFrequency: 95.2,
    averageDeviation: 0.049,
    trend: 'stable',
  },
  'pub-3': {
    publisherId: 'pub-3',
    historicalAccuracy: [99.0, 99.2, 99.3, 99.4, 99.5, 99.5, 99.5],
    priceDeviations: [0.02, 0.01, 0.01, 0.01, 0.01, 0.01, 0.01],
    submissionFrequency: 99.1,
    averageDeviation: 0.011,
    trend: 'improving',
  },
  'pub-4': {
    publisherId: 'pub-4',
    historicalAccuracy: [95.5, 95.2, 94.8, 94.5, 94.2, 94.8, 95.1],
    priceDeviations: [0.07, 0.08, 0.09, 0.08, 0.08, 0.07, 0.08],
    submissionFrequency: 92.3,
    averageDeviation: 0.079,
    trend: 'declining',
  },
  'pub-5': {
    publisherId: 'pub-5',
    historicalAccuracy: [97.0, 97.2, 97.4, 97.5, 97.6, 97.8, 98.1],
    priceDeviations: [0.04, 0.03, 0.03, 0.03, 0.03, 0.03, 0.03],
    submissionFrequency: 96.8,
    averageDeviation: 0.032,
    trend: 'improving',
  },
};

function TrendIndicator({
  trend,
  t,
}: {
  trend: 'improving' | 'stable' | 'declining';
  t: (key: string) => string;
}) {
  const config = {
    improving: {
      icon: '↑',
      color: 'text-success-600',
      bg: 'bg-success-50',
      label: t('publisherReliability.trend.improving'),
    },
    stable: {
      icon: '→',
      color: 'text-primary-600',
      bg: 'bg-primary-50',
      label: t('publisherReliability.trend.stable'),
    },
    declining: {
      icon: '↓',
      color: 'text-danger-600',
      bg: 'bg-danger-50',
      label: t('publisherReliability.trend.declining'),
    },
  };

  const { icon, color, bg, label } = config[trend];

  return (
    <span
      className={`inline-flex items-center gap-1 px-2 py-0.5  text-xs font-medium ${bg} ${color}`}
    >
      <span>{icon}</span>
      <span>{label}</span>
    </span>
  );
}

function MiniChart({ data, color = 'blue' }: { data: number[]; color?: string }) {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;

  const points = data.map((value, index) => {
    const x = (index / (data.length - 1)) * 100;
    const y = 100 - ((value - min) / range) * 100;
    return `${x},${y}`;
  });

  const colorClass =
    color === 'green'
      ? chartColors.semantic.success
      : color === 'red'
        ? chartColors.semantic.danger
        : chartColors.recharts.primary;

  return (
    <svg className="w-full h-12" viewBox="0 0 100 100" preserveAspectRatio="none">
      <polyline fill="none" stroke={colorClass} strokeWidth="2" points={points.join(' ')} />
    </svg>
  );
}

function AccuracyBar({ accuracy }: { accuracy: number }) {
  return (
    <div className="w-full bg-gray-100  h-2 overflow-hidden">
      <div
        className={`h-full  transition-all duration-500 ${
          accuracy >= 98 ? 'bg-success-500' : accuracy >= 95 ? 'bg-primary-500' : 'bg-warning-500'
        }`}
        style={{ width: `${accuracy}%` }}
      />
    </div>
  );
}

export function PublisherReliabilityScore({
  publisher,
  stats = mockStats[publisher.id] || mockStats['pub-1'],
}: PublisherReliabilityScoreProps) {
  const t = useTranslations();

  const avgAccuracy = useMemo(() => {
    if (stats.historicalAccuracy.length === 0) return 0;
    return stats.historicalAccuracy.reduce((a, b) => a + b, 0) / stats.historicalAccuracy.length;
  }, [stats.historicalAccuracy]);

  const deviationColor = useMemo(() => {
    if (stats.averageDeviation <= 0.02) return 'text-success-600';
    if (stats.averageDeviation <= 0.05) return 'text-primary-600';
    return 'text-warning-600';
  }, [stats.averageDeviation]);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h4 className="font-semibold text-gray-900">
          {publisher.name} {t('publisherReliability.statistics')}
        </h4>
        <TrendIndicator trend={stats.trend} t={t} />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-gray-50  p-4">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm text-gray-600">
              {t('publisherReliability.historicalAccuracy')}
            </span>
            <span className="text-lg font-bold text-gray-900">{avgAccuracy.toFixed(1)}%</span>
          </div>
          <AccuracyBar accuracy={avgAccuracy} />
          <div className="mt-3">
            <MiniChart data={stats.historicalAccuracy} color="green" />
          </div>
          <p className="text-xs text-gray-500 mt-1">{t('publisherReliability.last7Periods')}</p>
        </div>

        <div className="bg-gray-50  p-4">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm text-gray-600">
              {t('publisherReliability.priceDeviation')}
            </span>
            <span className={`text-lg font-bold ${deviationColor}`}>
              {stats.averageDeviation.toFixed(3)}%
            </span>
          </div>
          <div className="mt-2">
            <MiniChart data={stats.priceDeviations} color="blue" />
          </div>
          <p className="text-xs text-gray-500 mt-1">
            {t('publisherReliability.deviationFromMedian')}
          </p>
        </div>
      </div>

      <div className="bg-gray-50  p-4">
        <div className="flex items-center justify-between mb-3">
          <span className="text-sm font-medium text-gray-700">
            {t('publisherReliability.submissionFrequency')}
          </span>
          <span className="text-lg font-bold text-gray-900">{stats.submissionFrequency}%</span>
        </div>
        <div className="w-full bg-gray-200  h-3 overflow-hidden">
          <div
            className={`h-full  transition-all duration-500 ${
              stats.submissionFrequency >= 98
                ? 'bg-success-500'
                : stats.submissionFrequency >= 95
                  ? 'bg-primary-500'
                  : 'bg-warning-500'
            }`}
            style={{ width: `${stats.submissionFrequency}%` }}
          />
        </div>
        <div className="flex justify-between mt-2 text-xs text-gray-500">
          <span>0%</span>
          <span>{t('publisherReliability.target99')}</span>
          <span>100%</span>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-3">
        <div className="text-center p-3 bg-white border border-gray-200 ">
          <p className="text-2xl font-bold text-gray-900">
            {publisher.accuracy?.toFixed(1) ?? '-'}%
          </p>
          <p className="text-xs text-gray-500 mt-1">{t('publisherReliability.currentAccuracy')}</p>
        </div>
        <div className="text-center p-3 bg-white border border-gray-200 ">
          <p className="text-2xl font-bold text-gray-900">{publisher.latency}ms</p>
          <p className="text-xs text-gray-500 mt-1">{t('publisherReliability.avgLatency')}</p>
        </div>
        <div className="text-center p-3 bg-white border border-gray-200 ">
          <p className="text-2xl font-bold text-gray-900">
            {publisher.priceDeviation ? `${publisher.priceDeviation.toFixed(2)}%` : '-'}
          </p>
          <p className="text-xs text-gray-500 mt-1">{t('publisherReliability.priceDeviation')}</p>
        </div>
      </div>

      <div className="border-t border-gray-200 pt-4">
        <h5 className="text-sm font-medium text-gray-700 mb-3">
          {t('publisherReliability.recentActivity')}
        </h5>
        <div className="space-y-2">
          {stats.historicalAccuracy.slice(-5).map((acc, index) => (
            <div key={index} className="flex items-center justify-between text-sm">
              <span className="text-gray-500">
                {t('publisherReliability.period')} {index + 1}
              </span>
              <div className="flex items-center gap-4">
                <span className="text-gray-900">
                  {acc.toFixed(1)}% {t('publisherReliability.accuracy')}
                </span>
                <span className="text-gray-500">
                  {stats.priceDeviations[index]?.toFixed(3) ?? '-'}% {t('publisherReliability.dev')}
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';

import {
  Clock,
  Heart,
