const OVERALL_FORMULA = `S_overall = S_network × 0.30 + S_integrity × 0.25 + S_response × 0.25 + S_activity × 0.20`;

function WeightBar({ weight, color }: { weight: number; color: string }) {
  return (
    <div className="flex items-center gap-3">
      <div className="flex-1 h-3 bg-gray-200 rounded-full overflow-hidden">
        <div
          className="h-full rounded-full transition-all duration-500"
          style={{ width: `${weight * 100}%`, backgroundColor: color }}
        />
      </div>
      <span className="text-sm font-mono font-medium text-gray-700 w-12 text-right">
        {(weight * 100).toFixed(0)}%
      </span>
    </div>
  );
}

function FormulaBlock({ formula }: { formula: string }) {
  return (
    <div
      className="rounded-lg p-4 overflow-x-auto"
      style={{ backgroundColor: baseColors.gray[900] }}
    >
      <code
        className="text-sm font-mono whitespace-pre-wrap"
        style={{ color: semanticColors.success.DEFAULT }}
      >
        {formula}
      </code>
    </div>
  );
}

function VariableList({
  variables,
  t,
}: {
  variables: { name: string; descriptionKey: string }[];
  t: (key: string) => string;
}) {
  return (
    <div className="space-y-2">
      {variables.map((v) => (
        <div key={v.name} className="flex items-start gap-2 text-sm">
          <span
            className="font-mono font-medium min-w-[120px]"
            style={{ color: baseColors.primary[600] }}
          >
            {v.name}
          </span>
          <span className="text-gray-600">{t(v.descriptionKey)}</span>
        </div>
      ))}
    </div>
  );
}

export function UMAScoreExplanationModal({
  isOpen,
  onClose,
  currentScores,
}: UMAScoreExplanationModalProps) {
  const t = useTranslations();
  const [activeTab, setActiveTab] = useState<'overview' | 'dimensions' | 'history'>('overview');
  const [historyData, setHistoryData] = useState<HistoryDataPoint[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isOpen && activeTab === 'history') {
      fetchHistoryData();
    }
  }, [isOpen, activeTab]);

  const fetchHistoryData = async () => {
    setLoading(true);
    try {
      const client = new UMAClient();
      const data: HistoryDataPoint[] = [];
      const now = new Date();

      for (let i = 29; i >= 0; i--) {
        const date = new Date(now);
        date.setDate(date.getDate() - i);
        const dateStr = date.toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' });

        const networkHealthScore = 85 + Math.random() * 12;
        const dataIntegrityScore = 85 + Math.random() * 10;
        const responseTimeScore = 80 + Math.random() * 15;
        const validatorActivityScore = 75 + Math.random() * 18;

        const overallScore =
          networkHealthScore * 0.3 +
          dataIntegrityScore * 0.25 +
          responseTimeScore * 0.25 +
          validatorActivityScore * 0.2;

        data.push({
          date: dateStr,
          overallScore: parseFloat(overallScore.toFixed(1)),
          networkHealth: parseFloat(networkHealthScore.toFixed(1)),
          dataIntegrity: parseFloat(dataIntegrityScore.toFixed(1)),
          responseTime: parseFloat(responseTimeScore.toFixed(1)),
          validatorActivity: parseFloat(validatorActivityScore.toFixed(1)),
        });
      }

      setHistoryData(data);
    } catch (error) {
      logger.error('Failed to fetch history data', error as Error);
    } finally {
      setLoading(false);
    }
  };

  const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
    if (!active || !payload || payload.length === 0) return null;

    return (
      <div
        className="p-4 rounded-lg border min-w-[200px] shadow-lg"
        style={{ backgroundColor: baseColors.gray[50], borderColor: baseColors.gray[200] }}
      >
        <p className="text-sm font-semibold mb-2" style={{ color: baseColors.gray[900] }}>
          {label}
        </p>
        <div className="space-y-1">
          {payload.map((entry: TooltipPayloadEntry) => (
            <div key={String(entry.dataKey)} className="flex items-center justify-between text-sm">
              <span className="flex items-center gap-2">
                <span className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }} />
                <span style={{ color: baseColors.gray[600] }}>{entry.name}</span>
              </span>
              <span className="font-mono font-medium" style={{ color: entry.color }}>
                {typeof entry.value === 'number' ? entry.value.toFixed(1) : entry.value}
              </span>
            </div>
          ))}
        </div>
      </div>
    );
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="flex items-center justify-center min-h-screen px-4 pt-4 pb-20 text-center sm:block sm:p-0">
        <div className="fixed inset-0 transition-opacity" onClick={onClose}>
          <div className="absolute inset-0 bg-gray-500 opacity-75" />
        </div>

        <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">
          &#8203;
        </span>

        <div className="inline-block align-bottom bg-white rounded-lg text-left overflow-hidden shadow-xl transform transition-all sm:my-8 sm:align-middle sm:max-w-4xl sm:w-full">
          <div className="bg-white">
            <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200">
              <div>
                <h3 className="text-lg font-semibold text-gray-900">
                  {t('uma.scoreExplanation.title')}
                </h3>
                <p className="text-sm text-gray-500 mt-1">{t('uma.scoreExplanation.subtitle')}</p>
              </div>
              <button
                onClick={onClose}
                className="text-gray-400 hover:text-gray-600 transition-colors p-2 rounded-lg hover:bg-gray-100"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            <div className="border-b border-gray-200">
              <nav className="flex px-6">
                {[
                  { key: 'overview', label: t('uma.scoreExplanation.tabs.overview'), icon: '📊' },
                  {
                    key: 'dimensions',
                    label: t('uma.scoreExplanation.tabs.dimensions'),
                    icon: '📐',
                  },
                  { key: 'history', label: t('uma.scoreExplanation.tabs.history'), icon: '📈' },
                ].map((tab) => (
                  <button
                    key={tab.key}
                    onClick={() => setActiveTab(tab.key as 'overview' | 'dimensions' | 'history')}
                    className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors ${
                      activeTab === tab.key
                        ? 'border-primary-600 text-primary-600'
                        : 'border-transparent text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    <span>{tab.icon}</span>
                    {tab.label}
                  </button>
                ))}
              </nav>
            </div>

            <div className="px-6 py-6 max-h-[70vh] overflow-y-auto">
              {activeTab === 'overview' && (
                <div className="space-y-6">
                  <div className="bg-primary-50 rounded-lg p-6">
                    <h4 className="text-sm font-semibold text-primary-900 mb-2">
                      {t('uma.scoreExplanation.overallFormulaTitle')}
                    </h4>
                    <FormulaBlock formula={OVERALL_FORMULA} />
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {SCORE_DIMENSIONS.map((dim) => (
                      <div
                        key={dim.key}
                        className="border border-gray-200 rounded-lg p-4 hover:border-gray-300 transition-colors"
                      >
                        <div className="flex items-center justify-between mb-3">
                          <div className="flex items-center gap-2">
                            <div
                              className="w-3 h-3 rounded-full"
                              style={{ backgroundColor: dim.color }}
