                            <p className="text-xs text-gray-500 mb-1">{t(dim.nameKey)}</p>
                            <p className="text-2xl font-bold" style={{ color: dim.color }}>
                              {score.score.toFixed(1)}
                            </p>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              )}

              {activeTab === 'dimensions' && (
                <div className="space-y-6">
                  {SCORE_DIMENSIONS.map((dim) => (
                    <div
                      key={dim.key}
                      className="border border-gray-200 rounded-lg p-6 hover:border-gray-300 transition-colors"
                    >
                      <div className="flex items-center gap-3 mb-4">
                        <div
                          className="w-4 h-4 rounded-full"
                          style={{ backgroundColor: dim.color }}
                        />
                        <h4 className="text-lg font-semibold text-gray-900">{t(dim.nameKey)}</h4>
                        <span className="px-2 py-1 bg-gray-100 rounded text-xs font-mono text-gray-600">
                          {t('uma.scoreExplanation.weight')} {(dim.weight * 100).toFixed(0)}%
                        </span>
                      </div>

                      <p className="text-gray-600 mb-4">{t(dim.descriptionKey)}</p>

                      <div className="space-y-4">
                        <div>
                          <h5 className="text-sm font-medium text-gray-700 mb-2">
                            {t('uma.scoreExplanation.formula')}
                          </h5>
                          <FormulaBlock formula={dim.formula} />
                        </div>

                        <div>
                          <h5 className="text-sm font-medium text-gray-700 mb-2">
                            {t('uma.scoreExplanation.variables')}
                          </h5>
                          <VariableList variables={dim.variables} t={t} />
                        </div>
                      </div>
                    </div>
                  ))}

                  <div className="bg-amber-50 rounded-lg p-6 border border-amber-200">
                    <h4 className="text-sm font-semibold text-amber-900 mb-2">
                      {t('uma.scoreExplanation.scoreLevelTitle')}
                    </h4>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4">
                      <div className="flex items-center gap-2">
                        <div className="w-4 h-4 rounded bg-success-500" />
                        <div>
                          <p className="text-sm font-medium text-gray-900">
                            {t('uma.scoreExplanation.scoreLevels.excellent')}
                          </p>
                          <p className="text-xs text-gray-500">
                            90-100 {t('uma.scoreExplanation.points')}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <div className="w-4 h-4 rounded bg-warning-500" />
                        <div>
                          <p className="text-sm font-medium text-gray-900">
                            {t('uma.scoreExplanation.scoreLevels.good')}
                          </p>
                          <p className="text-xs text-gray-500">
                            70-89 {t('uma.scoreExplanation.points')}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <div className="w-4 h-4 rounded bg-warning-500" />
                        <div>
                          <p className="text-sm font-medium text-gray-900">
                            {t('uma.scoreExplanation.scoreLevels.pass')}
                          </p>
                          <p className="text-xs text-gray-500">
                            60-69 {t('uma.scoreExplanation.points')}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <div className="w-4 h-4 rounded bg-danger-500" />
                        <div>
                          <p className="text-sm font-medium text-gray-900">
                            {t('uma.scoreExplanation.scoreLevels.needsImprovement')}
                          </p>
                          <p className="text-xs text-gray-500">
                            &lt;60 {t('uma.scoreExplanation.points')}
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {activeTab === 'history' && (
                <div className="space-y-6">
                  {loading ? (
                    <div className="flex items-center justify-center h-64">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-600" />
                    </div>
                  ) : (
                    <>
                      <div className="bg-gray-50 rounded-lg p-4">
                        <h4 className="text-sm font-semibold text-gray-900 mb-4">
                          {t('uma.scoreExplanation.last30DaysTrend')}
                        </h4>
                        <div style={{ height: 350 }}>
                          <ResponsiveContainer width="100%" height="100%">
                            <LineChart
                              data={historyData}
                              margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
                            >
                              <CartesianGrid
                                strokeDasharray="3 3"
                                stroke={chartColors.recharts.grid}
                              />
                              <XAxis
                                dataKey="date"
                                stroke={chartColors.recharts.axis}
                                tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
