                    </thead>
                    <tbody className="divide-y divide-gray-100">
                      {previewData.map((row, i) => (
                        <tr key={i}>
                          {selectedFields.map((field) => (
                            <td
                              key={field.key}
                              className="px-3 py-2 text-gray-700 whitespace-nowrap"
