                </div>
                {scheduledExports.length === 0 ? (
                  <div className="text-xs text-gray-500 text-center py-2">
                    {t('api3.export.noScheduled') || 'No scheduled exports'}
                  </div>
                ) : (
                  <div className="space-y-2">
                    {scheduledExports.map((schedule) => (
