  signalPeriod?: number;
  height?: number;
  showSignals?: boolean;
}

function formatTime(timestamp: number): string {
  const date = new Date(timestamp);
  return `${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;
}

export function MACDIndicator({
  data,
  fastPeriod = 12,
  slowPeriod = 26,
  signalPeriod = 9,
  height = 200,
  showSignals = true,
}: MACDIndicatorProps) {
  const macdData = useMemo<MACDDataPoint[]>(() => {
    if (data.length === 0) return [];

    const { dif, dea, macd, signals } = calculateMACDExtended(
      data,
      fastPeriod,
      slowPeriod,
      signalPeriod
    );

    return data.map((point, index) => {
      const signal = signals[index];
      return {
        time: formatTime(point.timestamp),
        timestamp: point.timestamp,
        dif: dif[index],
        dea: dea[index],
        macd: macd[index],
        signal: signal,
        signalX: signal ? index : undefined,
        signalY: signal ? dif[index] : undefined,
        signalType: signal || undefined,
      };
    });
  }, [data, fastPeriod, slowPeriod, signalPeriod]);

  const currentData =
    macdData.length > 0 ? macdData[macdData.length - 1] : { dif: 0, dea: 0, macd: 0 };
  const lastSignal = (() => {
    for (let i = macdData.length - 1; i >= 0; i--) {
      if (macdData[i].signal) {
        return { type: macdData[i].signal, index: i };
      }
    }
    return null;
  })();

  const goldenCrossCount = macdData.filter((d) => d.signal === 'golden').length;
  const deathCrossCount = macdData.filter((d) => d.signal === 'death').length;

  const headerContent = (
    <div className="flex items-center justify-between w-full">
      <div>
        <span className="text-sm font-medium text-gray-700">MACD 指数平滑异同平均线</span>
        <span className="ml-2 text-xs text-gray-400">
          ({fastPeriod},{slowPeriod},{signalPeriod})
        </span>
        <div className="flex items-center gap-4 text-xs text-gray-500 mt-1">
          <span className="flex items-center gap-1">
            <span className="w-2 h-2  bg-primary-500" />
            DIF
          </span>
          <span className="flex items-center gap-1">
            <span className="w-2 h-2  bg-warning-500" />
            DEA
          </span>
          <span className="flex items-center gap-1">
            <span className="w-2 h-2  bg-gray-400" />
            MACD
          </span>
        </div>
      </div>
      <div className="flex items-center gap-2">
        <span className="text-xs text-gray-500">DIF:</span>
        <span
          className={`text-sm font-bold ${currentData.dif > 0 ? 'text-danger-500' : 'text-success-500'}`}
        >
          {currentData.dif > 0 ? '+' : ''}
          {currentData.dif.toFixed(4)}
        </span>
        <span className="text-xs text-gray-500 ml-2">DEA:</span>
        <span
          className={`text-sm font-bold ${currentData.dea > 0 ? 'text-danger-500' : 'text-success-500'}`}
        >
          {currentData.dea > 0 ? '+' : ''}
          {currentData.dea.toFixed(4)}
        </span>
        {lastSignal?.type === 'golden' && (
          <span className="px-2 py-0.5 text-xs bg-danger-100 text-danger-700 rounded">金叉</span>
        )}
        {lastSignal?.type === 'death' && (
          <span className="px-2 py-0.5 text-xs bg-success-100 text-success-700 rounded">死叉</span>
        )}
      </div>
    </div>
  );

  return (
    <DashboardCard title="" headerAction={headerContent}>
      <div style={{ height: `${height}px` }}>
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart data={macdData} margin={{ top: 10, right: 10, left: 0, bottom: 10 }}>
            <CartesianGrid strokeDasharray="3 3" stroke={chartColors.recharts.grid} opacity={0.5} />
            <XAxis
              dataKey="time"
              tick={{ fontSize: 10, fill: chartColors.recharts.tick }}
              tickLine={false}
              axisLine={{ stroke: chartColors.recharts.grid }}
              minTickGap={30}
            />
            <YAxis
              tick={{ fontSize: 10, fill: chartColors.recharts.tick }}
              tickLine={false}
              axisLine={{ stroke: chartColors.recharts.grid }}
            />
            <RechartsTooltip
              content={({ active, payload, label }) => {
                if (!active || !payload || payload.length === 0) return null;
                const data = payload[0].payload as MACDDataPoint;
                return (
                  <div className="bg-white border border-gray-200  p-2 ">
                    <p className="text-xs text-gray-500 mb-1">{label}</p>
                    <div className="space-y-1">
                      <p
                        className={`text-sm font-bold ${data.dif > 0 ? 'text-danger-600' : 'text-success-600'}`}
                      >
                        DIF: {data.dif > 0 ? '+' : ''}
                        {data.dif.toFixed(4)}
                      </p>
                      <p
                        className={`text-sm font-bold ${data.dea > 0 ? 'text-danger-600' : 'text-success-600'}`}
                      >
                        DEA: {data.dea > 0 ? '+' : ''}
                        {data.dea.toFixed(4)}
                      </p>
                      <p
                        className={`text-sm font-bold ${data.macd > 0 ? 'text-danger-600' : 'text-success-600'}`}
                      >
                        MACD: {data.macd > 0 ? '+' : ''}
                        {data.macd.toFixed(4)}
                      </p>
                      {data.signal === 'golden' && (
                        <p className="text-xs text-danger-500 mt-1">金叉信号</p>
                      )}
                      {data.signal === 'death' && (
                        <p className="text-xs text-success-500 mt-1">死叉信号</p>
                      )}
                    </div>
                  </div>
                );
              }}
            />
            <ReferenceLine y={0} stroke={chartColors.macd.zeroLine} strokeDasharray="3 3" />
            <Bar
              dataKey="macd"
              fill={chartColors.recharts.tick}
              opacity={0.6}
              shape={(props: {
                x?: number;
                y?: number;
                width?: number;
                height?: number;
                payload?: MACDDataPoint;
              }) => {
                const { x = 0, y = 0, width = 0, height = 0, payload } = props;
                const isPositive = (payload?.macd || 0) >= 0;
                return (
                  <rect
                    x={x}
                    y={isPositive ? y : y + height}
                    width={width}
                    height={Math.abs(height)}
                    fill={
                      isPositive
                        ? chartColors.macd.histogram.positive
                        : chartColors.macd.histogram.negative
                    }
                    opacity={0.6}
                  />
                );
              }}
            />
            <Line
              type="monotone"
              dataKey="dif"
              stroke={chartColors.macd.line}
              strokeWidth={1.5}
              dot={false}
              activeDot={{ r: 3, fill: chartColors.macd.line }}
            />
            <Line
              type="monotone"
              dataKey="dea"
              stroke={chartColors.macd.signal}
              strokeWidth={1.5}
              dot={false}
              activeDot={{ r: 3, fill: chartColors.macd.signal }}
            />
            {showSignals && (
              <>
                <Scatter
                  dataKey="signalY"
                  fill={chartColors.semantic.danger}
                  shape={(props: { cx?: number; cy?: number; payload?: MACDDataPoint }) => {
                    const { cx = 0, cy = 0, payload } = props;
                    if (payload?.signalType === 'golden') {
                      return (
                        <g>
                          <circle
                            cx={cx}
                            cy={cy}
                            r={6}
                            fill={chartColors.semantic.danger}
                            stroke={chartColors.recharts.white}
                            strokeWidth={2}
                          />
                          <text
                            x={cx}
                            y={cy - 10}
                            textAnchor="middle"
                            fill={chartColors.semantic.danger}
                            fontSize={10}
                          >
                            金叉
                          </text>
                        </g>
                      );
                    }
                    return null;
                  }}
                />
                <Scatter
                  dataKey="signalY"
                  fill={chartColors.semantic.success}
                  shape={(props: { cx?: number; cy?: number; payload?: MACDDataPoint }) => {
                    const { cx = 0, cy = 0, payload } = props;
                    if (payload?.signalType === 'death') {
                      return (
                        <g>
                          <circle
                            cx={cx}
                            cy={cy}
                            r={6}
                            fill={chartColors.semantic.success}
                            stroke={chartColors.recharts.white}
                            strokeWidth={2}
                          />
                          <text
                            x={cx}
                            y={cy - 10}
                            textAnchor="middle"
                            fill={chartColors.semantic.success}
                            fontSize={10}
                          >
                            死叉
                          </text>
                        </g>
                      );
                    }
                    return null;
                  }}
                />
              </>
            )}
          </ComposedChart>
        </ResponsiveContainer>
      </div>
      <div className="flex items-center justify-between mt-2 text-xs text-gray-500">
        <div className="flex items-center gap-4">
          <span className="flex items-center gap-1">
            <span className="w-3 h-3 bg-red-400 rounded" />
            红柱 (+)
          </span>
          <span className="flex items-center gap-1">
            <span className="w-3 h-3 bg-green-400 rounded" />
            绿柱 (-)
          </span>
        </div>
        <div className="flex items-center gap-4">
          <span className="text-danger-600">金叉: {goldenCrossCount}</span>
          <span className="text-success-600">死叉: {deathCrossCount}</span>
        </div>
      </div>
    </DashboardCard>
  );
}

