'use client';

import { useState, useEffect } from 'react';

import { Layers, Link2, Wallet, BarChart3, Zap, Globe, Database, Shield } from 'lucide-react';

import { DashboardCard, MetricCard } from '@/components/oracle/data-display/DashboardCard';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui';
import { useTranslations } from '@/i18n';
import { chartColors, getChartColor } from '@/lib/chartColors';
import { type BandProtocolClient } from '@/lib/oracles/bandProtocol';

interface CosmosEcosystemPanelProps {
  client: BandProtocolClient;
}

interface IBCChain {
  name: string;
  chainId: string;
  channelId: string;
  status: 'active' | 'inactive';
  tvl: number;
  volume24h: number;
}

export function CosmosEcosystemPanel({ client }: CosmosEcosystemPanelProps) {
  const t = useTranslations();
  const [ibcChains, setIbcChains] = useState<IBCChain[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const mockIBCChains: IBCChain[] = [
      {
        name: 'Cosmos Hub',
        chainId: 'cosmoshub-4',
        channelId: 'channel-0',
        status: 'active',
        tvl: 2500000000,
        volume24h: 150000000,
      },
      {
        name: 'Osmosis',
        chainId: 'osmosis-1',
        channelId: 'channel-1',
        status: 'active',
        tvl: 1800000000,
        volume24h: 280000000,
      },
      {
        name: 'Juno',
