export function CrossChainPanel({
  client,
  autoUpdate = true,
  updateInterval = 60000,
}: CrossChainPanelProps) {
  const t = useTranslations();
  const [stats, setStats] = useState<CrossChainStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [timeRange, setTimeRange] = useState<TimeRangeKey>('24h');
  const [selectedChain, setSelectedChain] = useState<ChainDataRequest | null>(null);
  const [selectedChainsForComparison, setSelectedChainsForComparison] = useState<
    ChainDataRequest[]
  >([]);
  const abortControllerRef = useRef<AbortController | null>(null);

  const TIME_RANGE_CONFIG: Record<TimeRangeKey, { label: string; field: keyof ChainDataRequest }> =
    {
      '24h': { label: t('crossChainPanel.timeRange24h'), field: 'requestCount24h' },
      '7d': { label: t('crossChainPanel.timeRange7d'), field: 'requestCount7d' },
      '30d': { label: t('crossChainPanel.timeRange30d'), field: 'requestCount30d' },
    };

  const fetchData = useCallback(async () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    const abortController = new AbortController();
    abortControllerRef.current = abortController;

    setLoading(true);
    setError(null);

    try {
      const data = await client.getCrossChainStats();
      if (!abortController.signal.aborted) {
        setStats(data);
      }
    } catch (err) {
      if (err instanceof Error && err.name === 'AbortError') return;
      setError(err instanceof Error ? err.message : t('crossChainPanel.fetchCrossChainDataFailed'));
    } finally {
      if (!abortController.signal.aborted) {
        setLoading(false);
      }
    }
  }, [client]);

  useEffect(() => {
    fetchData();

    let interval: NodeJS.Timeout | null = null;
    if (autoUpdate) {
      interval = setInterval(fetchData, updateInterval);
    }

    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
      if (interval) {
        clearInterval(interval);
      }
    };
  }, [fetchData, autoUpdate, updateInterval]);

  const chartData =
    stats?.chains.map((chain: ChainDataRequest, index) => ({
      name: chain.chainName,
      value: chain[TIME_RANGE_CONFIG[timeRange].field as keyof ChainDataRequest] as number,
      color: getChainColor(chain.chainName, index),
    })) || [];

  const totalRequests = stats
    ? (stats[
        `totalRequests${timeRange === '24h' ? '24h' : timeRange === '7d' ? '7d' : '30d'}` as keyof CrossChainStats
      ] as number)
    : 0;

  const toggleChainSelection = useCallback((chain: ChainDataRequest, e?: React.MouseEvent) => {
    if (e) {
      e.stopPropagation();
    }
    setSelectedChainsForComparison((prev) => {
      const isSelected = prev.some((c) => c.chainId === chain.chainId);
      if (isSelected) {
        return prev.filter((c) => c.chainId !== chain.chainId);
      } else if (prev.length < 5) {
        return [...prev, chain];
      }
      return prev;
    });
  }, []);

  if (loading && !stats) {
    return (
      <div className="h-64 flex items-center justify-center">
        <div className="flex items-center gap-3 text-gray-400">
          <svg className="animate-spin h-6 w-6" fill="none" viewBox="0 0 24 24">
            <circle
              className="opacity-25"
              cx="12"
              cy="12"
              r="10"
              stroke="currentColor"
              strokeWidth="4"
            />
            <path
              className="opacity-75"
              fill="currentColor"
              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
            />
          </svg>
          <span className="text-sm">{t('crossChainPanel.loadingCrossChainData')}</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="h-64 flex items-center justify-center">
        <div className="text-center">
          <svg
            className="w-12 h-12 text-red-400 mx-auto mb-3"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinejoin="round"
              strokeWidth={1.5}
              d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
            />
          </svg>
          <p className="text-gray-500 text-sm">{error}</p>
          <button
            onClick={fetchData}
            className="mt-3 px-4 py-2 bg-primary-500 text-white text-sm rounded-lg hover:bg-primary-600 transition-colors"
          >
            {t('crossChainPanel.retry')}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-bold text-gray-900">
            {t('crossChainPanel.crossChainRequestStats')}
          </h2>
          <p className="text-gray-500 text-sm mt-0.5">
            {t('crossChainPanel.bandProtocolDistribution')}
          </p>
        </div>
        <div className="flex items-center gap-3">
          <DataExportButton
            data={(stats?.chains || []) as unknown as ExportDataRow[]}
            filename="band_cross_chain_stats"
            columns={[
              { key: 'chainName', label: 'Chain' },
              { key: 'chainId', label: 'Chain ID' },
              { key: 'requestCount24h', label: '24h Requests' },
              { key: 'requestCount7d', label: '7d Requests' },
              { key: 'requestCount30d', label: '30d Requests' },
              { key: 'avgGasCost', label: 'Avg Gas Cost' },
            ]}
            compact
          />
          <div className="flex items-center gap-2 bg-gray-100 rounded-lg p-1">
            {(Object.keys(TIME_RANGE_CONFIG) as TimeRangeKey[]).map((key) => (
              <button
                key={key}
                onClick={() => setTimeRange(key)}
                className={`px-3 py-1.5 text-sm font-medium rounded-md transition-colors ${
                  timeRange === key
                    ? 'bg-white text-gray-900 shadow-sm'
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                {TIME_RANGE_CONFIG[key].label}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <StatCard
          title={t('crossChainPanel.totalRequests24h')}
          value={stats?.totalRequests24h || 0}
          trend={5.2}
          t={t}
          icon={
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinejoin="round" strokeWidth={1.5} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
            </svg>
          }
        />
        <StatCard
          title={t('crossChainPanel.totalRequests7d')}
          value={stats?.totalRequests7d || 0}
          trend={3.8}
          t={t}
          icon={
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path
                strokeLinejoin="round"
                strokeWidth={1.5}
                d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"
              />
            </svg>
          }
        />
        <StatCard
          title={t('crossChainPanel.totalRequests30d')}
          value={stats?.totalRequests30d || 0}
          trend={8.5}
          t={t}
          icon={
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path
                strokeLinejoin="round"
                strokeWidth={1.5}
                d="M7 12l3-3 3 3 4-4M8 21l4-4 4 4M3 4h18M4 4h16v12a1 1 0 01-1 1H5a1 1 0 01-1-1V4z"
              />
            </svg>
          }
        />
      </div>

      <CrossChainTrendChart
        client={client}
        chains={stats?.chains.map((c) => c.chainName) || []}
        defaultMetric="requests"
        defaultTimeRange="7d"
        height={350}
      />

      <RequestTrendChart client={client} autoUpdate={autoUpdate} updateInterval={updateInterval} />

      <RequestTypeDistribution />

      <div className="bg-white border border-gray-200 rounded-lg p-5">
        <div className="flex items-center justify-between mb-4">
          <div>
            <p className="text-gray-900 text-sm font-semibold">
              {t('crossChainPanel.chainRequestDistribution')}
            </p>
            <p className="text-gray-500 text-xs mt-0.5">
              {TIME_RANGE_CONFIG[timeRange].label}
              {t('crossChainPanel.totalRequests')}: {totalRequests.toLocaleString()}
            </p>
          </div>
          <div className="text-xs text-gray-400">{t('crossChainPanel.clickBarForDetails')}</div>
        </div>

        <div className="h-64">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 40 }}>
              <CartesianGrid
                strokeDasharray="3 3"
                stroke={chartColors.recharts.grid}
                strokeOpacity={0.5}
                vertical={false}
              />
              <XAxis
                dataKey="name"
                stroke={chartColors.recharts.axis}
                tick={{ fontSize: 10, fill: chartColors.recharts.tick }}
                tickLine={false}
                axisLine={{ stroke: chartColors.recharts.grid, strokeOpacity: 0.5 }}
                angle={-35}
                textAnchor="end"
                height={60}
              />
              <YAxis
                stroke={chartColors.recharts.axis}
                tick={{ fontSize: 11, fill: chartColors.recharts.tick }}
                tickLine={false}
                axisLine={{ stroke: chartColors.recharts.grid, strokeOpacity: 0.5 }}
                tickFormatter={(value) => formatNumber(value)}
                width={50}
              />
              <RechartsTooltip
                content={<CustomTooltip t={t} />}
                cursor={{ fill: animationColors.fade.cursor }}
              />
              <Bar
                dataKey="value"
                onClick={(data) => {
                  const chain = stats?.chains.find((c) => c.chainName === data.name);
                  if (chain) setSelectedChain(chain);
                }}
                className="cursor-pointer"
              >
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-white border border-gray-200 rounded-lg p-5">
        <div className="flex items-center justify-between mb-4">
          <p className="text-gray-900 text-sm font-semibold">
            {t('crossChainPanel.chainOverview')}
          </p>
          <p className="text-xs text-gray-500">
            {t('crossChainPanel.chainsSelectedForComparison', {
              count: selectedChainsForComparison.length,
            })}
          </p>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
          {stats?.chains.map((chain, index) => {
            const isSelected = selectedChainsForComparison.some((c) => c.chainId === chain.chainId);
            const isDisabled = !isSelected && selectedChainsForComparison.length >= 5;

            return (
              <div
                key={chain.chainId}
                onClick={() => setSelectedChain(chain)}
                className={`bg-gray-50 rounded-lg p-3 hover:bg-gray-100 transition-colors cursor-pointer group relative ${
                  isSelected ? 'ring-2 ring-primary-500 ring-offset-1' : ''
                } ${isDisabled ? 'opacity-60' : ''}`}
              >
                <div className="absolute top-2 right-2">
                  <label
                    className={`flex items-center justify-center w-5 h-5 rounded border-2 transition-all cursor-pointer ${
                      isSelected
                        ? 'bg-primary-500 border-primary-500'
                        : isDisabled
                          ? 'border-gray-200 bg-gray-100 cursor-not-allowed'
                          : 'border-gray-300 hover:border-primary-400'
                    }`}
                    onClick={(e) => e.stopPropagation()}
                  >
                    <input
                      type="checkbox"
                      checked={isSelected}
                      disabled={isDisabled}
                      onChange={(e) =>
                        toggleChainSelection(chain, e as unknown as React.MouseEvent)
                      }
                      className="sr-only"
                    />
                    {isSelected && (
                      <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20">
                        <path
                          fillRule="evenodd"
                          d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
                          clipRule="evenodd"
                        />
                      </svg>
                    )}
                  </label>
                </div>
                <div className="flex items-center gap-2 mb-2 pr-6">
                  <div
                    className="w-2.5 h-2.5 rounded-full"
                    style={{ backgroundColor: getChainColor(chain.chainName, index) }}
                  />
                  <span className="text-gray-900 font-medium text-sm">{chain.chainName}</span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span className="text-gray-500">{t('crossChainPanel.gas')}</span>
                  <span className="text-gray-700 font-mono">{chain.avgGasCost.toFixed(4)}</span>
                </div>
                <div className="flex items-center justify-between text-xs mt-1">
                  <span className="text-gray-500">{t('crossChainPanel.tokens')}</span>
                  <span className="text-gray-700">
                    {chain.supportedSymbols.slice(0, 3).join(', ')}
                    {chain.supportedSymbols.length > 3 ? '...' : ''}
                  </span>
                </div>
                <div className="flex items-center justify-between text-xs mt-1">
                  <span className="text-gray-500">{t('crossChainPanel.requestsLabel')}</span>
                  <span className="text-gray-700 font-medium">
                    {chain[
                      TIME_RANGE_CONFIG[timeRange].field as keyof ChainDataRequest
                    ].toLocaleString()}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {selectedChain && (
        <ChainDetailModal chain={selectedChain} onClose={() => setSelectedChain(null)} t={t} />
      )}

      {stats && (
        <ChainComparison
          chains={stats.chains}
          selectedChains={selectedChainsForComparison}
          onSelectionChange={setSelectedChainsForComparison}
        />
      )}
    </div>
  );
}

export type { CrossChainPanelProps, ChainDataRequest, CrossChainStats };

'use client';

import { useState } from 'react';

import { DashboardCard } from '@/components/oracle';
import { useTranslations } from '@/i18n';
import { type CustomFeed, type DataSourceTransparency } from '@/lib/oracles/dia';
import { type Blockchain } from '@/types/oracle/enums';

interface DIADataFeedsPanelProps {
  feeds: CustomFeed[];
  dataSources: DataSourceTransparency[];
}

type AssetType = 'all' | 'crypto' | 'fiat' | 'nft' | 'commodity';

export function DIADataFeedsPanel({ feeds, dataSources }: DIADataFeedsPanelProps) {
  const t = useTranslations();
  const [selectedAssetType, setSelectedAssetType] = useState<AssetType>('all');
  const [selectedChain, setSelectedChain] = useState<Blockchain | 'all'>('all');
  const [expandedFeed, setExpandedFeed] = useState<string | null>(null);

  const totalFeeds = feeds.length;
  const activeFeeds = feeds.filter((f) => f.status === 'active').length;
  const cryptoCount = feeds.filter((f) => f.assetType === 'crypto').length;
  const fiatCount = feeds.filter((f) => f.assetType === 'fiat').length;
  const nftCount = feeds.filter((f) => f.assetType === 'nft').length;
  const commodityCount = feeds.filter((f) => f.assetType === 'commodity').length;

  const allChains = Array.from(new Set(feeds.flatMap((f) => f.chains)));

  const filteredFeeds = feeds.filter((feed) => {
    const matchesAssetType = selectedAssetType === 'all' || feed.assetType === selectedAssetType;
    const matchesChain = selectedChain === 'all' || feed.chains.includes(selectedChain);
    return matchesAssetType && matchesChain;
  });

  const getAssetTypeLabel = (type: string) => {
    switch (type) {
      case 'crypto':
        return t('dia.dataFeeds.assetType.crypto');
      case 'fiat':
        return t('dia.dataFeeds.assetType.fiat');
      case 'nft':
        return t('dia.dataFeeds.assetType.nft');
      case 'commodity':
        return t('dia.dataFeeds.assetType.commodity');
      default:
        return type;
    }
  };

  const getAssetTypeBadgeColor = (type: string) => {
    switch (type) {
      case 'crypto':
        return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case 'fiat':
        return 'bg-primary-100 text-primary-700 border-primary-200';
      case 'nft':
        return 'bg-purple-100 text-purple-700 border-purple-200';
      case 'commodity':
        return 'bg-amber-100 text-amber-700 border-amber-200';
      default:
        return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'bg-success-500';
      case 'paused':
        return 'bg-warning-500';
      case 'deprecated':
        return 'bg-gray-400';
      default:
        return 'bg-gray-400';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case 'active':
        return t('dia.dataFeeds.status.active');
      case 'paused':
        return t('dia.dataFeeds.status.paused');
      case 'deprecated':
        return t('dia.dataFeeds.status.deprecated');
      default:
        return status;
    }
  };

  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 0.98) return 'text-success-600';
    if (confidence >= 0.95) return 'text-indigo-600';
    if (confidence >= 0.9) return 'text-warning-600';
    return 'text-warning-600';
  };

  const getConfidenceBgColor = (confidence: number) => {
    if (confidence >= 0.98) return 'bg-success-50';
    if (confidence >= 0.95) return 'bg-indigo-50';
    if (confidence >= 0.9) return 'bg-warning-50';
    return 'bg-warning-50';
  };

  const formatUpdateFrequency = (seconds: number) => {
    if (seconds < 60) return `${seconds}s`;
    if (seconds < 3600) return `${Math.floor(seconds / 60)}m`;
    return `${Math.floor(seconds / 3600)}h`;
  };

  const formatDate = (timestamp: number) => {
    return new Date(timestamp).toLocaleDateString();
  };

  const getDataSourceName = (sourceId: string) => {
    const source = dataSources.find((s) => s.sourceId === sourceId);
    return source ? source.name : sourceId;
  };

  const toggleExpand = (feedId: string) => {
    setExpandedFeed(expandedFeed === feedId ? null : feedId);
  };

  return (
    <div className="space-y-6">
      {/* Summary Stats */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
        <DashboardCard className="p-4">
          <p className="text-sm text-gray-600 mb-1">{t('dia.dataFeeds.totalFeeds')}</p>
          <p className="text-2xl font-bold text-indigo-600">{totalFeeds}</p>
        </DashboardCard>
        <DashboardCard className="p-4">
          <p className="text-sm text-gray-600 mb-1">{t('dia.dataFeeds.activeFeeds')}</p>
          <p className="text-2xl font-bold text-success-600">{activeFeeds}</p>
        </DashboardCard>
        <DashboardCard className="p-4">
          <p className="text-sm text-gray-600 mb-1">{t('dia.dataFeeds.crypto')}</p>
          <p className="text-2xl font-bold text-indigo-600">{cryptoCount}</p>
        </DashboardCard>
        <DashboardCard className="p-4">
          <p className="text-sm text-gray-600 mb-1">{t('dia.dataFeeds.fiat')}</p>
          <p className="text-2xl font-bold text-primary-600">{fiatCount}</p>
        </DashboardCard>
        <DashboardCard className="p-4">
          <p className="text-sm text-gray-600 mb-1">{t('dia.dataFeeds.nft')}</p>
          <p className="text-2xl font-bold text-purple-600">{nftCount}</p>
        </DashboardCard>
        <DashboardCard className="p-4">
          <p className="text-sm text-gray-600 mb-1">{t('dia.dataFeeds.commodity')}</p>
          <p className="text-2xl font-bold text-amber-600">{commodityCount}</p>
        </DashboardCard>
      </div>

      {/* Filters */}
      <DashboardCard className="p-6">
        {/* Asset Type Filters */}
        <div className="mb-4">
          <p className="text-sm font-medium text-gray-700 mb-2">
            {t('dia.dataFeeds.filterByAssetType')}
          </p>
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setSelectedAssetType('all')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                selectedAssetType === 'all'
                  ? 'bg-indigo-600 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              {t('dia.dataFeeds.all')}
            </button>
            <button
              onClick={() => setSelectedAssetType('crypto')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                selectedAssetType === 'crypto'
                  ? 'bg-indigo-600 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              {t('dia.dataFeeds.assetType.crypto')}
            </button>
            <button
              onClick={() => setSelectedAssetType('fiat')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                selectedAssetType === 'fiat'
                  ? 'bg-indigo-600 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              {t('dia.dataFeeds.assetType.fiat')}
            </button>
            <button
              onClick={() => setSelectedAssetType('nft')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                selectedAssetType === 'nft'
                  ? 'bg-indigo-600 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              {t('dia.dataFeeds.assetType.nft')}
            </button>
            <button
              onClick={() => setSelectedAssetType('commodity')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                selectedAssetType === 'commodity'
                  ? 'bg-indigo-600 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              {t('dia.dataFeeds.assetType.commodity')}
            </button>
          </div>
        </div>

        {/* Chain Filters */}
        <div>
          <p className="text-sm font-medium text-gray-700 mb-2">
            {t('dia.dataFeeds.filterByChain')}
          </p>
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setSelectedChain('all')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                selectedChain === 'all'
                  ? 'bg-indigo-600 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              {t('dia.dataFeeds.allChains')}
            </button>
            {allChains.map((chain) => (
              <button
                key={chain}
                onClick={() => setSelectedChain(chain)}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                  selectedChain === chain
                    ? 'bg-indigo-600 text-white'
                    : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                }`}
              >
                {chain}
              </button>
            ))}
          </div>
        </div>
      </DashboardCard>

      {/* Feeds List */}
      <DashboardCard>
        <div className="p-6 border-b border-gray-200">
          <h3 className="text-lg font-semibold text-gray-900">{t('dia.dataFeeds.title')}</h3>
          <p className="text-sm text-gray-600 mt-1">
            {t('dia.dataFeeds.showingCount', { count: filteredFeeds.length, total: feeds.length })}
          </p>
        </div>

        <div className="divide-y divide-gray-200">
          {filteredFeeds.map((feed) => (
            <div key={feed.feedId} className="p-6 hover:bg-gray-50 transition-colors">
              <div
                className="flex items-center justify-between cursor-pointer"
                onClick={() => toggleExpand(feed.feedId)}
              >
                <div className="flex items-center gap-4">
                  <div className="flex-shrink-0">
                    <span
                      className={`w-3 h-3 rounded-full inline-block ${getStatusColor(feed.status)}`}
                    />
                  </div>
                  <div>
                    <h4 className="font-semibold text-gray-900">{feed.name}</h4>
                    <p className="text-sm text-gray-500">{feed.feedId}</p>
                  </div>
                </div>

                <div className="flex items-center gap-6">
                  <span
                    className={`px-3 py-1 rounded-full text-xs font-medium border ${getAssetTypeBadgeColor(
                      feed.assetType
                    )}`}
                  >
                    {getAssetTypeLabel(feed.assetType)}
                  </span>

                  <div className="hidden md:flex items-center gap-2">
                    {feed.chains.slice(0, 3).map((chain) => (
                      <span
                        key={chain}
                        className="px-2 py-1 bg-gray-100 text-gray-700 text-xs rounded-md"
                      >
                        {chain}
                      </span>
                    ))}
                    {feed.chains.length > 3 && (
                      <span className="px-2 py-1 bg-gray-100 text-gray-700 text-xs rounded-md">
                        +{feed.chains.length - 3}
                      </span>
                    )}
                  </div>

                  <div className="text-sm text-gray-600">
                    <span className="text-gray-500">{t('dia.dataFeeds.updateFrequency')}:</span>{' '}
                    {formatUpdateFrequency(feed.updateFrequency)}
                  </div>

                  <div className={`px-3 py-1 rounded-lg ${getConfidenceBgColor(feed.confidence)}`}>
                    <span className={`font-semibold ${getConfidenceColor(feed.confidence)}`}>
                      {(feed.confidence * 100).toFixed(0)}%
                    </span>
                  </div>

                  <span className="text-sm text-gray-700">{getStatusLabel(feed.status)}</span>

                  <svg
                    className={`w-5 h-5 text-gray-400 transition-transform ${
                      expandedFeed === feed.feedId ? 'rotate-180' : ''
                    }`}
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M19 9l-7 7-7-7"
                    />
                  </svg>
                </div>
              </div>

              {/* Expanded Details */}
              {expandedFeed === feed.feedId && (
                <div className="mt-4 pt-4 border-t border-gray-200">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <h5 className="text-sm font-medium text-gray-700 mb-2">
                        {t('dia.dataFeeds.description')}
                      </h5>
                      <p className="text-sm text-gray-600">{feed.description}</p>
                    </div>

                    <div>
                      <h5 className="text-sm font-medium text-gray-700 mb-2">
                        {t('dia.dataFeeds.createdAt')}
                      </h5>
                      <p className="text-sm text-gray-600">{formatDate(feed.createdAt)}</p>
                    </div>

                    <div>
                      <h5 className="text-sm font-medium text-gray-700 mb-2">
                        {t('dia.dataFeeds.dataSources')}
                      </h5>
                      <div className="flex flex-wrap gap-2">
                        {feed.dataSources.map((source) => (
                          <span
                            key={source}
                            className="px-3 py-1 bg-indigo-50 text-indigo-700 text-sm rounded-lg"
                          >
                            {source}
                          </span>
                        ))}
                      </div>
                    </div>

                    <div>
                      <h5 className="text-sm font-medium text-gray-700 mb-2">
                        {t('dia.dataFeeds.supportedChains')}
                      </h5>
                      <div className="flex flex-wrap gap-2">
                        {feed.chains.map((chain) => (
                          <span
                            key={chain}
                            className="px-3 py-1 bg-gray-100 text-gray-700 text-sm rounded-lg"
                          >
                            {chain}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>

        {filteredFeeds.length === 0 && (
          <div className="p-12 text-center">
            <p className="text-gray-500">{t('dia.dataFeeds.noFeeds')}</p>
          </div>
        )}
      </DashboardCard>
    </div>
  );
}

