'use client';

import { useState, useMemo, useEffect } from 'react';

import { useTranslations } from '@/i18n';
import { chartColors } from '@/lib/config/colors';
import { type Publisher } from '@/types/oracle';

export interface DataQualityScorePanelProps {
  symbol?: string;
  className?: string;
}

export interface QualityDimension {
  name: string;
  score: number;
  weight: number;
  description: string;
  trend: 'up' | 'down' | 'stable';
  details: string;
}

export interface HistoricalScore {
  timestamp: number;
  score: number;
}

export interface QualityAlert {
  type: 'warning' | 'error' | 'info';
  message: string;
  timestamp: number;
}

type ScoreLevel = 'excellent' | 'good' | 'fair' | 'poor';

const SCORE_THRESHOLDS = {
  excellent: 80,
  good: 60,
  fair: 40,
};

const WEIGHTS = {
  confidenceInterval: 0.3,
  publisherReliability: 0.3,
  updateLatency: 0.2,
  crossChainConsistency: 0.2,
};

function getScoreLevel(score: number): ScoreLevel {
  if (score >= SCORE_THRESHOLDS.excellent) return 'excellent';
  if (score >= SCORE_THRESHOLDS.good) return 'good';
  if (score >= SCORE_THRESHOLDS.fair) return 'fair';
  return 'poor';
}

function getScoreColor(score: number): string {
  const level = getScoreLevel(score);
  switch (level) {
    case 'excellent':
      return 'text-success-600';
    case 'good':
      return 'text-primary-600';
    case 'fair':
      return 'text-warning-600';
    case 'poor':
      return 'text-danger-600';
  }
}

function getScoreBgColor(score: number): string {
  const level = getScoreLevel(score);
  switch (level) {
    case 'excellent':
      return 'bg-success-50';
    case 'good':
      return 'bg-primary-50';
    case 'fair':
      return 'bg-warning-50';
    case 'poor':
      return 'bg-danger-50';
  }
}

function getScoreRingColor(score: number): string {
  const level = getScoreLevel(score);
  switch (level) {
    case 'excellent':
      return chartColors.semantic.success;
    case 'good':
      return chartColors.recharts.primary;
    case 'fair':
      return chartColors.semantic.warning;
    case 'poor':
      return chartColors.semantic.danger;
  }
}

function getScoreLabel(level: ScoreLevel, t: (key: string) => string): string {
  switch (level) {
    case 'excellent':
      return t('pythNetwork.dataQuality.excellent');
    case 'good':
      return t('pythNetwork.dataQuality.good');
    case 'fair':
      return t('pythNetwork.dataQuality.fair');
    case 'poor':
      return t('pythNetwork.dataQuality.poor');
  }
}

function CircularProgress({
  score,
  size = 160,
  strokeWidth = 12,
}: {
  score: number;
  size?: number;
  strokeWidth?: number;
}) {
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;
  const offset = circumference - (score / 100) * circumference;
  const color = getScoreRingColor(score);

  return (
    <div className="relative" style={{ width: size, height: size }}>
      <svg className="transform -rotate-90" width={size} height={size}>
        <circle
          className="text-gray-200"
          strokeWidth={strokeWidth}
          stroke="currentColor"
          fill="transparent"
          r={radius}
          cx={size / 2}
          cy={size / 2}
        />
        <circle
          className="transition-all duration-1000 ease-out"
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          stroke={color}
          fill="transparent"
          r={radius}
          cx={size / 2}
          cy={size / 2}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span className={`text-4xl font-bold ${getScoreColor(score)}`}>{score.toFixed(0)}</span>
        <span className="text-sm text-gray-500">/ 100</span>
      </div>
    </div>
  );
}

function TrendIndicator({ trend }: { trend: 'up' | 'down' | 'stable' }) {
  if (trend === 'up') {
    return (
      <div className="flex items-center gap-1 text-success-600">
        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" />
        </svg>
      </div>
    );
  }
  if (trend === 'down') {
    return (
      <div className="flex items-center gap-1 text-danger-600">
        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinejoin="round" strokeWidth={2} d="M19 14l-7 7m0 0l-7-7m7 7V3" />
        </svg>
      </div>
    );
  }
  return (
    <div className="flex items-center gap-1 text-gray-400">
      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinejoin="round" strokeWidth={2} d="M5 12h14" />
      </svg>
    </div>
  );
}

function DimensionCard({ dimension, index }: { dimension: QualityDimension; index: number }) {
  const progressColor =
    dimension.score >= 80
      ? 'bg-success-500'
      : dimension.score >= 60
        ? 'bg-primary-500'
        : dimension.score >= 40
          ? 'bg-warning-500'
          : 'bg-danger-500';

  return (
    <div className="bg-white border border-gray-200  p-4 hover:border-gray-300 transition-colors duration-200">
      <div className="flex items-start justify-between mb-3">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-1">
            <span className="text-sm font-medium text-gray-900">{dimension.name}</span>
            <span className="text-xs text-gray-400">
              权重 {Math.round(dimension.weight * 100)}%
            </span>
          </div>
          <p className="text-xs text-gray-500">{dimension.description}</p>
        </div>
        <TrendIndicator trend={dimension.trend} />
      </div>
      <div className="flex items-center gap-3">
        <div className="flex-1 h-2 bg-gray-200  overflow-hidden">
          <div
            className={`h-full  transition-all duration-500 ${progressColor}`}
            style={{ width: `${Math.min(100, dimension.score)}%` }}
          />
        </div>
        <span className={`text-lg font-bold ${getScoreColor(dimension.score)}`}>
          {dimension.score.toFixed(0)}
        </span>
      </div>
      <p className="text-xs text-gray-500 mt-2">{dimension.details}</p>
    </div>
  );
}

function AlertBanner({ alert }: { alert: QualityAlert }) {
  const bgColor =
    alert.type === 'error'
      ? 'bg-danger-50 border-danger-200'
      : alert.type === 'warning'
        ? 'bg-warning-50 border-yellow-200'
        : 'bg-primary-50 border-primary-200';
  const textColor =
    alert.type === 'error'
      ? 'text-danger-800'
      : alert.type === 'warning'
        ? 'text-yellow-800'
        : 'text-primary-800';
  const iconColor =
    alert.type === 'error'
      ? 'text-danger-600'
      : alert.type === 'warning'
        ? 'text-warning-600'
        : 'text-primary-600';

  return (
    <div className={`${bgColor} border  p-4`}>
      <div className="flex items-start gap-3">
        <svg
          className={`w-5 h-5 ${iconColor} flex-shrink-0 mt-0.5`}
          fill="currentColor"
          viewBox="0 0 20 20"
        >
          <path
            fillRule="evenodd"
            d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z"
            clipRule="evenodd"
          />
        </svg>
        <div>
          <p className={`text-sm font-medium ${textColor}`}>{alert.message}</p>
          <p className="text-xs text-gray-500 mt-1">{new Date(alert.timestamp).toLocaleString()}</p>
        </div>
      </div>
    </div>
  );
}

const mockPublishers: Publisher[] = [
  {
    id: 'pub-1',
    name: 'Binance',
    reliabilityScore: 98.5,
    latency: 45,
    status: 'active',
    submissionCount: 15420,
    lastUpdate: Date.now() - 5000,
    accuracy: 99.2,
    priceDeviation: 0.02,
  },
  {
    id: 'pub-2',
    name: 'Coinbase',
