function DisputeTrendChart({ trends }: { trends: DisputeTrend[] }) {
  const t = useTranslations();
  const [showByType, setShowByType] = useState(false);

  const maxValue = Math.max(...trends.flatMap((d) => [d.filed, d.resolved]));
