'use client';

import { useEffect, useRef } from 'react';

import { TrendingUp, TrendingDown, Activity, Clock } from 'lucide-react';

import { DashboardCard } from '@/components/oracle/data-display/DashboardCard';
import { useTranslations } from '@/i18n';
