          data={regionChartData}
          title={t('uma.validatorAnalytics.geographicDistribution')}
          subtitle={t('uma.validatorAnalytics.performanceRanking')}
        />
        <PieChart
          data={typeChartData}
          title={t('uma.validatorAnalytics.validatorTypes')}
          subtitle={t('uma.validatorAnalytics.performanceRanking')}
        />
