'use client';

import Image from 'next/image';

import { useState } from 'react';

import { User, Mail, Save, Key, Loader2, CheckCircle } from 'lucide-react';

import { useTranslations } from '@/i18n';
import { updateUserProfile } from '@/lib/supabase/auth';
import { useUser, useProfile, useAuthActions } from '@/stores/authStore';
// AvatarUploader component placeholder
const AvatarUploader = ({
  currentAvatarUrl,
  userId,
  onAvatarUpdate,
  onError,
  onSuccess,
}: {
  currentAvatarUrl?: string | null;
  userId: string;
  onAvatarUpdate: (url: string) => Promise<void>;
  onError: (errorMsg: string) => void;
  onSuccess: (message: string) => void;
}) => (
  <div className="flex items-center gap-4">
    <div className="w-16 h-16 rounded-full bg-gray-200 flex items-center justify-center overflow-hidden">
      {currentAvatarUrl ? (
        <Image src={currentAvatarUrl} alt="Avatar" width={64} height={64} className="w-full h-full object-cover" />
      ) : (
        <User className="w-8 h-8 text-gray-500" />
      )}
    </div>
    <button
      type="button"
      className="px-4 py-2 text-sm font-medium text-blue-600 border border-blue-600 rounded-md hover:bg-blue-50"
      onClick={() => {
        // Placeholder upload functionality
        const mockUrl = `https://api.dicebear.com/7.x/avataaars/svg?seed=${userId}`;
        onAvatarUpdate(mockUrl)
          .then(() => onSuccess('Avatar updated successfully'))
          .catch(() => onError('Failed to update avatar'));
      }}
    >
      Upload Avatar
    </button>
  </div>
);

export function ProfilePanel() {
  const t = useTranslations();
  const user = useUser();
  const profile = useProfile();
  const { refreshProfile } = useAuthActions();
  const [displayName, setDisplayName] = useState(profile?.display_name || '');
  const [avatarUrl, setAvatarUrl] = useState(profile?.avatar_url || '');
  const [isSaving, setIsSaving] = useState(false);
  const [success, setSuccess] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showPasswordForm, setShowPasswordForm] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [isChangingPassword, setIsChangingPassword] = useState(false);

  const handleSaveProfile = async () => {
    if (!user) return;

    setIsSaving(true);
    setError(null);
    setSuccess(null);

    try {
      const { error: updateError } = await updateUserProfile(user.id, {
        display_name: displayName || null,
        avatar_url: avatarUrl || null,
      });

      if (updateError) {
        setError(updateError.message);
      } else {
        setSuccess(t('settings.profile.saveSuccess'));
        await refreshProfile();
      }
    } catch {
      setError(t('settings.profile.saveError'));
    } finally {
      setIsSaving(false);
    }
  };

  const handleAvatarUpdate = async (url: string) => {
    setAvatarUrl(url);
    // 立即刷新全局 profile 状态，确保导航栏等各处同步更新
    await refreshProfile();
  };

  const handleAvatarError = (errorMsg: string) => {
    setError(errorMsg);
  };

  const handleAvatarSuccess = (message: string) => {
    setSuccess(message);
  };

  const handleChangePassword = async () => {
    if (newPassword.length < 6) {
      setError(t('settings.profile.passwordMinLength'));
      return;
    }

    if (newPassword !== confirmPassword) {
      setError(t('settings.profile.passwordMismatch'));
      return;
    }

    setIsChangingPassword(true);
    setError(null);

    try {
      const { error: updateError } = await updateUserProfile(user?.id || '', {
        display_name: displayName,
      });

      if (updateError) {
        setError(updateError.message);
      } else {
        setSuccess(t('settings.profile.passwordUpdateSuccess'));
        setShowPasswordForm(false);
        setNewPassword('');
        setConfirmPassword('');
      }
    } catch {
      setError(t('settings.profile.passwordUpdateError'));
    } finally {
      setIsChangingPassword(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-lg border border-gray-200 shadow-sm overflow-hidden">
        <div className="px-6 py-4 border-b border-gray-100 bg-gray-50/50">
          <h2 className="text-lg font-semibold text-gray-900 flex items-center gap-2">
            <User className="w-5 h-5 text-gray-400" />
            {t('settings.profile.title')}
          </h2>
          <p className="text-sm text-gray-500 mt-1">{t('settings.profile.subtitle')}</p>
        </div>

        <div className="p-6 space-y-6">
          {error && (
            <div className="p-3 bg-danger-50 border border-danger-200 rounded-lg text-danger-700 text-sm">
              {error}
            </div>
          )}

          {success && (
            <div className="p-3 bg-success-50 border border-green-200 rounded-lg text-success-700 text-sm flex items-center gap-2">
              <CheckCircle className="w-4 h-4" />
              {success}
            </div>
          )}

          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-6">
            <AvatarUploader
              currentAvatarUrl={avatarUrl || profile?.avatar_url}
              userId={user?.id || ''}
              onAvatarUpdate={handleAvatarUpdate}
              onError={handleAvatarError}
              onSuccess={handleAvatarSuccess}
            />

            <div className="flex-1 w-full">
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    {t('settings.profile.displayNameLabel')}
                  </label>
                  <input
                    type="text"
                    value={displayName}
                    onChange={(e) => setDisplayName(e.target.value)}
                    placeholder={t('settings.profile.displayNamePlaceholder')}
                    className="w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 outline-none transition-all duration-200"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2 flex items-center gap-2">
                    <Mail className="w-4 h-4 text-gray-400" />
                    {t('settings.profile.emailLabel')}
                  </label>
                  <input
                    type="email"
                    value={user?.email || ''}
                    disabled
                    className="w-full px-4 py-2.5 border border-gray-200 rounded-lg bg-gray-50 text-gray-500 cursor-not-allowed"
                  />
                  <p className="text-xs text-gray-500 mt-1">
                    {t('settings.profile.emailNotEditable')}
                  </p>
                </div>
              </div>
            </div>
          </div>

          <div className="pt-4 border-t border-gray-100">
            <button
              onClick={handleSaveProfile}
              disabled={isSaving}
              className="inline-flex items-center gap-2 px-4 py-2.5 bg-primary-600 text-white rounded-lg hover:bg-primary-700 active:bg-primary-800 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed font-medium text-sm shadow-sm hover:shadow-md"
            >
              {isSaving ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <Save className="w-4 h-4" />
              )}
              {t('settings.profile.saveChanges')}
            </button>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-lg border border-gray-200 shadow-sm overflow-hidden">
        <div className="px-6 py-4 border-b border-gray-100 bg-gray-50/50">
          <h2 className="text-lg font-semibold text-gray-900 flex items-center gap-2">
            <Key className="w-5 h-5 text-gray-400" />
            {t('settings.profile.passwordManagement')}
          </h2>
          <p className="text-sm text-gray-500 mt-1">
            {t('settings.profile.passwordManagementDesc')}
          </p>
        </div>

        <div className="p-6">
          {!showPasswordForm ? (
            <button
              onClick={() => setShowPasswordForm(true)}
              className="inline-flex items-center gap-2 px-4 py-2.5 border border-gray-200 rounded-lg text-gray-700 hover:bg-gray-50 hover:border-gray-300 active:bg-gray-100 transition-all duration-200 font-medium text-sm"
            >
              <Key className="w-4 h-4" />
              {t('settings.profile.changePassword')}
            </button>
          ) : (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  {t('settings.profile.newPassword')}
                </label>
                <input
                  type="password"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  placeholder={t('settings.profile.newPasswordPlaceholder')}
                  className="w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 outline-none transition-all duration-200"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  {t('settings.profile.confirmNewPassword')}
                </label>
                <input
                  type="password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder={t('settings.profile.confirmNewPasswordPlaceholder')}
                  className="w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 outline-none transition-all duration-200"
                />
              </div>

              <div className="flex gap-3">
                <button
                  onClick={handleChangePassword}
                  disabled={isChangingPassword}
                  className="inline-flex items-center gap-2 px-4 py-2.5 bg-primary-600 text-white rounded-lg hover:bg-primary-700 active:bg-primary-800 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed font-medium text-sm shadow-sm hover:shadow-md"
                >
                  {isChangingPassword ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <CheckCircle className="w-4 h-4" />
                  )}
                  {t('settings.profile.updatePassword')}
                </button>
                <button
                  onClick={() => {
                    setShowPasswordForm(false);
                    setNewPassword('');
                    setConfirmPassword('');
                  }}
                  className="px-4 py-2.5 border border-gray-200 rounded-lg text-gray-700 hover:bg-gray-50 hover:border-gray-300 active:bg-gray-100 transition-all duration-200 font-medium text-sm"
                >
                  {t('settings.profile.cancel')}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { type ReactNode } from 'react';

import { Settings, User, Bell, Palette, Database } from 'lucide-react';

import { Icon } from '@/components/ui';

export type SettingsTab = 'profile' | 'preferences' | 'notifications' | 'data';

interface SettingsLayoutProps {
  children: ReactNode;
  activeTab: SettingsTab;
  onTabChange: (tab: SettingsTab) => void;
}

interface TabItem {
  id: SettingsTab;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  description: string;
}

const tabs: TabItem[] = [
  {
    id: 'profile',
    label: '个人资料',
    icon: User,
    description: '管理您的账户信息',
  },
  {
    id: 'preferences',
    label: '偏好设置',
    icon: Palette,
    description: '自定义应用设置',
  },
  {
    id: 'notifications',
    label: '通知设置',
    icon: Bell,
    description: '管理通知偏好',
  },
  {
    id: 'data',
    label: '数据管理',
    icon: Database,
    description: '导出和管理数据',
  },
];

export function SettingsLayout({ children, activeTab, onTabChange }: SettingsLayoutProps) {
  return (
    <div className="min-h-screen bg-insight">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="mb-8">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-10 h-10 bg-primary-600 rounded-lg flex items-center justify-center shadow-sm">
              <Settings className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-2xl font-semibold text-gray-900">设置</h1>
              <p className="text-sm text-gray-500 mt-0.5">管理您的账户和应用偏好</p>
            </div>
          </div>
        </div>

        <div className="flex flex-col lg:flex-row gap-6">
          <nav className="lg:w-64 flex-shrink-0">
            <div className="bg-white rounded-lg border border-gray-200 shadow-sm overflow-hidden">
              {tabs.map((tab, index) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;

                return (
                  <button
                    key={tab.id}
                    onClick={() => onTabChange(tab.id)}
                    className={`w-full flex items-center gap-3 px-4 py-3.5 text-left transition-all duration-200 relative rounded-lg ${
                      index !== 0 ? 'border-t border-gray-100' : ''
                    } ${
                      isActive
                        ? 'bg-primary-50/80 text-primary-600'
                        : 'text-gray-700 hover:bg-gray-50 hover:text-gray-900'
                    }`}
                  >
                    {isActive && (
                      <div className="absolute left-0 top-0 bottom-0 w-0.5 bg-primary-600" />
                    )}
                    <Icon
                      className={`w-5 h-5 transition-colors ${
                        isActive ? 'text-primary-600' : 'text-gray-400'
                      }`}
                    />
                    <div className="flex-1 min-w-0">
                      <div className="font-medium text-sm">{tab.label}</div>
                      <div
                        className={`text-xs truncate ${
                          isActive ? 'text-primary-500' : 'text-gray-400'
                        }`}
                      >
                        {tab.description}
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>
          </nav>

          <main className="flex-1 min-w-0">{children}</main>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, {
  useState,
  useCallback,
  useMemo,
  useRef,
  useEffect,
  type ReactNode,
  type CSSProperties,
} from 'react';

import { useVirtualizer } from '@tanstack/react-virtual';
import {
  ArrowUpDown,
  ArrowUp,
  ArrowDown,
  GripVertical,
  Settings2,
  Check,
  AlignJustify,
  Rows3,
  LayoutList,
} from 'lucide-react';

import { useTranslations } from '@/i18n';
import { semanticColors } from '@/lib/config/colors';
import { cn } from '@/lib/utils';

// ============================================
// Type Definitions
// ============================================

export type AlignType = 'left' | 'center' | 'right';

export interface ConditionalFormattingRule {
  condition: 'gt' | 'lt' | 'eq' | 'between' | 'gte' | 'lte';
  value: number | [number, number];
  style: 'success' | 'danger' | 'warning' | 'info';
}

export interface ConditionalFormattingConfig {
  field: string;
  rules: ConditionalFormattingRule[];
}

export interface ColumnDef<T> {
  key: string;
  header: string | ReactNode;
  width?: number;
  minWidth?: number;
  maxWidth?: number;
  align?: AlignType;
  sortable?: boolean;
  fixed?: 'left' | 'right';
  formatter?: (value: unknown, row: T) => ReactNode;
  conditionalFormat?: {
    rules: ConditionalFormattingRule[];
  };
}

export interface FixedColumnsConfig {
  left?: string[];
  right?: string[];
}

export interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

export interface DataTableProProps<T extends Record<string, unknown>> {
  data: T[];
  columns: ColumnDef<T>[];
  fixedColumns?: FixedColumnsConfig;
  conditionalFormatting?: ConditionalFormattingConfig[];
  multiSort?: boolean;
  resizable?: boolean;
  columnVisibility?: boolean;
  density?: 'compact' | 'normal' | 'comfortable';
  densityToggle?: boolean;
  virtualScroll?: boolean;
  rowHeight?: number;
  maxHeight?: number;
  loading?: boolean;
  emptyText?: string;
  scrollPositionKey?: string;
  onRowClick?: (row: T, index: number) => void;
  onSort?: (sortConfig: SortConfig[]) => void;
  onDensityChange?: (density: 'compact' | 'normal' | 'comfortable') => void;
  className?: string;
}

// ============================================
// Utility Functions
// ============================================

function getNestedValue<T>(obj: T, path: string): unknown {
  return path.split('.').reduce<unknown>((acc, key) => {
    if (acc === null || acc === undefined) return undefined;
    return (acc as Record<string, unknown>)[key];
  }, obj);
}

function evaluateCondition(
  value: number,
  condition: ConditionalFormattingRule['condition'],
  ruleValue: number | [number, number]
): boolean {
  switch (condition) {
    case 'gt':
      return value > (ruleValue as number);
    case 'gte':
      return value >= (ruleValue as number);
    case 'lt':
      return value < (ruleValue as number);
    case 'lte':
      return value <= (ruleValue as number);
    case 'eq':
      return value === ruleValue;
    case 'between':
      const [min, max] = ruleValue as [number, number];
      return value >= min && value <= max;
    default:
      return false;
  }
}

function getConditionalStyle(style: ConditionalFormattingRule['style']): string {
  switch (style) {
    case 'success':
      return 'font-medium';
    case 'danger':
      return 'font-medium';
    case 'warning':
      return 'font-medium';
    case 'info':
      return 'font-medium';
    default:
      return '';
  }
}

function getConditionalStyleCSS(style: ConditionalFormattingRule['style']): CSSProperties {
  switch (style) {
    case 'success':
      return {
        backgroundColor: semanticColors.success.light,
        color: semanticColors.success.text,
      };
    case 'danger':
      return {
        backgroundColor: semanticColors.danger.light,
        color: semanticColors.danger.text,
      };
    case 'warning':
      return {
        backgroundColor: semanticColors.warning.light,
        color: semanticColors.warning.text,
      };
    case 'info':
      return {
        backgroundColor: semanticColors.info.light,
        color: semanticColors.info.text,
      };
    default:
      return {};
  }
}

function getAlignClass(align?: AlignType): string {
  switch (align) {
    case 'center':
      return 'text-center';
    case 'right':
      return 'text-right';
    case 'left':
    default:
      return 'text-left';
  }
}

// ============================================
// Density Toggle Component
// ============================================

interface DensityToggleProps {
  density: 'compact' | 'normal' | 'comfortable';
  onChange: (density: 'compact' | 'normal' | 'comfortable') => void;
}

function DensityToggle({ density, onChange }: DensityToggleProps) {
  const t = useTranslations('ui.dataTable');
  const options = [
    { key: 'compact', icon: AlignJustify, label: t('density.compact') },
    { key: 'normal', icon: Rows3, label: t('density.normal') },
    { key: 'comfortable', icon: LayoutList, label: t('density.comfortable') },
  ] as const;

  return (
    <div className="flex items-center gap-1 p-1 bg-gray-100 rounded-md">
      {options.map((option) => {
        const Icon = option.icon;
        const isActive = density === option.key;
        return (
          <button
            key={option.key}
            type="button"
            onClick={() => onChange(option.key)}
            className={cn(
              'flex items-center gap-1 px-2 py-1 text-xs font-medium rounded transition-all',
              isActive
                ? 'bg-white text-gray-900 shadow-sm'
                : 'text-gray-500 hover:text-gray-700 hover:bg-gray-200/50'
            )}
            title={option.label}
          >
            <Icon className="w-3.5 h-3.5" />
            <span className="hidden sm:inline">{option.label}</span>
          </button>
        );
      })}
    </div>
  );
}

// ============================================
// Column Visibility Dropdown Component
// ============================================

interface ColumnVisibilityDropdownProps<T> {
  columns: ColumnDef<T>[];
  visibleColumns: Set<string>;
  onToggleColumn: (key: string) => void;
  onToggleAll: () => void;
}

function ColumnVisibilityDropdown<T>({
  columns,
  visibleColumns,
  onToggleColumn,
  onToggleAll,
}: ColumnVisibilityDropdownProps<T>) {
  const t = useTranslations('ui.dataTable');
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const allVisible = visibleColumns.size === columns.length;
  const someVisible = visibleColumns.size > 0 && visibleColumns.size < columns.length;

  return (
    <div ref={dropdownRef} className="relative">
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className={cn(
          'inline-flex items-center gap-1.5 px-2.5 py-1.5 text-xs font-medium rounded-md transition-colors',
          'border border-gray-200 bg-white text-gray-700 hover:bg-gray-50',
          someVisible && 'text-blue-600 border-blue-200 bg-blue-50'
        )}
        title={t('columnSettings')}
      >
        <Settings2 className="w-3.5 h-3.5" />
        <span className="hidden sm:inline">{t('columnSettings')}</span>
        {someVisible && <span className="ml-0.5 w-1.5 h-1.5 rounded-full bg-blue-500" />}
      </button>

      {isOpen && (
        <div className="absolute right-0 top-full mt-1 z-50 min-w-[180px] bg-white rounded-lg border border-gray-200 shadow-lg py-1">
          <div className="px-3 py-2 border-b border-gray-100">
            <button
              type="button"
              onClick={onToggleAll}
              className="flex items-center gap-2 text-xs text-gray-600 hover:text-gray-900 transition-colors"
            >
              <div
                className={cn(
                  'w-4 h-4 rounded border flex items-center justify-center transition-colors',
                  allVisible
                    ? 'bg-blue-600 border-blue-600'
                    : someVisible
                      ? 'bg-blue-600 border-blue-600'
                      : 'border-gray-300'
                )}
              >
                {(allVisible || someVisible) && <Check className="w-3 h-3 text-white" />}
              </div>
              <span>{allVisible ? t('deselectAll') : t('selectAll')}</span>
            </button>
          </div>

          <div className="max-h-[240px] overflow-y-auto py-1">
            {columns.map((column) => {
              const isVisible = visibleColumns.has(column.key);
              const isFixed = !!column.fixed;

              return (
                <button
                  key={column.key}
                  type="button"
                  onClick={() => onToggleColumn(column.key)}
                  disabled={isFixed}
                  className={cn(
                    'w-full flex items-center gap-2 px-3 py-1.5 text-xs transition-colors',
                    isFixed ? 'text-gray-400 cursor-not-allowed' : 'text-gray-700 hover:bg-gray-50'
                  )}
                >
                  <div
                    className={cn(
                      'w-4 h-4 rounded border flex items-center justify-center transition-colors',
                      isVisible ? 'bg-blue-600 border-blue-600' : 'border-gray-300'
                    )}
                  >
                    {isVisible && <Check className="w-3 h-3 text-white" />}
                  </div>
                  <span className="flex-1 text-left truncate">
                    {typeof column.header === 'string' ? column.header : column.key}
                  </span>
                  {isFixed && <span className="text-[10px] text-gray-400">{t('fixed')}</span>}
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

// ============================================
// Main Component
// ============================================

export function DataTablePro<T extends Record<string, unknown>>({
  data,
  columns,
  fixedColumns,
  conditionalFormatting,
  multiSort = false,
  resizable = false,
  columnVisibility = false,
  density: initialDensity = 'normal',
  densityToggle = false,
  virtualScroll = false,
  rowHeight = 48,
  maxHeight = 600,
  loading = false,
  emptyText,
  scrollPositionKey,
  onRowClick,
  onSort,
  onDensityChange,
  className,
}: DataTableProProps<T>) {
  const t = useTranslations('ui.dataTable');
  const containerRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [sortConfig, setSortConfig] = useState<SortConfig[]>([]);
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({});
  const [resizingColumn, setResizingColumn] = useState<string | null>(null);
  const [startX, setStartX] = useState(0);
  const [startWidth, setStartWidth] = useState(0);
  const [density, setDensity] = useState<'compact' | 'normal' | 'comfortable'>(initialDensity);
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(
    () => new Set(columns.map((c) => c.key))
  );

  // Sync density with prop changes
  useEffect(() => {
    setDensity(initialDensity);
  }, [initialDensity]);

  const handleDensityChange = useCallback(
    (newDensity: 'compact' | 'normal' | 'comfortable') => {
      setDensity(newDensity);
      onDensityChange?.(newDensity);
    },
    [onDensityChange]
  );

  // ============================================
  // Filtered Columns
  // ============================================

  const visibleColumnsList = useMemo(() => {
    return columns.filter((col) => visibleColumns.has(col.key));
  }, [columns, visibleColumns]);

  // ============================================
  // Column Visibility Handlers
  // ============================================

  const handleToggleColumn = useCallback((key: string) => {
    setVisibleColumns((prev) => {
      const next = new Set(prev);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  }, []);

  const handleToggleAllColumns = useCallback(() => {
    setVisibleColumns((prev) => {
      if (prev.size === columns.length) {
        // Keep fixed columns visible
        return new Set(columns.filter((c) => c.fixed).map((c) => c.key));
      }
      return new Set(columns.map((c) => c.key));
    });
  }, [columns]);

  // ============================================
  // Density Configuration
  // ============================================

  const densityConfig = useMemo(() => {
    switch (density) {
      case 'compact':
        return {
          rowHeight: 36,
          cellPadding: 'px-3 py-2',
          headerPadding: 'px-3 py-2',
          fontSize: 'text-xs',
        };
      case 'comfortable':
        return {
          rowHeight: 64,
          cellPadding: 'px-6 py-4',
          headerPadding: 'px-6 py-4',
          fontSize: 'text-base',
        };
      default:
        return {
          rowHeight: 48,
          cellPadding: 'px-3 py-2',
          headerPadding: 'px-3 py-2',
          fontSize: 'text-sm',
        };
    }
  }, [density]);

  // ============================================
  // Sorting Logic
  // ============================================

  const handleSort = useCallback(
    (key: string) => {
      setSortConfig((prev) => {
        const existingIndex = prev.findIndex((s) => s.key === key);

        if (existingIndex === -1) {
          // Add new sort
          const newSort: SortConfig = { key, direction: 'asc' };
          const newConfig = multiSort ? [...prev, newSort] : [newSort];
          onSort?.(newConfig);
          return newConfig;
        }

        const existing = prev[existingIndex];
        if (existing.direction === 'asc') {
          // Toggle to desc
          const updated = [...prev];
          updated[existingIndex] = { ...existing, direction: 'desc' };
          const newConfig = multiSort ? updated : [updated[existingIndex]];
          onSort?.(newConfig);
          return newConfig;
        }

        // Remove sort
        let newConfig: SortConfig[];
        if (multiSort) {
          newConfig = prev.filter((_, i) => i !== existingIndex);
        } else {
          newConfig = [];
        }
        onSort?.(newConfig);
        return newConfig;
      });
    },
    [multiSort, onSort]
  );

  const sortedData = useMemo(() => {
    if (sortConfig.length === 0) return data;

    return [...data].sort((a, b) => {
      for (const sort of sortConfig) {
        const aValue = getNestedValue(a, sort.key);
        const bValue = getNestedValue(b, sort.key);

        if (aValue === bValue) continue;

        if (typeof aValue === 'number' && typeof bValue === 'number') {
          return sort.direction === 'asc' ? aValue - bValue : bValue - aValue;
        }

        const aStr = String(aValue ?? '');
        const bStr = String(bValue ?? '');
        const comparison = aStr.localeCompare(bStr);
        return sort.direction === 'asc' ? comparison : -comparison;
      }
      return 0;
    });
  }, [data, sortConfig]);

  // ============================================
  // Column Resizing Logic
  // ============================================

  const handleResizeStart = useCallback(
    (e: React.MouseEvent, columnKey: string) => {
      if (!resizable) return;
      e.preventDefault();
      e.stopPropagation();

      const currentWidth =
        columnWidths[columnKey] || columns.find((c) => c.key === columnKey)?.width || 150;

      setResizingColumn(columnKey);
      setStartX(e.clientX);
      setStartWidth(currentWidth);
    },
    [resizable, columnWidths, columns]
  );

  useEffect(() => {
    if (!resizingColumn) return;

    const handleMouseMove = (e: MouseEvent) => {
      const diff = e.clientX - startX;
      const newWidth = Math.max(50, startWidth + diff);
      const column = columns.find((c) => c.key === resizingColumn);
      const maxWidth = column?.maxWidth;
      const minWidth = column?.minWidth ?? 50;

      const finalWidth = maxWidth ? Math.min(newWidth, maxWidth) : newWidth;
      const clampedWidth = Math.max(finalWidth, minWidth);

      setColumnWidths((prev) => ({
        ...prev,
        [resizingColumn]: clampedWidth,
      }));
    };

    const handleMouseUp = () => {
      setResizingColumn(null);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [resizingColumn, startX, startWidth, columns]);

  // ============================================
  // Conditional Formatting Logic
  // ============================================

  const getCellConditionalClass = useCallback(
    (columnKey: string, value: unknown): { className: string; style: CSSProperties } => {
      // First check column's own conditionalFormat
      const column = columns.find((c) => c.key === columnKey);
      if (column?.conditionalFormat && typeof value === 'number') {
        for (const rule of column.conditionalFormat.rules) {
          if (evaluateCondition(value, rule.condition, rule.value)) {
            return {
              className: getConditionalStyle(rule.style),
              style: getConditionalStyleCSS(rule.style),
            };
          }
        }
      }

      // Then check global conditionalFormatting
      if (conditionalFormatting) {
        const config = conditionalFormatting.find((c) => c.field === columnKey);
        if (config && typeof value === 'number') {
          for (const rule of config.rules) {
            if (evaluateCondition(value, rule.condition, rule.value)) {
              return {
                className: getConditionalStyle(rule.style),
                style: getConditionalStyleCSS(rule.style),
              };
            }
          }
        }
      }

      return { className: '', style: {} };
    },
    [conditionalFormatting, columns]
  );

  // ============================================
  // Virtual Scrolling with @tanstack/react-virtual
  // ============================================

  const currentRowHeight = rowHeight || densityConfig.rowHeight;

  const getSavedScrollPosition = useCallback((): number => {
    if (!scrollPositionKey || typeof window === 'undefined') return 0;
    try {
      const saved = sessionStorage.getItem(`datatable-scroll-${scrollPositionKey}`);
      return saved ? parseInt(saved, 10) : 0;
    } catch {
      return 0;
    }
  }, [scrollPositionKey]);

  const saveScrollPosition = useCallback(
    (offset: number) => {
      if (!scrollPositionKey || typeof window === 'undefined') return;
      try {
        sessionStorage.setItem(`datatable-scroll-${scrollPositionKey}`, String(offset));
      } catch {
        // Ignore sessionStorage errors
      }
    },
    [scrollPositionKey]
  );

  const virtualizer = useVirtualizer({
    count: virtualScroll ? sortedData.length : 0,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => currentRowHeight,
    overscan: 10,
    enabled: virtualScroll,
    initialOffset: getSavedScrollPosition(),
  });

  const virtualItems = virtualizer.getVirtualItems();

  useEffect(() => {
    if (!virtualScroll || !scrollPositionKey) return;

    const scrollElement = scrollRef.current;
    if (!scrollElement) return;

    const handleScroll = () => {
      const offset = scrollElement.scrollTop;
      saveScrollPosition(offset);
    };

    scrollElement.addEventListener('scroll', handleScroll);
    return () => scrollElement.removeEventListener('scroll', handleScroll);
  }, [virtualScroll, scrollPositionKey, saveScrollPosition]);

  // ============================================
  // Fixed Columns Logic
  // ============================================

  const isColumnFixed = useCallback(
    (key: string, position: 'left' | 'right'): boolean => {
      if (!fixedColumns) return false;
      return fixedColumns[position]?.includes(key) ?? false;
    },
    [fixedColumns]
  );

  const getColumnStickyStyle = useCallback(
    (key: string): CSSProperties => {
      if (!fixedColumns) return {};

      if (isColumnFixed(key, 'left')) {
        const leftColumns = fixedColumns.left || [];
        const columnIndex = leftColumns.indexOf(key);
        let leftOffset = 0;

        for (let i = 0; i < columnIndex; i++) {
          const colKey = leftColumns[i];
          const col = columns.find((c) => c.key === colKey);
          leftOffset += columnWidths[colKey] || col?.width || 150;
        }

        return {
          position: 'sticky',
          left: leftOffset,
          zIndex: 20,
        };
      }

      if (isColumnFixed(key, 'right')) {
        const rightColumns = fixedColumns.right || [];
        const columnIndex = rightColumns.indexOf(key);
        let rightOffset = 0;

        for (let i = rightColumns.length - 1; i > columnIndex; i--) {
          const colKey = rightColumns[i];
          const col = columns.find((c) => c.key === colKey);
          rightOffset += columnWidths[colKey] || col?.width || 150;
        }

        return {
          position: 'sticky',
          right: rightOffset,
          zIndex: 20,
        };
      }

      return {};
    },
    [fixedColumns, isColumnFixed, columns, columnWidths]
  );

  // ============================================
  // Render Helpers
  // ============================================

  const renderSortIcon = (columnKey: string) => {
    const sort = sortConfig.find((s) => s.key === columnKey);
    if (!sort) {
      return (
        <ArrowUpDown className="w-3.5 h-3.5 text-gray-400 opacity-0 group-hover:opacity-100 transition-opacity" />
      );
    }
    return sort.direction === 'asc' ? (
      <ArrowUp className="w-3.5 h-3.5 text-blue-600" />
    ) : (
      <ArrowDown className="w-3.5 h-3.5 text-blue-600" />
    );
  };

  const renderCell = (column: ColumnDef<T>, row: T) => {
    const value = getNestedValue(row, column.key);

    if (column.formatter) {
      return column.formatter(value, row);
    }

    if (value === null || value === undefined) {
      return <span className="text-gray-400">-</span>;
    }

    return String(value);
  };

  // ============================================
  // Empty State
  // ============================================

  if (!loading && data.length === 0) {
    return (
      <div
        className={cn(
          'flex flex-col items-center justify-center py-12 px-4 bg-white rounded-lg border border-gray-200',
          className
        )}
      >
        <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mb-4">
          <svg
            className="w-8 h-8 text-gray-400"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={1.5}
              d="M3 10h18M3 14h18m-9-4v8m-7 0h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"
            />
          </svg>
        </div>
        <p className="text-gray-500 text-sm">{emptyText || t('noData')}</p>
      </div>
    );
  }

  // ============================================
  // Main Render
  // ============================================

  return (
    <div ref={containerRef} className={cn('relative overflow-hidden', className)}>
      {/* Toolbar */}
      {(columnVisibility || densityToggle) && (
        <div className="flex items-center justify-between px-4 py-2 border-b border-gray-200 bg-gray-50/50">
          <div className="text-xs text-gray-500">
            {t('totalRecords', { count: data.length })}
            {sortConfig.length > 0 && (
              <span className="ml-2 text-blue-600">
                {t('sorted')}:{' '}
                {sortConfig.map((s) => `${s.key}(${s.direction === 'asc' ? '↑' : '↓'})`).join(', ')}
              </span>
            )}
          </div>
          <div className="flex items-center gap-2">
            {densityToggle && <DensityToggle density={density} onChange={handleDensityChange} />}
            {columnVisibility && (
              <ColumnVisibilityDropdown
                columns={columns}
                visibleColumns={visibleColumns}
                onToggleColumn={handleToggleColumn}
                onToggleAll={handleToggleAllColumns}
              />
            )}
          </div>
        </div>
      )}

      {/* Table Container */}
      <div
        ref={scrollRef}
        className={cn('overflow-auto', virtualScroll && 'overflow-y-auto')}
        style={{ maxHeight: virtualScroll ? maxHeight : undefined }}
      >
        <table className="w-full border-collapse">
          {/* Header */}
          <thead className="sticky top-0 z-30">
            <tr className="bg-transparent">
              {visibleColumnsList.map((column) => {
                const isFixedLeft = isColumnFixed(column.key, 'left');
                const isFixedRight = isColumnFixed(column.key, 'right');
                const stickyStyle = getColumnStickyStyle(column.key);
                const width = columnWidths[column.key] || column.width || 150;
                const alignClass = getAlignClass(column.align);

                return (
                  <th
                    key={column.key}
                    className={cn(
                      densityConfig.headerPadding,
                      densityConfig.fontSize,
                      'font-semibold text-gray-700 border-b border-gray-200 whitespace-nowrap select-none',
                      alignClass,
                      isFixedLeft &&
                        'sticky left-0 z-20 bg-white shadow-[2px_0_4px_-2px_rgba(0,0,0,0.1)]',
                      isFixedRight &&
                        'sticky right-0 z-20 bg-white shadow-[-2px_0_4px_-2px_rgba(0,0,0,0.1)]',
                      column.sortable && 'cursor-pointer group'
                    )}
                    style={{
                      ...stickyStyle,
                      width,
                      minWidth: column.minWidth || 50,
                      maxWidth: column.maxWidth,
                    }}
                    onClick={() => column.sortable && handleSort(column.key)}
                  >
                    <div className="flex items-center gap-2">
                      <span className="flex-1 truncate">{column.header}</span>
                      {column.sortable && (
                        <span className="flex-shrink-0">{renderSortIcon(column.key)}</span>
                      )}
                      {resizable && (
                        <div
                          className="absolute right-0 top-0 h-full w-1 cursor-col-resize hover:bg-blue-400 active:bg-blue-600 z-10"
                          onMouseDown={(e) => handleResizeStart(e, column.key)}
                        >
                          <GripVertical className="w-3 h-3 text-gray-300 absolute right-0 top-1/2 -translate-y-1/2" />
                        </div>
                      )}
                    </div>
                  </th>
                );
              })}
            </tr>
          </thead>

          {/* Body */}
          <tbody
            style={
              virtualScroll
                ? {
                    height: `${virtualizer.getTotalSize()}px`,
                    position: 'relative',
                  }
                : undefined
            }
          >
            {virtualScroll
              ? // Virtual scrolling rendering
                virtualItems.map((virtualItem) => {
                  const row = sortedData[virtualItem.index];
                  const actualIndex = virtualItem.index;

                  return (
                    <tr
                      key={virtualItem.key}
                      data-index={virtualItem.index}
                      ref={virtualizer.measureElement}
                      className={cn(
                        'transition-colors duration-150 hover:bg-gray-50',
                        onRowClick && 'cursor-pointer',
                        'border-b border-gray-100 last:border-b-0'
                      )}
                      style={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        width: '100%',
                        height: `${virtualItem.size}px`,
                        transform: `translateY(${virtualItem.start}px)`,
                      }}
                      onClick={() => onRowClick?.(row, actualIndex)}
                    >
                      {visibleColumnsList.map((column) => {
                        const isFixedLeft = isColumnFixed(column.key, 'left');
                        const isFixedRight = isColumnFixed(column.key, 'right');
                        const stickyStyle = getColumnStickyStyle(column.key);
                        const value = getNestedValue(row, column.key);
                        const conditionalFormattingResult = getCellConditionalClass(
                          column.key,
                          value
                        );
                        const width = columnWidths[column.key] || column.width || 150;
                        const alignClass = getAlignClass(column.align);

                        return (
                          <td
                            key={column.key}
                            className={cn(
                              densityConfig.cellPadding,
                              densityConfig.fontSize,
                              'text-gray-900 border-gray-100',
                              alignClass,
                              isFixedLeft &&
                                'sticky left-0 z-10 bg-white shadow-[2px_0_4px_-2px_rgba(0,0,0,0.1)]',
                              isFixedRight &&
                                'sticky right-0 z-10 bg-white shadow-[-2px_0_4px_-2px_rgba(0,0,0,0.1)]',
                              conditionalFormattingResult.className,
                              onRowClick && 'group-hover:bg-gray-50'
                            )}
                            style={{
                              ...stickyStyle,
                              ...conditionalFormattingResult.style,
                              width,
                              minWidth: column.minWidth || 50,
                              maxWidth: column.maxWidth,
                            }}
                          >
                            <div className="truncate">{renderCell(column, row)}</div>
                          </td>
                        );
                      })}
                    </tr>
                  );
                })
              : // Normal rendering without virtualization
                sortedData.map((row, rowIndex) => (
                  <tr
                    key={rowIndex}
                    className={cn(
                      'transition-colors duration-150 hover:bg-gray-50',
                      onRowClick && 'cursor-pointer',
                      'border-b border-gray-100 last:border-b-0'
                    )}
                    onClick={() => onRowClick?.(row, rowIndex)}
                  >
                    {visibleColumnsList.map((column) => {
                      const isFixedLeft = isColumnFixed(column.key, 'left');
                      const isFixedRight = isColumnFixed(column.key, 'right');
                      const stickyStyle = getColumnStickyStyle(column.key);
                      const value = getNestedValue(row, column.key);
                      const conditionalFormattingResult = getCellConditionalClass(
                        column.key,
                        value
                      );
                      const width = columnWidths[column.key] || column.width || 150;
                      const alignClass = getAlignClass(column.align);

                      return (
                        <td
                          key={column.key}
                          className={cn(
                            densityConfig.cellPadding,
                            densityConfig.fontSize,
                            'text-gray-900 border-gray-100',
                            alignClass,
                            isFixedLeft &&
                              'sticky left-0 z-10 bg-white shadow-[2px_0_4px_-2px_rgba(0,0,0,0.1)]',
                            isFixedRight &&
                              'sticky right-0 z-10 bg-white shadow-[-2px_0_4px_-2px_rgba(0,0,0,0.1)]',
                            conditionalFormattingResult.className,
                            onRowClick && 'group-hover:bg-gray-50'
                          )}
                          style={{
                            ...stickyStyle,
                            ...conditionalFormattingResult.style,
                            width,
                            minWidth: column.minWidth || 50,
                            maxWidth: column.maxWidth,
                          }}
                        >
                          <div className="truncate">{renderCell(column, row)}</div>
                        </td>
                      );
                    })}
                  </tr>
                ))}
          </tbody>
        </table>
      </div>

      {/* Resizing Overlay */}
      {resizingColumn && <div className="fixed inset-0 z-50 cursor-col-resize" />}

      {/* Loading Overlay */}
      {loading && (
        <div className="absolute inset-0 bg-white/80 backdrop-blur-sm flex items-center justify-center z-40">
          <div className="flex items-center gap-3">
            <div className="w-5 h-5 border-2 border-blue-600 border-t-transparent rounded-full animate-spin" />
            <span className="text-sm text-gray-600">{t('loading')}</span>
          </div>
        </div>
      )}
    </div>
  );
}

export default DataTablePro;

'use client';

import { useState, memo } from 'react';

import { TrendingUp, TrendingDown, Minus, Info } from 'lucide-react';

import { Skeleton } from '@/components/ui/Skeleton';
import { SparklineChart } from '@/components/ui/SparklineChart';
import { Tooltip } from '@/components/ui/Tooltip';
import { cn } from '@/lib/utils';

/**
 * Breakdown 数据项接口
 */
interface BreakdownItem {
  label: string;
  value: string | number;
  percentage: number;
}

/**
 * EnhancedStatCard Props 接口
 */
export interface EnhancedStatCardProps {
  /** 标题 */
  title: string;
  /** 主值 */
  value: number | string;
  /** 变化百分比（新接口） */
  change?: number;
  /** 变化数据（旧接口兼容） */
  changeData?: {
    value: number;
    percentage?: boolean;
    timeframe?: string;
  };
  /** 趋势方向 */
  trend?: 'up' | 'down' | 'stable';
  /** Sparkline 图表数据 (24小时趋势数据) */
  sparklineData?: number[];
  /** 置信度 (0-100) */
  confidence?: number;
  /** 细分数据（hover 时显示） */
  breakdown?: BreakdownItem[];
  /** 变体：紧凑或标准 */
  variant?: 'compact' | 'standard';
  /** 是否加载中 */
  isLoading?: boolean;
  /** 悬停提示内容 */
  tooltipContent?: string;
  /** 自定义类名 */
  className?: string;
  /** ARIA role */
  role?: string;
  /** ARIA label */
  'aria-label'?: string;
}

/**
 * 格式化数值显示
 */
function formatValue(value: number | string): string {
  if (typeof value === 'string') return value;

  // 处理大数值
  if (value >= 1000000000) {
    return `${(value / 1000000000).toFixed(2)}B`;
  }
  if (value >= 1000000) {
    return `${(value / 1000000).toFixed(2)}M`;
  }
  if (value >= 1000) {
    return `${(value / 1000).toFixed(2)}K`;
  }

  // 处理小数
  if (value < 1 && value > -1) {
    return value.toFixed(4);
  }

  return value.toFixed(2);
}

/**
 * 格式化变化值显示
 */
function formatChangeValue(value: number, isPercentage: boolean = true): string {
  const sign = value >= 0 ? '+' : '';
  const suffix = isPercentage ? '%' : '';
  return `${sign}${value.toFixed(2)}${suffix}`;
}

/**
 * 圆形进度条组件
 */
function CircularProgress({
  value,
  size = 40,
  strokeWidth = 3,
}: {
  value: number;
  size?: number;
  strokeWidth?: number;
}) {
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;
  const offset = circumference - (value / 100) * circumference;

  // 根据置信度确定颜色
  const getColor = () => {
    if (value >= 80) return 'var(--success-500, #10b981)';
    if (value >= 60) return 'var(--warning-500, #f59e0b)';
    return 'var(--danger-500, #ef4444)';
  };

  return (
    <div
      className="relative inline-flex items-center justify-center"
      style={{ width: size, height: size }}
    >
      <svg width={size} height={size} className="transform -rotate-90">
        {/* 背景圆环 */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="currentColor"
          strokeWidth={strokeWidth}
          className="text-gray-200 dark:text-gray-700"
        />
        {/* 进度圆环 */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={getColor()}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          className="transition-all duration-500 ease-out"
        />
      </svg>
      {/* 中心文字 */}
      <span className="absolute text-xs font-medium text-gray-600 dark:text-gray-400">
        {Math.round(value)}
      </span>
    </div>
  );
}

/**
 * 线性进度条组件
 */
function LinearProgress({ value, className }: { value: number; className?: string }) {
  // 根据置信度确定颜色
  const getColor = () => {
    if (value >= 80) return 'bg-success-500';
    if (value >= 60) return 'bg-warning-500';
    return 'bg-danger-500';
  };

  return (
    <div className={cn('w-full', className)}>
      <div className="flex items-center justify-between mb-1">
        <span className="text-xs text-gray-500 dark:text-gray-400">置信度</span>
        <span className="text-xs font-medium text-gray-700 dark:text-gray-300">
          {Math.round(value)}%
        </span>
      </div>
      <div className="h-1.5 w-full bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
        <div
          className={cn('h-full rounded-full transition-all duration-500 ease-out', getColor())}
          style={{ width: `${value}%` }}
        />
      </div>
    </div>
  );
}

/**
 * 加载状态骨架屏
 */
function EnhancedStatCardSkeleton({ variant = 'standard' }: { variant?: 'compact' | 'standard' }) {
  const isCompact = variant === 'compact';

  return (
    <div
      className={cn(
        'bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 shadow-sm',
        isCompact ? 'p-3' : 'p-4'
      )}
    >
      {/* 标题 */}
      <div className="flex items-center justify-between mb-3">
        <Skeleton variant="text" width={isCompact ? 60 : 80} height={isCompact ? 12 : 16} />
        <Skeleton variant="circular" width={isCompact ? 12 : 16} height={isCompact ? 12 : 16} />
      </div>

      {/* 主值 */}
      <div className="flex items-baseline gap-2 mb-3">
        <Skeleton variant="text" width={isCompact ? 80 : 120} height={isCompact ? 24 : 32} />
        {!isCompact && <Skeleton variant="text" width={60} height={20} />}
      </div>

      {/* Sparkline 占位 */}
      <Skeleton variant="rounded" width="100%" height={isCompact ? 28 : 40} className="mb-3" />

      {/* 置信度进度条 */}
      {!isCompact && <Skeleton variant="text" width="100%" height={24} />}
    </div>
  );
}

/**
 * EnhancedStatCard - 增强型统计卡片组件
 *
 * 功能特性：
 * - 大字数值显示和趋势指示（箭头+颜色）
 * - 集成 SparklineChart 迷你趋势图
 * - 置信度进度条指示器（圆形或线性）
 * - 细分数据展示（hover 时显示）
 * - 悬停效果显示详细信息（Tooltip）
 * - 加载状态支持（Skeleton）
 * - 暗色模式支持
 *
 * @example
 * ```tsx
 * // 基础用法（新接口）
 * <EnhancedStatCard
 *   title="总交易量"
 *   value={1234567}
 *   change={5.2}
 *   trend="up"
 *   sparklineData={[1, 2, 3, 2, 4, 5, 4, 6]}
 *   confidence={85}
 * />
 *
 * // 兼容旧接口
 * <EnhancedStatCard
 *   title="TVS"
 *   value="$1.2B"
 *   changeData={{ value: 5.2, percentage: true, timeframe: '24h' }}
 *   sparklineData={[1, 2, 3, 2, 4, 5, 4, 6]}
 *   breakdown={[{ label: 'ETH', value: '1B', percentage: 80 }]}
 *   variant="compact"
 * />
 *
 * // 加载状态
 * <EnhancedStatCard
 *   title="加载中..."
 *   value={0}
 *   isLoading={true}
 * />
 *
 * // 带 Tooltip
 * <EnhancedStatCard
 *   title="预测价格"
 *   value={45230}
 *   change={-2.1}
 *   trend="down"
 *   confidence={72}
 *   tooltipContent="基于过去24小时数据预测的BTC价格"
 * />
 * ```
 */
export function EnhancedStatCard({
  title,
  value,
  change,
  changeData,
  trend = 'stable',
  sparklineData,
  confidence,
  breakdown,
  variant = 'standard',
  isLoading = false,
  tooltipContent,
  className,
  role,
  'aria-label': ariaLabel,
}: EnhancedStatCardProps) {
  const [isHovered, setIsHovered] = useState(false);
  const isCompact = variant === 'compact';

  // 加载状态
  if (isLoading) {
    return <EnhancedStatCardSkeleton variant={variant} />;
  }

  // 确定变化值（兼容新旧接口）
  const changeValue = change !== undefined ? change : changeData?.value;
  const isPercentage = changeData?.percentage ?? true;

  // 确定趋势方向和颜色
  const isPositive = changeValue ? changeValue > 0 : trend === 'up';
  const isNegative = changeValue ? changeValue < 0 : trend === 'down';

  // 趋势颜色
  const trendColorClass = isPositive
    ? 'text-success-500'
    : isNegative
      ? 'text-danger-500'
      : 'text-gray-500';

  // 趋势图标
  const TrendIcon = isPositive ? TrendingUp : isNegative ? TrendingDown : Minus;

  // Sparkline 颜色
  const sparklineColor = isPositive ? '#10b981' : isNegative ? '#ef4444' : '#6b7280';

  // 卡片内容
  const cardContent = (
    <div
      className={cn(
        // 基础样式
        'relative bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700',
        'shadow-sm hover:shadow-md transition-all duration-200 ease-out',
        'hover:border-gray-300 dark:hover:border-gray-600',
        isCompact ? 'p-3' : 'p-4',
        className
      )}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      role={role}
      aria-label={ariaLabel}
    >
      {/* 标题行 */}
      <div className="flex items-center justify-between mb-2">
        <span
          className={cn(
            'font-medium text-gray-600 dark:text-gray-400',
            isCompact ? 'text-xs' : 'text-sm'
          )}
        >
          {title}
        </span>
        {(breakdown || tooltipContent) && (
          <Info
            className={cn(
              'text-gray-400 dark:text-gray-500',
              isCompact ? 'w-3 h-3' : 'w-4 h-4',
              tooltipContent && 'cursor-help'
            )}
            aria-hidden="true"
          />
        )}
      </div>

      {/* 主值和变化指示器 */}
      <div className="flex items-baseline gap-2 mb-2">
        <span
          className={cn(
            'font-bold text-gray-900 dark:text-white tabular-nums',
            isCompact ? 'text-lg' : 'text-2xl'
          )}
        >
          {formatValue(value)}
        </span>
        {changeValue !== undefined && (
          <div className={cn('flex items-center gap-0.5', trendColorClass)}>
            <TrendIcon
              className={cn('flex-shrink-0', isCompact ? 'w-3 h-3' : 'w-4 h-4')}
              aria-hidden="true"
            />
            <span className={cn('font-medium tabular-nums', isCompact ? 'text-xs' : 'text-sm')}>
              {formatChangeValue(changeValue, isPercentage)}
            </span>
          </div>
        )}
      </div>

      {/* 时间范围标签（仅在标准模式下显示） */}
      {!isCompact && changeData?.timeframe && (
        <div className="text-xs text-gray-500 dark:text-gray-400 mb-2">{changeData.timeframe}</div>
      )}

      {/* Sparkline 图表 */}
      {sparklineData && sparklineData.length > 0 && (
        <div className={cn('flex items-center justify-between', !isCompact && 'mb-3')}>
          <SparklineChart
            data={sparklineData}
            width={isCompact ? 80 : 120}
            height={isCompact ? 28 : 40}
            color={sparklineColor}
            fill
            animate={!isCompact}
          />
        </div>
      )}

      {/* 置信度指示器（仅在标准模式下显示） */}
      {!isCompact && confidence !== undefined && (
        <LinearProgress value={Math.max(0, Math.min(100, confidence))} />
      )}

      {/* Hover 时的 Breakdown Tooltip */}
      {breakdown && isHovered && (
        <div
          className={cn(
            'absolute z-50 left-0 right-0',
            'bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 shadow-lg',
            'p-3 animate-in fade-in zoom-in-95 duration-150',
            'top-full mt-2'
          )}
        >
          <div className="text-xs font-medium text-gray-500 dark:text-gray-400 mb-2">Breakdown</div>
          <div className="space-y-1.5">
            {breakdown.map((item, index) => (
              <div key={index} className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  {/* 进度条 */}
                  <div className="w-16 h-1.5 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-primary-500 rounded-full"
                      style={{ width: `${Math.min(item.percentage, 100)}%` }}
                    />
                  </div>
                  <span className="text-xs text-gray-600 dark:text-gray-400">{item.label}</span>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-xs font-medium text-gray-900 dark:text-gray-200 tabular-nums">
                    {item.value}
                  </span>
                  <span className="text-xs text-gray-400 dark:text-gray-500 tabular-nums w-10 text-right">
                    {item.percentage.toFixed(1)}%
                  </span>
                </div>
              </div>
            ))}
          </div>
          {/* 小三角箭头 */}
          <div
            className="absolute -top-1 left-6 w-2 h-2 bg-white dark:bg-gray-800 border-l border-t border-gray-200 dark:border-gray-700 transform rotate-45"
            aria-hidden="true"
          />
        </div>
      )}
    </div>
  );

  // 如果有 tooltipContent 且没有 breakdown，包裹在 Tooltip 组件中
  if (tooltipContent && !breakdown) {
    return (
      <Tooltip content={tooltipContent} placement="top">
        {cardContent}
      </Tooltip>
    );
  }

  return cardContent;
}

