'use client';

import { useState, useRef, useEffect, useCallback, useMemo } from 'react';

import { ChevronDown, Search, Check } from 'lucide-react';

import { type DropdownSelectProps, type SelectorOption } from './types';

export function DropdownSelect<T = string>({
  options,
  value,
  onChange,
  placeholder = '请选择...',
  disabled = false,
  searchable = false,
  searchPlaceholder = '搜索...',
  categories,
  defaultCategory,
  className = '',
  renderValue,
  renderOption,
  noOptionsMessage = '无匹配选项',
}: DropdownSelectProps<T>) {
  const [isOpen, setIsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string | undefined>(defaultCategory);
  const [highlightedIndex, setHighlightedIndex] = useState(0);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const selectedOption = options.find((o) => o.value === value);

  const filteredOptions = useMemo(() => {
    let filtered = options;

    if (selectedCategory && categories) {
      filtered = filtered.filter((o) => o.category === selectedCategory);
    }

    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(
        (o) =>
          o.label.toLowerCase().includes(query) || String(o.value).toLowerCase().includes(query)
      );
    }

    return filtered;
  }, [options, selectedCategory, searchQuery, categories]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen]);

  useEffect(() => {
    if (isOpen) {
      setSearchQuery('');
      setHighlightedIndex(0);
      if (searchable) {
        setTimeout(() => searchInputRef.current?.focus(), 0);
      }
    }
  }, [isOpen, searchable]);

  useEffect(() => {
    setHighlightedIndex(0);
  }, [searchQuery, selectedCategory]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (!isOpen) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          setIsOpen(true);
        }
        return;
      }

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault();
          setHighlightedIndex((prev) => (prev < filteredOptions.length - 1 ? prev + 1 : prev));
          break;
        case 'ArrowUp':
          e.preventDefault();
          setHighlightedIndex((prev) => (prev > 0 ? prev - 1 : 0));
          break;
        case 'Enter':
          e.preventDefault();
          if (filteredOptions[highlightedIndex]) {
            onChange(filteredOptions[highlightedIndex].value);
            setIsOpen(false);
          }
          break;
        case 'Escape':
          e.preventDefault();
          setIsOpen(false);
          break;
      }
    },
    [isOpen, filteredOptions, highlightedIndex, onChange]
  );

  const handleSelect = (option: SelectorOption<T>) => {
    if (option.disabled) return;
    onChange(option.value);
    setIsOpen(false);
  };

  const defaultRenderValue = (option: SelectorOption<T> | undefined) => {
    if (!option) return <span className="text-gray-400">{placeholder}</span>;
    return (
      <div className="flex items-center gap-2">
        {option.icon && (
          <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: option.color }} />
        )}
        <span className="font-medium text-gray-900">{option.label}</span>
      </div>
    );
  };

  const defaultRenderOption = (option: SelectorOption<T>, isSelected: boolean) => (
    <div className="flex items-center gap-2">
      {option.icon && (
        <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: option.color }} />
      )}
      <span className={isSelected ? 'font-medium' : ''}>{option.label}</span>
    </div>
  );

  return (
    <div className={`relative ${className}`} ref={dropdownRef}>
      <button
        type="button"
        onClick={() => !disabled && setIsOpen(!isOpen)}
        onKeyDown={handleKeyDown}
        disabled={disabled}
        className={`
          w-full flex items-center justify-between gap-2 px-3 py-2
          bg-white border border-gray-200 text-sm rounded-lg
          hover:border-gray-300 hover:bg-gray-50/50
          focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500
          transition-all duration-200 ease-out
          active:scale-[0.98]
          ${isOpen ? 'border-primary-500 ring-2 ring-primary-500/20' : ''}
          ${disabled ? 'opacity-50 cursor-not-allowed active:scale-100' : ''}
        `}
        aria-expanded={isOpen}
        aria-haspopup="listbox"
      >
        {renderValue ? renderValue(selectedOption!) : defaultRenderValue(selectedOption)}
        <ChevronDown
          className={`w-4 h-4 text-gray-400 transition-transform duration-200 ${
            isOpen ? 'rotate-180' : ''
          }`}
        />
      </button>

      {isOpen && (
        <div
          className="absolute top-full left-0 mt-1.5 w-full min-w-[200px] bg-white rounded-xl shadow-xl border border-gray-100 z-50 animate-in fade-in slide-in-from-top-1 duration-200 overflow-hidden"
          role="listbox"
        >
          {searchable && (
            <div className="p-2 border-b border-gray-100">
              <div className="relative">
                <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input
                  ref={searchInputRef}
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  onKeyDown={handleKeyDown}
                  placeholder={searchPlaceholder}
                  className="w-full pl-9 pr-3 py-2 text-sm bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:bg-white focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 transition-all duration-200"
                />
              </div>
            </div>
          )}

          {categories && !searchQuery && (
            <div className="flex border-b border-gray-100 bg-gray-50/50">
              {categories.map((cat) => (
                <button
                  key={cat.value}
                  onClick={() => setSelectedCategory(cat.value)}
                  className={`flex-1 px-3 py-2.5 text-xs font-medium transition-all duration-200 border-b-2 ${
                    selectedCategory === cat.value
                      ? 'text-primary-600 border-primary-600 bg-white'
                      : 'text-gray-600 border-transparent hover:text-gray-900 hover:bg-gray-100/50'
                  }`}
                >
                  {cat.label}
                </button>
              ))}
            </div>
          )}

          <div className="max-h-64 overflow-y-auto py-1">
            {filteredOptions.length === 0 ? (
              <div className="px-3 py-4 text-sm text-center text-gray-500">{noOptionsMessage}</div>
            ) : (
              filteredOptions.map((option, index) => {
                const isSelected = option.value === value;
                const isHighlighted = index === highlightedIndex;

                return (
                  <button
                    key={String(option.value)}
                    type="button"
                    onClick={() => handleSelect(option)}
                    onMouseEnter={() => setHighlightedIndex(index)}
                    disabled={option.disabled}
                    className={`
                      w-full flex items-center justify-between gap-2 px-3 py-2 text-left text-sm transition-colors duration-150
                      ${option.disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}
                      ${isSelected ? 'bg-primary-50 text-primary-700' : isHighlighted ? 'bg-gray-50' : 'hover:bg-gray-50'}
                    `}
                    role="option"
                    aria-selected={isSelected}
                  >
                    {renderOption
                      ? renderOption(option, isSelected)
                      : defaultRenderOption(option, isSelected)}
                    {isSelected && <Check className="w-4 h-4 text-primary-600 flex-shrink-0" />}
                  </button>
                );
              })
            )}
          </div>

          <div className="px-3 py-2 text-xs flex justify-between border-t border-gray-100 text-gray-400 bg-gray-50/50">
            <span>使用 ↑↓ 导航，Enter 选择</span>
            <span>共 {filteredOptions.length} 个</span>
          </div>
        </div>
      )}
    </div>
  );
}

import { renderHook, act, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ReactNode } from 'react';
import { useHoverPrefetch, useHoverPrefetchHandlers } from '../useHoverPrefetch';

const createWrapper = () => {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: {
        retry: false,
      },
    },
  });

  return function Wrapper({ children }: { children: ReactNode }) {
    return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>;
  };
};

describe('useHoverPrefetch', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('should not prefetch when disabled', async () => {
    const queryFn = jest.fn().mockResolvedValue({ data: 'test' });
    const { result } = renderHook(() => useHoverPrefetch({ enabled: false }), {
      wrapper: createWrapper(),
    });

    act(() => {
      result.current.prefetch({
        queryKey: ['test'],
        queryFn,
      });
    });

    jest.runAllTimers();

    await waitFor(() => {
      expect(queryFn).not.toHaveBeenCalled();
    });
  });

  it('should prefetch after delay', async () => {
    const queryFn = jest.fn().mockResolvedValue({ data: 'test' });
    const { result } = renderHook(() => useHoverPrefetch({ delay: 100 }), {
      wrapper: createWrapper(),
    });

    act(() => {
      result.current.prefetch({
        queryKey: ['test'],
        queryFn,
      });
    });

    expect(queryFn).not.toHaveBeenCalled();

    act(() => {
      jest.advanceTimersByTime(100);
    });

    await waitFor(() => {
      expect(queryFn).toHaveBeenCalled();
    });
  });

  it('should cancel pending prefetch', async () => {
    const queryFn = jest.fn().mockResolvedValue({ data: 'test' });
    const { result } = renderHook(() => useHoverPrefetch({ delay: 100 }), {
      wrapper: createWrapper(),
    });

    act(() => {
      result.current.prefetch({
        queryKey: ['test'],
        queryFn,
      });
    });

    act(() => {
      result.current.cancelPrefetch();
    });

    act(() => {
      jest.runAllTimers();
    });

    await waitFor(() => {
      expect(queryFn).not.toHaveBeenCalled();
    });
  });

  it('should call onSuccess callback', async () => {
    const queryFn = jest.fn().mockResolvedValue({ data: 'test' });
    const onSuccess = jest.fn();
    const { result } = renderHook(() =>
      useHoverPrefetch({ delay: 0, onSuccess })
    , {
      wrapper: createWrapper(),
    });

    act(() => {
      result.current.prefetch({
        queryKey: ['test'],
        queryFn,
      });
    });

    act(() => {
      jest.runAllTimers();
    });

    await waitFor(() => {
      expect(onSuccess).toHaveBeenCalled();
    });
  });

  it('should call onError callback on failure', async () => {
    const error = new Error('Test error');
    const queryFn = jest.fn().mockRejectedValue(error);
    const onError = jest.fn();
    const { result } = renderHook(() =>
      useHoverPrefetch({ delay: 0, onError })
    , {
      wrapper: createWrapper(),
    });

    act(() => {
      result.current.prefetch({
        queryKey: ['test'],
        queryFn,
      });
    });

    act(() => {
      jest.runAllTimers();
    });

    await waitFor(() => {
      expect(onError).toHaveBeenCalledWith(error);
    });
  });
});

describe('useHoverPrefetchHandlers', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('should return mouse event handlers', () => {
    const queryFn = jest.fn().mockResolvedValue({ data: 'test' });
    const { result } = renderHook(() =>
      useHoverPrefetchHandlers({
        queryKey: ['test'],
        queryFn,
      })
    , {
      wrapper: createWrapper(),
    });

    expect(result.current.onMouseEnter).toBeDefined();
    expect(result.current.onMouseLeave).toBeDefined();
    expect(result.current.isPrefetching).toBe(false);
  });

  it('should prefetch on mouse enter', async () => {
    const queryFn = jest.fn().mockResolvedValue({ data: 'test' });
    const { result } = renderHook(() =>
      useHoverPrefetchHandlers(
        {
          queryKey: ['test'],
          queryFn,
        },
        { delay: 0 }
      )
    , {
      wrapper: createWrapper(),
    });

    act(() => {
      result.current.onMouseEnter();
    });

    act(() => {
      jest.runAllTimers();
    });

    await waitFor(() => {
      expect(queryFn).toHaveBeenCalled();
    });
  });

  it('should cancel prefetch on mouse leave', async () => {
    const queryFn = jest.fn().mockResolvedValue({ data: 'test' });
    const { result } = renderHook(() =>
      useHoverPrefetchHandlers(
        {
          queryKey: ['test'],
          queryFn,
        },
        { delay: 100 }
      )
    , {
      wrapper: createWrapper(),
    });

    act(() => {
      result.current.onMouseEnter();
    });

    act(() => {
      result.current.onMouseLeave();
    });

    act(() => {
      jest.runAllTimers();
    });

    await waitFor(() => {
      expect(queryFn).not.toHaveBeenCalled();
    });
  });
});

