'use client';

import { useMemo } from 'react';

export type DataFreshnessStatus = 'fresh' | 'stale' | 'expired';

export interface UseDataFreshnessReturn {
  status: DataFreshnessStatus;
  ageInMinutes: number;
  message: string;
  shouldRefresh: boolean;
}

export function useDataFreshness(
  lastUpdated: Date | null,
  maxFreshTime: number = 5,
  maxStaleTime: number = 30
): UseDataFreshnessReturn {
  const result = useMemo(() => {
    if (!lastUpdated) {
      return {
        status: 'expired' as DataFreshnessStatus,
        ageInMinutes: 0,
        message: '数据未加载',
        shouldRefresh: true,
      };
    }

    const ageInMinutes = (Date.now() - lastUpdated.getTime()) / 60000;

    if (ageInMinutes < maxFreshTime) {
      return {
        status: 'fresh' as DataFreshnessStatus,
        ageInMinutes,
        message: '数据新鲜',
        shouldRefresh: false,
      };
    }

    if (ageInMinutes < maxStaleTime) {
      return {
        status: 'stale' as DataFreshnessStatus,
        ageInMinutes,
        message: '数据即将过期',
        shouldRefresh: false,
      };
    }

    return {
      status: 'expired' as DataFreshnessStatus,
      ageInMinutes,
      message: '数据已过期',
      shouldRefresh: true,
    };
  }, [lastUpdated, maxFreshTime, maxStaleTime]);

  return result;
}

'use client';

import { useMemo } from 'react';

/**
 * 偏离级别类型
 */
export type DeviationLevel = 'none' | 'warning' | 'danger';

/**
 * 偏离值类型
 */
export type DeviationType = 'percentage' | 'absolute';

/**
 * 阈值配置接口
 */
export interface DeviationThreshold {
  /** 警告阈值 */
  warning: number;
  /** 危险阈值 */
  danger: number;
}

/**
 * 偏离检测结果接口
 */
export interface DeviationDetectionResult {
  /** 偏离级别 */
  level: DeviationLevel;
  /** 是否处于警告状态 */
  isWarning: boolean;
  /** 是否处于危险状态 */
  isDanger: boolean;
  /** 是否偏离正常范围 */
  isDeviated: boolean;
  /** 颜色类名 */
  colorClass: string;
  /** 背景颜色类名 */
  bgClass: string;
  /** 边框颜色类名 */
  borderClass: string;
  /** 文字颜色类名 */
  textClass: string;
  /** 脉冲动画类名 */
  pulseClass: string;
}

/**
 * 默认阈值配置
 */
export const DEFAULT_DEVIATION_THRESHOLD: DeviationThreshold = {
  warning: 1,
  danger: 2,
};

/**
 * 偏离检测 Hook
 * @param value 偏离值（百分比或绝对值）
 * @param threshold 阈值配置
 * @param type 偏离值类型
 * @returns 偏离检测结果
 */
export function useDeviationDetection(
  value: number,
  threshold: Partial<DeviationThreshold> = {},
  type: DeviationType = 'percentage'
): DeviationDetectionResult {
  const mergedThreshold = useMemo(
    () => ({
      ...DEFAULT_DEVIATION_THRESHOLD,
      ...threshold,
    }),
    [threshold]
  );

  // 计算绝对值用于比较
  const absoluteValue = Math.abs(value);

  // 根据类型转换阈值
  const warningThreshold =
    type === 'percentage' ? mergedThreshold.warning : mergedThreshold.warning;
  const dangerThreshold = type === 'percentage' ? mergedThreshold.danger : mergedThreshold.danger;

  return useMemo(() => {
    let level: DeviationLevel = 'none';

    if (absoluteValue > dangerThreshold) {
      level = 'danger';
    } else if (absoluteValue > warningThreshold) {
      level = 'warning';
    }

    const isWarning = level === 'warning';
    const isDanger = level === 'danger';
    const isDeviated = isWarning || isDanger;

    // 颜色配置
    const colorConfig = {
      none: {
        color: 'text-gray-600',
        bg: 'bg-gray-50',
        border: 'border-gray-200',
        text: 'text-gray-700',
        pulse: '',
      },
      warning: {
        color: 'text-amber-500',
        bg: 'bg-amber-50 dark:bg-amber-950/30',
        border: 'border-amber-200 dark:border-amber-800',
        text: 'text-amber-700 dark:text-amber-400',
        pulse: 'animate-pulse-warning',
      },
      danger: {
        color: 'text-red-500',
        bg: 'bg-red-50 dark:bg-red-950/30',
        border: 'border-red-200 dark:border-red-800',
        text: 'text-red-700 dark:text-red-400',
        pulse: 'animate-pulse-danger',
      },
    };

    const config = colorConfig[level];

    return {
      level,
      isWarning,
      isDanger,
      isDeviated,
      colorClass: config.color,
      bgClass: config.bg,
      borderClass: config.border,
      textClass: config.text,
      pulseClass: config.pulse,
    };
  }, [absoluteValue, warningThreshold, dangerThreshold]);
}

/**
 * 批量偏离检测 Hook
 * @param values 偏离值数组
 * @param threshold 阈值配置
 * @param type 偏离值类型
 * @returns 批量偏离检测结果
 */
export function useBatchDeviationDetection(
  values: number[],
  threshold: Partial<DeviationThreshold> = {},
  type: DeviationType = 'percentage'
): {
  results: DeviationDetectionResult[];
  hasWarning: boolean;
  hasDanger: boolean;
  maxDeviation: number;
  maxLevel: DeviationLevel;
} {
  const mergedThreshold = useMemo(
    () => ({
      ...DEFAULT_DEVIATION_THRESHOLD,
      ...threshold,
    }),
    [threshold]
  );

  const results = useMemo(() => {
    return values.map((value) => useDeviationDetection(value, mergedThreshold, type));
  }, [values, mergedThreshold, type]);

  return useMemo(() => {
    const hasWarning = results.some((r) => r.isWarning);
    const hasDanger = results.some((r) => r.isDanger);
    const maxDeviation = Math.max(...values.map(Math.abs), 0);

    let maxLevel: DeviationLevel = 'none';
    if (hasDanger) {
      maxLevel = 'danger';
    } else if (hasWarning) {
      maxLevel = 'warning';
    }

    return {
      results,
      hasWarning,
      hasDanger,
      maxDeviation,
      maxLevel,
    };
  }, [results, values]);
}

export default useDeviationDetection;

'use client';

import { useCallback, useEffect, useRef, useState } from 'react';

import { track } from '@vercel/analytics';

import { env } from '@/lib/config/env';
import {
  onMetric,
  reportCustomMetric,
  getPerformanceScore,
  type WebVitalMetric,
  PERFORMANCE_THRESHOLDS,
} from '@/lib/monitoring/webVitals';

export interface OperationMetric {
  name: string;
  startTime: number;
  duration: number;
  metadata?: Record<string, unknown>;
}

export interface ComponentRenderMetric {
  componentName: string;
  renderTime: number;
  renderCount: number;
  mountTime?: number;
  updateCount?: number;
}

export interface PerformanceReport {
  timestamp: number;
  url: string;
  webVitals: WebVitalMetric[];
  operations: OperationMetric[];
  components: ComponentRenderMetric[];
  memory?: {
    usedJSHeapSize?: number;
    totalJSHeapSize?: number;
    jsHeapSizeLimit?: number;
  };
}

const isProduction = env.app.isProduction;
const enableAnalytics = env.features.enableAnalytics;

export function usePerformanceTracker(operationName: string) {
  const startTimeRef = useRef<number>(0);
  const isTrackingRef = useRef<boolean>(false);

  const start = useCallback(() => {
    startTimeRef.current = performance.now();
    isTrackingRef.current = true;
  }, []);

  const end = useCallback(
    (metadata?: Record<string, unknown>) => {
      if (!isTrackingRef.current) return 0;

      const duration = performance.now() - startTimeRef.current;
      isTrackingRef.current = false;

      const _metric: OperationMetric = {
        name: operationName,
        startTime: startTimeRef.current,
        duration,
        metadata,
      };

      if (isProduction && enableAnalytics) {
        track('performance-operation', {
          operation: operationName,
          duration: Math.round(duration),
          ...metadata,
        });
      }

      // Performance logging disabled in development to avoid console noise

      return duration;
    },
    [operationName]
  );

  const measureAsync = useCallback(
    async <T>(fn: () => Promise<T>, metadata?: Record<string, unknown>): Promise<T> => {
      start();
      try {
        const result = await fn();
        end(metadata);
        return result;
      } catch (error) {
        end({ ...metadata, error: true });
        throw error;
      }
    },
    [start, end]
  );

  return { start, end, measureAsync };
}

export function useComponentPerformance(componentName: string, enabled = true) {
  const renderCountRef = useRef(0);
  const mountTimeRef = useRef<number>(0);
  const updateCountRef = useRef(0);
  const [metrics, setMetrics] = useState<ComponentRenderMetric | null>(null);
  const [renderCount, setRenderCount] = useState(0);

  useEffect(() => {
    if (!enabled) return;

    mountTimeRef.current = performance.now();

    return () => {
      const mountDuration = performance.now() - mountTimeRef.current;

      if (isProduction && enableAnalytics) {
        track('component-performance', {
          component: componentName,
          renderCount: renderCountRef.current,
          mountDuration: Math.round(mountDuration),
          updateCount: updateCountRef.current,
        });
      }

      // Component performance logging disabled in development
    };
  }, [componentName, enabled]);

  useEffect(() => {
    if (!enabled) return;

    renderCountRef.current++;
    const renderTime = performance.now();
    const currentRenderCount = renderCountRef.current;

    setRenderCount(currentRenderCount);
    setMetrics((prev) => ({
      componentName,
      renderTime,
      renderCount: currentRenderCount,
      mountTime: prev?.mountTime,
      updateCount: updateCountRef.current,
    }));
  }, [componentName, enabled]);

  const markUpdate = useCallback(() => {
    updateCountRef.current++;
  }, []);

  return { metrics, markUpdate, renderCount };
}

export function useWebVitalsMonitor() {
  const [metrics, setMetrics] = useState<WebVitalMetric[]>([]);
  const [score, setScore] = useState<number>(100);

  useEffect(() => {
    const unsubscribe = onMetric((metric) => {
      setMetrics((prev) => {
        const existing = prev.findIndex((m) => m.name === metric.name);
        if (existing >= 0) {
          const updated = [...prev];
          updated[existing] = metric;
          return updated;
        }
        return [...prev, metric];
      });
    });

    const updateScore = () => {
      const result = getPerformanceScore();
      setScore(result.score);
    };

    updateScore();
    const interval = setInterval(updateScore, 5000);

    return () => {
      unsubscribe();
      clearInterval(interval);
    };
  }, []);

  const getMetricByName = useCallback(
    (name: string): WebVitalMetric | undefined => {
      return metrics.find((m) => m.name === name);
    },
    [metrics]
  );

  const getRating = useCallback(
    (name: string, value: number): 'good' | 'needs-improvement' | 'poor' => {
      const thresholds = PERFORMANCE_THRESHOLDS[name as keyof typeof PERFORMANCE_THRESHOLDS];
      if (!thresholds) return 'good';
      if (value <= thresholds.good) return 'good';
      if (value <= thresholds.poor) return 'needs-improvement';
      return 'poor';
    },
    []
  );

  return { metrics, score, getMetricByName, getRating };
}

export function useMemoryMonitor(enabled = true) {
  const [memoryInfo, setMemoryInfo] = useState<{
    usedJSHeapSize: number;
    totalJSHeapSize: number;
    jsHeapSizeLimit: number;
    usagePercentage: number;
  } | null>(null);

  useEffect(() => {
    if (!enabled || typeof window === 'undefined') return;

    const updateMemoryInfo = () => {
      const memory = (performance as Performance & { memory?: MemoryInfo }).memory;
      if (memory) {
        setMemoryInfo({
          usedJSHeapSize: memory.usedJSHeapSize,
          totalJSHeapSize: memory.totalJSHeapSize,
          jsHeapSizeLimit: memory.jsHeapSizeLimit,
          usagePercentage: (memory.usedJSHeapSize / memory.jsHeapSizeLimit) * 100,
        });
      }
    };

    updateMemoryInfo();
    const interval = setInterval(updateMemoryInfo, 10000);

    return () => clearInterval(interval);
  }, [enabled]);

  return memoryInfo;
}

export function usePerformanceReport() {
  const [report, setReport] = useState<PerformanceReport | null>(null);

  const generateReport = useCallback(() => {
    const webVitals: WebVitalMetric[] = [];
    const memory = (performance as Performance & { memory?: MemoryInfo }).memory;

    const perfReport: PerformanceReport = {
      timestamp: Date.now(),
      url: window.location.href,
      webVitals,
      operations: [],
      components: [],
      memory: memory
        ? {
            usedJSHeapSize: memory.usedJSHeapSize,
            totalJSHeapSize: memory.totalJSHeapSize,
            jsHeapSizeLimit: memory.jsHeapSizeLimit,
          }
        : undefined,
    };

    setReport(perfReport);
    return perfReport;
  }, []);

  const reportOperation = useCallback((operation: OperationMetric) => {
    if (isProduction && enableAnalytics) {
      track('custom-operation', {
        name: operation.name,
        duration: Math.round(operation.duration),
        ...operation.metadata,
      });
    }

    reportCustomMetric(operation.name, operation.duration);
  }, []);

  return { report, generateReport, reportOperation };
}

export function useLongTaskMonitor(threshold = 50) {
  const [longTasks, setLongTasks] = useState<PerformanceEntry[]>([]);

  useEffect(() => {
    if (typeof window === 'undefined' || !('PerformanceObserver' in window)) return;

    const observer = new PerformanceObserver((list) => {
      const entries = list.getEntries();
      setLongTasks((prev) => [...prev, ...entries].slice(-50));

      entries.forEach((entry) => {
        if (isProduction && enableAnalytics) {
          track('long-task', {
            duration: Math.round(entry.duration),
            startTime: Math.round(entry.startTime),
            name: entry.name,
          });
        }

        // Long task warnings disabled in development
      });
    });

    try {
      observer.observe({ entryTypes: ['longtask'] });
    } catch {
      console.warn('Long task monitoring not supported');
    }

    return () => observer.disconnect();
  }, [threshold]);

  return longTasks;
}

export function useResourceTimingMonitor() {
  const [resources, setResources] = useState<PerformanceResourceTiming[]>([]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const updateResources = () => {
      const entries = performance.getEntriesByType('resource') as PerformanceResourceTiming[];
      setResources(entries.slice(-100));
    };

    updateResources();
    const interval = setInterval(updateResources, 10000);

    return () => clearInterval(interval);
  }, []);

  const getSlowResources = useCallback(
    (threshold = 1000) => {
      return resources.filter((r) => r.duration > threshold);
    },
    [resources]
  );

  const getResourceByType = useCallback(
    (type: 'script' | 'stylesheet' | 'image' | 'fetch' | 'xhr') => {
      return resources.filter((r) => r.initiatorType === type);
    },
    [resources]
  );

  return { resources, getSlowResources, getResourceByType };
}

interface MemoryInfo {
  usedJSHeapSize: number;
  totalJSHeapSize: number;
  jsHeapSizeLimit: number;
}

