    targets: [
      {
        queryKey: ['oracles', 'detail', 'band-protocol'],
        queryFn: () => fetch('/api/oracles/band-protocol').then((r) => r.json()),
        type: 'network',
        priority: 'high',
      },
    ],
  },
  '/redstone': {
    route: '/redstone',
    priority: 'high',
