export interface BatchIndicatorOptions {
  chunkSize?: number;
  onProgress?: (progress: number) => void;
}

export function useBatchTechnicalIndicators(options: BatchIndicatorOptions = {}) {
  const { chunkSize = 1000, onProgress } = options;
  const [isCalculating, setIsCalculating] = useState(false);
  const [progress, setProgress] = useState(0);
  const abortControllerRef = useRef<AbortController | null>(null);

  const calculateBatch = useCallback(
    async (
      data: IndicatorDataPoint[],
      settings: IndicatorSettings
    ): Promise<IndicatorDataPoint[]> => {
      if (data.length === 0) return data;

      abortControllerRef.current = new AbortController();
      setIsCalculating(true);
      setProgress(0);

      return new Promise((resolve, reject) => {
        const results: IndicatorDataPoint[] = [];
        let index = 0;

        const processChunk = () => {
          if (abortControllerRef.current?.signal.aborted) {
            reject(new Error('Calculation aborted'));
            return;
          }

          const endIndex = Math.min(index + chunkSize, data.length);
          const chunk = data.slice(0, endIndex);

          const processedChunk = calculateAllIndicators(chunk, settings);

          results.length = 0;
          results.push(...processedChunk);

          index = endIndex;
          const currentProgress = Math.round((index / data.length) * 100);
          setProgress(currentProgress);
          onProgress?.(currentProgress);

          if (index < data.length) {
            requestAnimationFrame(processChunk);
          } else {
            setIsCalculating(false);
            resolve(results);
          }
        };

        requestAnimationFrame(processChunk);
      });
    },
    [chunkSize, onProgress]
  );

  const abort = useCallback(() => {
    abortControllerRef.current?.abort();
    setIsCalculating(false);
  }, []);

  useEffect(() => {
    return () => {
      abort();
    };
  }, [abort]);

  return { calculateBatch, isCalculating, progress, abort };
}

export default useTechnicalIndicators;

'use client';

import { useEffect, useRef, useState, useCallback, useMemo } from 'react';

import {
  type WebSocketManager,
  type WebSocketStatus,
  type WebSocketMessage,
  type ConnectionStats,
  type WebSocketConfig,
  createWebSocketManager,
  releaseWebSocketManager,
} from '@/lib/realtime/WebSocketManager';
import { createLogger } from '@/lib/utils/logger';

const logger = createLogger('useWebSocket');

// ==================== Type Definitions ====================

export interface UseWebSocketOptions {
  url: string;
  channels?: string[];
  autoConnect?: boolean;
  reconnectInterval?: number;
  maxReconnectAttempts?: number;
  heartbeatInterval?: number;
  onConnect?: () => void;
  onDisconnect?: () => void;
  onError?: (error: Error) => void;
  onReconnect?: (attempt: number) => void;
}

export interface UseWebSocketReturn<T = unknown> {
  status: WebSocketStatus;
  lastMessage: WebSocketMessage<T> | null;
  lastUpdated: Date | null;
  stats: ConnectionStats;
  connect: () => void;
  disconnect: () => void;
  reconnect: () => void;
  subscribe: (channel: string, handler: (message: WebSocketMessage<T>) => void) => () => void;
  send: (message: Record<string, unknown>) => void;
  isConnected: boolean;
  isConnecting: boolean;
  isReconnecting: boolean;
}

// ==================== Hook Implementation ====================

/**
 * Optimized WebSocket Hook
 * Provides type safety, performance monitoring, and automatic reconnection
 */
export function useWebSocket<T = unknown>(options: UseWebSocketOptions): UseWebSocketReturn<T> {
  const {
    url,
    channels = [],
    autoConnect = true,
    reconnectInterval,
    maxReconnectAttempts,
    heartbeatInterval,
    onConnect,
    onDisconnect,
    onError,
    onReconnect,
  } = options;

  const managerRef = useRef<WebSocketManager | null>(null);
  const [status, setStatus] = useState<WebSocketStatus>('disconnected');
  const [lastMessage, setLastMessage] = useState<WebSocketMessage<T> | null>(null);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [stats, setStats] = useState<ConnectionStats>({
    connectionCount: 0,
    reconnectionCount: 0,
    messageCount: 0,
    errorCount: 0,
    lastConnectedAt: null,
    lastDisconnectedAt: null,
    totalUptime: 0,
    averageLatency: 0,
  });

  // Create WebSocket manager
  useEffect(() => {
    const config: WebSocketConfig = {
      url,
      reconnectInterval,
      maxReconnectAttempts,
      heartbeatInterval,
      onConnect: () => {
        logger.debug('WebSocket connected');
        onConnect?.();
      },
      onDisconnect: () => {
        logger.debug('WebSocket disconnected');
        onDisconnect?.();
      },
      onError: (error) => {
        logger.error('WebSocket error', error);
        onError?.(error);
      },
      onReconnect: (attempt) => {
        logger.debug(`WebSocket reconnecting, attempt ${attempt}`);
        onReconnect?.(attempt);
      },
    };

    managerRef.current = createWebSocketManager(config);

    // Listen for status changes
    const unsubscribeStatus = managerRef.current.onStatusChange((newStatus) => {
      setStatus(newStatus);
      setStats(managerRef.current!.getStats());
    });

    if (autoConnect) {
      managerRef.current.connect();
    }

    return () => {
      unsubscribeStatus();
      if (managerRef.current) {
        releaseWebSocketManager(config);
        managerRef.current = null;
      }
    };
  }, [
    url,
    autoConnect,
    reconnectInterval,
    maxReconnectAttempts,
    heartbeatInterval,
    onConnect,
    onDisconnect,
    onError,
    onReconnect,
  ]);

  // Subscribe to channels
  const channelsKey = useMemo(() => channels.join(','), [channels]);

  useEffect(() => {
    if (!managerRef.current || channels.length === 0) return;

    const unsubscribes: (() => void)[] = [];

    channels.forEach((channel) => {
      const unsubscribe = managerRef.current!.subscribe<T>(channel, (message) => {
        setLastMessage(message);
        setLastUpdated(new Date());
        setStats(managerRef.current!.getStats());
      });
      unsubscribes.push(unsubscribe);
    });

    return () => {
      unsubscribes.forEach((unsubscribe) => unsubscribe());
    };
  }, [channelsKey, channels]);

  // Control methods
  const connect = useCallback(() => {
    managerRef.current?.connect();
  }, []);

  const disconnect = useCallback(() => {
    managerRef.current?.disconnect();
  }, []);

  const reconnect = useCallback(() => {
    managerRef.current?.reconnect();
  }, []);

  const subscribe = useCallback(
    (channel: string, handler: (message: WebSocketMessage<T>) => void) => {
      if (!managerRef.current) {
        return () => {};
      }
      return managerRef.current.subscribe<T>(channel, handler);
    },
    []
  );

  const send = useCallback((message: Record<string, unknown>) => {
    managerRef.current?.send(message);
  }, []);

  return {
    status,
    lastMessage,
    lastUpdated,
    stats,
    connect,
    disconnect,
    reconnect,
    subscribe,
    send,
    isConnected: status === 'connected',
    isConnecting: status === 'connecting',
    isReconnecting: status === 'reconnecting',
  };
}

