import { NextResponse } from 'next/server';

import {
  AppError,
  isAppError,
  ValidationError,
  AuthenticationError,
  AuthorizationError,
  NotFoundError,
  RateLimitError,
  InternalError,
  PriceFetchError,
  OracleClientError,
} from '@/lib/errors';
import { createLogger } from '@/lib/utils/logger';

import { ApiResponseBuilder } from '../response';

const logger = createLogger('enhanced-error-middleware');

export interface EnhancedErrorMiddlewareOptions {
  includeStackTrace?: boolean;
  logErrors?: boolean;
  includeRequestId?: boolean;
  includeTimestamp?: boolean;
  includeDocumentationUrl?: boolean;
  errorCodePrefix?: string;
}

export interface StandardizedErrorResponse {
  success: false;
  error: {
    code: string;
    message: string;
    details?: Record<string, unknown>;
    retryable: boolean;
    i18nKey?: string;
    documentationUrl?: string;
    requestId?: string;
    timestamp: number;
    stackTrace?: string;
  };
  meta: {
    requestId?: string;
    timestamp: number;
    path?: string;
    method?: string;
  };
}

/**
 * HTTP 状态码到错误码的映射
 */
const HTTP_STATUS_TO_ERROR_CODE: Record<number, string> = {
  400: 'BAD_REQUEST',
  401: 'UNAUTHORIZED',
  403: 'FORBIDDEN',
  404: 'NOT_FOUND',
  405: 'METHOD_NOT_ALLOWED',
  408: 'REQUEST_TIMEOUT',
  409: 'CONFLICT',
  410: 'GONE',
  413: 'PAYLOAD_TOO_LARGE',
  415: 'UNSUPPORTED_MEDIA_TYPE',
  422: 'UNPROCESSABLE_ENTITY',
  429: 'RATE_LIMIT_EXCEEDED',
  500: 'INTERNAL_SERVER_ERROR',
  502: 'BAD_GATEWAY',
  503: 'SERVICE_UNAVAILABLE',
  504: 'GATEWAY_TIMEOUT',
};

/**
 * 错误码到文档 URL 的映射
 */
const ERROR_CODE_DOCUMENTATION: Record<string, string> = {
  VALIDATION_ERROR: '/docs/errors/validation',
  AUTHENTICATION_ERROR: '/docs/errors/authentication',
  AUTHORIZATION_ERROR: '/docs/errors/authorization',
  NOT_FOUND: '/docs/errors/not-found',
  RATE_LIMIT_EXCEEDED: '/docs/errors/rate-limit',
  INTERNAL_ERROR: '/docs/errors/internal',
  PRICE_FETCH_ERROR: '/docs/errors/price-fetch',
  ORACLE_CLIENT_ERROR: '/docs/errors/oracle-client',
  BAD_REQUEST: '/docs/errors/bad-request',
  UNAUTHORIZED: '/docs/errors/unauthorized',
  FORBIDDEN: '/docs/errors/forbidden',
  CONFLICT: '/docs/errors/conflict',
  SERVICE_UNAVAILABLE: '/docs/errors/service-unavailable',
};

/**
 * 生成唯一请求 ID
 */
function generateRequestId(): string {
  return `${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
}

/**
 * 获取错误对应的文档 URL
 */
function getDocumentationUrl(errorCode: string, baseUrl?: string): string | undefined {
  const docPath = ERROR_CODE_DOCUMENTATION[errorCode];
  if (!docPath) return undefined;
  return baseUrl ? `${baseUrl}${docPath}` : docPath;
}

/**
 * 判断错误是否可重试
 */
function isRetryableError(error: unknown): boolean {
  if (isAppError(error)) {
    return !error.isOperational;
  }

  if (error instanceof Error) {
    const retryablePatterns = [
      'network',
      'fetch',
      'timeout',
      'ECONNREFUSED',
      'ECONNRESET',
      'ETIMEDOUT',
      'ENOTFOUND',
      'EAI_AGAIN',
    ];
    return retryablePatterns.some((pattern) =>
      error.message.toLowerCase().includes(pattern.toLowerCase())
    );
  }

  return false;
}

/**
 * 提取 HTTP 状态码
 */
function extractStatusCode(error: unknown): number {
  if (isAppError(error)) {
    return error.statusCode;
  }

  if (error instanceof Error) {
    const statusMatch = error.message.match(/\b(\d{3})\b/);
    if (statusMatch) {
      const status = parseInt(statusMatch[1], 10);
      if (status >= 100 && status < 600) {
        return status;
      }
    }
  }

  return 500;
}

/**
 * 创建增强的错误响应
 */
function createErrorResponse(
  error: unknown,
  options: EnhancedErrorMiddlewareOptions,
  requestInfo?: { requestId?: string; path?: string; method?: string }
): StandardizedErrorResponse {
  const timestamp = Date.now();
  const requestId = requestInfo?.requestId || generateRequestId();

  let errorCode: string;
  let message: string;
  let details: Record<string, unknown> | undefined;
  let i18nKey: string | undefined;
  let stackTrace: string | undefined;

  if (isAppError(error)) {
    errorCode = error.code;
    message = error.message;
    details = error.details as Record<string, unknown> | undefined;
    i18nKey = error.i18nKey;
  } else if (error instanceof SyntaxError && error.message.includes('JSON')) {
    errorCode = 'INVALID_JSON';
    message = 'Invalid JSON in request body';
    i18nKey = 'errors.invalidJson';
  } else if (error instanceof Error) {
    const statusCode = extractStatusCode(error);
    errorCode = HTTP_STATUS_TO_ERROR_CODE[statusCode] || 'INTERNAL_ERROR';
    message = error.message;

    if (options.includeStackTrace && process.env.NODE_ENV !== 'production') {
      stackTrace = error.stack;
    }
  } else {
    errorCode = 'UNKNOWN_ERROR';
    message = 'An unexpected error occurred';
  }

  const documentationUrl = options.includeDocumentationUrl
    ? getDocumentationUrl(errorCode)
    : undefined;

  return {
    success: false,
    error: {
      code: errorCode,
      message,
      details,
      retryable: isRetryableError(error),
      i18nKey,
      documentationUrl,
      requestId: options.includeRequestId ? requestId : undefined,
      timestamp,
      stackTrace,
    },
    meta: {
      requestId: options.includeRequestId ? requestId : undefined,
      timestamp,
      path: requestInfo?.path,
      method: requestInfo?.method,
    },
  };
}

/**
 * 创建增强的错误处理中间件
 */
export function createEnhancedErrorMiddleware(options: EnhancedErrorMiddlewareOptions = {}) {
  const {
    includeStackTrace = false,
    logErrors = true,
    includeRequestId = true,
    includeTimestamp = true,
    includeDocumentationUrl = true,
  } = options;

  return async (
    error: unknown,
    request?: Request,
    requestId?: string
  ): Promise<NextResponse<StandardizedErrorResponse>> => {
    const generatedRequestId = requestId || generateRequestId();
    const requestInfo = request
      ? {
          requestId: generatedRequestId,
          path: new URL(request.url).pathname,
          method: request.method,
        }
      : { requestId: generatedRequestId };

    // 日志记录
    if (logErrors) {
      const logContext = {
        requestId: generatedRequestId,
        path: requestInfo.path,
        method: requestInfo.method,
        timestamp: new Date().toISOString(),
      };

      if (isAppError(error)) {
        logger.error(`[${error.code}] ${error.message}`, error as Error, {
          ...logContext,
          statusCode: error.statusCode,
          details: error.details,
          isOperational: error.isOperational,
        });
      } else if (error instanceof Error) {
        logger.error(`[Unhandled] ${error.message}`, error, logContext);
      } else {
        logger.error('[Unknown] Unknown error type', undefined, {
          ...logContext,
          error: String(error),
        });
      }
    }

    // 创建标准化错误响应
    const errorResponse = createErrorResponse(error, options, requestInfo);
    const statusCode = extractStatusCode(error);

    const response = NextResponse.json(errorResponse, { status: statusCode });

    // 添加响应头
    if (includeRequestId) {
      response.headers.set('X-Request-ID', generatedRequestId);
    }

    // 添加重试相关的响应头
    if (errorResponse.error.retryable) {
      response.headers.set('X-Retryable', 'true');
      const retryAfter = errorResponse.error.details?.retryAfter;
      if (typeof retryAfter === 'number') {
        response.headers.set('Retry-After', String(retryAfter));
      }
    }

    return response;
  };
}

/**
 * 默认的增强错误处理中间件
 */
export const enhancedErrorMiddleware = createEnhancedErrorMiddleware();

/**
 * 开发环境错误处理中间件（包含堆栈跟踪）
 */
export const developmentErrorMiddleware = createEnhancedErrorMiddleware({
  includeStackTrace: true,
  logErrors: true,
  includeRequestId: true,
  includeTimestamp: true,
  includeDocumentationUrl: true,
});

/**
 * 生产环境错误处理中间件（不包含敏感信息）
 */
export const productionErrorMiddleware = createEnhancedErrorMiddleware({
  includeStackTrace: false,
  logErrors: true,
  includeRequestId: true,
  includeTimestamp: true,
  includeDocumentationUrl: true,
});

/**
 * 包装 API 路由处理函数，自动处理错误
 */
export function withEnhancedErrorHandling<T>(
  handler: (request: Request) => Promise<T>,
  options?: EnhancedErrorMiddlewareOptions
): (request: Request) => Promise<T | NextResponse<StandardizedErrorResponse>> {
  const middleware = createEnhancedErrorMiddleware(options);

  return async (request: Request) => {
    try {
      return await handler(request);
    } catch (error) {
      return middleware(error, request);
    }
  };
}

/**
 * 错误分类工具函数
 */
export function classifyError(error: unknown): {
  category: 'client' | 'server' | 'network' | 'unknown';
  severity: 'low' | 'medium' | 'high' | 'critical';
} {
  if (isAppError(error)) {
    if (error.statusCode >= 500) {
      return { category: 'server', severity: 'high' };
    }
    if (error.statusCode >= 400) {
      return { category: 'client', severity: 'medium' };
    }
  }

  if (error instanceof Error) {
    const message = error.message.toLowerCase();
    if (
      message.includes('network') ||
      message.includes('fetch') ||
      message.includes('timeout') ||
      message.includes('econnrefused')
    ) {
      return { category: 'network', severity: 'high' };
    }
  }

  return { category: 'unknown', severity: 'critical' };
}

/**
 * 获取建议的用户操作
 */
export function getSuggestedAction(errorCode: string): string | undefined {
  const suggestions: Record<string, string> = {
    VALIDATION_ERROR: '请检查输入数据是否符合要求',
    AUTHENTICATION_ERROR: '请重新登录或检查您的认证信息',
    AUTHORIZATION_ERROR: '请确认您有权限执行此操作',
    NOT_FOUND: '请确认请求的资源存在',
    RATE_LIMIT_EXCEEDED: '请稍后再试，或降低请求频率',
    INTERNAL_ERROR: '请稍后重试，如果问题持续存在请联系支持团队',
    PRICE_FETCH_ERROR: '请检查网络连接或稍后重试',
    ORACLE_CLIENT_ERROR: '预言机服务暂时不可用，请稍后重试',
    BAD_REQUEST: '请检查请求参数是否正确',
    UNAUTHORIZED: '请先登录后再执行此操作',
    FORBIDDEN: '您没有权限访问此资源',
    CONFLICT: '请求与当前资源状态冲突，请刷新后重试',
    SERVICE_UNAVAILABLE: '服务暂时不可用，请稍后重试',
  };

  return suggestions[errorCode];
}

export default createEnhancedErrorMiddleware;

'use client';

import { useState, useCallback, useRef, useEffect } from 'react';

import { captureException, addBreadcrumb } from '@/lib/monitoring';
import { createLogger } from '@/lib/utils/logger';

import {
  EnhancedRetryManager,
  type EnhancedRetryConfig,
  type RetryResult,
  type RetryCallbacks,
  retryStrategies,
} from '../retry/enhancedRetry';

const logger = createLogger('error-recovery-hook');

/**
 * 恢复策略类型
 */
export type RecoveryStrategy = 'retry' | 'fallback' | 'cache' | 'graceful-degradation' | 'manual';

/**
 * 错误恢复状态
 */
export interface ErrorRecoveryState<T> {
  /** 当前数据 */
  data: T | null;
  /** 是否正在加载 */
  isLoading: boolean;
  /** 是否出错 */
  isError: boolean;
  /** 错误对象 */
  error: Error | null;
  /** 是否正在恢复 */
  isRecovering: boolean;
  /** 恢复尝试次数 */
  recoveryAttempts: number;
  /** 是否使用降级数据 */
  isDegraded: boolean;
  /** 最后一次成功的时间 */
  lastSuccessAt: number | null;
  /** 最后一次错误的时间 */
  lastErrorAt: number | null;
}

/**
 * 错误恢复操作
 */
export interface ErrorRecoveryActions<T> {
  /** 手动重试 */
  retry: () => Promise<void>;
  /** 使用降级数据 */
  useFallback: (fallbackData: T) => void;
  /** 重置状态 */
  reset: () => void;
  /** 清除错误 */
  clearError: () => void;
}

/**
 * 错误恢复配置
 */
export interface ErrorRecoveryConfig<T> {
  /** 重试配置 */
  retryConfig?: Partial<EnhancedRetryConfig>;
  /** 恢复策略 */
  recoveryStrategy?: RecoveryStrategy;
  /** 降级数据提供函数 */
  fallbackData?: () => T | Promise<T>;
  /** 缓存键（用于本地存储缓存） */
  cacheKey?: string;
  /** 缓存过期时间（毫秒） */
  cacheTTL?: number;
  /** 是否启用自动恢复 */
  autoRecover?: boolean;
  /** 最大恢复尝试次数 */
  maxRecoveryAttempts?: number;
  /** 恢复成功回调 */
  onRecoverySuccess?: (data: T) => void;
  /** 恢复失败回调 */
  onRecoveryFailure?: (error: Error) => void;
  /** 降级模式回调 */
  onDegraded?: (fallbackData: T) => void;
}

/**
 * 错误恢复 Hook 返回类型
 */
export interface UseErrorRecoveryReturn<T> extends ErrorRecoveryState<T>, ErrorRecoveryActions<T> {
  /** 执行数据获取操作 */
  execute: (operation: () => Promise<T>, operationName?: string) => Promise<void>;
  /** 当前使用的策略 */
  currentStrategy: RecoveryStrategy;
  /** 重试管理器实例 */
  retryManager: EnhancedRetryManager;
}

/**
 * 本地存储缓存管理器
 */
class LocalStorageCache<T> {
  private key: string;
  private ttl: number;

  constructor(key: string, ttl: number = 5 * 60 * 1000) {
    this.key = `error_recovery_cache_${key}`;
    this.ttl = ttl;
  }

  get(): T | null {
    if (typeof window === 'undefined') return null;

    try {
      const item = localStorage.getItem(this.key);
      if (!item) return null;

      const parsed = JSON.parse(item) as { data: T; timestamp: number };
      const now = Date.now();

      if (now - parsed.timestamp > this.ttl) {
        localStorage.removeItem(this.key);
        return null;
      }

      return parsed.data;
    } catch {
      return null;
    }
  }

  set(data: T): void {
    if (typeof window === 'undefined') return;

    try {
      localStorage.setItem(
        this.key,
        JSON.stringify({
          data,
          timestamp: Date.now(),
        })
      );
    } catch (error) {
      logger.warn('Failed to save to localStorage cache', { error });
    }
  }

  clear(): void {
    if (typeof window === 'undefined') return;

    try {
      localStorage.removeItem(this.key);
    } catch (error) {
      logger.warn('Failed to clear localStorage cache', { error });
    }
  }
}

/**
 * 错误恢复 Hook
 *
 * @example
 * ```tsx
 * const { data, isLoading, isError, error, retry, execute } = useErrorRecovery<PriceData>({
 *   retryConfig: retryStrategies.standard,
 *   fallbackData: () => ({ price: 0, timestamp: Date.now() }),
 *   cacheKey: 'price_data',
 * });
 *
 * useEffect(() => {
 *   execute(() => fetchPriceData(symbol), 'fetchPrice');
 * }, [symbol]);
 * ```
 */
export function useErrorRecovery<T>(
  config: ErrorRecoveryConfig<T> = {}
): UseErrorRecoveryReturn<T> {
  const {
    retryConfig,
    recoveryStrategy = 'retry',
    fallbackData,
    cacheKey,
    cacheTTL = 5 * 60 * 1000,
    autoRecover = true,
    maxRecoveryAttempts = 3,
    onRecoverySuccess,
    onRecoveryFailure,
    onDegraded,
  } = config;

  // 状态
  const [state, setState] = useState<ErrorRecoveryState<T>>({
    data: null,
    isLoading: false,
    isError: false,
    error: null,
    isRecovering: false,
    recoveryAttempts: 0,
    isDegraded: false,
    lastSuccessAt: null,
    lastErrorAt: null,
  });

  const [currentStrategy, setCurrentStrategy] = useState<RecoveryStrategy>(recoveryStrategy);

  // Refs
  const retryManagerRef = useRef(new EnhancedRetryManager(retryConfig));
  const cacheRef = useRef(cacheKey ? new LocalStorageCache<T>(cacheKey, cacheTTL) : null);
  const isMountedRef = useRef(true);
  const abortControllerRef = useRef<AbortController | null>(null);

  // 清理函数
  useEffect(() => {
    return () => {
      isMountedRef.current = false;
      abortControllerRef.current?.abort();
    };
  }, []);

  // 安全的状态更新
  const safeSetState = useCallback(
    (updater: (prev: ErrorRecoveryState<T>) => ErrorRecoveryState<T>) => {
      if (isMountedRef.current) {
        setState(updater);
      }
    },
    []
  );

  // 执行数据获取操作
  const execute = useCallback(
    async (operation: () => Promise<T>, operationName?: string) => {
      // 取消之前的操作
      abortControllerRef.current?.abort();
      abortControllerRef.current = new AbortController();

      safeSetState((prev) => ({
        ...prev,
        isLoading: true,
        isError: false,
        error: null,
        isRecovering: prev.recoveryAttempts > 0,
      }));

      try {
        // 首先尝试正常执行
        const result = await retryManagerRef.current.execute(operation, operationName, {
          onRetry: (context) => {
            safeSetState((prev) => ({
              ...prev,
              recoveryAttempts: context.attempt,
              isRecovering: true,
            }));

            addBreadcrumb({
              category: 'error-recovery',
              message: `Retry attempt ${context.attempt}`,
              level: 'info',
              data: { operationName, delay: context.delay },
            });
          },
        });

        if (result.success) {
          // 成功
          const data = result.data!;

          // 保存到缓存
          cacheRef.current?.set(data);

          safeSetState((prev) => ({
            ...prev,
            data,
            isLoading: false,
            isError: false,
            error: null,
            isRecovering: false,
            recoveryAttempts: 0,
            isDegraded: false,
            lastSuccessAt: Date.now(),
          }));

          setCurrentStrategy('retry');
          onRecoverySuccess?.(data);

          addBreadcrumb({
            category: 'error-recovery',
            message: 'Operation succeeded',
            level: 'info',
            data: { operationName, attempts: result.attempts },
          });
        } else {
          // 重试后仍然失败，尝试恢复策略
          throw result.error || new Error('Operation failed after retries');
        }
      } catch (error) {
        const err = error instanceof Error ? error : new Error(String(error));

        logger.warn(`Operation ${operationName || ''} failed, attempting recovery`, {
          error: err.message,
          strategy: currentStrategy,
        });

        // 尝试恢复
        await attemptRecovery(err, operation, operationName);
      }
    },
    [currentStrategy, onRecoverySuccess, safeSetState]
  );

  // 尝试恢复
  const attemptRecovery = useCallback(
    async (error: Error, originalOperation: () => Promise<T>, operationName?: string) => {
      const strategies: RecoveryStrategy[] = [
        'cache',
        'fallback',
        'graceful-degradation',
        'manual',
      ];

      for (const strategy of strategies) {
        if (!autoRecover && strategy !== 'manual') continue;

        try {
          let recovered = false;
          let recoveredData: T | null = null;

          switch (strategy) {
            case 'cache': {
              // 尝试从缓存恢复
              const cachedData = cacheRef.current?.get();
              if (cachedData) {
                recoveredData = cachedData;
                recovered = true;
                logger.info('Recovered from cache', { operationName });
              }
              break;
            }

            case 'fallback': {
              // 尝试使用降级数据
              if (fallbackData) {
                recoveredData = await fallbackData();
                recovered = true;
                logger.info('Recovered using fallback data', { operationName });
              }
              break;
            }

            case 'graceful-degradation': {
              // 尝试返回部分数据或默认值
              if (state.data) {
                recoveredData = state.data;
                recovered = true;
                logger.info('Using stale data for graceful degradation', { operationName });
              }
              break;
            }

            case 'manual':
            default:
              // 手动恢复模式，不自动恢复
              break;
          }

          if (recovered && recoveredData !== null) {
            safeSetState((prev) => ({
              ...prev,
              data: recoveredData,
              isLoading: false,
              isError: false,
              error: null,
              isRecovering: false,
              isDegraded: strategy !== 'cache',
              lastErrorAt: Date.now(),
            }));

            setCurrentStrategy(strategy);

            if (strategy === 'fallback' || strategy === 'graceful-degradation') {
              onDegraded?.(recoveredData);
            }

            addBreadcrumb({
              category: 'error-recovery',
              message: `Recovered using ${strategy} strategy`,
              level: 'info',
              data: { operationName, strategy },
            });

            return;
          }
        } catch (recoveryError) {
          logger.warn(`Recovery strategy ${strategy} failed`, { recoveryError });
        }
      }

      // 所有恢复策略都失败了
      safeSetState((prev) => ({
        ...prev,
        isLoading: false,
        isError: true,
        error,
        isRecovering: false,
        lastErrorAt: Date.now(),
      }));

      setCurrentStrategy('manual');
      onRecoveryFailure?.(error);

      captureException(error, {
        operationName,
        recoveryAttempts: state.recoveryAttempts,
        message: 'All recovery strategies failed',
      });
    },
    [
      autoRecover,
      fallbackData,
      state.data,
      state.recoveryAttempts,
      onDegraded,
      onRecoveryFailure,
      safeSetState,
    ]
  );

  // 手动重试
  const retry = useCallback(async () => {
    if (state.recoveryAttempts >= maxRecoveryAttempts) {
      logger.warn('Max recovery attempts reached');
      return;
    }

    safeSetState((prev) => ({
      ...prev,
      recoveryAttempts: prev.recoveryAttempts + 1,
    }));

    // 触发重新执行需要外部传入 operation
    // 这里只是重置状态，实际重试由调用方控制
    safeSetState((prev) => ({
      ...prev,
      isError: false,
      error: null,
    }));
  }, [maxRecoveryAttempts, state.recoveryAttempts, safeSetState]);

  // 使用降级数据
  const useFallback = useCallback(
    (fallbackDataValue: T) => {
      safeSetState((prev) => ({
        ...prev,
        data: fallbackDataValue,
        isLoading: false,
        isError: false,
        error: null,
        isDegraded: true,
      }));

      setCurrentStrategy('fallback');
      onDegraded?.(fallbackDataValue);
    },
    [onDegraded, safeSetState]
  );

  // 重置状态
  const reset = useCallback(() => {
    safeSetState(() => ({
      data: null,
      isLoading: false,
      isError: false,
      error: null,
      isRecovering: false,
      recoveryAttempts: 0,
      isDegraded: false,
      lastSuccessAt: null,
      lastErrorAt: null,
    }));

    setCurrentStrategy(recoveryStrategy);
    cacheRef.current?.clear();
  }, [recoveryStrategy, safeSetState]);

  // 清除错误
  const clearError = useCallback(() => {
    safeSetState((prev) => ({
      ...prev,
      isError: false,
      error: null,
    }));
  }, [safeSetState]);

  return {
    ...state,
    execute,
    retry,
    useFallback,
    reset,
    clearError,
    currentStrategy,
    retryManager: retryManagerRef.current,
  };
}

/**
 * 批量错误恢复 Hook
 * 用于管理多个并发操作的错误恢复
 */
export function useBatchErrorRecovery<T extends Record<string, unknown>>(
  config: ErrorRecoveryConfig<T> = {}
) {
  const [results, setResults] = useState<{
    [K in keyof T]?: ErrorRecoveryState<T[K]>;
  }>({});

  const retryManagerRef = useRef(new EnhancedRetryManager(config.retryConfig));

  const executeBatch = useCallback(
    async (
      operations: { [K in keyof T]: () => Promise<T[K]> },
      options?: {
        continueOnError?: boolean;
        onPartialSuccess?: (key: keyof T, data: T[keyof T]) => void;
      }
    ) => {
      const entries = Object.entries(operations) as [keyof T, () => Promise<T[keyof T]>][];
      const newResults: Partial<{ [K in keyof T]: ErrorRecoveryState<T[K]> }> = {};

      for (const [key, operation] of entries) {
        try {
          const result = await retryManagerRef.current.execute(operation, String(key));

          if (result.success) {
            newResults[key] = {
              data: result.data!,
              isLoading: false,
              isError: false,
              error: null,
              isRecovering: false,
              recoveryAttempts: result.attempts,
              isDegraded: false,
              lastSuccessAt: Date.now(),
              lastErrorAt: null,
            };

            options?.onPartialSuccess?.(key, result.data!);
          } else {
            throw result.error || new Error('Operation failed');
          }
        } catch (error) {
          const err = error instanceof Error ? error : new Error(String(error));

          newResults[key] = {
            data: null,
            isLoading: false,
            isError: true,
            error: err,
            isRecovering: false,
            recoveryAttempts: 0,
            isDegraded: false,
            lastSuccessAt: null,
            lastErrorAt: Date.now(),
          };

          if (!options?.continueOnError) {
            break;
          }
        }
      }

      setResults((prev) => ({ ...prev, ...newResults }));
      return newResults as { [K in keyof T]: ErrorRecoveryState<T[K]> };
    },
    []
  );

  return {
    results,
    executeBatch,
    retryManager: retryManagerRef.current,
  };
}

