/**
 * API 错误类型定义
 * 提供统一的错误类型系统
 */

/**
 * 标准 API 错误响应
 */
export interface ApiErrorResponse {
  success: false;
  error: {
    /** 错误码 */
    code: string;
    /** 错误消息 */
    message: string;
    /** 错误详情 */
    details?: Record<string, unknown>;
    /** 是否可重试 */
    retryable: boolean;
    /** 国际化键 */
    i18nKey?: string;
    /** 文档链接 */
    documentationUrl?: string;
    /** 请求 ID */
    requestId?: string;
    /** 时间戳 */
    timestamp: number;
    /** 堆栈跟踪（仅开发环境） */
    stackTrace?: string;
    /** 建议的用户操作 */
    suggestedAction?: string;
  };
  meta: {
    requestId?: string;
    timestamp: number;
    path?: string;
    method?: string;
  };
}

/**
 * 标准 API 成功响应
 */
export interface ApiSuccessResponse<T> {
  success: true;
  data: T;
  meta?: {
    timestamp: number;
    requestId?: string;
    [key: string]: unknown;
  };
}

/**
 * 统一的 API 响应类型
 */
export type ApiResponse<T> = ApiSuccessResponse<T> | ApiErrorResponse;

